const arTerm = (lang, value) => {
  if (lang !== "ar" || value == null) return value;
  const text = String(value);
  const exact = AR_TERM_MAP[text] || AR_TERM_MAP[text.toLowerCase()];
  if (exact) return exact;
  let localized = text;
  Object.entries(AR_TERM_MAP)
    .filter(([source]) => source && /[A-Za-z]/.test(source))
    .sort((a, b) => b[0].length - a[0].length)
    .forEach(([source, replacement]) => {
      const escaped = source.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
      const pattern = /^[A-Za-z0-9 ]+$/.test(source)
        ? new RegExp(`\\b${escaped}\\b`, "gi")
        : new RegExp(escaped, "g");
      localized = localized.replace(pattern, replacement);
    });
  localized = localized
    .replace(/\bnow\b/gi, "الآن")
    .replace(/\bmin ago\b/gi, "دقيقة مضت")
    .replace(/\bhr ago\b/gi, "ساعة مضت")
    .replace(/\bday\b/gi, "يوم")
    .replace(/\bdays\b/gi, "أيام")
    .replace(/\bstaff\b/gi, "موظفين")
    .replace(/\bin queue\b/gi, "في الطابور")
    .replace(/\bsale\b/gi, "بيع")
    .replace(/\bago\b/gi, "مضت")
    .replace(/\blow-stock alerts\b/gi, "تنبيهات مخزون منخفض")
    .replace(/\blow\b/gi, "منخفض")
    .replace(/\bstocked\b/gi, "متوفر")
    .replace(/\bcritical\b/gi, "حرج")
    .replace(/\bitems in good standing\b/gi, "بنود بحالة جيدة")
    .replace(/\brunout\b/gi, "نفاد خلال")
    .replace(/\btarget\b/gi, "الهدف")
    .replace(/\bestimated loss\b/gi, "خسارة تقديرية")
    .replace(/\bpts over\b/gi, "نقاط فوق")
    .replace(/\bcards\b/gi, "بطاقات")
    .replace(/\bgenerated just now\b/gi, "تم توليده الآن")
    .replace(/\bconf\b/gi, "ثقة")
    .replace(/\bscore\b/gi, "درجة")
    .replace(/\borders\b/gi, "طلبات")
    .replace(/\bstock\b/gi, "مخزون")
    .replace(/\bwaste\b/gi, "هدر")
    .replace(/\bsource rows\b/gi, "صفوف المصدر")
    .replace(/\bmonthly budget used\b/gi, "من الميزانية الشهرية المستخدمة")
    .replace(/\bsince\b/gi, "منذ")
    .replace(/\bprice hike\b/gi, "زيادة السعر")
    .replace(/pts\b/gi, "نقاط")
    .replace(/\bcard\b/gi, "بطاقة")
    .replace(/\battach\b/gi, "إرفاق")
    .replace(/\bmargin\b/gi, "هامش")
    .replace(/\brange\b/gi, "النطاق")
    .replace(/\btoday\b/gi, "اليوم")
    .replace(/\bactual\b/gi, "فعلي")
    .replace(/\bqueued\b/gi, "بانتظار")
    .replace(/\bpayroll\b/gi, "رواتب")
    .replace(/\bexpenses\b/gi, "مصروفات")
    .replace(/\bgateway batch\b/gi, "دفعة بوابة")
    .replace(/\bbank batch\b/gi, "دفعة بنكية")
    .replace(/\bshift cash count\b/gi, "عد نقد الوردية")
    .replace(/\bmanager verified\b/gi, "موثق من المدير")
    .replace(/\bpolicy\b/gi, "سياسة")
    .replace(/\bready\b/gi, "جاهز")
    .replace(/\breceived\b/gi, "مستلم")
    .replace(/\bcreatedReceive\b/gi, "تم إنشاء الاستلام");
  return localized;
};

const unwrapOdoo = (payload) => {
  if (!payload || typeof payload !== "object") return payload;
  return payload.message || payload.data || payload;
};

const LIVE_ONLY_KEY = "__bayaanLiveOnly";

const EMPTY_ENGINE_SNAPSHOT = {
  [LIVE_ONLY_KEY]: true,
  engine: "odoo_pos",
  summary: null,
  kiosks: [],
  products: [],
  recipes: [],
  purchase_orders: [],
  transfers: [],
  suggested_transfers: [],
  closings: [],
  warehouse_stock: [],
  kiosk_stock: {},
  kiosk_stock_rows: [],
  kioskStockDetails: {},
  today: {
    orders: [],
    payments: [],
    sales: [],
    consumption: [],
    waste: [],
  },
};

const EMPTY_WAREHOUSE_SETUP = {
  [LIVE_ONLY_KEY]: true,
  engine: "odoo_pos",
  company: null,
  warehouses: [],
  locations: [],
  kiosks: [],
  pos_configs: [],
};

const markLiveOnlySnapshot = (payload) => {
  const snapshot = unwrapOdoo(payload);
  if (!snapshot || typeof snapshot !== "object") return EMPTY_ENGINE_SNAPSHOT;
  return {
    ...EMPTY_ENGINE_SNAPSHOT,
    ...snapshot,
    [LIVE_ONLY_KEY]: true,
    today: {
      ...EMPTY_ENGINE_SNAPSHOT.today,
      ...(snapshot.today || {}),
    },
  };
};

const markLiveOnlyWarehouseSetup = (payload) => {
  const setup = unwrapOdoo(payload);
  if (!setup || typeof setup !== "object") return EMPTY_WAREHOUSE_SETUP;
  return {
    ...EMPTY_WAREHOUSE_SETUP,
    ...setup,
    [LIVE_ONLY_KEY]: true,
  };
};

const isLiveOnlyPayload = (payload) => Boolean(unwrapOdoo(payload)?.[LIVE_ONLY_KEY]);
const isSimulationPayload = (payload) => unwrapOdoo(payload)?.engine === "bayaan_peak_simulation";
const isSimulationRuntime = () => {
  if (typeof window === "undefined") return false;
  const params = new URLSearchParams(window.location.search);
  return (
    params.get("bayaanSimulation") === "peak"
    || params.get("bayaanSimulation") === "peak-full"
    || params.get("bayaanMode") === "simulation"
    || window.localStorage.getItem("BAYAAN_SIMULATION") === "peak"
  );
};
const canUseDemoFallback = (payload) => !isLiveOnlyPayload(payload) && !isSimulationPayload(payload) && !isSimulationRuntime();
const isSourceDrivenPayload = (payload) => isLiveOnlyPayload(payload) || isSimulationPayload(payload) || isSimulationRuntime();
const simulationRuntimeSpeed = () => {
  if (typeof window === "undefined") return 1;
  const params = new URLSearchParams(window.location.search);
  const speed = Number(params.get("bayaanSimSpeed") || window.localStorage.getItem("BAYAAN_SIMULATION_SPEED") || 1);
  return [1, 2, 5, 10].includes(speed) ? speed : 1;
};
const simulationRuntimeMinutes = () => {
  if (typeof window === "undefined") return 60;
  const params = new URLSearchParams(window.location.search);
  const minutes = Number(params.get("bayaanSimMinutes") || window.localStorage.getItem("BAYAAN_SIMULATION_MINUTES") || 60);
  return Number.isFinite(minutes) && minutes >= 30 ? Math.min(120, Math.trunc(minutes)) : 60;
};

const odooSummary = (bootstrap) => unwrapOdoo(bootstrap)?.summary || null;

const odooMinutePulse = (bootstrap) => {
  const summary = odooSummary(bootstrap);
  const rows = summary?.minutePulse;
  if (!(isSimulationPayload(bootstrap) || isSimulationRuntime()) || !Array.isArray(rows) || !rows.length) return null;
  const activeIndex = rows.reduce((last, row, index) => Number(row?.orders || 0) > 0 ? index : last, -1);
  const avgRevenue = rows.reduce((sum, row) => sum + Number(row?.revenue || 0), 0) / Math.max(1, rows.length);
  return rows.map((row, index) => ({
    label: index % 5 === 0 ? String(index).padStart(2, "0") : "",
    value: Number(row?.revenue || 0),
    expected: Math.max(avgRevenue * 0.72, Number(row?.revenue || 0) * 0.82),
    state: index === activeIndex ? "current" : index < activeIndex ? "past" : "future",
  }));
};

const odooHourlyPulse = (bootstrap) => {
  const summary = odooSummary(bootstrap);
  const source = summary?.hourlySales || summary?.hourlyPulse;
  if (!source) return null;
  const buckets = Array(24).fill(0);
  if (Array.isArray(source)) {
    if (source.every((value) => Number.isFinite(Number(value)))) {
      source.slice(0, 24).forEach((value, hour) => {
        buckets[hour] = Number(value || 0);
      });
    } else {
      source.forEach((row, index) => {
        const hour = Number(row?.hour ?? row?.hourOfDay ?? row?.h ?? index);
        const value = Number(row?.revenue ?? row?.sales ?? row?.amount ?? row?.total ?? row?.value ?? 0);
        if (hour >= 0 && hour < 24) buckets[hour] = value;
      });
    }
  } else if (typeof source === "object") {
    Object.entries(source).forEach(([hourKey, value]) => {
      const hour = Number(hourKey);
      const amount = typeof value === "object"
        ? Number(value?.revenue ?? value?.sales ?? value?.amount ?? value?.total ?? value?.value ?? 0)
        : Number(value || 0);
      if (hour >= 0 && hour < 24) buckets[hour] = amount;
    });
  }
  return buckets.some((value) => Number(value || 0) > 0) ? buckets : null;
};

const normalizeLookup = (value) => String(value || "").toLowerCase().replace(/[^a-z0-9]+/g, "");

const kioskLookupValues = (kiosk) => [
  kiosk?.id,
  kiosk?.name,
  kiosk?.kiosk_code,
  kiosk?.kioskName,
  kiosk?.pos_config,
  kiosk?.posConfig,
  kiosk?.warehouse,
  kiosk?.stockLocation,
].filter(Boolean);

const matchesKiosk = (value, kiosk) => {
  const left = normalizeLookup(value);
  if (left.length < 2) return false;
  return kioskLookupValues(kiosk).some((candidate) => {
    const right = normalizeLookup(candidate);
    if (right.length < 2) return false;
    return left === right || left.includes(right) || right.includes(left);
  });
};

const matchesItem = (value, item) => {
  const left = normalizeLookup(value);
  const right = normalizeLookup(item);
  if (left.length < 2 || right.length < 2) return false;
  return left === right || left.includes(right) || right.includes(left);
};

const cleanDisplayName = (value) => String(value || "").replace(/^\[[^\]]+\]\s*/, "");

const compactError = (error) => {
  if (!error) return "";
  const message = error.message || String(error);
  return message.length > 120 ? `${message.slice(0, 117)}...` : message;
};

const isSuperadminAuth = (auth) => (
  auth?.user?.primaryRole === "superadmin" || auth?.user?.roles?.includes("superadmin")
);

const auditSeverityClass = (severity) => {
  if (severity === "critical") return "badge-crit";
  if (severity === "warning") return "badge-warn";
  if (severity === "success") return "badge-pos";
  return "";
};

const auditDotClass = (severity) => {
  if (severity === "critical") return "crit";
  if (severity === "warning") return "warn";
  if (severity === "success") return "pos";
  return "";
};

const auditTimeLabel = (value) => {
  if (!value) return "";
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return String(value);
  return date.toLocaleTimeString("en", { hour: "2-digit", minute: "2-digit" });
};

const normalizeAuditEvents = (payload) => {
  const data = unwrapOdoo(payload);
  const rows = Array.isArray(data?.events) ? data.events : [];
  return rows.map((event) => ({
    id: event.id,
    title: event.title || event.action || "System event",
    detail: event.detail || event.message || "",
    actor: event.actor || "Bayaan",
    action: event.action || "",
    eventType: event.eventType || event.event_type || "",
    severity: event.severity || "info",
    reference: event.reference || event.ref || "",
    model: event.model || event.modelName || "",
    kiosk: event.kiosk || event.kioskName || "",
    occurredAt: event.occurredAt || event.occurred_at || event.at || "",
  }));
};

const normalizeRealtimeAuditEvent = (event) => ({
  id: `rt-${event.id || Date.now()}`,
  title: event.title || event.action || "Realtime event",
  detail: event.detail || "",
  actor: "Bayaan stream",
  action: event.action || event.type || "",
  eventType: event.eventType || "",
  severity: event.severity || "info",
  reference: event.reference || "",
  model: event.model || "",
  kiosk: event.kiosk || event.kioskName || "",
  occurredAt: event.occurredAt || new Date().toISOString(),
});

const readFileAsBase64 = (file) => new Promise((resolve, reject) => {
  if (!file) {
    resolve("");
    return;
  }
  const reader = new FileReader();
  reader.onload = () => {
    const result = String(reader.result || "");
    resolve(result.includes(",") ? result.split(",").pop() || "" : result);
  };
  reader.onerror = () => reject(reader.error || new Error("Could not read file"));
  reader.readAsDataURL(file);
});

function Modal({ open, onClose, title, sub, width = 460, children }) {
  useEffect(() => {
    if (!open) return;
    const onKey = (e) => { if (e.key === "Escape") onClose?.(); };
    window.addEventListener("keydown", onKey);
    const prev = document.body.style.overflow;
    document.body.style.overflow = "hidden";
    return () => {
      window.removeEventListener("keydown", onKey);
      document.body.style.overflow = prev;
    };
  }, [open, onClose]);
  if (!open) return null;
  const overlay = (
    <div onClick={onClose}
      role="dialog"
      aria-modal="true"
      style={{ position: "fixed", inset: 0, background: "rgba(0,0,0,0.45)", zIndex: 80, display: "flex", flexDirection: "column", overflowY: "auto", padding: 20 }}>
      <div onClick={(e) => e.stopPropagation()}
        className="card"
        // `margin: auto` centers the card both ways when it fits; when the card is
        // taller than the viewport, auto margins collapse to 0 and the overlay scrolls,
        // so both the top and the bottom (e.g. the Save button) stay reachable —
        // unlike grid/flex center-alignment, which clips the overflowing top.
        style={{ width: "100%", maxWidth: width, margin: "auto", background: "var(--paper)", borderRadius: 12, padding: 20, boxShadow: "0 24px 48px rgba(0,0,0,0.18)" }}>
        <div className="between" style={{ marginBottom: 14, alignItems: "flex-start", gap: 12 }}>
          <div style={{ flex: 1, minWidth: 0 }}>
            <div style={{ fontWeight: 500, fontSize: 14 }}>{title}</div>
            {sub && <div className="t-small muted" style={{ marginTop: 2 }}>{sub}</div>}
          </div>
          <button type="button" onClick={onClose} className="btn btn-ghost"
            aria-label="Close"
            style={{ width: 28, height: 28, padding: 0, justifyContent: "center", flexShrink: 0 }}>
            <Icon name="x" size={14}/>
          </button>
        </div>
        {children}
      </div>
    </div>
  );
  // Portal the overlay up to the `.app-frame` root. Rendered inline, the modal nests
  // inside each page's `.fade-up` wrapper, whose `transform` keyframes establish a
  // containing block for `position: fixed` descendants — so on a scrolled page the
  // overlay anchors to the top of the scrolled content instead of the viewport, and
  // the user has to scroll up to see it. `.app-frame` carries data-theme/dir/lang and
  // has no transformed ancestor, so the cascade (incl. dark mode + RTL) is preserved.
  if (typeof document === "undefined") return overlay;
  return createPortal(overlay, document.querySelector(".app-frame") || document.body);
}

// Per-kiosk approximate daily P&L straight from the deterministic byKiosk summary
// (sales / ledger COGS / waste / prorated staff cost). Today scope, matching byKiosk.
const odooKioskPnlRows = (bootstrap, period = "Daily") => {
  const snapshot = unwrapOdoo(bootstrap);
  const periodKey = String(period || "Daily").toLowerCase();
  const periodRows = snapshot?.summary?.reportPeriods?.[periodKey]?.byKiosk;
  const rows = (Array.isArray(periodRows) && periodRows.length ? periodRows : snapshot?.summary?.byKiosk) || [];
  return rows.map((row) => {
    const sales = Number(row.sales || 0);
    const cogs = Number(row.cogs || 0);
    const wasteCost = Number(row.wasteCost || 0);
    const staffCost = Number(row.staffCost || 0);
    const approxProfit = row.approxProfit != null ? Number(row.approxProfit) : sales - cogs - wasteCost - staffCost;
    return {
      id: row.kioskId,
      name: row.name || row.kioskId,
      city: row.city || "",
      orders: Number(row.orders || 0),
      sales,
      cogs,
      wasteCost,
      staffCost,
      grossProfit: row.grossProfit != null ? Number(row.grossProfit) : sales - cogs,
      approxProfit,
      margin: row.margin != null ? Number(row.margin) : (sales ? (approxProfit / sales) * 100 : 0),
    };
  });
};

// Period-scoped view of the live bootstrap for a non-daily global scope. Swaps the order
// list (and the today.sales / today.payments rows derived from it) plus the headline and
// per-kiosk summary totals for the selected period, while preserving the live-only marker
// (it's a plain key on the flat snapshot, so a spread copy keeps it). Every screen that
// reads bootstrap.today.* / summary.* then follows the scope with no per-screen plumbing.
// Daily, a missing period, or not-yet-loaded orders return the bootstrap untouched.
const buildScopedBootstrap = (bootstrap, scope, periodOrders) => {
  if (!bootstrap || typeof bootstrap !== "object") return bootstrap;
  if (!scope || scope === "Daily" || !Array.isArray(periodOrders)) return bootstrap;
  const scopeKey = String(scope).toLowerCase();
  const period = bootstrap?.summary?.reportPeriods?.[scopeKey];
  const sales = periodOrders.map((order) => ({
    name: order.name,
    kiosk: order.kiosk,
    pos_config: order.pos_config,
    revenue: order.amount_total,
    orders: 1,
    amount_total: order.amount_total,
    consumption_state: order.consumption_state,
  }));
  const payments = periodOrders.flatMap((order) => (order.payments || []).map((payment) => ({
    order: order.name,
    kiosk: order.kiosk,
    method: payment.method,
    category: payment.category,
    provider: payment.provider,
    amount: payment.amount,
  })));
  const baseTotals = bootstrap?.summary?.totals || null;
  const scopedTotals = (baseTotals && period) ? {
    ...baseTotals,
    salesToday: Number(period.revenue ?? period.sales ?? baseTotals.salesToday ?? 0),
    ordersToday: Number(period.orders ?? baseTotals.ordersToday ?? 0),
    profitEstimate: period.netProfitAfterPayroll != null ? Number(period.netProfitAfterPayroll)
      : period.netProfit != null ? Number(period.netProfit) : baseTotals.profitEstimate,
    cogs: period.cogs != null ? Number(period.cogs) : baseTotals.cogs,
    wasteCost: period.wasteCost != null ? Number(period.wasteCost) : baseTotals.wasteCost,
    cashExpected: period.cashExpected != null ? Number(period.cashExpected) : baseTotals.cashExpected,
    digitalPayments: period.digitalPayments != null ? Number(period.digitalPayments) : baseTotals.digitalPayments,
  } : baseTotals;
  // Hour-of-day revenue distribution across the period so the Overview "sales flow"
  // (24-bucket hourly chart) reflects the selected period instead of just today.
  const hourly = Array(24).fill(0);
  periodOrders.forEach((order) => {
    const hour = Number(String(order.date_order || "").slice(11, 13));
    if (hour >= 0 && hour < 24) hourly[hour] += Number(order.amount_total || 0);
  });
  return {
    ...bootstrap,
    summary: {
      ...bootstrap.summary,
      totals: scopedTotals,
      byKiosk: (period?.byKiosk && period.byKiosk.length) ? period.byKiosk : bootstrap?.summary?.byKiosk,
      // Drop the daily payment split so the payment-mix helper recomputes from the period's
      // today.payments (below); feed the period's hour-of-day curve to the sales-flow chart.
      payments: undefined,
      hourlySales: hourly,
      hourlyPulse: hourly,
    },
    today: {
      ...bootstrap.today,
      orders: periodOrders,
      sales,
      payments,
    },
  };
};

const odooKioskRows = (bootstrap, scope = "Daily") => {
  const snapshot = unwrapOdoo(bootstrap);
  const useDemo = canUseDemoFallback(bootstrap);
  if (!snapshot?.kiosks?.length) return useDemo ? MOCK.kiosks : [];
  const summaryRows = snapshot?.summary?.byKiosk || [];
  // Global scope overlay: for a non-daily scope, each kiosk's revenue/orders/waste/margin
  // come from that period's deterministic reportPeriods.byKiosk aggregate instead of today.
  // Daily (or a missing period) leaves the today-scoped figures untouched.
  const scopeKey = String(scope || "Daily").toLowerCase();
  const periodByKiosk = scopeKey !== "daily"
    ? (snapshot?.summary?.reportPeriods?.[scopeKey]?.byKiosk || [])
    : [];
  const salesByKiosk = {};
  (snapshot.today?.sales || []).forEach((sale) => {
    const code = sale.kiosk || sale.pos_config;
    if (!code) return;
    salesByKiosk[code] = salesByKiosk[code] || { revenue: 0, orders: 0 };
    salesByKiosk[code].revenue += Number(sale.revenue || sale.amount_total || 0);
    salesByKiosk[code].orders += Number(sale.orders || 1);
  });

  return snapshot.kiosks.map((kiosk, index) => {
    const fallback = useDemo
      ? MOCK.kiosks[index % MOCK.kiosks.length]
      : {
          id: kiosk.kiosk_code || `K-${index + 1}`,
          name: kiosk.name || "Kiosk",
          city: kiosk.city || kiosk.area || "-",
          revenue: 0,
          orders: 0,
          margin: 0,
          waste: 0,
          wasteLoad: 0,
          stockHealth: 0,
          variance: 0,
          criticalStock: "-",
          issue: "No verified activity yet",
          staff: 0,
          status: "good",
          trend: [],
        };
    const summary = summaryRows.find((row) => matchesKiosk(row.kioskId || row.name, kiosk));
    const periodRow = periodByKiosk.length
      ? periodByKiosk.find((row) => matchesKiosk(row.kioskId || row.name, kiosk))
      : null;
    const sales = Object.entries(salesByKiosk).find(([key]) => matchesKiosk(key, kiosk))?.[1] || {};
    const stockRows = Object.entries(snapshot.kiosk_stock || {}).find(([key]) => matchesKiosk(key, kiosk))?.[1] || [];
    const stockRowsWithStatus = stockRows.map((row) => ({
      row,
      status: inventoryStatusFor(Number(row.actual_qty || 0), row),
    }));
    const trackedStockRows = stockRowsWithStatus.filter((entry) => entry.status !== "unconfigured");
    const actionableStockRows = stockRowsWithStatus.filter((entry) => isInventoryActionStatus(entry.status));
    const stockItems = Number(summary?.stockItems ?? stockRows.length ?? 0);
    const lowStockItems = Number(summary?.lowStockItems ?? actionableStockRows.length ?? 0);
    const zeroStockItems = Number(summary?.zeroStockItems ?? stockRowsWithStatus.filter((entry) => entry.status === "crit" && Number(entry.row.actual_qty || 0) <= 0).length ?? 0);
    const wasteRows = (snapshot.today?.waste || []).filter((row) => row.kiosk === kiosk.kiosk_code || row.kiosk === kiosk.name);
    const revenue = Math.round(Number(periodRow?.sales ?? summary?.sales ?? sales.revenue ?? fallback.revenue));
    const orders = Math.round(Number(periodRow?.orders ?? summary?.orders ?? sales.orders ?? fallback.orders));
    const wasteCost = Number(periodRow?.wasteCost ?? summary?.wasteCost ?? wasteRows.reduce((sum, row) => sum + Number(row.estimated_cost || 0), 0));
    const waste = revenue ? Number(((wasteCost / revenue) * 100).toFixed(1)) : fallback.waste;
    const stockHealth = summary?.stockHealth != null
      ? Number(summary.stockHealth)
      : trackedStockRows.length
      ? Math.round(trackedStockRows.reduce((sum, entry) => {
          const explicit = Number(entry.row.stock_percent ?? entry.row.stockPercent);
          if (Number.isFinite(explicit) && explicit > 0) return sum + explicit;
          return sum + (entry.status === "ok" ? 100 : entry.status === "low" ? 50 : 10);
        }, 0) / trackedStockRows.length)
      : fallback.stockHealth;
    const wasteLoad = Math.min(100, Math.round((waste / 6) * 100));
    const summaryStatus = String(summary?.status || "");
    const status = summaryStatus === "variance_issue"
      ? "crit"
      : ["low_stock", "needs_closing"].includes(summaryStatus)
        ? "warn"
        : stockHealth < 50 || waste > 5.5 ? "crit" : stockHealth < 70 || waste > 3.5 ? "warn" : "good";
    return {
      ...fallback,
      id: kiosk.kiosk_code || fallback.id,
      name: kiosk.name || fallback.name,
      city: kiosk.city || kiosk.area || fallback.city,
      kiosk_code: kiosk.kiosk_code,
      posConfig: kiosk.pos_config,
      stockLocation: kiosk.warehouse,
      manager: kiosk.manager,
      supervisor: kiosk.supervisor,
      revenue,
      orders,
      margin: periodRow?.margin != null ? Number(periodRow.margin) : summary?.margin != null ? Number(summary.margin) : fallback.margin,
      waste,
      wasteLoad,
      stockHealth,
      stockItems,
      lowStockItems,
      zeroStockItems,
      status,
      criticalStock: actionableStockRows[0]?.row?.item || fallback.criticalStock,
      issue: status === "crit" ? "Stock or waste needs action" : status === "warn" ? "Watch stock levels" : "Synced from engine",
    };
  });
};

const inventoryCategoryFor = (mode, fallback = "") => {
  if (fallback) return fallback;
  if (mode === "recipe") return "Recipe product";
  if (mode === "hybrid") return "Hybrid product";
  if (mode === "none") return "Non-stock product";
  return "Stock item";
};

const INVENTORY_UNCONFIGURED_STATUSES = new Set(["unconfigured", "not_configured", "no_target"]);
const INVENTORY_ACTION_STATUSES = new Set(["crit", "low"]);
const isInventoryActionStatus = (status) => INVENTORY_ACTION_STATUSES.has(String(status || "").toLowerCase());

const inventoryStatusFor = (qty, row = {}) => {
  const sourceStatus = String(row.stock_status || row.status || "").toLowerCase();
  if (INVENTORY_UNCONFIGURED_STATUSES.has(sourceStatus)) return "unconfigured";
  if (["empty", "critical", "crit"].includes(sourceStatus)) return "crit";
  if (["low", "watch"].includes(sourceStatus)) return "low";
  if (["ok", "over_target"].includes(sourceStatus)) return "ok";
  const critical = Number(row.critical_qty || row.critical || 0);
  const reorder = Number(row.reorder_qty || row.reorder || 0);
  const target = Number(row.target_qty || row.target || row.targetQty || 0);
  if (!target && !critical && !reorder) return "unconfigured";
  if (critical && qty <= critical) return "crit";
  if (reorder && qty <= reorder) return "low";
  if (qty <= 0) return "crit";
  return "ok";
};

const isInventoryActionable = (row) => isInventoryActionStatus(row?.status);

const inventoryDaysFor = (row, status, useDemoEstimate) => {
  const explicit = row.days ?? row.days_cover ?? row.cover_days ?? row.coverDays;
  if (explicit !== undefined && explicit !== null && explicit !== "") {
    return Number(explicit);
  }
  if (!useDemoEstimate) return null;
  return status === "crit" ? 0.6 : status === "low" ? 1.8 : 6.4;
};

const odooInventoryRows = (bootstrap) => {
  const snapshot = unwrapOdoo(bootstrap);
  const useDemo = canUseDemoFallback(bootstrap);
  if (!snapshot?.warehouse_stock?.length && !snapshot?.kiosk_stock_rows?.length) {
    return useDemo
      ? MOCK.inventory.map((row) => ({ ...row, location: "Central warehouse", locationKey: "central-warehouse" }))
      : [];
  }
  const productMeta = new Map();
  (snapshot.products || []).forEach((product) => {
    [product.default_code, product.name, cleanDisplayName(product.name)].filter(Boolean).forEach((key) => {
      productMeta.set(String(key), product);
    });
  });
  const makeRow = (row, location, locationKey) => {
    const meta = productMeta.get(String(row.item)) || productMeta.get(cleanDisplayName(row.item)) || {};
    const qty = Number(row.actual_qty || 0);
    const status = inventoryStatusFor(qty, row);
    const unitCost = Number(row.unit_cost || row.standard_price || meta.standard_price || 0);
    return {
      item: row.item || "Stock item",
      consumptionMode: meta.consumption_mode || row.mode || "",
      category: inventoryCategoryFor(row.mode || meta.consumption_mode, row.category || meta.category),
      stock: Math.round(qty * 100) / 100,
      unit: row.uom || "u",
      reorder: Number(row.reorder_qty || row.reorder || 0),
      target: Number(row.target_qty || row.target || meta.target_qty || 0),
      critical: Number(row.critical_qty || row.critical || meta.critical_qty || 0),
      stockPercent: Number(row.stock_percent || row.stockPercent || 0),
      targetSource: row.target_source || row.targetSource || "",
      defaultPurchaseQty: Number(row.default_purchase_qty || row.defaultPurchaseQty || row.purchase_qty || row.purchaseQty || 0),
      days: inventoryDaysFor(row, status, useDemo),
      supplier: row.supplier || meta.supplier || "Bayaan",
      unitCost,
      status,
      location,
      locationKey,
    };
  };
  const warehouseRows = (snapshot.warehouse_stock || []).slice(0, 500).map((row) => makeRow(row, "Central warehouse", "central-warehouse"));
  const kioskRows = (snapshot.kiosk_stock_rows || []).slice(0, 500).map((row) => makeRow(row, row.kiosk || "Kiosk location", row.kiosk || "kiosk"));
  // Recipe/combo products are MADE on demand from these items — they are never stocked,
  // allocated, or purchased — so they do not belong in any stock view (catalog, Stock &
  // Allocation, or Suppliers). Finished resale stock and raw ingredients stay.
  return [...warehouseRows, ...kioskRows].filter((row) => String(row.consumptionMode || "").toLowerCase() !== "recipe");
};

const mapPosOrderRows = (rows) => [...rows].sort((left, right) => (
    String(right.date_order || "").localeCompare(String(left.date_order || ""))
  )).map((order, index) => {
    const firstLine = order.lines?.[0];
    const firstPayment = order.payments?.[0];
    const state = String(order.state || "paid");
    const recipeState = String(order.consumption_state || "");
    const paymentLabel = firstPayment?.provider?.label || firstPayment?.method || "unpaid";
    const paymentMethod = String(paymentLabel).toLowerCase() === "cash" ? "cash" : String(paymentLabel);
    return {
      id: order.name || `POS-${index + 1}`,
      time: String(order.date_order || "").slice(11, 19) || "--:--",
      date: String(order.date_order || "").slice(0, 10),
      kioskId: order.kiosk || order.pos_config || `K-${index + 1}`,
      kiosk: order.kiosk || order.pos_config || "POS kiosk",
      cashier: order.cashier || "Cashier",
      product: cleanDisplayName(firstLine?.product) || `${order.lines?.length || 0} lines`,
      qty: Number(firstLine?.qty || 1),
      payment: paymentMethod,
      amount: Number(order.amount_total || 0),
      status: state,
      recipe: recipeState === "posted" ? "posted" : recipeState || "held",
      sync: "live",
    };
  });

const odooPosOrderRows = (bootstrap) => {
  const snapshot = unwrapOdoo(bootstrap);
  const rows = snapshot?.today?.orders || [];
  if (!rows.length) return canUseDemoFallback(bootstrap) ? MOCK.posOrders : [];
  return mapPosOrderRows(rows);
};

const POS_ORDER_FILTERS = ["All", "Needs action", "Recipe held", "Unpaid", "Returns"];
const POS_ORDER_PAGE_SIZE = 10;

const posOrderTimeValue = (time) => {
  const parts = String(time || "").split(":").map((part) => Number(part || 0));
  return (parts[0] || 0) * 3600 + (parts[1] || 0) * 60 + (parts[2] || 0);
};

const posPaymentStatus = (order) => {
  const status = String(order.status || "").toLowerCase();
  const payment = String(order.payment || "").toLowerCase();
  if (status.includes("refund")) return "Refunded";
  if (payment.includes("unpaid") || payment.includes("pending") || Number(order.amount || 0) <= 0) return "Pending";
  return "Paid";
};

// Recipe states that mean the variance-loop deduction did NOT post cleanly — these must
// never read as "Fulfilled"/"all posted" or the manager loses sight of the exact failure
// the product is pitched on.
const POS_RECIPE_UNPOSTED = ["held", "missing_recipe", "failed"];

const posFulfillmentStatus = (order) => {
  const status = String(order.status || "").toLowerCase();
  if (status.includes("refund") || status.includes("void")) return "Returned";
  if (POS_RECIPE_UNPOSTED.includes(order.recipe) || order.sync !== "live") return "Unfulfilled";
  return "Fulfilled";
};

const posOrderMatchesFilter = (row, filter) => {
  if (filter === "Needs action") return row.paymentStatus !== "Paid" || row.fulfillmentStatus !== "Fulfilled";
  if (filter === "Recipe held") return POS_RECIPE_UNPOSTED.includes(row.recipe);
  if (filter === "Unpaid") return row.paymentStatus === "Pending";
  if (filter === "Returns") return row.paymentStatus === "Refunded" || row.fulfillmentStatus === "Returned";
  return true;
};

function PosStatusBadge({ children, tone = "default" }) {
  const className = tone === "pos"
    ? "badge badge-pos ecommerce-order-badge"
    : tone === "crit"
      ? "badge badge-crit ecommerce-order-badge"
      : tone === "warn"
        ? "badge badge-warn ecommerce-order-badge"
        : "badge ecommerce-order-badge";
  return (
    <span className={className}>
      <span className="ecommerce-order-badge-dot" />
      {children}
    </span>
  );
}

function RecentPosOrdersTable({
  orders,
  kioskOptions,
  paymentOptions,
  kioskFilter,
  setKioskFilter,
  paymentFilter,
  setPaymentFilter,
  ar,
  sourceDriven = false,
}) {
  const lang = ar ? "ar" : "en";
  const [statusFilter, setStatusFilter] = useState("All");
  const [sortDirection, setSortDirection] = useState("desc");
  const [pageIndex, setPageIndex] = useState(0);
  const [selected, setSelected] = useState({});
  const tableRows = useMemo(() => orders.map((order) => ({
    ...order,
    paymentStatus: posPaymentStatus(order),
    fulfillmentStatus: posFulfillmentStatus(order),
    items: `${arTerm(lang, order.product || "POS item")}${Number(order.qty || 0) > 1 ? ` x${order.qty}` : ""}`,
    customer: `${arTerm(lang, order.kiosk || "Kiosk")} / ${arTerm(lang, order.cashier || "Cashier")}`,
    totalLabel: fmtMoney(Number(order.amount || 0)),
    dateLabel: sourceDriven && order.date
      ? `${order.time || "--:--"} - ${order.date}`
      : ar ? `${order.time || "--:--"} - 9 مايو 2026` : `${order.time || "--:--"} - May 9, 2026`,
    sortValue: posOrderTimeValue(order.time),
  })), [orders, sourceDriven]);
  const filteredRows = useMemo(
    () => tableRows.filter((row) => posOrderMatchesFilter(row, statusFilter)),
    [tableRows, statusFilter],
  );
  const sortedRows = useMemo(() => [...filteredRows].sort((left, right) => (
    sortDirection === "asc" ? left.sortValue - right.sortValue : right.sortValue - left.sortValue
  )), [filteredRows, sortDirection]);
  const pageCount = Math.max(1, Math.ceil(sortedRows.length / POS_ORDER_PAGE_SIZE));
  const currentPage = Math.min(pageIndex, pageCount - 1);
  const visibleRows = sortedRows.slice(currentPage * POS_ORDER_PAGE_SIZE, (currentPage + 1) * POS_ORDER_PAGE_SIZE);
  const selectedCount = sortedRows.filter((row) => selected[row.id]).length;
  const allPageSelected = visibleRows.length > 0 && visibleRows.every((row) => selected[row.id]);
  const somePageSelected = visibleRows.some((row) => selected[row.id]);
  const orderCountDescription = selectedCount > 0
    ? (ar ? `${selectedCount} محدد` : `${selectedCount} ${selectedCount === 1 ? "order" : "orders"} selected`)
    : (ar ? `${filteredRows.length.toLocaleString("en")} طلبات` : `${filteredRows.length.toLocaleString("en")} ${statusFilter === "All" ? "orders" : statusFilter.toLowerCase() + " orders"}`);
  const pageNumbers = useMemo(() => {
    if (pageCount <= 3) return Array.from({ length: pageCount }, (_, index) => index + 1);
    const page = currentPage + 1;
    if (page <= 2) return [1, 2, 3];
    if (page >= pageCount - 1) return [pageCount - 2, pageCount - 1, pageCount];
    return [page - 1, page, page + 1];
  }, [currentPage, pageCount]);

  useEffect(() => {
    setPageIndex(0);
  }, [statusFilter, kioskFilter, paymentFilter, sortDirection, orders.length]);

  const toggleAllPageRows = (checked) => {
    setSelected((current) => {
      const next = { ...current };
      visibleRows.forEach((row) => {
        if (checked) next[row.id] = true;
        else delete next[row.id];
      });
      return next;
    });
  };

  const toggleRow = (rowId, checked) => {
    setSelected((current) => {
      const next = { ...current };
      if (checked) next[rowId] = true;
      else delete next[rowId];
      return next;
    });
  };

  return (
    <div className="card ecommerce-orders-card">
      <div className="ecommerce-orders-header">
        <div>
          <div className="ecommerce-orders-title">
            {sourceDriven ? (ar ? "طلبات POS من المصدر" : "Source POS orders") : (ar ? "طلبات POS تجريبية" : "Demo POS orders")}
          </div>
          <div className="ecommerce-orders-description">{orderCountDescription}</div>
        </div>
        <div className="ecommerce-orders-actions">
          <button aria-label={ar ? "فتح الطلبات" : "Open orders"} className="ecommerce-icon-button" type="button">
            <Icon name="chevRight" size={14} />
          </button>
          <button aria-label={ar ? "تنزيل الطلبات" : "Download orders"} className="ecommerce-icon-button" type="button">
            <Icon name="download" size={14} />
          </button>
          <button aria-label={ar ? "إجراءات طلب إضافية" : "More order actions"} className="ecommerce-icon-button" type="button">
            <Icon name="dots" size={14} />
          </button>
        </div>
      </div>

      <div className="ecommerce-orders-controls">
        <div className="ecommerce-toggle-group" role="tablist" aria-label={ar ? "حالة الطلب" : "Order status"}>
          {POS_ORDER_FILTERS.map((filter) => (
            <button
              aria-selected={statusFilter === filter}
              className={statusFilter === filter ? "on" : ""}
              key={filter}
              onClick={() => setStatusFilter(filter)}
              role="tab"
              type="button"
            >
              {arTerm(lang, filter)}
            </button>
          ))}
        </div>
        <div className="ecommerce-orders-filter-row">
          <select className="input ecommerce-orders-select" value={kioskFilter} onChange={(event) => setKioskFilter(event.target.value)}>
            {kioskOptions.map((kiosk) => <option key={kiosk} value={kiosk}>{kiosk === "all" ? (ar ? "كل الأكشاك" : "All kiosks") : arTerm(lang, kiosk)}</option>)}
          </select>
          <select className="input ecommerce-orders-select" value={paymentFilter} onChange={(event) => setPaymentFilter(event.target.value)}>
            {paymentOptions.map((payment) => <option key={payment} value={payment}>{payment === "all" ? (ar ? "كل طرق الدفع" : "All payments") : arTerm(lang, payment)}</option>)}
          </select>
          <button
            aria-label={ar ? "ترتيب الطلبات حسب الوقت" : "Sort orders by time"}
            className="ecommerce-icon-button"
            onClick={() => setSortDirection((direction) => direction === "asc" ? "desc" : "asc")}
            type="button"
          >
            <Icon name={sortDirection === "asc" ? "chevUp" : "chevDown"} size={14} />
          </button>
        </div>
      </div>

      <div className="ecommerce-orders-table-wrap">
        <table className="ecommerce-orders-table">
          <thead>
            <tr>
              <th scope="col" className="ecommerce-orders-select-col">
                <input
                  aria-label={ar ? "تحديد كل الطلبات" : "Select all orders"}
                  checked={allPageSelected}
                  ref={(node) => {
                    if (node) node.indeterminate = !allPageSelected && somePageSelected;
                  }}
                  type="checkbox"
                  onChange={(event) => toggleAllPageRows(event.target.checked)}
                />
              </th>
              <th scope="col">{ar ? "الطلب" : "Order"}</th>
              <th scope="col">{ar ? "الكشك / الكاشير" : "Kiosk / cashier"}</th>
              <th scope="col">{ar ? "الحالة" : "Status"}</th>
              <th scope="col">{ar ? "الإجمالي" : "Total"}</th>
              <th scope="col">{ar ? "الوقت" : "Date"}</th>
              <th scope="col" style={{ textAlign: "end" }}>{ar ? "إجراءات" : "Actions"}</th>
            </tr>
          </thead>
          <tbody>
            {visibleRows.length ? visibleRows.map((row) => {
              const paymentTone = row.paymentStatus === "Paid" ? "pos" : row.paymentStatus === "Refunded" ? "crit" : "warn";
              const fulfillmentTone = row.fulfillmentStatus === "Fulfilled" ? "pos" : "crit";
              return (
                <tr key={row.id} data-state={selected[row.id] ? "selected" : undefined}>
                  <td className="ecommerce-orders-select-col">
                    <input
                      aria-label={ar ? `تحديد الطلب ${row.id}` : `Select order ${row.id}`}
                      checked={Boolean(selected[row.id])}
                      type="checkbox"
                      onChange={(event) => toggleRow(row.id, event.target.checked)}
                    />
                  </td>
                  <td>
                    <div className="ecommerce-order-primary">{row.id}</div>
                    <div className="ecommerce-order-muted">{row.items}</div>
                    <div className="ecommerce-order-muted">{arTerm(lang, row.payment)}</div>
                  </td>
                  <td>
                    <div>{arTerm(lang, row.kiosk)}</div>
                    <div className="ecommerce-order-muted">{arTerm(lang, row.cashier)} - {row.kioskId}</div>
                  </td>
                  <td>
                    <div className="ecommerce-order-statuses">
                      <PosStatusBadge tone={paymentTone}>{arTerm(lang, row.paymentStatus)}</PosStatusBadge>
                      <PosStatusBadge tone={fulfillmentTone}>{arTerm(lang, row.fulfillmentStatus)}</PosStatusBadge>
                    </div>
                  </td>
                  <td className="t-num">{row.totalLabel}</td>
                  <td className="ecommerce-order-muted">{row.dateLabel}</td>
                  <td>
                    <details className="ecommerce-order-actions-menu">
                      <summary aria-label={ar ? "فتح إجراءات الطلب" : "Open order actions"}>
                        <Icon name="dots" size={14} />
                      </summary>
                      <div className="ecommerce-order-menu">
                        <button type="button">{ar ? "عرض الطلب" : "View order"}</button>
                        <button type="button">{ar ? "نسخ رقم الطلب" : "Copy order ID"}</button>
                        <button type="button">{ar ? "مراجعة الوصفة" : "Review recipe"}</button>
                      </div>
                    </details>
                  </td>
                </tr>
              );
            }) : (
              <tr>
                <td className="ecommerce-orders-empty" colSpan={7}>{ar ? "لا توجد طلبات." : "No orders found."}</td>
              </tr>
            )}
          </tbody>
        </table>
      </div>

      <div className="ecommerce-orders-footer">
        <p>{ar ? `عرض ${visibleRows.length} من ${filteredRows.length.toLocaleString("en")} طلبات` : `Viewing ${visibleRows.length} out of ${filteredRows.length.toLocaleString("en")} orders`}</p>
        <div className="ecommerce-pagination">
          <button disabled={currentPage === 0} onClick={() => setPageIndex((page) => Math.max(0, page - 1))} type="button">
            {ar ? "السابق" : "Previous"}
          </button>
          {pageNumbers[0] > 1 && <span className="ecommerce-pagination-ellipsis">...</span>}
          {pageNumbers.map((pageNumber) => (
            <button
              className={currentPage === pageNumber - 1 ? "on" : ""}
              key={pageNumber}
              onClick={() => setPageIndex(pageNumber - 1)}
              type="button"
            >
              {pageNumber}
            </button>
          ))}
          {pageNumbers[pageNumbers.length - 1] < pageCount && <span className="ecommerce-pagination-ellipsis">...</span>}
          <button disabled={currentPage >= pageCount - 1} onClick={() => setPageIndex((page) => Math.min(pageCount - 1, page + 1))} type="button">
            {ar ? "التالي" : "Next"}
          </button>
        </div>
      </div>
    </div>
  );
}

const closeInvestigationStatus = (close) => {
  if (close.status === "approved") return "Approved";
  if (close.status === "open") return "Waiting for count";
  if (close.status === "issue") return "Investigation open";
  if (close.status === "pending") return "Manager review";
  return "Ready for approval";
};

const odooClosingRows = (bootstrap) => {
  const snapshot = unwrapOdoo(bootstrap);
  const rows = snapshot?.closings?.length
    ? snapshot.closings
    : canUseDemoFallback(bootstrap)
      ? MOCK.closings
      : [];
  return rows.map((row) => {
    const expectedCash = Number(row.expectedCash ?? row.expected_cash ?? 0);
    const countedCash = row.countedCash ?? row.actualCash ?? row.actual_cash;
    const cashVariance = row.cashVariance ?? row.cash_variance
      ?? (countedCash == null ? null : Number(countedCash || 0) - expectedCash);
    return {
      ...row,
      city: row.city || row.area || "",
      sales: Number(row.sales ?? row.revenue ?? row.totalSales ?? row.amount_total ?? 0),
      expectedCash,
      countedCash: countedCash == null ? null : Number(countedCash || 0),
      cashVariance,
      digitalPayments: Number(row.digitalPayments ?? row.digital_payments ?? 0),
      stock: (row.stock || []).map((line) => ({
        ...line,
        item: cleanDisplayName(line.item),
        unit: line.unit || line.uom || "",
        expected: Number(line.expected ?? line.expected_qty ?? 0),
        actual: Number(line.actual ?? line.actual_qty ?? 0),
        variance: Number(line.variance ?? 0),
        value: Number(line.value ?? line.varianceValue ?? line.variance_value ?? 0),
      })),
      // Server-computed variance-loop inputs for this close's own window
      // (opening + received - consumed - waste = expected). See
      // _serialize_shift_close; never re-derive these from today's snapshot.
      varianceInputs: (row.varianceInputs || []).map((line) => ({
        item: cleanDisplayName(line.item),
        unit: line.unit || "",
        opening: Number(line.opening || 0),
        received: Number(line.received || 0),
        consumed: Number(line.consumed || 0),
        waste: Number(line.waste || 0),
        expected: Number(line.expected || 0),
        actual: Number(line.actual || 0),
        variance: Number(line.variance || 0),
        value: Number(line.value || 0),
      })),
      investigationStatus: row.investigationStatus || closeInvestigationStatus(row),
      notes: row.notes || (row.status === "approved" ? "No exceptions." : "Awaiting manager note."),
      recipePostingIssues: Number(row.recipePostingIssues || 0),
      recipePostingIssueOrders: row.recipePostingIssueOrders || [],
    };
  });
};

const odooKioskStockReconciliationRows = (bootstrap, kiosk, { live = false } = {}) => {
  const snapshot = unwrapOdoo(bootstrap);
  const base = snapshot || (canUseDemoFallback(bootstrap) ? MOCK : {});

  const consumptionRows = (base.today?.consumption || []).filter((row) => matchesKiosk(row.kiosk, kiosk));
  const wasteRows = (base.today?.waste || []).filter((row) => matchesKiosk(row.kiosk, kiosk));
  const orderRows = (base.today?.orders || []).filter((row) => matchesKiosk(row.kiosk, kiosk));
  const closing = (base.closings || []).find((row) => matchesKiosk(row.kioskId || row.kioskName, kiosk));
  const consumedFor = (item) => consumptionRows
    .filter((row) => matchesItem(row.ingredient || row.item || row.item_code, item))
    .reduce((sum, row) => sum + Number(row.qty || 0), 0);
  const wastedFor = (item) => wasteRows
    .filter((row) => matchesItem(row.product || row.ingredient || row.item || row.item_code, item))
    .reduce((sum, row) => sum + Number(row.qty || 0), 0);
  // Finished/hybrid goods (e.g. a cheesecake bought whole) decrement their OWN stock on sale and
  // never write recipe-ingredient consumption, so their "used today" = units sold, not ledger rows.
  const finishedProducts = (base.products || []).filter((p) => ["finished", "hybrid"].includes(p.consumption_mode));
  const finishedSoldFor = (item) => {
    if (!finishedProducts.some((p) => matchesItem(item, p.default_code) || matchesItem(item, p.name))) return 0;
    return orderRows.reduce((sum, o) => sum + (o.lines || [])
      .filter((ln) => matchesItem(ln.product, item))
      .reduce((s, ln) => s + Number(ln.qty || 0), 0), 0);
  };
  const statusFor = (variance, actual) => {
    if (Math.abs(Number(variance || 0)) >= 1 || Number(actual || 0) <= 0) return "issue";
    if (Math.abs(Number(variance || 0)) > 0 || Number(actual || 0) <= 5) return "watch";
    return "ok";
  };
  const detailMap = base.kioskStockDetails || base.kiosk_stock_details || null;
  let detailRows = null;
  if (detailMap && typeof detailMap === "object") {
    const matchKey = Object.keys(detailMap).find((key) => matchesKiosk(key, kiosk));
    detailRows = matchKey ? detailMap[matchKey] : null;
  }

  if (!live && closing?.stock?.length) {
    return closing.stock.map((line) => {
      const detail = Array.isArray(detailRows)
        ? detailRows.find((row) => matchesItem(row.item || row.name || row.product, line.item))
        : null;
      const consumed = detail ? Number(detail.consumed || 0) : consumedFor(line.item);
      const waste = detail ? Number(detail.waste || 0) : wastedFor(line.item);
      const received = detail ? Number(detail.received || 0) : 0;
      const expected = Number(line.expected || detail?.expected || 0);
      const actual = Number(line.actual || 0);
      const variance = Number(line.variance || actual - expected || 0);
      return {
        item: detail?.name || cleanDisplayName(line.item),
        unit: line.unit || detail?.unit || detail?.uom || "u",
        opening: detail ? Number(detail.opening || 0) : Math.max(0, expected - received + consumed + waste),
        received,
        consumed,
        waste,
        expected,
        actual,
        variance,
        status: statusFor(variance, actual),
      };
    });
  }

  if (!live && Array.isArray(detailRows) && detailRows.length) {
    return detailRows.slice(0, 12).map((row) => ({
        item: row.item || "Stock item",
        unit: row.unit || row.uom || "u",
        opening: Number(row.opening || 0),
        received: Number(row.received || 0),
        consumed: Number(row.consumed || 0),
        waste: Number(row.waste || 0),
        expected: Number(row.expected || row.expected_qty || 0),
        actual: Number(row.actual || row.actual_qty || 0),
        variance: Number(row.variance || 0),
        status: row.status || "ok",
    }));
  }

  const stockRows = (base.kiosk_stock_rows || [])
    .filter((row) => matchesKiosk(row.kiosk, kiosk));
  if (!stockRows.length) return null;
  const nameByCode = new Map((base.products || []).map((p) => [String(p.default_code || "").toUpperCase(), cleanDisplayName(p.name || p.default_code || "")]));

  return stockRows.slice(0, 12).map((row) => {
    const code = String(row.item || "");
    const item = nameByCode.get(code.toUpperCase()) || cleanDisplayName(code) || "Stock item";
    // "Used today" = recipe-ingredient consumption + finished-good units sold (so a finished item
    // like a cheesecake bought whole is counted, not shown as 0).
    const consumed = consumedFor(code) + finishedSoldFor(code);
    const waste = wastedFor(code);
    const actual = Number(row.actual_qty || 0);
    return {
      item,
      unit: row.uom || "u",
      opening: actual + consumed + waste,
      received: 0,
      consumed,
      waste,
      expected: actual,
      actual,
      variance: 0,
      status: row.stock_status || statusFor(0, actual),
      stockPercent: Number(row.stock_percent || 0),
    };
  });
};

const movementTimeLabel = (value) => auditTimeLabel(value) || "--:--";
const movementSortValue = (value) => {
  const date = new Date(value || "");
  return Number.isNaN(date.getTime()) ? 0 : date.getTime();
};
const movementQtyLabel = (qty, uom) => {
  const value = Number(qty || 0).toLocaleString("en", { maximumFractionDigits: 2 });
  return uom ? `${value} ${uom}` : value;
};
const movementLineSummary = (lines = []) => {
  const visible = lines.slice(0, 3).map((line) => {
    const qty = Number(line.doneQty || line.qty || 0).toLocaleString("en", { maximumFractionDigits: 2 });
    return `${cleanDisplayName(line.product || "Item")} x ${qty}${line.uom ? ` ${line.uom}` : ""}`;
  });
  if (lines.length > 3) visible.push(`+${lines.length - 3} more`);
  return visible.join(", ");
};
const transferMovementAction = (transfer, selectedKiosk) => {
  const status = String(transfer.bayaan_state || transfer.bayaanState || transfer.state || "draft").toLowerCase();
  const incoming = matchesKiosk(transfer.toKioskId || transfer.to || transfer.location_dest, selectedKiosk);
  if (incoming && ["received", "done", "completed"].includes(status)) return "Transfer received";
  if (incoming && status === "dispatched") return "Transfer expected";
  if (incoming) return `Transfer ${status}`;
  if (["received", "done", "completed"].includes(status)) return "Transfer completed";
  if (status === "dispatched") return "Transfer dispatched";
  return `Transfer ${status}`;
};
const odooKioskStockMovementRows = (bootstrap, kiosk) => {
  const snapshot = unwrapOdoo(bootstrap);
  if (!snapshot) return [];
  const rows = [];
  const addRow = (row) => {
    const at = row.at || "";
    rows.push({
      id: row.id || `${row.source}-${row.action}-${at}-${rows.length}`,
      time: movementTimeLabel(at),
      sortAt: movementSortValue(at),
      ...row,
    });
  };

  (snapshot.closings || [])
    .filter((close) => matchesKiosk(close.kioskId || close.kioskName, kiosk))
    .forEach((close) => {
      const lineCount = close.stock?.length || close.ingredientVariance?.length || 0;
      if (close.openedAt) {
        addRow({
          id: `${close.name || close.id}-opening`,
          at: close.openedAt,
          action: "Opening stock baseline",
          detail: `${lineCount || "Shift"} stock lines opened by ${close.cashier || "cashier"}`,
          source: "bayaan.shift.close",
        });
      }
      if (close.closedAt) {
        addRow({
          id: `${close.name || close.id}-closing`,
          at: close.closedAt,
          action: "Closing stock count",
          detail: `${lineCount || "Shift"} stock lines counted - ${close.status || "pending"}`,
          source: "bayaan.shift.close",
        });
      }
    });

  (snapshot.transfers || [])
    .filter((transfer) => (
      matchesKiosk(transfer.toKioskId || transfer.to || transfer.location_dest, kiosk)
      || matchesKiosk(transfer.from || transfer.location_src, kiosk)
    ))
    .forEach((transfer) => {
      const lines = movementLineSummary(transfer.lines || []);
      addRow({
        id: transfer.name || `transfer-${transfer.id}`,
        at: transfer.doneAt || transfer.scheduledAt || transfer.createdAt,
        action: transferMovementAction(transfer, kiosk),
        detail: `${transfer.name ? `${transfer.name} - ` : ""}${transfer.from || "Warehouse"} -> ${transfer.toKioskId || transfer.to || "Kiosk"}${lines ? ` - ${lines}` : ""}`,
        source: "stock.picking",
      });
    });

  (snapshot.today?.consumption || [])
    .filter((line) => matchesKiosk(line.kiosk, kiosk))
    .forEach((line, index) => {
      const ingredient = cleanDisplayName(line.ingredient || "Ingredient");
      const product = cleanDisplayName(line.sold_product || line.product || "POS sale");
      const order = line.order ? ` (${line.order})` : "";
      addRow({
        id: `consumption-${line.id || index}`,
        at: line.consumed_at || line.create_date,
        action: "Recipe deduction",
        detail: `${movementQtyLabel(line.qty, line.uom)} ${ingredient} for ${product}${order}`,
        source: "bayaan.consumption.ledger",
      });
    });

  (snapshot.today?.waste || [])
    .filter((entry) => matchesKiosk(entry.kiosk, kiosk))
    .forEach((entry, index) => {
      addRow({
        id: `waste-${entry.id || index}`,
        at: entry.create_date,
        action: "Waste recorded",
        detail: `${movementQtyLabel(entry.qty, entry.uom)} ${cleanDisplayName(entry.product || "Waste item")} - ${entry.reason || entry.state || "recorded"}`,
        source: "bayaan.waste.entry",
      });
    });

  return rows
    .sort((a, b) => b.sortAt - a.sortAt)
    .slice(0, 80);
};

const odooPosSessionRows = (bootstrap, kiosk = null) => {
  const snapshot = unwrapOdoo(bootstrap);
  if (!snapshot) return [];
  const rows = snapshot.today?.sessions || snapshot.sessions || snapshot.posSessions || snapshot.pos_sessions || [];
  return rows
    .filter((session) => !kiosk || matchesKiosk(session.kiosk || session.kioskName || session.kiosk_id || session.pos_config, kiosk))
    .map((session, index) => ({
      id: session.id || session.name || `session-${index + 1}`,
      name: session.name || session.session || `Session ${index + 1}`,
      kiosk: session.kiosk || session.kioskName || session.kiosk_id || session.pos_config || "-",
      open: session.open || session.openedAt || session.start_at || session.startAt || session.start || "",
      close: session.close || session.closedAt || session.stop_at || session.stopAt || session.stop || "",
      cashier: session.cashier || session.user || session.openedBy || "-",
      orders: Number(session.orders || session.orderCount || session.order_count || 0),
      revenue: Number(session.revenue || session.amount_total || session.sales || 0),
      status: String(session.status || session.state || "open"),
    }));
};

const PAYMENT_GATEWAY_PROVIDERS = [
  { id: "cash", label: "Cash", category: "cash", kind: "cash_drawer", settlement: "drawer_count", aliases: ["cash"] },
  { id: "bank_card", label: "Bank card terminal", category: "card", kind: "card_terminal", settlement: "bank_batch", aliases: ["card", "visa", "mastercard", "master card", "terminal", "pos terminal"] },
  { id: "generic_qr", label: "Generic QR", category: "qr", kind: "qr", settlement: "gateway_batch", aliases: ["qr", "qr code", "qrcode"] },
  { id: "zain_cash", label: "Zain Cash", category: "mobile_wallet", kind: "wallet", settlement: "gateway_batch", aliases: ["zain cash", "zaincash", "zain wallet", "zain"] },
  { id: "fib", label: "FIB", category: "bank_app", kind: "bank_app", settlement: "gateway_batch", aliases: ["fib", "first iraqi bank", "first iraqi", "fib pay", "fib qr"] },
  { id: "qi_card", label: "Qi Card / SuperQi", category: "card", kind: "card_wallet", settlement: "bank_batch", aliases: ["qi card", "qicard", "superqi", "super qi", "qi"] },
  { id: "nass_wallet", label: "NassWallet / NASS Pay", category: "mobile_wallet", kind: "wallet", settlement: "gateway_batch", aliases: ["nasswallet", "nass wallet", "nasspay", "nass pay", "nass"] },
  { id: "fastpay", label: "FastPay", category: "mobile_wallet", kind: "wallet_qr", settlement: "gateway_batch", aliases: ["fastpay", "fast pay"] },
  { id: "asia_hawala", label: "AsiaHawala", category: "mobile_wallet", kind: "wallet", settlement: "gateway_batch", aliases: ["asiahawala", "asia hawala", "asiacell hawala", "asia wallet"] },
  { id: "manual_bank_transfer", label: "Manual bank transfer", category: "manual_digital", kind: "manual_transfer", settlement: "manager_verified", aliases: ["manual digital", "manual bank", "bank transfer", "transfer", "bank deposit"] },
  { id: "other_digital", label: "Other digital", category: "digital_other", kind: "other_digital", settlement: "gateway_batch", aliases: ["digital", "online", "e-payment", "epayment"] },
];

const PAYMENT_GATEWAY_BY_ID = Object.fromEntries(PAYMENT_GATEWAY_PROVIDERS.map((provider) => [provider.id, provider]));
const PAYMENT_GATEWAY_ALIAS_ROWS = PAYMENT_GATEWAY_PROVIDERS
  .flatMap((provider) => provider.aliases.map((alias) => [alias.replace(/[^a-z0-9]+/gi, "").toLowerCase(), provider]))
  .sort(([a], [b]) => b.length - a.length);

const createPaymentSplit = () => ({
  cash: 0,
  card: 0,
  qr: 0,
  mobile_wallet: 0,
  bank_app: 0,
  manual_digital: 0,
  digital_other: 0,
  digital: 0,
  total: 0,
  _byMethod: {},
  _byProvider: {},
});

const normalizePaymentText = (value) => String(value || "").replace(/[^a-z0-9]+/gi, "").toLowerCase();

const classifyPaymentProvider = (methodName, providerValue) => {
  const configuredId = typeof providerValue === "string"
    ? providerValue
    : providerValue?.id || providerValue?.provider;
  if (configuredId && PAYMENT_GATEWAY_BY_ID[configuredId]) return PAYMENT_GATEWAY_BY_ID[configuredId];
  const normalized = normalizePaymentText(methodName);
  if (normalized === "cash") return PAYMENT_GATEWAY_BY_ID.cash;
  const matched = PAYMENT_GATEWAY_ALIAS_ROWS.find(([alias]) => alias && normalized.includes(alias));
  return matched?.[1] || PAYMENT_GATEWAY_BY_ID.other_digital;
};

const paymentIconForProvider = (provider) => provider.category === "cash" ? "cash" : "card";

const sourcePosPaymentOptions = (bootstrap, kioskId, ar = false) => {
  const snapshot = unwrapOdoo(bootstrap);
  const configs = snapshot?.pos_configs || [];
  const kiosk = (snapshot?.kiosks || []).find((row) => matchesKiosk(row.kiosk_code || row.id || row.name, { id: kioskId, kiosk_code: kioskId }));
  const configId = kiosk?.pos_config_id || kiosk?.posConfigId;
  const configName = kiosk?.pos_config || kiosk?.posConfig;
  const config = configs.find((row) => (
    (configId && String(row.id) === String(configId))
    || (configName && row.name === configName)
  )) || (configs.length === 1 ? configs[0] : null);
  return (config?.payment_methods || [])
    .map((method) => {
      const provider = classifyPaymentProvider(method.name, method.provider);
      const label = method.name || provider.label;
      const providerLabel = method.provider?.label || provider.label;
      return {
        id: label,
        icon: paymentIconForProvider(provider),
        label,
        sub: ar ? `${providerLabel} · طريقة POS مهيأة` : `${providerLabel} · configured POS method`,
        category: provider.category,
        provider: provider.id,
      };
    })
    .filter((option) => option.id);
};

const addPaymentToSplit = (split, methodName, amountValue, providerValue) => {
  const amount = Number(amountValue || 0);
  const provider = classifyPaymentProvider(methodName, providerValue);
  const category = split[provider.category] == null ? "digital_other" : provider.category;
  const method = String(methodName || provider.label);
  split[category] += amount;
  if (category !== "cash") split.digital += amount;
  split.total += amount;
  split._byMethod[method] = split._byMethod[method] || {
    method,
    category,
    provider: provider.id,
    providerLabel: provider.label,
    amount: 0,
  };
  split._byMethod[method].amount += amount;
  split._byProvider[provider.id] = split._byProvider[provider.id] || {
    provider: provider.id,
    label: provider.label,
    category,
    kind: provider.kind,
    settlement: provider.settlement,
    amount: 0,
  };
  split._byProvider[provider.id].amount += amount;
};

const finalizePaymentSplit = (split) => {
  const byMethod = Object.values(split._byMethod || {}).sort((a, b) => b.amount - a.amount || a.method.localeCompare(b.method));
  const byProvider = Object.values(split._byProvider || {}).sort((a, b) => b.amount - a.amount || a.label.localeCompare(b.label));
  const { _byMethod, _byProvider, ...publicSplit } = split;
  return { ...publicSplit, by_method: byMethod, by_provider: byProvider };
};

const normalizePaymentSplit = (payments) => {
  const { _byMethod, _byProvider, ...base } = createPaymentSplit();
  return {
    ...base,
    ...(payments || {}),
    bank_app: Number(payments?.bank_app || 0),
    by_method: payments?.by_method || [],
    by_provider: payments?.by_provider || [],
  };
};

const demoPaymentSplit = () => {
  const split = createPaymentSplit();
  [
    ["Cash", 718_000, "cash"],
    ["Bank card terminal", 213_000, "bank_card"],
    ["Qi Card", 45_000, "qi_card"],
    ["Generic QR", 92_000, "generic_qr"],
    ["Zain Cash", 52_000, "zain_cash"],
    ["FIB", 84_000, "fib"],
    ["NassWallet", 28_000, "nass_wallet"],
    ["FastPay", 24_000, "fastpay"],
    ["Manual bank transfer", 28_000, "manual_bank_transfer"],
  ].forEach(([method, amount, provider]) => addPaymentToSplit(split, method, amount, provider));
  return finalizePaymentSplit(split);
};

const paymentCategoryLabel = (category) => ({
  cash: "Cash",
  card: "Card",
  qr: "QR",
  mobile_wallet: "Wallet",
  bank_app: "Bank app",
  manual_digital: "Manual",
  digital_other: "Other",
}[category] || "Digital");

const paymentGatewayRows = (payments, includeCatalog = true) => {
  const byProvider = new Map(includeCatalog
    ? PAYMENT_GATEWAY_PROVIDERS.map((provider) => [
      provider.id,
      { ...provider, provider: provider.id, amount: 0 },
    ])
    : []);
  (payments?.by_provider || []).forEach((row) => {
    const providerId = row.provider || row.id;
    if (!providerId) return;
    const provider = byProvider.get(providerId) || PAYMENT_GATEWAY_BY_ID[providerId] || {
      id: providerId,
      provider: providerId,
      label: row.label || providerId,
      category: row.category || "digital_other",
      settlement: row.settlement || "gateway_batch",
    };
    byProvider.set(providerId, {
      ...provider,
      provider: providerId,
      label: row.label || provider.label,
      category: row.category || provider.category,
      settlement: row.settlement || provider.settlement,
      amount: Number(row.amount || 0),
    });
  });
  const preferredOrder = [
    "zain_cash",
    "fib",
    "qi_card",
    "nass_wallet",
    "fastpay",
    "asia_hawala",
    "bank_card",
    "generic_qr",
    "manual_bank_transfer",
    "other_digital",
  ];
  return [
    ...preferredOrder.map((id) => byProvider.get(id)).filter(Boolean),
    ...Array.from(byProvider.values()).filter((row) => !preferredOrder.includes(row.provider || row.id)),
  ];
};

const odooPaymentSplit = (bootstrap) => {
  const snapshot = unwrapOdoo(bootstrap);
  const summaryPayments = snapshot?.summary?.payments;
  if (summaryPayments) return normalizePaymentSplit(summaryPayments);
  const payments = snapshot?.today?.payments || [];
  if (!payments.length) return null;
  const split = createPaymentSplit();
  payments.forEach((payment) => addPaymentToSplit(split, payment.method, payment.amount, payment.provider));
  return finalizePaymentSplit(split);
};

const odooTransferRows = (bootstrap) => {
  const snapshot = unwrapOdoo(bootstrap);
  const rows = snapshot?.transfers || [];
  if (!rows.length) return canUseDemoFallback(bootstrap) ? MOCK.pendingTransfers : [];
  return rows.map((transfer) => ({
    id: transfer.name || `PICK-${transfer.id}`,
    from: transfer.from || "Central Warehouse",
    to: transfer.toKioskId || transfer.to || "Kiosk",
    toKioskId: transfer.toKioskId || transfer.to_kiosk_id || transfer.kiosk || "",
    items: transfer.lines?.length
      ? transfer.lines.slice(0, 2).map((line) => `${line.product} x ${Number(line.qty || 0).toLocaleString("en", { maximumFractionDigits: 2 })}`).join(", ")
      : `${transfer.items || 0} items`,
    lines: transfer.lines || [],
    eta: transfer.scheduledAt ? String(transfer.scheduledAt).slice(11, 16) : "--:--",
    status: transfer.bayaan_state || transfer.bayaanState || transfer.state || "draft",
    engineState: transfer.state || "draft",
    origin: transfer.origin || "",
    requested: Boolean(transfer.requested) || /^Kiosk stock request/i.test(String(transfer.origin || "")),
  }));
};

const transferQtyValue = (qty) => Number(String(qty ?? 0).replace(/,/g, "").match(/[\d.]+/)?.[0] ?? 0);
const transferQtyUnit = (qty) => String(qty ?? "").replace(/^[\d.,\s]+/, "").trim();
const transferKioskId = (value) => String(value || "").match(/K-\d+/)?.[0] || String(value || "");

const odooTransferSuggestionRows = (bootstrap) => {
  const snapshot = unwrapOdoo(bootstrap);
  const rows = snapshot?.suggested_transfers || [];
  if (!rows.length && !canUseDemoFallback(bootstrap)) return [];
  if (!rows.length) return MOCK.transferSuggestions.map((row) => ({
    ...row,
    kioskId: transferKioskId(row.kiosk),
    itemId: row.item,
    qtyValue: transferQtyValue(row.qty),
    uom: transferQtyUnit(row.qty),
  }));
  return rows.slice(0, 12).map((row) => ({
    kiosk: row.kioskName ? `${row.kiosk} ${row.kioskName}` : row.kiosk || "Kiosk",
    kioskId: row.kiosk || "",
    item: row.item || "Stock item",
    itemId: row.item || "Stock item",
    qty: `${Number(row.qty || 0).toLocaleString("en", { maximumFractionDigits: 2 })} ${row.uom || ""}`.trim(),
    qtyValue: Number(row.qty || 0),
    uom: row.uom || "",
    cover: row.cover || "<1 day",
    reason: row.reason || "below configured reorder target",
    actualQty: Number(row.actual_qty || 0),
    targetQty: Number(row.target_qty || 0),
    reorderQty: Number(row.reorder_qty || 0),
    criticalQty: Number(row.critical_qty || 0),
    stockPercent: Number(row.stock_percent || 0),
  }));
};

const demoRecipeMarginRows = () => ([
  { product: "Orange Juice 350ml", version: "v4 - effective today", ingredients: "Orange 0.35kg, sugar 0.01kg, cup, straw", price: 7_500, cost: 2_180, margin: "70.9%", status: "active" },
  { product: "Iced Spanish", version: "v2 - Apr 22", ingredients: "Espresso, milk, condensed milk, cup, lid", price: 9_000, cost: 3_060, margin: "66.0%", status: "active" },
  { product: "Pistachio Cake", version: "v3 - supplier watch", ingredients: "Cake slice, pistachio paste 12g, plate, fork", price: 11_000, cost: 5_740, margin: "47.8%", status: "watch" },
  { product: "Croissant - Plain", version: "finished SKU", ingredients: "Finished stock move only", price: 4_000, cost: 1_600, margin: "60.0%", status: "finished" },
]);

const odooRecipeMarginRows = (bootstrap) => {
  const snapshot = unwrapOdoo(bootstrap);
  const recipes = snapshot?.recipes || [];
  if (!recipes.length) return canUseDemoFallback(bootstrap) ? demoRecipeMarginRows() : [];
  const products = snapshot?.products || [];
  return recipes.slice(0, 12).map((recipe) => {
    const product = products.find((row) => matchesItem(row.default_code || row.name, recipe.product_code || recipe.product));
    const price = Number(product?.list_price || 0);
    const cost = Number(recipe.estimated_unit_cost || 0);
    const marginPct = price > 0 ? ((price - cost) / price) * 100 : 0;
    return {
      product: recipe.product || "Product",
      version: `${recipe.version || "v1"} - ${recipe.state || "draft"}`,
      ingredients: recipe.lines?.length
        ? recipe.lines.map((line) => `${line.ingredient} ${Number(line.qty || 0).toLocaleString("en", { maximumFractionDigits: 3 })}${line.uom ? ` ${line.uom}` : ""}`).join(", ")
        : "No recipe lines",
      price,
      cost,
      margin: price > 0 ? `${marginPct.toFixed(1)}%` : "-",
      status: recipe.state === "active" ? "active" : "watch",
    };
  });
};

const productCategoryLabel = (category = "", mode = "") => {
  const text = String(category || "").split("/").pop()?.trim();
  if (text && text !== "All") return text;
  if (mode === "recipe") return "Recipe products";
  if (mode === "hybrid") return "Hybrid products";
  if (mode === "finished") return "Finished goods";
  return "Products";
};

const odooProductCatalogRows = (bootstrap) => {
  const snapshot = unwrapOdoo(bootstrap);
  const rows = snapshot?.products || [];
  if (!rows.length) return canUseDemoFallback(bootstrap) ? null : [];
  return rows
    .filter((product) => product.available_in_pos || ["recipe", "finished", "hybrid"].includes(product.consumption_mode))
    .map((product, index) => {
      // POS options are sourced per-product from Odoo (product.pos_options) instead of
      // being hardcoded in the frontend. data.ts category bindings are only a fallback.
      const opts = product.pos_options && typeof product.pos_options === "object" ? product.pos_options : {};
      const posGroups = Array.isArray(opts.modifier_groups) ? opts.modifier_groups : [];
      const posSizes = Array.isArray(opts.sizes) ? opts.sizes.map((s) => String(s).trim()).filter(Boolean) : [];
      const category = productCategoryLabel(product.category, product.consumption_mode);
      return {
        id: product.id || index + 1,
        odooId: product.id,
        code: product.default_code || "",
        category,
        name: cleanDisplayName(product.name || product.default_code || "Product"),
        image: product.image_data_url || slugify(product.default_code || product.name || `product-${product.id || index}`),
        price: Number(product.list_price || 0),
        standardPrice: Number(product.standard_price || 0),
        sizes: posSizes.length ? posSizes : defaultSizesForCategory(category),
        modifierGroups: posGroups,
        consumptionMode: product.consumption_mode || "finished",
        availableInPos: Boolean(product.available_in_pos),
        uom: product.uom || "Units",
      };
    });
};

const odooIngredientOptions = (bootstrap) => {
  const snapshot = unwrapOdoo(bootstrap);
  const rows = snapshot?.products || [];
  if (!rows.length && canUseDemoFallback(bootstrap)) {
    return MOCK.inventory.map((it) => ({ value: it.item, label: it.item, unit: it.unit }));
  }
  return rows
    .filter((product) => !product.available_in_pos || !["recipe", "hybrid"].includes(product.consumption_mode))
    .map((product) => ({
      value: product.default_code || product.name,
      label: cleanDisplayName(product.name || product.default_code),
      unit: product.uom || "Units",
    }))
    .filter((option) => option.value);
};

const odooPosMenu = (bootstrap) => {
  const products = (odooProductCatalogRows(bootstrap) || []).filter((product) => product.availableInPos);
  const groups = new Map();
  products.forEach((product) => {
    const category = product.category || "Products";
    if (!groups.has(category)) groups.set(category, { cat: category, items: [] });
    groups.get(category).items.push({
      id: product.code || product.name,
      name: product.name,
      image: product.image,
      price: product.price,
      sizes: product.sizes?.length ? product.sizes : ["S"],
      // Carry the real category so modifier resolution works on the "All" tab too.
      category,
      modifierGroups: Array.isArray(product.modifierGroups) ? product.modifierGroups : [],
    });
  });
  return Array.from(groups.values()).filter((group) => group.items.length > 0);
};

// ---------- POS option (modifier group) helpers for the product create/edit dialog ----------
const cloneJson = (value) => {
  try { return JSON.parse(JSON.stringify(value ?? null)); } catch { return null; }
};
const optionUid = (prefix = "opt") =>
  `${prefix}-${Math.random().toString(36).slice(2, 8)}`;
// Sensible per-category default option groups (deep-cloned from the static bindings so the
// draft can be edited freely). These are only a STARTING point — saved per product to Odoo.
const defaultModifierGroupsForCategory = (category) =>
  (cloneJson(resolveModifierGroups({ id: "", category: category || "" }, productModifierBindings)) || []);
const defaultSizesForCategory = (category) => {
  const sizeGroup = resolveModifierGroups({ id: "", category: category || "" }, productModifierBindings)
    .find((group) => group.id === "size");
  if (!sizeGroup) return ["S"];
  const sizes = sizeGroup.values
    .map((v) => String(v?.name?.en || v?.id || "").trim().charAt(0).toUpperCase())
    .filter(Boolean);
  return sizes.length ? sizes : ["S"];
};

// Robust POS option resolution — a product must NEVER silently skip its size/options prompt
// regardless of data mode or how the Odoo product is configured:
//   1) per-product options from the source (Odoo product.pos_options.modifier_groups) win;
//   2) else static per-category bindings (data.ts) — matched on the product's own category;
//   3) else synthesize a Size group from the product's sizes, defaulting made-to-order
//      (recipe/hybrid) drinks to S/M/L, so live products with no configured options still prompt.
// Single-size finished goods (e.g. a cake slice) intentionally return [] and add straight to cart.
const POS_SIZE_LABELS = {
  s: { en: "Small", ar: "صغير" }, small: { en: "Small", ar: "صغير" },
  m: { en: "Medium", ar: "وسط" }, medium: { en: "Medium", ar: "وسط" },
  l: { en: "Large", ar: "كبير" }, large: { en: "Large", ar: "كبير" },
  xl: { en: "Extra large", ar: "كبير جدًا" },
};
const posSizeLabel = (s) => POS_SIZE_LABELS[String(s).trim().toLowerCase()] || { en: String(s), ar: String(s) };
const synthSizeGroup = (sizes) => ({
  id: "size",
  name: { en: "Size", ar: "الحجم" },
  selection: "single",
  required: true,
  // No fabricated price/recipe deltas — a synthesized size is a recorded choice only; real
  // per-size pricing/consumption comes from Odoo pos_options when configured.
  values: sizes.map((s, i) => ({ id: `${slugify(String(s)) || "size"}-${i}`, name: posSizeLabel(s), default: i === 0 })),
});
const posModifierGroupsFor = (item, categoryName) => {
  if (Array.isArray(item.modifierGroups) && item.modifierGroups.length) return item.modifierGroups;
  const byCategory = resolveModifierGroups({ id: item.id, category: item.category || categoryName }, productModifierBindings);
  if (byCategory.length) return byCategory;
  let sizes = (Array.isArray(item.sizes) ? item.sizes : []).map((s) => String(s).trim()).filter(Boolean);
  if (sizes.length <= 1 && ["recipe", "hybrid"].includes(item.consumptionMode)) sizes = ["S", "M", "L"];
  if (sizes.length > 1) return [synthSizeGroup(sizes)];
  return [];
};
const emptyModifierGroup = () => ({
  id: optionUid("grp"),
  name: { en: "", ar: "" },
  selection: "single",
  required: false,
  values: [],
});
const emptyModifierValue = () => ({
  id: optionUid("val"),
  name: { en: "", ar: "" },
  priceDelta: 0,
  recipeFactor: 1,
});
// Strip empty groups/values and mirror en->ar so the saved payload is clean.
const sanitizeModifierGroups = (groups) =>
  (Array.isArray(groups) ? groups : [])
    .map((group) => {
      const en = String(group?.name?.en || "").trim();
      if (!en) return null;
      const values = (group.values || [])
        .map((value) => {
          const ven = String(value?.name?.en || "").trim();
          if (!ven) return null;
          const out = {
            id: value.id || optionUid("val"),
            name: { en: ven, ar: String(value?.name?.ar || "").trim() || ven },
          };
          if (Number.isFinite(Number(value.priceDelta)) && Number(value.priceDelta) !== 0) out.priceDelta = Math.round(Number(value.priceDelta));
          if (Number.isFinite(Number(value.recipeFactor)) && Number(value.recipeFactor) !== 1) out.recipeFactor = Number(value.recipeFactor);
          if (value.default) out.default = true;
          return out;
        })
        .filter(Boolean);
      if (!values.length) return null;
      return {
        id: group.id || optionUid("grp"),
        name: { en, ar: String(group?.name?.ar || "").trim() || en },
        selection: group.selection === "multi" ? "multi" : "single",
        required: Boolean(group.required),
        values,
      };
    })
    .filter(Boolean);

// Shared visual editor for per-product POS options (sizes + modifier groups).
// Used by both the create dialog and the inline edit form so the configuration UI
// is identical and the data round-trips to Odoo (product.bayaan_pos_options).
function PosOptionsEditor({ ar, draft, setDraft }) {
  const groups = draft.modifierGroups || [];
  const setGroups = (next) => setDraft({ ...draft, modifierGroups: next });
  const addGroup = () => setGroups([...groups, emptyModifierGroup()]);
  const removeGroup = (gi) => setGroups(groups.filter((_, i) => i !== gi));
  const patchGroup = (gi, patch) => setGroups(groups.map((g, i) => (i === gi ? { ...g, ...patch } : g)));
  const addValue = (gi) => setGroups(groups.map((g, i) => (i === gi ? { ...g, values: [...(g.values || []), emptyModifierValue()] } : g)));
  const removeValue = (gi, vi) => setGroups(groups.map((g, i) => (i === gi ? { ...g, values: g.values.filter((_, j) => j !== vi) } : g)));
  const patchValue = (gi, vi, patch) => setGroups(groups.map((g, i) => (i === gi ? { ...g, values: g.values.map((v, j) => (j === vi ? { ...v, ...patch } : v)) } : g)));
  const loadCategoryDefaults = () => setDraft({
    ...draft,
    modifierGroups: defaultModifierGroupsForCategory(draft.category),
    sizes: defaultSizesForCategory(draft.category),
  });
  return (
    <div className="col" style={{ gap: 8, marginTop: 4, padding: 12, border: "1px solid var(--line)", borderRadius: 10, background: "var(--surface-sunk)" }}>
      <div className="between">
        <div className="t-micro" style={{ fontWeight: 600 }}>
          {ar ? "خيارات نقطة البيع (الأحجام والإضافات)" : "POS options (sizes & customizations)"}
        </div>
        <button type="button" className="btn btn-ghost" style={{ height: 24, fontSize: 11 }} onClick={loadCategoryDefaults}>
          {ar ? `تحميل افتراضيات ${arTerm("ar", draft.category)}` : `Load ${draft.category} defaults`}
        </button>
      </div>
      <div className="t-small muted">
        {ar
          ? "تُحفظ هذه الخيارات مع المنتج وتظهر للكاشير في نقطة البيع. «سعر+» يُعدّل إجمالي السطر و«وصفة×» يضاعف استهلاك المكونات عند البيع."
          : "Saved with the product and shown to the cashier at the POS. “Δ price” adjusts the line total; “recipe ×” scales ingredient consumption at sale time."}
      </div>
      {groups.length === 0 ? (
        <div className="t-small muted" style={{ padding: "4px 0" }}>
          {ar ? "لا توجد خيارات. أضف مجموعة لتفعيل التخصيص." : "No options yet. Add a group to enable customization."}
        </div>
      ) : groups.map((g, gi) => (
        <div key={g.id || gi} className="col" style={{ gap: 6, padding: 10, border: "1px solid var(--line)", borderRadius: 8, background: "var(--surface)" }}>
          <div className="row" style={{ gap: 8, alignItems: "center" }}>
            <input
              value={g.name?.en || ""}
              onChange={(e) => patchGroup(gi, { name: { en: e.target.value, ar: e.target.value } })}
              placeholder={ar ? "اسم المجموعة (مثال: الحجم)" : "Group name (e.g. Size)"}
              style={{ ...editorInput, flex: 2 }}
            />
            <select value={g.selection || "single"} onChange={(e) => patchGroup(gi, { selection: e.target.value })} style={{ ...editorInput, width: 140 }}>
              <option value="single">{ar ? "اختيار واحد" : "Single choice"}</option>
              <option value="multi">{ar ? "متعدد" : "Multi-select"}</option>
            </select>
            <label className="row" style={{ gap: 4, fontSize: 12, whiteSpace: "nowrap" }}>
              <input type="checkbox" checked={!!g.required} onChange={(e) => patchGroup(gi, { required: e.target.checked })}/>
              {ar ? "مطلوب" : "Required"}
            </label>
            <button type="button" className="btn btn-ghost" style={{ height: 24, fontSize: 11, marginInlineStart: "auto" }} onClick={() => removeGroup(gi)}>
              {ar ? "حذف" : "Remove"}
            </button>
          </div>
          {(g.values || []).map((v, vi) => (
            <div key={v.id || vi} className="row" style={{ gap: 6, alignItems: "center", paddingInlineStart: 8 }}>
              <input
                value={v.name?.en || ""}
                onChange={(e) => patchValue(gi, vi, { name: { en: e.target.value, ar: e.target.value } })}
                placeholder={ar ? "اسم الخيار (مثال: كبير)" : "Option (e.g. Large)"}
                style={{ ...editorInput, flex: 2 }}
              />
              <div className="row" style={{ gap: 3, alignItems: "center" }}>
                <span className="t-micro muted">{ar ? "سعر+" : "Δ price"}</span>
                <input type="number" step={250} value={v.priceDelta ?? 0}
                  onChange={(e) => patchValue(gi, vi, { priceDelta: Number(e.target.value) })}
                  style={{ ...editorInput, width: 84 }}/>
              </div>
              <span className="t-micro" style={{ color: "var(--ink-3)", whiteSpace: "nowrap" }} title={ar ? "السعر الفعلي" : "Effective price"}>
                = {(Math.max(0, Number(draft.price) || 0) + (Number(v.priceDelta) || 0)).toLocaleString("en")}
              </span>
              <div className="row" style={{ gap: 3, alignItems: "center" }}>
                <span className="t-micro muted">{ar ? "وصفة×" : "recipe ×"}</span>
                <input type="number" step={0.05} value={v.recipeFactor ?? 1}
                  onChange={(e) => patchValue(gi, vi, { recipeFactor: Number(e.target.value) })}
                  style={{ ...editorInput, width: 72 }}/>
              </div>
              <label className="row" style={{ gap: 3, fontSize: 11, whiteSpace: "nowrap" }} title={ar ? "افتراضي" : "Default"}>
                <input type="checkbox" checked={!!v.default} onChange={(e) => patchValue(gi, vi, { default: e.target.checked })}/>
                {ar ? "افتراضي" : "default"}
              </label>
              <button type="button" className="btn btn-ghost" style={{ height: 22, fontSize: 13, padding: "0 8px" }} onClick={() => removeValue(gi, vi)}>×</button>
            </div>
          ))}
          <button type="button" className="btn btn-ghost" style={{ height: 22, fontSize: 11, alignSelf: "start" }} onClick={() => addValue(gi)}>
            <Icon name="plus" size={10}/>{ar ? "إضافة خيار" : "Add option"}
          </button>
        </div>
      ))}
      <button type="button" className="btn btn-ghost" style={{ height: 26, fontSize: 11, alignSelf: "start" }} onClick={addGroup}>
        <Icon name="plus" size={11}/>{ar ? "إضافة مجموعة خيارات" : "Add option group"}
      </button>
    </div>
  );
}

const odooPurchaseOrderRows = (bootstrap) => {
  const snapshot = unwrapOdoo(bootstrap);
  const rows = snapshot?.purchase_orders || [];
  if (!rows.length) {
    return canUseDemoFallback(bootstrap) ? [
      { po: "PO-2026-0509-007", supplier: "Baghdad Dairy", invoice: "INV-BD-501", warehouse: DEFAULT_WAREHOUSE_NAME, items: "Milk, cream, yogurt", value: 2_950_000, status: "created" },
      { po: "PO-2026-0509-008", supplier: "Mesopotamia Foods", invoice: "INV-MF-118", warehouse: DEFAULT_WAREHOUSE_NAME, items: "Pistachio paste 50 kg", value: 11_125_000, status: "created" },
      { po: "PO-2026-0509-009", supplier: "Najaf Fresh", invoice: "INV-NF-772", warehouse: "Baghdad Area Warehouse", items: "Oranges, lemons, mint", value: 1_840_000, status: "received" },
    ] : [];
  }
  return rows.slice(0, 12).map((order) => {
    const receiptState = String(order.receipt_state || order.receiptState || "").toLowerCase();
    const status = receiptState === "done"
      ? "received"
      : receiptState === "partial"
        ? "partial"
        : order.state || "created";
    return {
      po: order.name || `PO-${order.id}`,
      supplier: order.supplier || "Supplier",
      invoice: order.invoice || order.vendor_bill || order.vendorBill || "-",
      warehouse: order.warehouse || order.receiving_warehouse || "",
      items: order.lines?.length
        ? order.lines.slice(0, 3).map((line) => {
          const orderedRaw = line.orderedQty ?? line.ordered_qty ?? line.qty ?? 0;
          const receivedRaw = line.receivedQty ?? line.received_qty ?? 0;
          const ordered = Number(orderedRaw).toLocaleString("en", { maximumFractionDigits: 2 });
          const received = Number(receivedRaw).toLocaleString("en", { maximumFractionDigits: 2 });
          return `${line.product} ${received}/${ordered}${line.uom ? ` ${line.uom}` : ""} received`;
        }).join(", ")
        : "No lines",
      value: Number(order.amount_total || 0),
      status,
      receiptState: receiptState || "none",
    };
  });
};

