const HR_ROLE_LABELS = {
  any: "Any role",
  cashier: "Cashier",
  barista: "Barista",
  supervisor: "Supervisor",
  warehouse: "Warehouse",
  manager: "Manager",
  accountant: "Accountant",
  other: "Other",
};
const HR_ROLE_LABELS_AR = {
  any: "أي دور",
  cashier: "كاشير",
  barista: "باريستا",
  supervisor: "مشرف",
  warehouse: "مستودع",
  manager: "مدير",
  accountant: "محاسب",
  other: "أخرى",
};
const WEEKDAY_LABELS = ["Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"];
const WEEKDAY_LABELS_AR = ["الاثنين", "الثلاثاء", "الأربعاء", "الخميس", "الجمعة", "السبت", "الأحد"];

const normalizeHrRole = (role) => {
  const normalized = String(role || "").trim().toLowerCase();
  if (normalized === "operations mgr") return "manager";
  if (normalized === "any role" || normalized === "all") return "any";
  return HR_ROLE_LABELS[normalized] ? normalized : "other";
};

const hrRoleLabel = (role, lang = "en") => (
  lang === "ar"
    ? HR_ROLE_LABELS_AR[normalizeHrRole(role)] || HR_ROLE_LABELS_AR.other
    : HR_ROLE_LABELS[normalizeHrRole(role)] || "Other"
);

