// ============================================================
// Same-day hourly sales flow — reuses the demo-mode StudioPatternBarChart
// engine (identical look to QualifiedSalesFlowChart), fed by today's real
// per-hour revenue buckets (summary.hourlySales) with a demo-curve fallback.
// ============================================================
function HourlySalesFlowChart({ data, ar }) {
  const hasReal = Array.isArray(data) && data.some((value) => Number(value) > 0);
  const buckets = Array.from({ length: 24 }, (_, hour) => {
    if (hasReal) return Number(data[hour] || 0);
    const idx = hour - HOURLY_PULSE_START;
    return idx >= 0 && idx < HOURLY_PULSE_REVENUE.length ? HOURLY_PULSE_REVENUE[idx] : 0;
  });
  // Trim to the active operating window so the chart isn't padded with empty hours.
  let firstHour = buckets.findIndex((value) => value > 0);
  let lastHour = -1;
  buckets.forEach((value, hour) => { if (value > 0) lastHour = hour; });
  if (firstHour < 0) { firstHour = 8; lastHour = 20; }
  const chartRows = [];
  for (let hour = firstHour; hour <= lastHour; hour += 1) {
    chartRows.push({ hour, label: String(hour).padStart(2, "0"), sales: buckets[hour] });
  }
  const totalSales = chartRows.reduce((sum, row) => sum + row.sales, 0);
  const peakRow = chartRows.reduce((best, row) => (row.sales > (best?.sales || 0) ? row : best), null);
  const fmtHour = (hour) => {
    const n = Number(hour);
    const suffix = n < 12 ? (ar ? "ص" : "AM") : (ar ? "م" : "PM");
    const display = n % 12 === 0 ? 12 : n % 12;
    return `${display}${suffix}`;
  };

  return (
    <div className="sales-flow-card sales-flow-card-qualified">
      <StudioPatternBarChart
        ar={ar}
        ariaLabel={ar ? "مبيعات اليوم بالساعة" : "Today's sales by hour"}
        rows={chartRows}
        xDataKey="label"
        valueDataKey="sales"
        barSize={Math.max(9, Math.min(38, Math.round(560 / Math.max(chartRows.length, 1))))}
        interval={chartRows.length > 12 ? 1 : 0}
        tickFormatter={(value) => fmtHour(value)}
        tooltipTitle={(row) => fmtHour(row?.hour)}
        tooltipValue={(row) => fmtCompact(Number(row?.sales || 0))}
        valueLabel={ar ? "المبيعات" : "Sales"}
      />

      <div className="sales-flow-side">
        <div>
          <div className="sales-flow-total">
            {fmtMoney(totalSales).replace("IQD ", "")}
            <span>{ar ? " د.ع" : " IQD"}</span>
          </div>
          <div className="t-small muted" style={{ lineHeight: 1.45 }}>
            {ar ? "إجمالي مبيعات اليوم حتى الآن، موزعة بالساعة." : "Today's sales so far, broken down by hour."}
          </div>
        </div>

        <div className="sales-flow-progress-card">
          <div className="sales-flow-progress-label">{ar ? "ساعة الذروة" : "Peak hour"}</div>
          <div className="sales-flow-progress-value">
            {peakRow ? fmtHour(peakRow.hour) : "—"}
            <span>{peakRow ? fmtCompact(peakRow.sales) : ""}</span>
          </div>
          <div className="sales-flow-progress-meta">
            <span>{ar ? `${chartRows.length} ساعات` : `${chartRows.length} hrs`}</span>
            <span>{hasReal ? (ar ? "مباشر" : "live") : (ar ? "تجريبي" : "demo")}</span>
          </div>
        </div>
      </div>
    </div>
  );
}

const SALES_FLOW_WEEKDAYS = {
  en: ["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"],
  ar: ["أحد", "إثن", "ثلا", "أرب", "خمي", "جمع", "سبت"],
};
const SALES_FLOW_MONTHS = {
  en: ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"],
  ar: ["ينا", "فبر", "مار", "أبر", "ماي", "يون", "يول", "أغس", "سبت", "أكت", "نوف", "ديس"],
};

// Sales-flow chart that follows the GLOBAL scope dropdown: Daily -> per hour,
// Weekly/Monthly -> per day, Yearly -> per month. Buckets are derived from the
// scope-aware order list (scopedBootstrap.today.orders) so the chart always reconciles
// with the period the rest of the dashboard is showing. No local hour/day toggle.
function ScopedSalesFlowChart({ orders, scope, ar, allowDemoFallback = false }) {
  const key = String(scope || "Daily").toLowerCase();
  const safeOrders = Array.isArray(orders) ? orders : [];
  const fmtHourLabel = (hour) => {
    const n = Number(hour);
    const suffix = n < 12 ? (ar ? "ص" : "AM") : (ar ? "م" : "PM");
    const display = n % 12 === 0 ? 12 : n % 12;
    return `${display}${suffix}`;
  };
  let chartRows = [];
  let granularityLabel = "";
  let peakLabel = "";
  if (key === "weekly" || key === "monthly") {
    const byDay = new Map();
    safeOrders.forEach((order) => {
      const day = String(order.date_order || "").slice(0, 10);
      if (day) byDay.set(day, (byDay.get(day) || 0) + Number(order.amount_total || 0));
    });
    chartRows = Array.from(byDay.keys()).sort().map((day) => {
      const [y, m, d] = day.split("-").map(Number);
      const weekday = new Date(y, (m || 1) - 1, d || 1).getDay();
      const label = key === "weekly"
        ? `${(ar ? SALES_FLOW_WEEKDAYS.ar : SALES_FLOW_WEEKDAYS.en)[weekday]} ${d}`
        : String(d);
      return { label, sales: byDay.get(day), tip: day };
    });
    granularityLabel = key === "weekly"
      ? (ar ? "هذا الأسبوع · يومي" : "this week, by day")
      : (ar ? "هذا الشهر · يومي" : "this month, by day");
    peakLabel = ar ? "أعلى يوم" : "Peak day";
  } else if (key === "yearly") {
    const byMonth = new Map();
    safeOrders.forEach((order) => {
      const month = String(order.date_order || "").slice(0, 7);
      if (month) byMonth.set(month, (byMonth.get(month) || 0) + Number(order.amount_total || 0));
    });
    chartRows = Array.from(byMonth.keys()).sort().map((month) => {
      const mi = Number(month.split("-")[1]) - 1;
      return { label: (ar ? SALES_FLOW_MONTHS.ar : SALES_FLOW_MONTHS.en)[mi] || month, sales: byMonth.get(month), tip: month };
    });
    granularityLabel = ar ? "هذه السنة · شهري" : "this year, by month";
    peakLabel = ar ? "أعلى شهر" : "Peak month";
  } else {
    const buckets = Array(24).fill(0);
    let hasReal = false;
    safeOrders.forEach((order) => {
      const hour = Number(String(order.date_order || "").slice(11, 13));
      if (hour >= 0 && hour < 24) { buckets[hour] += Number(order.amount_total || 0); hasReal = true; }
    });
    if (!hasReal && allowDemoFallback) {
      HOURLY_PULSE_REVENUE.forEach((value, i) => {
        const hour = HOURLY_PULSE_START + i;
        if (hour < 24) buckets[hour] = value;
      });
    }
    let first = buckets.findIndex((value) => value > 0);
    let last = -1;
    buckets.forEach((value, hour) => { if (value > 0) last = hour; });
    if (first < 0) { first = 8; last = 20; }
    for (let hour = first; hour <= last; hour += 1) {
      chartRows.push({ label: fmtHourLabel(hour), sales: buckets[hour], tip: fmtHourLabel(hour) });
    }
    granularityLabel = ar ? "اليوم · ساعي" : "today, by hour";
    peakLabel = ar ? "ساعة الذروة" : "Peak hour";
  }
  const totalSales = chartRows.reduce((sum, row) => sum + row.sales, 0);
  const peakRow = chartRows.reduce((best, row) => (row.sales > (best?.sales || 0) ? row : best), null);
  const count = chartRows.length;
  return (
    <div className="sales-flow-card sales-flow-card-qualified">
      <StudioPatternBarChart
        ar={ar}
        ariaLabel={ar ? "تدفق المبيعات" : "Sales flow"}
        rows={chartRows}
        xDataKey="label"
        valueDataKey="sales"
        barSize={Math.max(8, Math.min(38, Math.round(560 / Math.max(count, 1))))}
        interval={count > 16 ? Math.ceil(count / 12) : 0}
        tickFormatter={(value) => value}
        tooltipTitle={(row) => row?.tip || row?.label}
        tooltipValue={(row) => fmtCompact(Number(row?.sales || 0))}
        valueLabel={ar ? "المبيعات" : "Sales"}
      />
      <div className="sales-flow-side">
        <div>
          <div className="sales-flow-total">
            {fmtMoney(totalSales).replace("IQD ", "")}
            <span>{ar ? " د.ع" : " IQD"}</span>
          </div>
          <div className="t-small muted" style={{ lineHeight: 1.45 }}>{granularityLabel}</div>
        </div>
        <div className="sales-flow-progress-card">
          <div className="sales-flow-progress-label">{peakLabel}</div>
          <div className="sales-flow-progress-value">
            {peakRow ? peakRow.label : "—"}
            <span>{peakRow ? fmtCompact(peakRow.sales) : ""}</span>
          </div>
          <div className="sales-flow-progress-meta">
            <span>{count} {ar ? "شرائح" : "buckets"}</span>
            <span>{ar ? "مباشر" : "live"}</span>
          </div>
        </div>
      </div>
    </div>
  );
}

// ============================================================
// Status / direction marker for rank rows
// ============================================================
function RankIndicator({ rank }) {
  return (
    <span className="t-num" style={{
      fontFamily: "var(--font-mono)",
      fontSize: 10.5, color: "var(--ink-3)",
      width: 22, textAlign: "end",
      letterSpacing: "0.02em",
    }}>#{rank + 1}</span>
  );
}

// ============================================================
// Main screen
// ============================================================
function OverviewScreen({ lang, bootstrap, scope = "Daily" }) {
  const ar = lang === "ar";
  const liveOnly = isLiveOnlyPayload(bootstrap);
  const isDailyScope = !scope || scope === "Daily";
  // Per-kiosk rows follow the global scope via the shared scope-aware helper.
  const sourceKiosks = useMemo(() => odooKioskRows(bootstrap, scope), [bootstrap, scope]);
  const closeRows = useMemo(() => odooClosingRows(bootstrap), [bootstrap]);
  const paymentSplit = useMemo(() => odooPaymentSplit(bootstrap), [bootstrap]);
  const summary = useMemo(() => odooSummary(bootstrap), [bootstrap]);
  // Scope-aware order list (period orders for non-daily) feeding the Sales-flow chart.
  const flowOrders = useMemo(() => unwrapOdoo(bootstrap)?.today?.orders || [], [bootstrap]);
  const sourceDriven = isSourceDrivenPayload(bootstrap);
  const liveProductRows = useMemo(() => {
    if (!sourceDriven) return [];
    const snapshot = unwrapOdoo(bootstrap);
    const byProduct = new Map();
    (snapshot?.today?.orders || []).forEach((order) => {
      (order.lines || []).forEach((line) => {
        const name = cleanDisplayName(line.product || line.name || "POS item");
        const current = byProduct.get(name) || { id: `live-product-${byProduct.size}`, name, cat: "Engine", rev: 0, qty: 0 };
        current.rev += Number(line.price_subtotal_incl || line.price_subtotal || line.subtotal || line.amount || (Number(line.price_unit || 0) * Number(line.qty || 0)) || 0);
        current.qty += Number(line.qty || 0);
        byProduct.set(name, current);
      });
    });
    return Array.from(byProduct.values()).sort((a, b) => b.rev - a.rev).slice(0, 8);
  }, [bootstrap, sourceDriven]);
  const liveWasteRows = useMemo(() => {
    if (!sourceDriven) return [];
    return odooWasteRows(bootstrap).map((row, index) => ({
      id: `live-waste-${index}`,
      name: cleanDisplayName(row.item || "Waste item"),
      cat: row.reason || "Waste",
      cost: Number(row.cost || 0),
      qty: Number(row.qty || 0),
    }));
  }, [bootstrap, sourceDriven]);
  const liveFeedRows = useMemo(() => {
    if (!sourceDriven) return [];
    const snapshot = unwrapOdoo(bootstrap);
    const kioskNames = new Map(sourceKiosks.map((kiosk) => [kiosk.id, kiosk.name]));
    const now = Date.now();
    return [...(snapshot?.today?.orders || [])]
      .sort((left, right) => String(right.date_order || "").localeCompare(String(left.date_order || "")))
      .slice(0, 14)
      .map((order, index) => {
      const firstLine = order.lines?.[0];
      const item = firstLine
        ? cleanDisplayName(firstLine.product || firstLine.name)
        : cleanDisplayName(order.name || "POS order");
      return {
        id: order.name || `live-order-${index}`,
        kid: order.kiosk || order.pos_config || "-",
        kiosk: kioskNames.get(order.kiosk) || order.kiosk || order.pos_config || "POS kiosk",
        item,
        amount: Number(order.amount_total || firstLine?.price_subtotal_incl || 0),
        ago: order.date_order ? String(order.date_order).slice(11, 16) : "synced",
        ts: now - index * 1000,
      };
      });
  }, [bootstrap, sourceDriven, sourceKiosks]);
  // ---- Live state: per-kiosk metrics (revenue + stock %) ----
  const initial = useMemo(() => {
    const baseSeed = (s) => {
      // hash-ish for deterministic init
      let h = 0;
      for (let i = 0; i < s.length; i++) h = (h * 31 + s.charCodeAt(i)) | 0;
      return Math.abs(h);
    };
    return sourceKiosks.map((k) => {
      const seed = baseSeed(k.id);
      // MOCK.kiosks already stores per-kiosk daily revenue in raw IQD; just add a small
      // jitter so adjacent kiosks have natural swap headroom for the rank animation.
      const rev = sourceDriven ? Number(k.revenue || 0) : k.revenue + (seed % 500000);
      // initial stock %, lower for warn/crit
      const stockBase = sourceDriven ? Number(k.stockHealth || 0)
                      : k.status === "crit" ? 22 + (seed % 18)
                      : k.status === "warn" ? 44 + (seed % 18)
                      : 62 + (seed % 32);
      const stockItem = ["Milk, cups, oranges","Pistachio paste","Oat milk","Mint, lemons","Coffee beans","Vanilla syrup","Chocolate","Cinnamon","Sugar","Croissants"][seed % 10];
      return { ...k, liveRev: rev, liveStock: stockBase, stockItem, liveOrders: k.orders };
    });
  }, [sourceDriven, sourceKiosks]);

  const [kiosks, setKiosks] = useState(initial);
  useEffect(() => {
    setKiosks(initial);
    setFeed(sourceDriven ? liveFeedRows : seedFeed(initial));
  }, [initial, sourceDriven, liveFeedRows]);

  // Live products (revenue tickers)
  const initialProducts = useMemo(() => sourceDriven ? liveProductRows : ([
    { id: "p1", name: "Iced Latte",       cat: "Iced Coffee", rev: 3_690_000, qty: 415 },
    { id: "p2", name: "Iced Americano",   cat: "Iced Coffee", rev: 2_620_000, qty: 392 },
    { id: "p3", name: "Orange Juice",     cat: "Juice",       rev: 2_330_000, qty: 301 },
    { id: "p4", name: "Latte",            cat: "Hot Coffee",  rev: 2_130_000, qty: 271 },
    { id: "p5", name: "Pistachio Cake",   cat: "Cake",        rev: 1_670_000, qty: 148 },
    { id: "p6", name: "Cold Brew",        cat: "Iced Coffee", rev: 1_630_000, qty: 172 },
    { id: "p7", name: "Cappuccino",       cat: "Hot Coffee",  rev: 1_580_000, qty: 215 },
    { id: "p8", name: "Mocha",            cat: "Hot Coffee",  rev: 1_410_000, qty: 178 },
  ]), [sourceDriven, liveProductRows]);
  const [products, setProducts] = useState(initialProducts);
  useEffect(() => {
    setProducts(initialProducts);
  }, [initialProducts]);

  // Live waste leaderboard (cost lost per item — ticks like products)
  const initialWaste = useMemo(() => sourceDriven ? liveWasteRows : ([
    { id: "w1", name: "Croissant - chocolate", cat: "Bakery",      cost: 412_000, qty: 28 },
    { id: "w2", name: "Pistachio cake slice",  cat: "Cake",        cost: 384_000, qty: 18 },
    { id: "w3", name: "Iced latte",            cat: "Iced Coffee", cost: 294_000, qty: 22 },
    { id: "w4", name: "Mango juice",           cat: "Juice",       cost: 168_000, qty: 14 },
    { id: "w5", name: "Croissant - plain",     cat: "Bakery",      cost: 142_000, qty: 19 },
    { id: "w6", name: "Espresso shot",         cat: "Coffee",      cost: 84_000,  qty: 12 },
  ]), [sourceDriven, liveWasteRows]);
  const [waste, setWaste] = useState(initialWaste);
  useEffect(() => {
    setWaste(initialWaste);
  }, [initialWaste]);

  // Live activity feed (rolling event stream)
  const [feed, setFeed] = useState(() => sourceDriven ? liveFeedRows : seedFeed(initial));
  const eventCounterRef = useRef(1000);

  // Hourly bars — current hour ticks up
  // ---- Tick: nudge metrics, occasionally trigger rank swaps ----
  useEffect(() => {
    if (sourceDriven || !initial.length) return undefined;
    let alive = true;

    // Frequent tick: small revenue/orders nudges + new feed entry
    const tickFast = setInterval(() => {
      if (!alive) return;
      // append a random transaction
      const k = initial[Math.floor(Math.random() * initial.length)];
      eventCounterRef.current += 1;
      const items = [
        { name: "Iced Latte M - Pistachio Cake", amt: 19500 },
        { name: "Mocha L - Cinnamon Roll",       amt: 14000 },
        { name: "Spanish Latte M - Tiramisu",    amt: 19000 },
        { name: "Cold Brew L - Cheesecake",      amt: 19500 },
        { name: "Mango Juice L",                  amt: 8500 },
        { name: "Orange Juice L",                 amt: 9000 },
        { name: "Cappuccino L - Croissant",       amt: 16500 },
        { name: "Americano - Plain Croissant",    amt: 11000 },
        { name: "Iced Mocha - Carrot Cake",       amt: 21500 },
      ];
      const ev = items[Math.floor(Math.random() * items.length)];
      setFeed((prev) => [
        { id: "ev-" + eventCounterRef.current, kid: k.id, kiosk: k.name, item: ev.name, amount: ev.amt, ago: "now", ts: Date.now() },
        ...prev.map((e, i) => ({ ...e, ago: i === 0 ? `${1 + (Date.now() - e.ts) / 1000 | 0}s ago` : `${(Date.now() - e.ts) / 1000 | 0}s ago` })),
      ].slice(0, 14));

      // bump kiosk metrics
      setKiosks((prev) => prev.map((kk) => {
        const isWinner = kk.id === k.id;
        return {
          ...kk,
          liveRev: kk.liveRev + (isWinner ? ev.amt + 4000 : Math.random() * 3500),
          liveOrders: kk.liveOrders + (isWinner ? 1 : 0),
          // stock slowly declines, more for top-sellers
          liveStock: Math.max(8, kk.liveStock - (isWinner ? 0.18 : 0.06) + (Math.random() * 0.04 - 0.02)),
        };
      }));

      // bump products
      setProducts((prev) => prev.map((p) => ({
        ...p,
        rev: p.rev + Math.random() * 24000,
        qty: p.qty + (Math.random() < 0.4 ? 1 : 0),
      })));

      // bump waste (smaller increments — waste accrues slowly relative to sales)
      setWaste((prev) => prev.map((w) => ({
        ...w,
        cost: w.cost + Math.random() * 2400,
        qty: w.qty + (Math.random() < 0.18 ? 1 : 0),
      })));

    }, 1800);

    // Slower tick: targeted bumps to force a rank swap somewhere
    const tickSwap = setInterval(() => {
      if (!alive) return;
      setKiosks((prev) => {
        if (prev.length < 2) return prev;
        // sort by liveRev desc so we know current ranks
        const sorted = [...prev].sort((a, b) => b.liveRev - a.liveRev);
        // pick a random adjacent pair within top 6 to swap
        const idx = Math.floor(Math.random() * Math.min(5, sorted.length - 1));
        const a = sorted[idx], b = sorted[idx + 1];
        const gap = a.liveRev - b.liveRev;
        // give b a sudden burst that pushes it past a
        const burst = gap + 50000 + Math.random() * 80000;
        return prev.map((kk) => kk.id === b.id ? { ...kk, liveRev: kk.liveRev + burst, liveOrders: kk.liveOrders + 4 } : kk);
      });
    }, 5500);

    // Also occasionally swap restock priority (lowest stock)
    const tickStockSwap = setInterval(() => {
      if (!alive) return;
      setKiosks((prev) => {
        const sorted = [...prev].sort((a, b) => a.liveStock - b.liveStock);
        const idx = Math.floor(Math.random() * Math.min(5, sorted.length - 1));
        const a = sorted[idx], b = sorted[idx + 1];
        const gap = b.liveStock - a.liveStock;
        // push b's stock below a's (a got a delivery; b consumed faster)
        return prev.map((kk) => {
          if (kk.id === b.id) return { ...kk, liveStock: Math.max(8, kk.liveStock - gap - 1.2 - Math.random() * 2) };
          if (kk.id === a.id) return { ...kk, liveStock: Math.min(96, kk.liveStock + 0.8) };
          return kk;
        });
      });
    }, 7200);

    // Occasional product swap
    const tickProdSwap = setInterval(() => {
      if (!alive) return;
      setProducts((prev) => {
        if (prev.length < 2) return prev;
        const sorted = [...prev].sort((a, b) => b.rev - a.rev);
        const idx = Math.floor(Math.random() * Math.min(4, sorted.length - 1));
        const a = sorted[idx], b = sorted[idx + 1];
        const gap = a.rev - b.rev;
        return prev.map((p) => p.id === b.id ? { ...p, rev: p.rev + gap + 30000 + Math.random() * 60000, qty: p.qty + 8 } : p);
      });
    }, 6400);

    // Occasional waste swap — different cadence so animations don't coincide
    const tickWasteSwap = setInterval(() => {
      if (!alive) return;
      setWaste((prev) => {
        if (prev.length < 2) return prev;
        const sorted = [...prev].sort((a, b) => b.cost - a.cost);
        const idx = Math.floor(Math.random() * Math.min(4, sorted.length - 1));
        const a = sorted[idx], b = sorted[idx + 1];
        const gap = a.cost - b.cost;
        return prev.map((w) => w.id === b.id ? { ...w, cost: w.cost + gap + 8000 + Math.random() * 14000, qty: w.qty + 2 } : w);
      });
    }, 8100);

    return () => { alive = false; clearInterval(tickFast); clearInterval(tickSwap); clearInterval(tickStockSwap); clearInterval(tickProdSwap); clearInterval(tickWasteSwap); };
  }, [initial, sourceDriven]);

  // ---- Derived sorted lists ----
  const topPerformers = useMemo(
    () => [...kiosks].sort((a, b) => b.liveRev - a.liveRev).slice(0, 5),
    [kiosks]
  );
  const restockPriority = useMemo(
    () => [...kiosks].sort((a, b) => a.liveStock - b.liveStock).slice(0, 5),
    [kiosks]
  );
  const topProducts = useMemo(
    () => [...products].sort((a, b) => b.rev - a.rev).slice(0, 5),
    [products]
  );
  const topWaste = useMemo(
    () => [...waste].sort((a, b) => b.cost - a.cost).slice(0, 5),
    [waste]
  );

  // ---- KPI aggregates (live) ----
  const liveTotalRev = useMemo(() => kiosks.reduce((s, k) => s + k.liveRev, 0), [kiosks]);
  const liveTotalOrders = useMemo(() => kiosks.reduce((s, k) => s + k.liveOrders, 0), [kiosks]);
  const baseTotals = summary?.totals || null;
  // Headline KPI tiles follow the same global scope. For a non-daily scope, swap the
  // period-varying figures for that period's reportPeriods summary; everything else and
  // the Daily case stay exactly as before. Missing fields fall back to the daily totals.
  const summaryTotals = useMemo(() => {
    if (!baseTotals) return baseTotals;
    const reportPeriods = unwrapOdoo(bootstrap)?.summary?.reportPeriods;
    if (isDailyScope) {
      // One profit definition across every scope: net after payroll accrual
      // (reportPeriods.*.netProfitAfterPayroll). Daily previously showed the
      // pre-payroll totals.profitEstimate, so toggling Daily -> Weekly made
      // the tile collapse by the salary accrual and read as a broken number.
      const daily = reportPeriods?.daily;
      const dailyNet = daily?.netProfitAfterPayroll ?? daily?.netProfit;
      return dailyNet != null ? { ...baseTotals, profitEstimate: Number(dailyNet) } : baseTotals;
    }
    const ps = reportPeriods?.[String(scope).toLowerCase()];
    if (!ps) return baseTotals;
    return {
      ...baseTotals,
      salesToday: Number(ps.revenue ?? ps.sales ?? baseTotals.salesToday ?? 0),
      ordersToday: Number(ps.orders ?? baseTotals.ordersToday ?? 0),
      profitEstimate: ps.netProfitAfterPayroll != null ? Number(ps.netProfitAfterPayroll)
        : ps.netProfit != null ? Number(ps.netProfit) : baseTotals.profitEstimate,
      wasteCost: ps.wasteCost != null ? Number(ps.wasteCost) : baseTotals.wasteCost,
      cashExpected: ps.cashExpected != null ? Number(ps.cashExpected) : baseTotals.cashExpected,
      digitalPayments: ps.digitalPayments != null ? Number(ps.digitalPayments) : baseTotals.digitalPayments,
    };
  }, [scope, isDailyScope, baseTotals, bootstrap]);
  const totalRev = summaryTotals?.salesToday != null ? Number(summaryTotals.salesToday || 0) : liveTotalRev;
  const totalOrders = summaryTotals?.ordersToday != null ? Number(summaryTotals.ordersToday || 0) : liveTotalOrders;
  const grossProfitKnown = summaryTotals?.profitEstimate != null || !liveOnly;
  const grossProfit = summaryTotals?.profitEstimate != null
    ? Number(summaryTotals.profitEstimate || 0)
    : liveOnly
      ? null
      : totalRev * 0.289;
  const profitMarginLabel = totalRev
    ? ar ? `${((grossProfit / totalRev) * 100).toFixed(1)}% هامش` : `${((grossProfit / totalRev) * 100).toFixed(1)}% margin`
    : ar ? "0.0% هامش" : "0.0% margin";
  const profitMarginDisplay = grossProfitKnown && totalRev && isFiniteNumber(grossProfit)
    ? profitMarginLabel
    : liveOnly
      ? (ar ? "بانتظار ملخص المحرك" : "awaiting engine totals")
      : profitMarginLabel;
  const cashExpectedKnown = summaryTotals?.cashExpected != null || Boolean(paymentSplit) || !liveOnly;
  const cashExpected = summaryTotals?.cashExpected != null
    ? Number(summaryTotals.cashExpected || 0)
    : paymentSplit
      ? Number(paymentSplit.cash || 0)
      : liveOnly
        ? null
        : totalRev * 0.64;
  const digitalPaymentsKnown = summaryTotals?.digitalPayments != null || Boolean(paymentSplit) || !liveOnly;
  const digitalPayments = summaryTotals?.digitalPayments != null
    ? Number(summaryTotals.digitalPayments || 0)
    : paymentSplit
      ? Number(paymentSplit.digital || 0)
      : liveOnly
        ? null
        : totalRev * 0.36;
  const closedKiosks = summaryTotals?.closedKiosks != null ? Number(summaryTotals.closedKiosks || 0) : closeRows.filter((close) => close.status !== "open").length;
  const openKiosks = summaryTotals?.openKiosks != null ? Number(summaryTotals.openKiosks || 0) : Math.max(0, kiosks.length - closedKiosks);
  const lowStockAlerts = summary?.alerts ? Number(summary.alerts.lowStockItems || 0) : liveOnly ? null : kiosks.filter((k) => k.liveStock < 50).length;
  const unresolvedVariances = summary?.alerts ? Number(summary.alerts.unresolvedVariances || 0) : liveOnly ? null : closeRows.filter((close) => close.status === "pending" || close.status === "issue").length;
  const liveWasteCost = liveWasteRows.reduce((sum, row) => sum + Number(row.cost || 0), 0);
  const wastePct = summaryTotals?.salesToday
    ? Number(((Number(summaryTotals.wasteCost || 0) / Number(summaryTotals.salesToday || 1)) * 100).toFixed(1))
    : liveOnly && totalRev > 0 && liveWasteCost > 0
      ? Number(((liveWasteCost / totalRev) * 100).toFixed(1))
      : liveOnly
        ? null
        : 3.1;
  const variancePct = summaryTotals?.variancePct != null ? Number(summaryTotals.variancePct || 0) : liveOnly ? null : -1.3;

  // The Today Command Center follows the GLOBAL scope dropdown (Daily/Weekly/Monthly/
  // Yearly). Every figure reads the scope-aware bootstrap, so there is no local period
  // toggle or display multiplier here.
  const scopeSubtitle = scope === "Monthly"
    ? (ar ? "هذا الشهر" : "this month")
    : scope === "Weekly"
      ? (ar ? "هذا الأسبوع" : "this week")
      : scope === "Yearly"
        ? (ar ? "هذه السنة" : "this year")
        // Lowercase "today" to stay consistent with the other scope subtitles
        // (this week / this month / this year) and to read correctly inside the
        // "Total sales today" / "by revenue - today" labels.
        : (ar ? "اليوم" : "today");
  const planDelta = sourceDriven
    ? (ar ? "المحرك فقط" : "engine only")
    : scope === "Monthly"
      ? (ar ? "+11.2% مقابل الخطة" : "+11.2% vs plan")
      : scope === "Weekly"
        ? (ar ? "+9.6% مقابل الخطة" : "+9.6% vs plan")
        : (ar ? "+8.4% مقابل الخطة" : "+8.4% vs plan");
  const paymentMixRows = useMemo(() => {
    const splitTotal = Number(paymentSplit?.total || 0);
    const hasGatewaySplit = splitTotal > 0;
    if (sourceDriven && !hasGatewaySplit) return [];
    const cash = hasGatewaySplit ? Number(paymentSplit.cash || 0) : Number(cashExpected || 0);
    const digital = hasGatewaySplit ? Number(paymentSplit.digital || 0) : Number(digitalPayments || 0);
    const rows = hasGatewaySplit ? [
      { id: "cash", label: ar ? "نقد" : "Cash", value: Number(paymentSplit.cash || 0), color: "var(--chart-5)" },
      { id: "card", label: ar ? "بطاقات" : "Cards", value: Number(paymentSplit.card || 0), color: "var(--chart-2)" },
      { id: "qr", label: ar ? "QR" : "QR", value: Number(paymentSplit.qr || 0), color: "var(--chart-3)" },
      { id: "wallet", label: ar ? "محافظ" : "Wallets", value: Number(paymentSplit.mobile_wallet || 0), color: "var(--chart-4)" },
      { id: "bank", label: ar ? "تطبيقات بنك" : "Bank apps", value: Number(paymentSplit.bank_app || 0), color: "var(--accent)" },
      { id: "manual", label: ar ? "يدوي" : "Manual", value: Number(paymentSplit.manual_digital || 0), color: "var(--warn)" },
      { id: "other", label: ar ? "أخرى" : "Other", value: Number(paymentSplit.digital_other || 0), color: "var(--ink-3)" },
    ] : [
      { id: "cash", label: ar ? "نقد" : "Cash", value: cash, color: "var(--chart-5)" },
      { id: "card", label: ar ? "بطاقات" : "Cards", value: digital * 0.46, color: "var(--chart-2)" },
      { id: "qr", label: ar ? "QR" : "QR", value: digital * 0.2, color: "var(--chart-3)" },
      { id: "wallet", label: ar ? "محافظ" : "Wallets", value: digital * 0.24, color: "var(--chart-4)" },
      { id: "manual", label: ar ? "يدوي" : "Manual", value: digital * 0.1, color: "var(--warn)" },
    ];
    return rows
      .map((row) => ({ ...row, value: Math.max(0, row.value) }))
      .filter((row) => row.value > 0);
  }, [paymentSplit, cashExpected, digitalPayments, sourceDriven, ar]);
  const paymentMixTotal = useMemo(() => paymentMixRows.reduce((sum, row) => sum + row.value, 0), [paymentMixRows]);
  const alertRows = sourceDriven ? [] : MOCK.alerts;
  const actionRows = sourceDriven ? [] : [
    { label: "Auto-PO drafted - Baghdad Dairy", sub: "Milk x 4 kiosks - IQD 1.2M", ok: true },
    { label: "Pre-prep schedule shifted", sub: "Zayouna Plaza - 7:30 to 7:45", ok: true },
    { label: "Pistachio recipe flagged", sub: "12g to 9g - awaiting approval", ok: false },
  ];

  return (
    <div className="col" style={{ gap: 12, height: "calc(100vh - 130px)", overflow: "hidden" }}>
      {/* keyframes */}
      <style>{`
        @keyframes ovPulse { 0% { transform: scale(0.8); opacity: 0.55; } 70% { transform: scale(2); opacity: 0; } 100% { transform: scale(2); opacity: 0; } }
        @keyframes ovBarPulse { 0%, 100% { opacity: 0.0; } 50% { opacity: 0.4; } }
        @keyframes ovBlink { 0%, 49% { opacity: 1; } 50%, 100% { opacity: 0; } }
        @keyframes ovScan {
          0% { transform: translateX(-30%); }
          100% { transform: translateX(130%); }
        }
        .ov-row {
          background: var(--surface);
          border: 1px solid var(--line-soft);
          border-radius: 6px;
          padding: 7px 10px;
          display: grid;
          /* rank | name (fixed width so bars line up across rows) | bar (fills) | value */
          grid-template-columns: 22px 120px 1fr auto;
          align-items: center;
          gap: 10px;
          transition: background 200ms ease, border-color 200ms ease;
        }
        .ov-row > .ov-name {
          display: flex;
          align-items: center;
          gap: 6px;
          min-width: 0;
          overflow: hidden;
        }
        .ov-row > .ov-name > span:first-child {
          white-space: nowrap;
          overflow: hidden;
          text-overflow: ellipsis;
        }
        .ov-row[data-swap-dir="up"] {
          background: linear-gradient(90deg, rgba(14,122,78,0.08), var(--surface) 60%);
          border-color: rgba(14,122,78,0.35);
        }
        .ov-row[data-swap-dir="down"] {
          background: linear-gradient(90deg, rgba(20,20,25,0.04), var(--surface) 60%);
        }
        .ov-row .swap-badge {
          opacity: 0;
          transition: opacity 240ms ease;
        }
        .ov-row[data-swap-dir] .swap-badge {
          opacity: 1;
        }
        .ov-section {
          background: var(--surface);
          border: 1px solid var(--line);
          border-radius: 8px;
          overflow: hidden;
        }
        .ov-section-head {
          display: flex; align-items: center; justify-content: space-between;
          padding: 10px 14px;
          border-bottom: 1px solid var(--line-soft);
          background: var(--surface-2);
        }
        .ov-section-title {
          display: flex; align-items: center; gap: 8px;
          font-size: 11px; font-weight: 600;
          letter-spacing: 0.08em; text-transform: uppercase;
          color: var(--ink-1);
          font-family: var(--font-mono);
        }
        .ov-bar-track {
          height: 4px; background: var(--surface-sunk); border-radius: 2px; overflow: hidden;
          position: relative;
        }
        .ov-bar-fill {
          height: 100%; border-radius: 2px;
          transition: width 700ms cubic-bezier(0.22,1,0.36,1), background 300ms ease;
        }
        .ov-cursor::after {
          content: "_"; margin-left: 2px; animation: ovBlink 1.1s step-end infinite;
          color: var(--ink-3); font-weight: 400;
        }
        .ov-scan {
          position: relative; overflow: hidden;
        }
        .ov-scan::after {
          content: ""; position: absolute; top: 0; bottom: 0; width: 30%;
          background: linear-gradient(90deg, transparent, rgba(35,66,216,0.07), transparent);
          animation: ovScan 6s linear infinite;
          pointer-events: none;
        }
        .ov-period {
          display: inline-flex;
          border: 1px solid var(--terminal-line);
          border-radius: 4px;
          overflow: hidden;
          font-family: var(--font-mono);
          font-size: 10.5px;
          letter-spacing: 0.06em;
        }
        .ov-period button {
          padding: 3px 9px;
          color: var(--terminal-muted);
          background: transparent;
          border: 0;
          border-inline-end: 1px solid var(--terminal-line-soft);
          cursor: pointer;
          transition: color 120ms ease, background 120ms ease;
        }
        .ov-period button:last-child { border-inline-end: 0; }
        .ov-period button:hover { color: var(--terminal-ink); }
        .ov-period button.on {
          color: var(--terminal-active-ink);
          background: var(--terminal-active-bg);
        }
        .ov-kpi-row {
          display: grid;
          grid-template-columns: 1fr auto;
          align-items: center;
          gap: 10px;
          padding: 8px 12px;
          border-bottom: 1px solid var(--line-soft);
        }
        .ov-kpi-row:last-child { border-bottom: 0; }
        .ov-kpi-label {
          font-size: 9.5px;
          font-family: var(--font-mono);
          color: var(--ink-3);
          letter-spacing: 0.06em;
          text-transform: uppercase;
          line-height: 1.3;
        }
        .ov-kpi-delta {
          font-size: 10.5px;
          font-family: var(--font-mono);
          line-height: 1.3;
          margin-top: 1px;
        }
        .ov-kpi-value {
          font-family: var(--font-mono);
          font-size: 14px;
          font-weight: 500;
          font-variant-numeric: tabular-nums;
          letter-spacing: -0.01em;
          text-align: end;
          line-height: 1.1;
        }
      `}</style>

      {/* ============ Terminal status bar ============ */}
      <div className="ov-scan" style={{
        background: "var(--terminal)", color: "var(--terminal-ink)",
        borderRadius: 8, padding: "10px 16px",
        display: "flex", alignItems: "center", gap: 18,
        fontFamily: "var(--font-mono)", fontSize: 11.5,
        letterSpacing: "0.04em",
      }}>
        <div className="row" style={{ gap: 8 }}>
          <PulseDot color="#48D597"/>
          <span style={{ fontWeight: 600 }}>{ar ? "التدفق نشط" : "STREAM ACTIVE"}</span>
        </div>
        <span style={{ color: "var(--terminal-faint)" }}>|</span>
        <span style={{ color: "var(--terminal-muted)" }}>
          <LiveClock style={{ color: "var(--terminal-ink)" }}/>
          <span style={{ marginInlineStart: 6, opacity: 0.55 }}>BAGHDAD - UTC+3</span>
        </span>
        <span style={{ color: "var(--terminal-faint)" }}>|</span>
        <span style={{ color: "var(--terminal-muted)" }}>
          <span style={{ color: "var(--terminal-ink)", fontWeight: 600 }}>{kiosks.length}/{kiosks.length}</span> {ar ? "الأكشاك متصلة" : "KIOSKS ONLINE"}
        </span>
        <span style={{ color: "var(--terminal-faint)" }}>|</span>
        <span style={{ color: "var(--terminal-muted)" }}>
          <span style={{ color: "var(--terminal-ink)" }}>42</span>{ar ? " مللي ثانية زمن الاستجابة" : "ms LATENCY"}
        </span>
        <span style={{ flex: 1 }}/>
        <span className="ov-cursor" style={{ color: "var(--terminal-muted)" }}>
          {ar ? `يراقب ${kiosks.length} مواقع - ${feed.length} أحداث في الانتظار` : `watching ${kiosks.length} sites - ${feed.length} events buffered`}
        </span>
      </div>

      {/* KPI ribbon moved into the center column (compact stacked card above Live activity) */}

      {/* ============ Main grid ============ */}
      <div style={{
        display: "grid",
        // Narrow rank-list column (~30% slimmer than before) + very narrow live activity.
        // The right column absorbs the freed width so the sales flow chart can breathe.
        gridTemplateColumns: "minmax(190px, 0.6fr) minmax(190px, 0.45fr) 687.1875px",
        gap: 12, alignItems: "stretch",
        flex: 1, minHeight: 0,
      }}>
        {/* ---- LEFT column ---- */}
        <div className="col" style={{ gap: 10, minHeight: 0 }}>
          <div className="ov-section">
            <div className="ov-section-head">
              <div className="ov-section-title">
                <PulseDot color="var(--pos)"/>
                {ar ? "أعلى الأكشاك" : "Top performers"}
              </div>
              <span className="t-small subtle" style={{ fontSize: 10.5, fontFamily: "var(--font-mono)" }}>
                {ar ? "حسب الإيرادات" : `by revenue - ${scopeSubtitle}`}
              </span>
            </div>
            <div style={{ padding: 10 }}>
              <RankList
                items={topPerformers}
                rowHeight={32}
                renderRow={(k, idx) => {
                  const max = topPerformers[0].liveRev || 1;
                  const pct = (k.liveRev / max) * 100;
                  return (
                    <div className="ov-row">
                      <RankIndicator rank={idx}/>
                      <span className="ov-name">
                        <span style={{ fontSize: 12.5, fontWeight: 500 }}>{arTerm(lang, k.name)}</span>
                        <span className="swap-badge t-num" style={{ fontSize: 10, fontWeight: 600, color: "var(--pos)", fontFamily: "var(--font-mono)" }}>+</span>
                      </span>
                      <div className="ov-bar-track">
                        <div className="ov-bar-fill" style={{ width: `${pct}%`, background: idx === 0 ? "var(--pos)" : "var(--ink-2)" }}/>
                      </div>
                      <span className="t-num" style={{ fontSize: 12, fontFamily: "var(--font-mono)", fontWeight: 500, fontVariantNumeric: "tabular-nums", minWidth: 48, textAlign: "end" }}>
                        <TickerNum value={k.liveRev} format={(v) => fmtCompact(v)}/>
                      </span>
                    </div>
                  );
                }}
              />
            </div>
          </div>

          <div className="ov-section">
            <div className="ov-section-head">
              <div className="ov-section-title">
                <PulseDot color="var(--crit)"/>
                {ar ? "أولوية إعادة التزويد" : "Restock priority"}
              </div>
              <span className="t-small" style={{
                fontSize: 10, fontWeight: 600, fontFamily: "var(--font-mono)",
                color: "var(--crit)", letterSpacing: "0.08em",
              }}>{ar ? "تصرف الآن" : "ACT NOW"}</span>
            </div>
            <div style={{ padding: 10 }}>
              <RankList
                items={restockPriority}
                rowHeight={32}
                renderRow={(k, idx) => {
                  const pct = k.liveStock; // 0-100
                  const tone = pct < 30 ? "var(--crit)" : pct < 50 ? "var(--warn)" : "var(--pos)";
                  return (
                    <div className="ov-row">
                      <RankIndicator rank={idx}/>
                      <span className="ov-name">
                        <span style={{ fontSize: 12.5, fontWeight: 500 }}>{arTerm(lang, k.name)}</span>
                        <span className="swap-badge t-num" style={{ fontSize: 10, fontWeight: 600, color: tone, fontFamily: "var(--font-mono)" }}>!</span>
                      </span>
                      <div className="ov-bar-track">
                        <div className="ov-bar-fill" style={{ width: `${pct}%`, background: tone }}/>
                      </div>
                      <span className="t-num" style={{ fontSize: 12, fontFamily: "var(--font-mono)", fontWeight: 500, color: tone, fontVariantNumeric: "tabular-nums", minWidth: 40, textAlign: "end" }}>
                        <TickerNum value={pct} format={(v) => Math.round(v) + "%"}/>
                      </span>
                    </div>
                  );
                }}
              />
            </div>
          </div>

          <div className="ov-section">
            <div className="ov-section-head">
              <div className="ov-section-title">
                <PulseDot color="var(--pos)"/>
                {ar ? "أعلى المنتجات" : "Top products"}
              </div>
              <span className="t-small subtle" style={{ fontSize: 10.5, fontFamily: "var(--font-mono)" }}>
                {ar ? "حسب الإيرادات" : "by revenue"} - {scopeSubtitle}
              </span>
            </div>
            <div style={{ padding: 10 }}>
              <RankList
                items={topProducts}
                rowHeight={32}
                renderRow={(p, idx) => {
                  const max = topProducts[0].rev || 1;
                  const pct = (p.rev / max) * 100;
                  return (
                    <div className="ov-row">
                      <RankIndicator rank={idx}/>
                      <span className="ov-name">
                        <span style={{ fontSize: 12.5, fontWeight: 500 }}>{arTerm(lang, p.name)}</span>
                        <span className="swap-badge t-num" style={{ fontSize: 10, fontWeight: 600, color: "var(--pos)", fontFamily: "var(--font-mono)" }}>+</span>
                      </span>
                      <div className="ov-bar-track">
                        <div className="ov-bar-fill" style={{ width: `${pct}%`, background: idx === 0 ? "var(--accent)" : "var(--ink-2)" }}/>
                      </div>
                      <span className="t-num" style={{ fontSize: 12, fontFamily: "var(--font-mono)", fontWeight: 500, fontVariantNumeric: "tabular-nums", minWidth: 48, textAlign: "end" }}>
                        <TickerNum value={p.rev} format={(v) => fmtCompact(v)}/>
                      </span>
                    </div>
                  );
                }}
              />
            </div>
          </div>

          <div className="ov-section">
            <div className="ov-section-head">
              <div className="ov-section-title">
                <PulseDot color="var(--warn)"/>
                {ar ? "أعلى الهدر" : "Top waste"}
              </div>
              <span className="t-small subtle" style={{ fontSize: 10.5, fontFamily: "var(--font-mono)" }}>
                {ar ? "حسب التكلفة" : "by cost"} - {scopeSubtitle}
              </span>
            </div>
            <div style={{ padding: 10 }}>
              <RankList
                items={topWaste}
                rowHeight={32}
                renderRow={(w, idx) => {
                  const max = topWaste[0].cost || 1;
                  const pct = (w.cost / max) * 100;
                  return (
                    <div className="ov-row">
                      <RankIndicator rank={idx}/>
                      <span className="ov-name">
                        <span style={{ fontSize: 12.5, fontWeight: 500 }}>{arTerm(lang, w.name)}</span>
                        <span className="swap-badge t-num" style={{ fontSize: 10, fontWeight: 600, color: "var(--warn)", fontFamily: "var(--font-mono)" }}>!</span>
                      </span>
                      <div className="ov-bar-track">
                        <div className="ov-bar-fill" style={{ width: `${pct}%`, background: idx === 0 ? "var(--crit)" : "var(--warn)" }}/>
                      </div>
                      <span className="t-num" style={{ fontSize: 12, fontFamily: "var(--font-mono)", fontWeight: 500, color: "var(--crit)", fontVariantNumeric: "tabular-nums", minWidth: 48, textAlign: "end" }}>
                        <TickerNum value={w.cost} format={(v) => fmtCompact(v)}/>
                      </span>
                    </div>
                  );
                }}
              />
            </div>
          </div>
        </div>

        {/* ---- CENTER column: KPI summary card stacked above Live activity ---- */}
        <div className="col" style={{ gap: 10, minHeight: 0 }}>
          {/* KPI summary — was the full-width ribbon, now a single compact card */}
          <div className="ov-section">
            <div className="ov-section-head">
              <div className="ov-section-title">
                <PulseDot color="var(--accent)"/>
                {ar ? "المؤشرات" : "KPIs"}
              </div>
              <span className="t-small subtle" style={{ fontSize: 10.5, fontFamily: "var(--font-mono)" }}>
                {scopeSubtitle}
              </span>
            </div>
            <div>
              <div className="ov-kpi-row">
                <div>
                  <div className="ov-kpi-label">{ar ? `الإيرادات ${scopeSubtitle}` : `Total sales ${scopeSubtitle}`}</div>
                  <div className="ov-kpi-delta" style={{ color: sourceDriven ? "var(--ink-3)" : "var(--pos)" }}>{planDelta}</div>
                </div>
                <div className="ov-kpi-value">
                  <TickerNum value={totalRev} format={(v) => fmtIQD(v)}/>
                </div>
              </div>
              <div className="ov-kpi-row">
                <div>
                  <div className="ov-kpi-label">{ar ? "صافي الربح التقديري" : "Profit estimate"}</div>
                  <div className="ov-kpi-delta" style={{ color: grossProfitKnown ? "var(--pos)" : "var(--ink-3)" }}>{profitMarginDisplay}</div>
                </div>
                <div className="ov-kpi-value">
                  {grossProfitKnown && isFiniteNumber(grossProfit)
                    ? <TickerNum value={Number(grossProfit)} format={(v) => fmtIQD(v)}/>
                    : "—"}
                </div>
              </div>
              <div className="ov-kpi-row">
                <div>
                  <div className="ov-kpi-label">{ar ? "النقد المتوقع" : "Cash expected"}</div>
                  <div className="ov-kpi-delta" style={{ color: "var(--ink-3)" }}>{ar ? "إجمالي درج النقد" : "cash drawer total"}</div>
                </div>
                <div className="ov-kpi-value">
                  {cashExpectedKnown && isFiniteNumber(cashExpected)
                    ? <TickerNum value={Number(cashExpected)} format={(v) => fmtIQD(v)}/>
                    : "—"}
                </div>
              </div>
              <div className="ov-kpi-row">
                <div>
                  <div className="ov-kpi-label">{ar ? "المدفوعات الرقمية" : "Digital payments"}</div>
                  <div className="ov-kpi-delta" style={{ color: "var(--ink-3)" }}>{ar ? "بطاقة، QR، محفظة، يدوي" : "card, QR, wallet, manual"}</div>
                </div>
                <div className="ov-kpi-value">
                  {digitalPaymentsKnown && isFiniteNumber(digitalPayments)
                    ? <TickerNum value={Number(digitalPayments)} format={(v) => fmtIQD(v)}/>
                    : "—"}
                </div>
              </div>
              <div className="ov-kpi-row">
                <div>
                  <div className="ov-kpi-label">{ar ? "الأكشاك" : "Kiosk status"}</div>
                  <div className="ov-kpi-delta" style={{ color: lowStockAlerts == null ? "var(--ink-3)" : "var(--warn)" }}>{lowStockAlerts == null ? (ar ? "تنبيهات المخزون غير متاحة" : "Stock alerts not available yet") : (ar ? `${lowStockAlerts} تنبيهات مخزون منخفض` : `${lowStockAlerts} low-stock alerts`)}</div>
                </div>
                <div className="ov-kpi-value">{ar ? `${openKiosks} مفتوح / ${closedKiosks} مغلق` : `${openKiosks} open / ${closedKiosks} closed`}</div>
              </div>
              <div className="ov-kpi-row">
                <div>
                  <div className="ov-kpi-label">{ar ? "الطلبات" : "Orders"}</div>
                  <div className="ov-kpi-delta" style={{ color: "var(--ink-3)" }}>{ar ? "متوسط" : "avg"} {fmtIQD(totalRev/Math.max(1,totalOrders)).replace("IQD ", "")}</div>
                </div>
                <div className="ov-kpi-value">
                  <TickerNum value={totalOrders} format={(v) => fmtNum(Math.round(v))}/>
                </div>
              </div>
              <div className="ov-kpi-row">
                <div>
                  <div className="ov-kpi-label">{ar ? "الهدر" : "Waste"}</div>
                  <div className="ov-kpi-delta" style={{ color: wastePct == null ? "var(--ink-3)" : "var(--pos)" }}>{wastePct == null ? (ar ? "بانتظار بيانات الهدر" : "Awaiting engine waste totals") : (ar ? "+ الهدف ٤٪" : "+ target 4%")}</div>
                </div>
                <div className="ov-kpi-value">{wastePct == null ? "—" : `${wastePct.toFixed(1)}%`}</div>
              </div>
              <div className="ov-kpi-row">
                <div>
                  <div className="ov-kpi-label">{ar ? "الفرق" : "Variance"}</div>
                  <div className="ov-kpi-delta" style={{ color: unresolvedVariances == null ? "var(--ink-3)" : "var(--crit)" }}>{unresolvedVariances == null ? (ar ? "بانتظار تقفيلات موثقة" : "Awaiting verified closes") : (ar ? `${unresolvedVariances} إغلاقات غير محلولة` : `${unresolvedVariances} unresolved closes`)}</div>
                </div>
                <div className="ov-kpi-value" style={{ color: variancePct == null ? "var(--ink-3)" : "var(--crit)" }}>{variancePct == null ? "—" : `${variancePct.toFixed(1)}%`}</div>
              </div>
            </div>
          </div>

          {/* Live activity grows to fill the remaining height */}
          <div className="ov-section" style={{ display: "flex", flexDirection: "column", flex: 1, minHeight: 0 }}>
            <div className="ov-section-head">
              <div className="ov-section-title">
                <PulseDot color="var(--pos)"/>
                {ar ? "النشاط المباشر" : "Live activity"}
              </div>
              <span className="t-small subtle" style={{ fontSize: 10.5, fontFamily: "var(--font-mono)" }}>
                {ar ? "يتدفق عبر الأكشاك" : "streaming across kiosks"}
              </span>
            </div>
            <div style={{ overflow: "auto", flex: 1, minHeight: 0 }}>
              <LiveFeed events={feed} maxRows={14} ar={ar}/>
            </div>
          </div>
        </div>

        {/* ---- RIGHT column ---- */}
        <div className="col" style={{ gap: 12 }}>
          <div className="ov-top-analytics">
          <div className="ov-section qualified-lead-flow-panel">
            <div className="ov-section-head">
              <div className="ov-section-title">
                <span className="hourly-pulse-tone-dot" />
                {ar ? "تدفق المبيعات" : "Sales flow"}
              </div>
              <span className="t-small subtle" style={{ fontSize: 10.5, fontFamily: "var(--font-mono)" }}>
                {scopeSubtitle}
              </span>
            </div>
            <ScopedSalesFlowChart orders={flowOrders} scope={scope} ar={ar} />
          </div>

          <div className="ov-section">
            <div className="ov-section-head">
              <div className="ov-section-title">
                <PulseDot color="var(--chart-3)"/>
                {ar ? "مزيج الدفع" : "Payment mix"}
              </div>
              <span className="t-small subtle" style={{ fontSize: 10.5, fontFamily: "var(--font-mono)" }}>
                {ar ? `${paymentMixRows.length} مسارات` : `${paymentMixRows.length} rails`}
              </span>
            </div>
            <PaymentMixDonut
              rows={paymentMixRows}
              total={paymentMixTotal}
              centerLabel={ar ? "الإجمالي" : "Total"}
              centerValue={fmtCompact(paymentMixTotal)}
            />
          </div>
          </div>

          <div className="ov-section">
            <div className="ov-section-head">
              <div className="ov-section-title">
                <PulseDot color="var(--warn)"/>
                {ar ? "تنبيهات" : "Alerts"}
              </div>
              <span className="badge" style={{ height: 18, fontSize: 10 }}>{alertRows.length}</span>
            </div>
            <div>
              {alertRows.length ? alertRows.map((a, i) => (
                <div key={a.id} style={{
                  padding: "11px 14px",
                  borderBottom: i < alertRows.length - 1 ? "1px solid var(--line-soft)" : 0,
                  display: "flex", gap: 10, alignItems: "flex-start"
                }}>
                  <span className={`dot ${a.level}`} style={{ marginTop: 6, flexShrink: 0 }}></span>
                  <div style={{ flex: 1, minWidth: 0 }}>
                    <div style={{ fontWeight: 500, fontSize: 12.5, lineHeight: 1.35 }}>{arTerm(lang, a.title)}</div>
                    <div className="t-small subtle" style={{ fontSize: 11, marginTop: 3, lineHeight: 1.45 }}>{arTerm(lang, a.body)}</div>
                    <div className="t-small faint" style={{ fontSize: 10.5, marginTop: 5, fontFamily: "var(--font-mono)" }}>{arTerm(lang, a.time)}</div>
                  </div>
                </div>
              )) : (
                <div className="t-small muted" style={{ padding: "14px", lineHeight: 1.5 }}>
                  {arTerm(lang, "No verified alerts from the engine yet.")}
                </div>
              )}
            </div>
          </div>

          <div className="ov-section">
            <div className="ov-section-head">
              <div className="ov-section-title">
                <PulseDot color="var(--accent)"/>
                {ar ? "إجراءات تلقائية" : "Auto-actions"}
              </div>
              <span className="t-small subtle" style={{ fontSize: 10.5, fontFamily: "var(--font-mono)" }}>{ar ? "الطابور" : "queue"} - {actionRows.length}</span>
            </div>
            <div style={{ padding: "10px 14px" }}>
              {actionRows.length ? actionRows.map((a, i) => (
                <div key={i} className="row" style={{ padding: "8px 0", gap: 8, borderBottom: i < actionRows.length - 1 ? "1px solid var(--line-soft)" : 0 }}>
                  <span style={{
                    width: 14, height: 14, borderRadius: 3, flexShrink: 0,
                    background: a.ok ? "var(--pos-soft)" : "var(--warn-soft)",
                    color: a.ok ? "var(--pos)" : "var(--warn)",
                    display: "grid", placeItems: "center", fontSize: 10, fontWeight: 700,
                  }}>{a.ok ? "OK" : "?"}</span>
                  <div style={{ flex: 1, minWidth: 0 }}>
                    <div style={{ fontSize: 12, fontWeight: 500, lineHeight: 1.3 }}>{arTerm(lang, a.label)}</div>
                    <div className="t-small subtle" style={{ fontSize: 10.5 }}>{arTerm(lang, a.sub)}</div>
                  </div>
                </div>
              )) : (
                <div className="t-small muted" style={{ padding: "4px 0", lineHeight: 1.5 }}>
                  {arTerm(lang, "No automated actions without verified engine inputs.")}
                </div>
              )}
            </div>
          </div>

          <div className="ov-section">
            <div className="ov-section-head">
              <div className="ov-section-title">
                <PulseDot color="var(--ai)"/>
                {ar ? "ملخص الذكاء" : "AI summary"}
              </div>
              <span className="badge badge-ai" style={{ height: 18, fontSize: 10 }}>{ar ? "قابل للتتبع" : "traceable"}</span>
            </div>
            <div style={{ padding: "12px 14px" }}>
              <div className="ai-block">
                <div style={{ fontSize: 12.5, fontWeight: 500, lineHeight: 1.45 }}>
                  {sourceDriven
                    ? "No AI summary until verified engine rows are synced."
                    : ar ? MOCK.ai.varianceLead.headlineAr : MOCK.ai.varianceLead.headlineEn}
                </div>
                <div className="t-small muted" style={{ fontSize: 11, marginTop: 5, lineHeight: 1.45 }}>
                  {ar
                    ? "الأرقام مرتبطة بإغلاق الوردية ودفتر الاستهلاك. الذكاء لا يحسب الرقم الرسمي."
                    : "Numbers link back to shift close and the consumption ledger. AI does not compute the official total."}
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

// ---------- Seed initial activity feed ----------
function seedFeed(kiosks) {
  if (!kiosks?.length) return [];
  const items = [
    { name: "Orange Juice L", amt: 9000 },
    { name: "Mocha L - Cinnamon Roll", amt: 14000 },
    { name: "Iced Latte M - Pistachio Cake", amt: 19500 },
    { name: "Spanish Latte M - Tiramisu", amt: 19000 },
    { name: "Spanish Latte M - Tiramisu", amt: 19000 },
    { name: "Cold Brew L - Cheesecake", amt: 19500 },
    { name: "Iced Latte M - Pistachio Cake", amt: 19500 },
    { name: "Cold Brew L - Cheesecake", amt: 19500 },
    { name: "Mango Juice L", amt: 8500 },
  ];
  const now = Date.now();
  return items.map((it, i) => {
    const k = kiosks[i % kiosks.length];
    return {
      id: "ev-init-" + i,
      kid: k.id,
      kiosk: k.name,
      item: it.name,
      amount: it.amt,
      ago: i === 0 ? "now" : `${i * 6}s ago`,
      ts: now - i * 6000,
    };
  });
}


