              loadingThreads: ar ? "تحميل المحادثات" : "Loading threads",
              moreOptions: ar ? "خيارات إضافية" : "More options",
              newChat: ar ? "محادثة جديدة" : "New Chat",
              newThread: ar ? "محادثة جديدة" : "New Thread",
