// Commit context for the AI product draft. InsightsScreen provides the live
// gateway, toast, refresh, and the role gate so the form (rendered deep inside the
// artifact canvas) can confirm without threading props through every renderer.
const ProductDraftContext = React.createContext(null);

function productDraftSeed(proposal) {
  const p = proposal || {};
  const recipe = p.recipe || null;
  return {
    name: p.name || "",
    consumptionMode: ["recipe", "finished", "hybrid", "none"].includes(p.consumptionMode) ? p.consumptionMode : "recipe",
    uom: p.uom || "",
    category: p.category || "",
    listPrice: p.listPrice != null ? String(p.listPrice) : "",
    standardPrice: p.standardPrice != null ? String(p.standardPrice) : "",
    availableInPos: p.availableInPos !== false,
    sizes: Array.isArray(p.sizes) ? p.sizes.join(", ") : "",
    modifierGroups: Array.isArray(p.modifierGroups) ? p.modifierGroups : [],
    ingredientWarnings: Array.isArray(p.ingredientWarnings) ? p.ingredientWarnings : [],
    wasteAllowancePercent: recipe && recipe.wasteAllowancePercent != null ? String(recipe.wasteAllowancePercent) : "0",
    ingredients: recipe && Array.isArray(recipe.ingredients)
      ? recipe.ingredients.map((line) => ({
          // Prefer the resolvable default_code; the numeric id is only a fallback. The
          // backend resolves either, but sending the code avoids the numeric-id path.
          ingredientId: String(line.ingredientCode || line.ingredientId || ""),
          ingredientCode: String(line.ingredientCode || ""),
          ingredientName: line.ingredientName || line.ingredientCode || line.ingredientId || "",
          qty: line.qty != null ? String(line.qty) : "",
          uom: line.uom || "",
        }))
      : [],
  };
}

// AI-drafted, human-confirmed product + recipe creation. The AI only pre-fills the
// fields (productProposal); nothing is created until a human edits/reviews and clicks
// Confirm, which calls the deterministic, role-gated, audited /product_create_bundle
// route. The consumption mode is surfaced prominently with the AI's rationale because
// the wrong mode silently breaks accounting.
function AiProductDraftForm({ proposal, lang }) {
  const ar = lang === "ar";
  const ctx = React.useContext(ProductDraftContext) || {};
  const gateway = ctx.gateway;
  const showToast = ctx.showToast || (() => {});
  const ingredientOptions = Array.isArray(ctx.ingredientOptions) ? ctx.ingredientOptions : [];
  const canConfirm = ctx.canConfirm !== false; // default allow in demo; backend enforces in live
  const signature = useMemoIns(() => JSON.stringify(proposal || {}), [proposal]);
  const [form, setForm] = useStateIns(() => productDraftSeed(proposal));
  const [busy, setBusy] = useStateIns(false);
  const [created, setCreated] = useStateIns(null);
  const [image, setImage] = useStateIns(null); // { base64, mimeType, dataUrl, name }
  useEffectIns(() => {
    setForm(productDraftSeed(proposal));
    setCreated(null);
    setBusy(false);
    setImage(null);
  }, [signature]);

  if (!proposal) return null;

  const pickImage = async (file) => {
    if (!file) return;
    if (!/^image\//.test(file.type || "")) { showToast(ar ? "اختر ملف صورة" : "Please choose an image file", "warn"); return; }
    try {
      const base64 = await readFileAsBase64(file);
      const mimeType = file.type || "image/png";
      setImage({ base64, mimeType, dataUrl: `data:${mimeType};base64,${base64}`, name: file.name || "image" });
    } catch {
      showToast(ar ? "تعذّر قراءة الصورة" : "Could not read the image", "warn");
    }
  };

  // AI product photo draft: the backend builds the prompt from the product name and
  // returns base64 into the same image slot the manual upload uses — the human still
  // reviews it on the card and nothing is stored until Confirm.
  const [aiImageBusy, setAiImageBusy] = useStateIns(false);
  const generateImage = async () => {
    if (!form.name.trim()) { showToast(ar ? "اكتب اسم المنتج أولاً" : "Enter the product name first", "warn"); return; }
    if (!gateway?.generateProductImage) {
      showToast(ar ? "اربط الخلفية المباشرة لتوليد الصور" : "Connect the live backend to generate images", "warn");
      return;
    }
    setAiImageBusy(true);
    try {
      const result = unwrapOdoo(await gateway.generateProductImage({
        name: form.name.trim(),
        category: form.category.trim() || undefined,
      }));
      const base64 = result?.imageBase64;
      if (!base64) throw new Error(result?.error || (ar ? "تعذّر توليد الصورة" : "Could not generate the image"));
      const mimeType = result?.mimeType || "image/png";
      setImage({ base64, mimeType, dataUrl: `data:${mimeType};base64,${base64}`, name: ar ? "صورة مولّدة بالذكاء" : "AI-generated image" });
    } catch (error) {
      showToast(compactError(error) || (ar ? "تعذّر توليد الصورة" : "Could not generate the image"), "warn");
    } finally {
      setAiImageBusy(false);
    }
  };

  const requiresRecipe = form.consumptionMode === "recipe" || form.consumptionMode === "hybrid";
  const set = (key, value) => setForm((prev) => ({ ...prev, [key]: value }));
  const setIngredient = (idx, key, value) => setForm((prev) => ({
    ...prev,
    ingredients: prev.ingredients.map((line, i) => (i === idx ? { ...line, [key]: value } : line)),
  }));
  const removeIngredient = (idx) => setForm((prev) => ({
    ...prev,
    ingredients: prev.ingredients.filter((_, i) => i !== idx),
  }));

  const inputStyle = { width: "100%", height: 30, padding: "0 8px", border: "1px solid var(--line)", borderRadius: 5, background: "var(--bg)", color: "var(--ink-1)", fontSize: 12.5 };
  const labelStyle = { fontSize: 11, fontWeight: 600, marginBottom: 4, display: "block" };
  const MODE_LABELS = {
    recipe: ar ? "وصفة (يخصم المكونات)" : "Recipe (deduct ingredients)",
    finished: ar ? "منتج جاهز للبيع" : "Finished good",
    hybrid: ar ? "هجين (الاثنان)" : "Hybrid (both)",
    none: ar ? "خدمة / بدون مخزون" : "Service / none",
  };

  const confirm = async () => {
    if (!form.name.trim()) { showToast(ar ? "اسم المنتج مطلوب" : "Product name is required", "warn"); return; }
    const cleanIngredients = form.ingredients.filter((line) => line.ingredientId && Number(line.qty) > 0);
    if (requiresRecipe && cleanIngredients.length === 0) {
      showToast(ar ? "الوصفة تحتاج مكوناً واحداً على الأقل بكمية صحيحة" : "A recipe product needs at least one ingredient with a quantity", "warn");
      return;
    }
    if (!gateway?.createProductBundle) {
      showToast(ar ? "اربط الخلفية المباشرة أولاً لإنشاء المنتجات" : "Connect the live backend to create products", "warn");
      return;
    }
    const payload = {
      name: form.name.trim(),
      consumptionMode: form.consumptionMode,
      uom: form.uom.trim() || undefined,
      category: form.category.trim() || undefined,
      listPrice: Number(form.listPrice || 0),
      standardPrice: Number(form.standardPrice || 0),
      availableInPos: form.availableInPos,
      sizes: form.sizes.split(",").map((s) => s.trim()).filter(Boolean),
      modifierGroups: Array.isArray(form.modifierGroups) ? form.modifierGroups : [],
      imageBase64: image?.base64 || undefined,
      imageMimeType: image?.mimeType || undefined,
      recipe: requiresRecipe
        ? {
            wasteAllowancePercent: Number(form.wasteAllowancePercent || 0),
            ingredients: cleanIngredients.map((line) => ({ ingredientId: line.ingredientId, qty: Number(line.qty), uom: line.uom || undefined })),
          }
        : undefined,
    };
    setBusy(true);
    try {
      const result = unwrapOdoo(await gateway.createProductBundle(payload));
      setCreated(result || { ok: true });
      showToast(ar ? `تم إنشاء المنتج: ${form.name.trim()}` : `Product created: ${form.name.trim()}`, "success");
      await ctx.refreshOdoo?.();
    } catch (error) {
      showToast(compactError(error) || (ar ? "تعذر إنشاء المنتج" : "Could not create product"), "warn");
    } finally {
      setBusy(false);
    }
  };

  if (created) {
    return (
      <div className="ins-card" style={{ display: "grid", gap: 8, placeItems: "center", textAlign: "center", padding: "28px 18px" }}>
        <Icon name="check" size={20}/>
        <div style={{ fontSize: 15, fontWeight: 600 }}>{ar ? "تم إنشاء المنتج" : "Product created"}</div>
        <div className="t-small subtle" style={{ maxWidth: 360, lineHeight: 1.5 }}>
          {ar
            ? `${form.name.trim()} أُنشئ في المحرك${created.recipe_state ? ` ووصفته ${created.recipe_state}` : ""}. يظهر الحدث في السجل الفوري.`
            : `${form.name.trim()} was created in the engine${created.recipe_state ? `, recipe ${created.recipe_state}` : ""}. The event appears in the realtime audit log.`}
        </div>
      </div>
    );
  }

  return (
    <div className="ins-card" style={{ display: "grid", gap: 12 }}>
      <div className="row" style={{ gap: 6, flexWrap: "wrap" }}>
        <span className="badge" style={{ height: 18, fontSize: 10 }}>{aiCanvasText(lang, "human-confirm")}</span>
        <span className="t-small subtle" style={{ fontSize: 11, lineHeight: 1.5 }}>
          {ar ? "الذكاء جهّز هذه المسودة فقط — لا يُنشأ شيء حتى تراجع وتؤكد." : "The AI only drafted this — nothing is created until you review and confirm."}
        </span>
      </div>

      {Array.isArray(form.ingredientWarnings) && form.ingredientWarnings.length > 0 && (
        <div style={{ border: "1px solid var(--warn, #b45309)", background: "rgba(180,83,9,0.08)", borderRadius: 6, padding: "8px 10px", display: "grid", gap: 4 }}>
          <div className="row" style={{ gap: 6, alignItems: "center" }}>
            <Icon name="flag" size={14}/>
            <strong style={{ fontSize: 12 }}>{ar ? "تنبيه عن المكونات" : "Ingredient notice"}</strong>
          </div>
          {form.ingredientWarnings.map((w, i) => (
            <div key={i} className="t-small" style={{ fontSize: 11, lineHeight: 1.5 }}>
              {w.status === "substituted"
                ? (ar
                    ? `«${w.requested}» غير موجود في الكتالوج — استبدله الذكاء بـ ${w.substitutedWithCode || "بديل"}. تحقّق قبل التأكيد.`
                    : `"${w.requested}" is not in your catalog — the AI substituted ${w.substitutedWithCode || "an alternative"}. Verify before confirming.`)
                : (ar
                    ? `«${w.requested}» غير موجود في الكتالوج. ${w.note || "أضِفه كمكوّن أولاً أو عدّل الوصفة."}`
                    : `"${w.requested}" is not in your catalog. ${w.note || "Add it as an ingredient first, or edit the recipe."}`)}
            </div>
          ))}
        </div>
      )}

      {/* Image hero: the product photo owns the left half of the row; name +
          generate/upload controls own the right half. The pane doubles as the
          dropzone/upload target and shows a spinner overlay while generating. */}
      <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 12, alignItems: "stretch" }}>
        <label
          onDragOver={(e) => e.preventDefault()}
          onDrop={(e) => { e.preventDefault(); if (!aiImageBusy) pickImage(e.dataTransfer?.files?.[0]); }}
          style={{ position: "relative", display: "grid", placeItems: "center", aspectRatio: "1 / 1", minHeight: 150, border: image ? "1px solid var(--line)" : "1px dashed var(--line)", borderRadius: 8, overflow: "hidden", cursor: aiImageBusy ? "progress" : "pointer", background: "var(--surface-sunk)" }}
        >
          {image && (
            <img src={image.dataUrl} alt="" style={{ position: "absolute", inset: 0, width: "100%", height: "100%", objectFit: "cover" }}/>
          )}
          {aiImageBusy ? (
            <>
              <span style={{ position: "absolute", inset: 0, background: "var(--surface)", opacity: 0.78 }}/>
              <span style={{ position: "relative", display: "grid", gap: 8, placeItems: "center", textAlign: "center", padding: 10 }}>
                <span className="assistant-artifact-loader-icon"/>
                <span className="t-small" style={{ fontSize: 11.5, fontWeight: 600 }}>{ar ? "جارٍ توليد الصورة…" : "Generating image…"}</span>
              </span>
            </>
          ) : !image && (
            <span className="t-small subtle" style={{ fontSize: 11.5, textAlign: "center", lineHeight: 1.6, padding: 12 }}>
              {ar ? "لا توجد صورة بعد — اسحب صورة هنا أو انقر للاختيار" : "No image yet — drag one here or click to choose"}
            </span>
          )}
          <input type="file" accept="image/*" style={{ display: "none" }} disabled={aiImageBusy} onChange={(e) => pickImage(e.target.files?.[0])}/>
        </label>

        <div style={{ display: "grid", gap: 8, alignContent: "start" }}>
          <div>
            <label style={labelStyle}>{ar ? "اسم المنتج" : "Product name"}</label>
            <input style={inputStyle} value={form.name} onChange={(e) => set("name", e.target.value)} placeholder={ar ? "مثال: عصير مانجو" : "e.g. Mango Smoothie"}/>
          </div>
          <span className="t-small subtle" style={{ fontSize: 11, lineHeight: 1.5 }}>
            {ar ? "ولّد صورة المنتج من الاسم بالذكاء، أو ارفع صورتك الخاصة." : "Generate a product photo from the name with AI, or upload your own."}
          </span>
          <button type="button" className="btn btn-accent" style={{ height: 30, fontSize: 12 }} disabled={aiImageBusy} onClick={generateImage}>
            {aiImageBusy
              ? (ar ? "جارٍ توليد الصورة…" : "Generating image…")
              : image
                ? (ar ? "إعادة التوليد بالذكاء" : "Regenerate with AI")
                : (ar ? "توليد صورة بالذكاء" : "Generate image with AI")}
          </button>
          {image && !aiImageBusy && (
            <button type="button" className="btn btn-ghost" style={{ height: 28, fontSize: 11.5 }} onClick={() => setImage(null)}>
              {ar ? "إزالة الصورة" : "Remove image"}
            </button>
          )}
          {image?.name && !aiImageBusy && (
            <span className="t-small subtle" style={{ fontSize: 10.5, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>{image.name}</span>
          )}
        </div>
      </div>

      <div style={{ border: "1px solid var(--line-soft)", borderRadius: 6, padding: 10, display: "grid", gap: 8 }}>
        <div>
          <label style={labelStyle}>{ar ? "وضع الاستهلاك (يؤثر على المحاسبة)" : "Consumption mode (affects accounting)"}</label>
          <select style={inputStyle} value={form.consumptionMode} onChange={(e) => set("consumptionMode", e.target.value)}>
            {Object.keys(MODE_LABELS).map((key) => (<option key={key} value={key}>{MODE_LABELS[key]}</option>))}
          </select>
        </div>
        {proposal.modeRationale && (
          <div className="t-small subtle" style={{ fontSize: 11, lineHeight: 1.5 }}>
            <strong>{ar ? "سبب الذكاء: " : "AI rationale: "}</strong>{proposal.modeRationale}
          </div>
        )}
      </div>

      <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 8 }}>
        <div>
          <label style={labelStyle}>{ar ? "وحدة القياس" : "Unit of measure"}</label>
          <input style={inputStyle} value={form.uom} onChange={(e) => set("uom", e.target.value)} placeholder={ar ? "Units" : "Units"}/>
        </div>
        <div>
          <label style={labelStyle}>{ar ? "الفئة" : "Category"}</label>
          <input style={inputStyle} value={form.category} onChange={(e) => set("category", e.target.value)}/>
        </div>
        <div>
          <label style={labelStyle}>{ar ? "سعر البيع" : "Sale price"}</label>
          <input style={inputStyle} type="number" value={form.listPrice} onChange={(e) => set("listPrice", e.target.value)}/>
        </div>
        <div>
          <label style={labelStyle}>{ar ? "التكلفة" : "Unit cost"}</label>
          <input style={inputStyle} type="number" value={form.standardPrice} onChange={(e) => set("standardPrice", e.target.value)}/>
        </div>
      </div>

      <div>
        <label style={labelStyle}>{ar ? "الأحجام (افصل بفاصلة)" : "Sizes (comma-separated)"}</label>
        <input style={inputStyle} value={form.sizes} onChange={(e) => set("sizes", e.target.value)} placeholder={ar ? "صغير، وسط، كبير" : "Small, Medium, Large"}/>
      </div>

      <label className="row" style={{ gap: 6, fontSize: 12 }}>
        <input type="checkbox" checked={form.availableInPos} onChange={(e) => set("availableInPos", e.target.checked)}/>
        {ar ? "متاح في نقطة البيع" : "Available in POS"}
      </label>

      {requiresRecipe && (
        <div style={{ border: "1px solid var(--line-soft)", borderRadius: 6, padding: 10, display: "grid", gap: 8 }}>
          <div className="between">
            <div style={{ fontSize: 12, fontWeight: 600 }}>{ar ? "الوصفة (المكونات تُخصم من المخزون)" : "Recipe (ingredients deducted from stock)"}</div>
            <input style={{ ...inputStyle, width: 92, height: 26 }} type="number" value={form.wasteAllowancePercent} onChange={(e) => set("wasteAllowancePercent", e.target.value)} title={ar ? "نسبة الهدر %" : "Waste allowance %"} placeholder="%"/>
          </div>
          {form.ingredients.length === 0 ? (
            <div className="t-small subtle" style={{ fontSize: 11 }}>{ar ? "لا توجد مكونات في المسودة." : "No ingredients in the draft."}</div>
          ) : form.ingredients.map((line, idx) => (
            <div key={`${line.ingredientId}-${idx}`} className="row" style={{ gap: 6, alignItems: "center" }}>
              {ingredientOptions.length > 0 ? (
                // Editable picker so a reviewer can correct a wrong AI ingredient pick,
                // not just delete the line. Option value is the resolvable default_code.
                <select
                  style={{ ...inputStyle, flex: 1, minWidth: 0 }}
                  value={line.ingredientId}
                  onChange={(e) => {
                    const opt = ingredientOptions.find((o) => o.value === e.target.value);
                    setForm((prev) => ({
                      ...prev,
                      ingredients: prev.ingredients.map((l, i) => (i === idx ? {
                        ...l,
                        ingredientId: e.target.value,
                        ingredientCode: e.target.value,
                        ingredientName: opt ? opt.label : l.ingredientName,
                        uom: l.uom || (opt ? opt.unit : ""),
                      } : l)),
                    }));
                  }}
                >
                  {line.ingredientId && !ingredientOptions.some((o) => o.value === line.ingredientId) && (
                    <option value={line.ingredientId}>{line.ingredientName || line.ingredientId}</option>
                  )}
                  {ingredientOptions.map((opt) => (
                    <option key={opt.value} value={opt.value}>{opt.label}</option>
                  ))}
                </select>
              ) : (
                <span className="t-small" style={{ flex: 1, minWidth: 0, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap", fontSize: 12 }}>{line.ingredientName}</span>
              )}
              <input style={{ ...inputStyle, width: 72 }} type="number" value={line.qty} onChange={(e) => setIngredient(idx, "qty", e.target.value)} placeholder={ar ? "كمية" : "qty"}/>
              <input style={{ ...inputStyle, width: 64 }} value={line.uom} onChange={(e) => setIngredient(idx, "uom", e.target.value)} placeholder="uom"/>
              <button type="button" className="btn btn-ghost" style={{ height: 26, fontSize: 11 }} onClick={() => removeIngredient(idx)} title={ar ? "حذف" : "Remove"}>×</button>
            </div>
          ))}
          {ingredientOptions.length > 0 && (
            // Lets the reviewer add a recipe line — essential when the AI flagged a
            // missing ingredient and left the recipe empty, or to add more lines.
            <button
              type="button"
              className="btn btn-ghost"
              style={{ height: 28, fontSize: 11.5, justifySelf: "start" }}
              onClick={() => {
                const first = ingredientOptions[0];
                setForm((prev) => ({
                  ...prev,
                  ingredients: [...prev.ingredients, {
                    ingredientId: first ? first.value : "",
                    ingredientCode: first ? first.value : "",
                    ingredientName: first ? first.label : "",
                    qty: "",
                    uom: first ? first.unit : "",
                  }],
                }));
              }}
            >
              + {ar ? "إضافة مكوّن" : "Add ingredient"}
            </button>
          )}
        </div>
      )}

      {!canConfirm && (
        <div className="t-small subtle" style={{ fontSize: 11, lineHeight: 1.5 }}>
          {ar ? "إنشاء المنتجات يتطلب صلاحية مدير. راجع المسودة وأرسلها إلى مدير لتأكيدها." : "Creating products requires manager rights. Review the draft and hand it to a manager to confirm."}
        </div>
      )}

      <div className="between" style={{ marginTop: 2 }}>
        <span className="t-small subtle" style={{ fontSize: 10.5 }}>
          {ar ? "التأكيد ينشئ عبر مسار مؤمَّن ومُدقَّق" : "Confirm commits via a guarded, audited route"}
        </span>
        <button type="button" className="btn btn-primary" style={{ height: 32, fontSize: 12.5 }} disabled={busy || !canConfirm} onClick={confirm}>
          {busy ? (ar ? "جارٍ الإنشاء…" : "Creating…") : (ar ? "تأكيد وإنشاء المنتج" : "Confirm & create product")}
        </button>
      </div>
    </div>
  );
}

// Commit context for the AI invoice scan. InsightsScreen provides the live
// gateway, toast, refresh, role gate, plus the warehouses and product catalog the
// form needs (it renders deep inside the artifact canvas).
const InvoiceDraftContext = React.createContext(null);

function invoiceDraftSeed(proposal) {
  const p = proposal || {};
  const supplier = p.supplier || {};
  return {
    supplierName: supplier.name || "",
    supplierAddress: supplier.address || "",
    supplierCategory: supplier.category || "",
    invoiceRef: p.invoiceRef || "",
    invoiceDate: p.invoiceDate || "",
    warehouseId: "",
    lines: Array.isArray(p.lines)
      ? p.lines.map((line) => ({
          description: line.description || "",
          productId: line.matchedProductId || "",
          productName: line.matchedProductName || "",
          qty: line.qty != null ? String(line.qty) : "",
          unitPrice: line.unitPrice != null ? String(line.unitPrice) : "",
        }))
      : [],
  };
}

// AI-drafted, human-confirmed supplier-invoice intake. The AI only transcribed the
// photo; nothing is created until the human verifies the figures against the shown
// image, maps/creates every line to a real product, and clicks Confirm — which
// calls the deterministic /invoice_commit route (supplier + PO + warehouse receipt
// in one atomic transaction). Numbers are editable drafts; Odoo computes the
// official totals and stock valuation.
function AiInvoiceDraftForm({ proposal, scannedImage, lang }) {
  const ar = lang === "ar";
  const ctx = React.useContext(InvoiceDraftContext) || {};
  const gateway = ctx.gateway;
  const showToast = ctx.showToast || (() => {});
  const canConfirm = ctx.canConfirm !== false;
  const warehouses = Array.isArray(ctx.warehouses) ? ctx.warehouses : [];
  const signature = useMemoIns(() => JSON.stringify(proposal || {}), [proposal]);
  const [form, setForm] = useStateIns(() => invoiceDraftSeed(proposal));
  const [catalog, setCatalog] = useStateIns(() => (Array.isArray(ctx.catalog) ? ctx.catalog : []));
  const [busy, setBusy] = useStateIns(false);
  const [created, setCreated] = useStateIns(null);
  useEffectIns(() => {
    setForm(invoiceDraftSeed(proposal));
    setCatalog(Array.isArray(ctx.catalog) ? ctx.catalog : []);
    setCreated(null);
    setBusy(false);
  }, [signature]);

  if (!proposal) return null;

  const inputStyle = { width: "100%", height: 30, padding: "0 8px", border: "1px solid var(--line)", borderRadius: 5, background: "var(--bg)", color: "var(--ink-1)", fontSize: 12.5 };
  const labelStyle = { fontSize: 11, fontWeight: 600, marginBottom: 4, display: "block" };

  if (proposal.extractable === false) {
    return (
      <div className="ins-card" style={{ display: "grid", gap: 10, placeItems: "center", textAlign: "center", padding: "26px 18px" }}>
        <Icon name="alert-triangle" size={20}/>
        <div style={{ fontSize: 15, fontWeight: 600 }}>{ar ? "تعذّرت قراءة الفاتورة" : "Couldn't read the invoice"}</div>
        <div className="t-small subtle" style={{ maxWidth: 360, lineHeight: 1.5 }}>
          {ar ? "التقط صورة أوضح للفاتورة وحاول مرة أخرى." : "Take a clearer, well-lit photo of the invoice and try again."}
        </div>
      </div>
    );
  }

  const set = (key, value) => setForm((prev) => ({ ...prev, [key]: value }));
  const setLine = (idx, key, value) => setForm((prev) => ({
    ...prev,
    lines: prev.lines.map((line, i) => (i === idx ? { ...line, [key]: value } : line)),
  }));
  const removeLine = (idx) => setForm((prev) => ({ ...prev, lines: prev.lines.filter((_, i) => i !== idx) }));

  const createItemForLine = async (idx) => {
    const line = form.lines[idx];
    const name = (line.description || "").trim();
    if (!name) { showToast(ar ? "وصف الصنف مطلوب" : "Item description is required", "warn"); return; }
    if (!gateway?.createStockItem) { showToast(ar ? "اربط الخلفية المباشرة" : "Connect the live backend", "warn"); return; }
    try {
      const result = unwrapOdoo(await gateway.createStockItem({ name, uom: "Units", consumptionMode: "none", availableInPos: false }));
      const product = result?.product || {};
      const id = String(product.id ?? product.default_code ?? name);
      setCatalog((prev) => [...prev, { id, code: product.default_code || "", name: product.name || name, uom: product.uom || "Units" }]);
      setForm((prev) => ({
        ...prev,
        lines: prev.lines.map((l, i) => (i === idx ? { ...l, productId: id, productName: product.name || name } : l)),
      }));
      showToast(ar ? `تم إنشاء ${name}` : `Created ${name}`, "success");
    } catch (error) {
      showToast(compactError(error) || (ar ? "تعذّر إنشاء الصنف" : "Could not create item"), "warn");
    }
  };

  const confirm = async () => {
    if (!form.supplierName.trim()) { showToast(ar ? "اسم المورد مطلوب" : "Supplier name is required", "warn"); return; }
    const linesReady = form.lines.filter((l) => l.productId && Number(l.qty) > 0);
    const unmatched = form.lines.some((l) => Number(l.qty) > 0 && !l.productId);
    if (unmatched) { showToast(ar ? "طابق أو أنشئ كل بند قبل الاستلام" : "Map or create every line before receiving", "warn"); return; }
    if (linesReady.length === 0) { showToast(ar ? "طابق صنفاً واحداً على الأقل بكمية صحيحة" : "Match at least one line to a product with a quantity", "warn"); return; }
    if (!gateway?.commitInvoice) { showToast(ar ? "اربط الخلفية المباشرة لاستلام الفواتير" : "Connect the live backend to receive invoices", "warn"); return; }
    setBusy(true);
    try {
      const result = unwrapOdoo(await gateway.commitInvoice({
        supplier: {
          name: form.supplierName.trim(),
          address: form.supplierAddress.trim() || undefined,
          category: form.supplierCategory.trim() || undefined,
        },
        warehouse: form.warehouseId ? (Number(form.warehouseId) || form.warehouseId) : undefined,
        invoiceRef: form.invoiceRef.trim() || undefined,
        invoiceDate: form.invoiceDate?.trim() || undefined,
        currency: proposal.currency || undefined,
        invoiceName: scannedImage?.name || "invoice",
        invoiceFileBase64: scannedImage?.base64 || undefined,
        invoiceMimeType: scannedImage?.mimeType || undefined,
        lines: linesReady.map((l) => ({ productId: l.productId, qty: Number(l.qty), unitPrice: Number(l.unitPrice || 0) })),
      }));
      setCreated(result || { ok: true });
      showToast(ar ? `تم استلام الفاتورة: ${result?.name || form.supplierName.trim()}` : `Invoice received: ${result?.name || form.supplierName.trim()}`, "success");
      await ctx.refreshOdoo?.();
    } catch (error) {
      showToast(compactError(error) || (ar ? "تعذّر استلام الفاتورة" : "Could not receive invoice"), "warn");
    } finally {
      setBusy(false);
    }
  };

  if (created) {
    return (
      <div className="ins-card" style={{ display: "grid", gap: 8, placeItems: "center", textAlign: "center", padding: "28px 18px" }}>
        <Icon name="check" size={20}/>
        <div style={{ fontSize: 15, fontWeight: 600 }}>{ar ? "تم استلام الفاتورة" : "Invoice received"}</div>
        <div className="t-small subtle" style={{ maxWidth: 380, lineHeight: 1.5 }}>
          {ar
            ? `${created.name || form.supplierName.trim()} — أُنشئ المورد وأمر الشراء وزاد مخزون المستودع${created.receipt_state ? ` (الاستلام ${created.receipt_state})` : ""}. يظهر الحدث في السجل الفوري.`
            : `${created.name || form.supplierName.trim()} — supplier + purchase order created and warehouse stock received${created.receipt_state ? ` (receipt ${created.receipt_state})` : ""}. The event appears in the realtime audit log.`}
        </div>
      </div>
    );
  }

  const totals = proposal.totals || {};

  return (
    <div className="ins-card" style={{ display: "grid", gap: 12 }}>
      <div className="row" style={{ gap: 6, flexWrap: "wrap" }}>
        <span className="badge" style={{ height: 18, fontSize: 10 }}>{aiCanvasText(lang, "human-confirm")}</span>
        <span className="t-small subtle" style={{ fontSize: 11, lineHeight: 1.5 }}>
          {ar ? "الذكاء نسخ الفاتورة فقط — تحقّق من الأرقام مقابل الصورة قبل الاستلام." : "The AI only transcribed the invoice — verify the figures against the image before receiving."}
        </span>
      </div>

      <div style={{ display: "grid", gridTemplateColumns: "minmax(180px, 1fr) minmax(0, 1.3fr)", gap: 12, alignItems: "start" }}>
        <div style={{ border: "1px solid var(--line-soft)", borderRadius: 6, padding: 6, position: "sticky", top: 0 }}>
          {scannedImage?.dataUrl ? (
            <img src={scannedImage.dataUrl} alt={ar ? "الفاتورة الممسوحة" : "Scanned invoice"} style={{ width: "100%", maxHeight: 360, objectFit: "contain", borderRadius: 4, display: "block" }}/>
          ) : (
            <div className="t-small subtle" style={{ padding: 16, textAlign: "center" }}>{ar ? "لا توجد صورة" : "No image"}</div>
          )}
        </div>

        <div style={{ display: "grid", gap: 8 }}>
          <div>
            <label style={labelStyle}>{ar ? "اسم المورد" : "Supplier name"}</label>
            <input style={inputStyle} value={form.supplierName} onChange={(e) => set("supplierName", e.target.value)}/>
          </div>
          <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 8 }}>
            <div>
              <label style={labelStyle}>{ar ? "العنوان" : "Address"}</label>
              <input style={inputStyle} value={form.supplierAddress} onChange={(e) => set("supplierAddress", e.target.value)}/>
            </div>
            <div>
              <label style={labelStyle}>{ar ? "الفئة" : "Category"}</label>
              <input style={inputStyle} value={form.supplierCategory} onChange={(e) => set("supplierCategory", e.target.value)}/>
            </div>
            <div>
              <label style={labelStyle}>{ar ? "مرجع الفاتورة" : "Invoice ref"}</label>
              <input style={inputStyle} value={form.invoiceRef} onChange={(e) => set("invoiceRef", e.target.value)}/>
            </div>
            <div>
              <label style={labelStyle}>{ar ? "المستودع" : "Warehouse"}</label>
              <select style={inputStyle} value={form.warehouseId} onChange={(e) => set("warehouseId", e.target.value)}>
                <option value="">{ar ? "الافتراضي" : "Default"}</option>
                {warehouses.map((wh) => (<option key={String(wh.id ?? wh.code)} value={String(wh.id ?? wh.code)}>{wh.name || wh.code}</option>))}
              </select>
            </div>
          </div>
        </div>
      </div>

      <div style={{ border: "1px solid var(--line-soft)", borderRadius: 6, padding: 10, display: "grid", gap: 8 }}>
        <div style={{ fontSize: 12, fontWeight: 600 }}>{ar ? "البنود (تُضاف إلى مخزون المستودع)" : "Line items (added to warehouse stock)"}</div>
        {form.lines.length === 0 ? (
          <div className="t-small subtle" style={{ fontSize: 11 }}>{ar ? "لم تُستخرج أي بنود." : "No line items were extracted."}</div>
        ) : form.lines.map((line, idx) => (
          <div key={idx} style={{ display: "grid", gap: 4, borderBottom: "1px solid var(--line-soft)", paddingBottom: 6 }}>
            <div className="t-small" style={{ fontSize: 11.5 }}>{line.description || (ar ? "بند" : "Line")}</div>
            <div className="row" style={{ gap: 6, alignItems: "center", flexWrap: "wrap" }}>
              <select style={{ ...inputStyle, flex: 1, minWidth: 140 }} value={line.productId} onChange={(e) => {
                const id = e.target.value;
                const match = catalog.find((p) => String(p.id) === id);
                setLine(idx, "productId", id);
                setLine(idx, "productName", match?.name || "");
              }}>
                <option value="">{ar ? "اختر منتجاً…" : "Select product…"}</option>
                {catalog.map((p) => (<option key={String(p.id)} value={String(p.id)}>{p.name}{p.code ? ` (${p.code})` : ""}</option>))}
              </select>
              {!line.productId && (
                <button type="button" className="btn btn-ghost" style={{ height: 28, fontSize: 11 }} onClick={() => createItemForLine(idx)} title={ar ? "إنشاء صنف من الوصف" : "Create item from description"}>
                  {ar ? "+ صنف" : "+ item"}
                </button>
              )}
              <input style={{ ...inputStyle, width: 72 }} type="number" value={line.qty} onChange={(e) => setLine(idx, "qty", e.target.value)} placeholder={ar ? "كمية" : "qty"}/>
              <input style={{ ...inputStyle, width: 84 }} type="number" value={line.unitPrice} onChange={(e) => setLine(idx, "unitPrice", e.target.value)} placeholder={ar ? "سعر" : "price"}/>
              <button type="button" className="btn btn-ghost" style={{ height: 28, fontSize: 11 }} onClick={() => removeLine(idx)} title={ar ? "حذف" : "Remove"}>×</button>
            </div>
          </div>
        ))}
        {(Number(totals.total) > 0 || Number(totals.subtotal) > 0) && (
          <div className="t-small subtle" style={{ fontSize: 10.5 }}>
            {ar ? "إجمالي الفاتورة المنسوخ (للمراجعة فقط): " : "Transcribed invoice total (for cross-check only): "}
            {Number(totals.total || totals.subtotal || 0).toLocaleString("en")} {proposal.currency || ""}
          </div>
        )}
      </div>

      {!canConfirm && (
        <div className="t-small subtle" style={{ fontSize: 11, lineHeight: 1.5 }}>
          {ar ? "استلام الفواتير يتطلب صلاحية لوجستيات أو مدير." : "Receiving invoices requires logistics or manager rights."}
        </div>
      )}

      <div className="between" style={{ marginTop: 2 }}>
        <span className="t-small subtle" style={{ fontSize: 10.5 }}>
          {ar ? "التأكيد ينشئ المورد وأمر الشراء ويستلم المخزون" : "Confirm creates supplier + PO and receives stock"}
        </span>
        <button type="button" className="btn btn-primary" style={{ height: 32, fontSize: 12.5 }} disabled={busy || !canConfirm} onClick={confirm}>
          {busy ? (ar ? "جارٍ الاستلام…" : "Receiving…") : (ar ? "تأكيد واستلام" : "Confirm & receive")}
        </button>
      </div>
    </div>
  );
}

function BayaanAssistantArtifactCanvas({ artifact, pending, selectedItemId, stage, lang, onExport }) {
  const selected = assistantArtifactSelectedItem(artifact, selectedItemId, lang);
  const itemCount = assistantArtifactItems(artifact, lang).length;
  return (
    <section className="bayaan-assistant-artifact-pane" aria-live="polite" dir={lang === "ar" ? "rtl" : "ltr"}>
      {pending && !artifact ? (
        <AssistantArtifactPreparing lang={lang} stage={stage || "thinking"} hasText={false}/>
      ) : selected ? (
        <>
          <div className="bayaan-assistant-artifact-head">
            <div>
              <div className="bayaan-assistant-artifact-kicker">{aiCanvasText(lang, "Selected artifact")}</div>
              <div className="bayaan-assistant-artifact-title">{selected.title}</div>
              <div className="bayaan-assistant-artifact-meta">{selected.meta} · {selected.detail}</div>
            </div>
            <div className="row" style={{ gap: 8, alignItems: "center" }}>
              {itemCount > 1 && (
                <span className="badge badge-ai" style={{ height: 22, fontSize: 10.5 }}>
                  {itemCount} {aiCanvasText(lang, "artifacts")}
                </span>
              )}
              {onExport && assistantArtifactHasCanvas(artifact) && (
                <button
                  type="button"
                  className="btn btn-ghost"
                  style={{ height: 26, fontSize: 11.5 }}
                  onClick={() => onExport({ mode: "artifact", turns: [{ artifact }] })}
                  title={lang === "ar" ? "تصدير هذا التحليل كـ PDF" : "Export this artifact as PDF"}
                >
                  <Icon name="download" size={12}/>PDF
                </button>
              )}
            </div>
          </div>
          {selected.kind === "product-draft"
            ? <AiProductDraftForm proposal={selected.artifact?.productProposal} lang={lang}/>
            : selected.kind === "invoice-draft"
            ? <AiInvoiceDraftForm proposal={selected.artifact?.invoiceProposal} scannedImage={selected.artifact?.scannedImage} lang={lang}/>
            : <AiMessageArtifact artifact={selected.artifact} lang={lang}/>}
        </>
      ) : (
        <AssistantArtifactPreparing lang={lang} stage={stage || "thinking"} hasText={false}/>
      )}
    </section>
  );
}

// Model picker for the AI insights: the user chooses Standard (fast, cheap) or
// Deep (gpt-5.4 + high reasoning effort). No automatic escalation — the user decides.
function ReasoningModeToggle({ mode, onChange, lang }) {
  const ar = lang === "ar";
  const options = [
    { id: "standard", label: ar ? "قياسي" : "Standard", icon: "zap", title: ar ? "النموذج السريع منخفض التكلفة (gpt-5.4-mini)" : "Fast, low-cost model (gpt-5.4-mini)" },
    { id: "deep", label: ar ? "عميق" : "Deep", icon: "brain", title: ar ? "نموذج الاستدلال العميق — أبطأ وأعمق (gpt-5.4)" : "Deep reasoning model — slower, deeper (gpt-5.4)" },
  ];
  return (
    <div className="segmented" aria-label={ar ? "وضع الاستدلال" : "Reasoning mode"} style={{ height: 28, marginInlineStart: 10 }}>
      {options.map((opt) => (
        <button
          key={opt.id}
          type="button"
          className={`seg-btn ${mode === opt.id ? "active" : ""}`}
          title={opt.title}
          onClick={() => onChange && onChange(opt.id)}
        >
          <Icon name={opt.icon} size={12}/>{opt.label}
        </button>
      ))}
    </div>
  );
}

// Reads every turn from the assistant-ui thread runtime and hands the whole
// conversation (questions + summaries + artifacts) to the export overlay.
function ExportConversationButton({ lang, onExport }) {
  const ar = lang === "ar";
  const thread = useThreadRuntime();
  const handle = () => {
    if (!onExport) return;
    const state = typeof thread?.getState === "function" ? thread.getState() : null;
    const messages = Array.isArray(state?.messages) ? state.messages : [];
    const turns = [];
    let pendingQuestion = "";
    messages.forEach((message) => {
      if (message?.role === "user") {
        pendingQuestion = threadMessageText(message).trim();
        return;
      }
      if (message?.role !== "assistant") return;
      const summary = threadMessageText(message).trim();
      const artifact = message?.metadata?.custom?.artifact || null;
      // Skip the standing greeting (no question, no artifact).
      if (!pendingQuestion && !assistantArtifactHasCanvas(artifact)) return;
      turns.push({ question: pendingQuestion, summary, artifact });
      pendingQuestion = "";
    });
    onExport({ mode: "conversation", turns });
  };
  return (
    <button
      type="button"
      className="btn btn-ghost"
      style={{ height: 28, fontSize: 12, marginInlineStart: "auto" }}
      onClick={handle}
      title={ar ? "تصدير المحادثة كـ PDF" : "Export the whole conversation as PDF"}
    >
      <Icon name="download" size={12}/>{ar ? "تصدير PDF" : "Export PDF"}
    </button>
  );
}

// On-screen print preview that scopes window.print() to just the report
// (see .bayaan-export-overlay / @media print in exact.css).
function BayaanInsightsExportOverlay({ payload, lang, onClose }) {
  const ar = lang === "ar";
  const mode = payload?.mode || "conversation";
  const turns = (payload?.turns || []).filter(
    (turn) => turn && (turn.question || turn.summary || assistantArtifactHasCanvas(turn.artifact)),
  );
  const title = mode === "artifact"
    ? (ar ? "تصدير التحليل" : "Insight artifact")
    : (ar ? "ملخص المحادثة" : "Conversation summary");
  const dateStr = new Date().toLocaleDateString(ar ? "ar-IQ" : "en-GB", {
    year: "numeric", month: "short", day: "numeric",
  });

  const handlePrint = () => {
    if (typeof window === "undefined") return;
    const root = document.documentElement;
    const previous = root.dataset.print;
    const cleanup = () => {
      if (previous) root.dataset.print = previous; else delete root.dataset.print;
      window.removeEventListener("afterprint", cleanup);
    };
    root.dataset.print = "report";
    window.addEventListener("afterprint", cleanup);
    window.print();
    setTimeout(cleanup, 2000); // belt-and-suspenders if afterprint never fires
  };

  const content = (
    <div className="bayaan-export-overlay" dir={ar ? "rtl" : "ltr"} role="dialog" aria-modal="true">
      <div className="bayaan-export-toolbar">
        <div className="bayaan-export-toolbar-title">{title}</div>
        <div className="row" style={{ gap: 8 }}>
          <button type="button" className="btn btn-primary" style={{ height: 30 }} onClick={handlePrint}>
            <Icon name="download" size={13}/>{ar ? "حفظ كـ PDF" : "Save as PDF"}
          </button>
          <button type="button" className="btn btn-ghost" style={{ height: 30 }} onClick={onClose}>
            {ar ? "إغلاق" : "Close"}
          </button>
        </div>
      </div>
      <div className="bayaan-export-report">
        <div className="bayaan-export-report-head">
          <div className="bayaan-export-report-brand">{ar ? "مساعد ميزا الذكي" : "Miza AI Assistant"}</div>
          <div className="bayaan-export-report-sub">{title} · {dateStr}</div>
        </div>
        {turns.length === 0 ? (
          <div className="t-small muted">{ar ? "لا توجد عناصر للتصدير بعد." : "Nothing to export yet — ask the assistant a question first."}</div>
        ) : turns.map((turn, index) => (
          <section key={index} className="bayaan-export-turn">
            {turn.question ? (
              <div className="bayaan-export-turn-q">
                <span className="bayaan-export-turn-label">{ar ? "السؤال" : "Question"}</span>
                {turn.question}
              </div>
            ) : null}
            {turn.summary ? (
              <div className="bayaan-export-turn-a">{turn.summary}</div>
            ) : null}
            {assistantArtifactHasCanvas(turn.artifact) ? (
              <AiMessageArtifact artifact={turn.artifact} lang={lang}/>
            ) : null}
          </section>
        ))}
      </div>
    </div>
  );
  // Portal to <body> so the report escapes .app-frame's height/overflow clipping —
  // otherwise print pages come out empty. Theme tokens live on :root, so styling survives.
  if (typeof document === "undefined") return content;
  return createPortal(<div className="bayaan-export-portal">{content}</div>, document.body);
}

function BayaanAssistantMeta({ sourceMeta, lang }) {
  return (
    <div className="assistant-thread-meta">
      {sourceMeta?.header && (
        <span className="assistant-thread-window">{arTerm(lang, sourceMeta.header)}</span>
      )}
      {(sourceMeta?.chips || []).map(([label, value]) => (
        <span key={label} className="badge">
          {arTerm(lang, label)} <span className="t-num" style={{ marginInlineStart: 4 }}>{Number(value || 0).toLocaleString("en")}</span>
        </span>
      ))}
      <span className="badge badge-ai">{arTerm(lang, sourceMeta?.budget || "Daily summaries tier")}</span>
      {sourceMeta?.window && (
        <span className="assistant-thread-window">{arTerm(lang, sourceMeta.window)}</span>
      )}
    </div>
  );
}

function BayaanAssistantQuickPrompts({ lang }) {
  const ar = lang === "ar";
  const thread = useThreadRuntime();
  const running = useAuiState((s) => s.thread.isRunning);
  return (
    <div className="assistant-thread-suggestions">
      {SUGGESTED.map((s) => (
        <button
          key={s.id}
          type="button"
          className="assistant-thread-suggestion"
          disabled={running}
          onClick={() => thread.append({
            role: "user",
            content: [{ type: "text", text: suggestedText(s, lang) }],
            metadata: { custom: { sceneIdHint: s.id } },
            startRun: true,
          })}
        >
          {ar ? s.textAr : s.text}
        </button>
      ))}
    </div>
  );
}

function BayaanAssistantComposer({ lang }) {
  const ar = lang === "ar";
  const running = useAuiState((s) => s.thread.isRunning);
  return (
    <ComposerPrimitive.Root className="aui-composer-root assistant-thread-composer" data-slot="aui_composer-root">
      <ComposerPrimitive.Input
        className="aui-composer-input assistant-thread-input"
        placeholder={ar ? "اسألني أي سؤال..." : "Ask anything..."}
        rows={1}
        submitMode="enter"
        disabled={running}
        aria-label={ar ? "رسالة إلى مساعد بيان" : "Message Bayaan assistant"}
      />
      {running ? (
        <ComposerPrimitive.Cancel className="aui-composer-cancel assistant-thread-send is-cancel" aria-label={ar ? "إيقاف" : "Stop"}>
          <Icon name="x" size={15}/>
        </ComposerPrimitive.Cancel>
      ) : (
        <ComposerPrimitive.Send className="aui-composer-send assistant-thread-send" aria-label={ar ? "إرسال" : "Send"}>
          <Icon name="arrowUp" size={15}/>
        </ComposerPrimitive.Send>
      )}
    </ComposerPrimitive.Root>
  );
}

function AssistantArtifactPreparing({ lang, stage = "thinking", hasText = false }) {
  const ar = lang === "ar";
  const title = ar
    ? (hasText ? "أحضّر التصور الموثق..." : "أقرأ البيانات وأفكر...")
    : (hasText ? "Preparing source-backed visualization..." : "Reading sources and thinking...");
  const detail = ar
    ? (stage === "assembling" ? "أربط الرسم بالأدلة الرقمية قبل عرضه." : "ستظهر البطاقات عندما يكتمل رد النموذج.")
    : (stage === "assembling" ? "Binding the visual to numeric proof before showing it." : "The visual cards will appear when the model finishes.");
  return (
    <div className="assistant-artifact-loader" role="status" aria-live="polite">
      <div className="assistant-artifact-loader-icon" aria-hidden="true"/>
      <div className="assistant-artifact-loader-copy">
        <div className="assistant-artifact-loader-title">{title}</div>
        <div className="assistant-artifact-loader-detail">{detail}</div>
        <div className="assistant-artifact-loader-bars" aria-hidden="true">
          <span/>
          <span/>
          <span/>
        </div>
      </div>
    </div>
  );
}

function BayaanAssistantExtras({ lang, onArtifactSelect, selectedItemId, selectedMessageKey }) {
  const message = useAuiState((s) => s.message);
  const custom = message?.metadata?.custom || {};
  const running = message?.status?.type === "running";
  const target = threadMessageText(message);
  const showCanvasPending = running && custom.visualPending === true;
  const artifact = custom.artifact;
  const artifactItems = assistantArtifactItems(artifact, lang);
  const messageKey = custom.artifactBundleId || assistantArtifactBundleId(artifact, message?.id || target);

  return (
    <>
      {showCanvasPending && (
        <div className="assistant-thread-artifact-tray" role="status" aria-live="polite">
          <span className="assistant-thread-artifact-chip is-loading">
            <span className="assistant-thread-canvas-pulse" aria-hidden="true"/>
            {lang === "ar" ? "يتم تجهيز الأثر" : "Preparing artifact"}
          </span>
        </div>
      )}
      {artifactItems.length > 0 && (
        <div className="assistant-thread-artifact-tray" role="list" aria-label={aiCanvasText(lang, "artifacts")}>
          {artifactItems.map((item) => {
            const active = selectedMessageKey === messageKey && selectedItemId === item.id;
            return (
              <button
                key={item.id}
                type="button"
                className={`assistant-thread-artifact-chip${active ? " is-active" : ""}`}
                aria-pressed={active}
                onClick={() => onArtifactSelect?.(artifact, item.id, messageKey)}
              >
                <Icon name={item.kind === "sources" ? "fileText" : item.kind === "proof" ? "clipboardCheck" : "chart"} size={13}/>
                <span className="assistant-thread-artifact-chip-copy">
                  <b>{item.title}</b>
                  <span>{item.meta}</span>
                </span>
                <Icon name={lang === "ar" ? "arrowLeft" : "arrowRight"} size={12}/>
              </button>
            );
          })}
        </div>
      )}
      {custom.cite && (
        <div className="assistant-thread-cite">
          {lang === "ar" ? arTerm(lang, "rendered") : "rendered"} {arTerm(lang, custom.cite)} {lang === "ar" ? aiCanvasText(lang, "canvas") : "canvas"}
        </div>
      )}
    </>
  );
}

function BayaanThreadMessage({ lang }) {
  const ar = lang === "ar";
  const message = useAuiState((s) => s.message);
  const isUser = message?.role === "user";
  const custom = message?.metadata?.custom || {};
  const target = threadMessageText(message);
  const display = ar && custom.nativeLocale && custom.nativeLocale !== "ar" ? arTerm(lang, target) : target;
  const running = message?.status?.type === "running";

  if (isUser) {
    return (
      <MessagePrimitive.Root className="assistant-thread-message assistant-thread-message-user" data-role="user">
        <div className="assistant-thread-bubble">{display || target}</div>
      </MessagePrimitive.Root>
    );
  }

  return (
    <MessagePrimitive.Root className="assistant-thread-message assistant-thread-message-assistant" data-role="assistant">
      <div className="assistant-thread-assistant-head">
        <AITag>AI</AITag>
        <span>{ar ? BRAND.arabic : BRAND.name.toLowerCase()}</span>
      </div>
      <div className="assistant-thread-answer">
        {display || (running ? (ar ? "أفكر..." : "Thinking...") : "")}
        {running && <span className="ins-caret"/>}
      </div>
      {custom.cite && (
        <div className="assistant-thread-cite">
          {ar ? arTerm(lang, "rendered") : "rendered"} {arTerm(lang, custom.cite)} {ar ? aiCanvasText(lang, "canvas") : "canvas"}
        </div>
      )}
    </MessagePrimitive.Root>
  );
}

const AI_VISUAL_COLORS = [
  "var(--chart-5)",
  "var(--chart-2)",
  "var(--chart-3)",
  "var(--chart-4)",
  "var(--accent)",
  "var(--warn)",
  "var(--ink-3)",
];

function aiVisualText(lang, value) {
  const text = String(value || "");
  if (lang !== "ar") return text;
  if (hasArabicText(text)) return text;
  return AI_CANVAS_AR[text] || text;
}

function aiVisualSeries(visual) {
  return (Array.isArray(visual?.series) ? visual.series : [])
    .map((item) => ({
      label: String(item?.label || "value"),
      value: Number(item?.value || 0),
      unit: String(item?.unit || ""),
      category: String(item?.category || item?.label || "value"),
    }))
    .filter((item) => Number.isFinite(item.value))
    .slice(0, 12);
}

function formatAiVisualValue(value, unit) {
  const normalizedUnit = String(unit || "").toLowerCase();
  if (normalizedUnit === "currency" || normalizedUnit === "iqd") return fmtMoneyShort(Number(value || 0));
  const formatted = Number(value || 0).toLocaleString("en");
  return unit ? `${formatted} ${unit}` : formatted;
}

function aiVisualCommonUnit(series) {
  const units = Array.from(new Set(series.map((item) => String(item.unit || "").trim()).filter(Boolean)));
  return units.length === 1 ? units[0] : "";
}

function AiStudioBarChart({ rows, lang }) {
  const ar = lang === "ar";
  return (
    <StudioPatternBarChart
      ar={ar}
      ariaLabel={ar ? "رسم أعمدة للذكاء" : "AI bar chart"}
      barSize={34}
      className="ai-studio-bar"
      initialDimension={{ width: 520, height: 230 }}
      rows={rows}
      tickFormatter={(value) => {
        const text = String(value || "");
        return text.length > 10 ? `${text.slice(0, 10)}...` : text;
      }}
      tooltipTitle={(row) => row.label}
      tooltipValue={(row) => formatAiVisualValue(row.value, row.unit)}
      valueDataKey="value"
      valueLabel={ar ? "القيمة" : "Value"}
      xDataKey="label"
    />
  );
}

function aiTokenBudgetBadgeText(lang, totalTokens, remainingTokens) {
  const isFiniteCount = (value) => (
    value !== null &&
    value !== undefined &&
    value !== false &&
    value !== "" &&
    Number.isFinite(Number(value))
  );
  if (isFiniteCount(totalTokens)) return `${Number(totalTokens).toLocaleString("en")} ${aiCanvasText(lang, "tokens")}`;
  if (remainingTokens === false) return aiCanvasText(lang, "unlimited");
  if (isFiniteCount(remainingTokens)) return `${Number(remainingTokens).toLocaleString("en")} ${aiCanvasText(lang, "left")}`;
  return aiCanvasText(lang, "token guarded");
}

function AiAgentVisualization({ visual, lang, index = 0 }) {
  const type = String(visual?.type || "callout");
  const series = aiVisualSeries(visual);
  const sourceRefs = Array.isArray(visual?.sourceRefs) ? visual.sourceRefs.slice(0, 4) : [];
  const max = Math.max(...series.map((item) => Math.abs(item.value)), 1);
  const chartData = series.map((item, itemIndex) => ({
    ...item,
    label: aiVisualText(lang, item.label),
    fill: AI_VISUAL_COLORS[itemIndex % AI_VISUAL_COLORS.length],
  }));
  const pieData = chartData.filter((item) => item.value > 0);
  const commonUnit = aiVisualCommonUnit(series);

  const renderBody = () => {
    if (type === "pie-chart" && pieData.length) {
      const total = pieData.reduce((sum, item) => sum + Number(item.value || 0), 0);
      return (
        <div className="ai-agent-chart ai-payment-visual ai-studio-pie-visual">
          <PaymentMixDonut
            centerLabel={aiCanvasText(lang, "Total")}
            centerValue={formatAiVisualValue(total, commonUnit)}
            compact
            formatValue={(amount) => formatAiVisualValue(amount, commonUnit)}
            rows={pieData.map((item, itemIndex) => ({
              id: `${item.category || item.label}-${itemIndex}`,
              label: item.label,
              value: item.value,
              color: item.fill,
            }))}
            total={total}
          />
        </div>
      );
    }

    if (type === "bar-chart" && chartData.length) {
      return (
        <div className="ai-agent-chart">
          <AiStudioBarChart rows={chartData} lang={lang}/>
        </div>
      );
    }

    if ((type === "metric-card" || type === "metric-grid") && series.length) {
      return (
        <div className="ai-agent-metric-grid">
          {series.map((item, itemIndex) => (
            <div key={`${item.label}-${itemIndex}`} className="ai-agent-metric" style={{ "--ai-agent-delay": `${itemIndex * 70}ms` }}>
              <span>{aiVisualText(lang, item.label)}</span>
              <strong>{formatAiVisualValue(item.value, item.unit)}</strong>
            </div>
          ))}
        </div>
      );
    }

    if (type === "rank-list" || type === "proposal-list" || type === "timeline" || type === "table") {
      return (
        <div className="ai-agent-rank-list">
          {series.length ? series.map((item, itemIndex) => (
            <div key={`${item.label}-${itemIndex}`} className="ai-agent-rank-row" style={{ "--ai-agent-delay": `${itemIndex * 70}ms` }}>
              <div className="ai-agent-rank-meta">
                <span>{aiVisualText(lang, item.label)}</span>
                <b>{formatAiVisualValue(item.value, item.unit)}</b>
              </div>
              <div className="ai-agent-rank-track">
                <div style={{ width: `${Math.max(4, Math.min(100, Math.abs(item.value) / max * 100))}%` }}/>
              </div>
            </div>
          )) : (
            <div className="t-small subtle">{aiVisualText(lang, visual?.reason || "No numeric rows needed for this response.")}</div>
          )}
        </div>
      );
    }

    return (
      <div className="ai-agent-callout">
        {aiVisualText(lang, visual?.reason || "")}
      </div>
    );
  };

  return (
    <div className="ai-agent-visual-card" style={{ "--ai-agent-index": index, "--ai-agent-card-delay": `${index * 110}ms` }}>
      <div className="ai-agent-visual-head">
        <span className="badge badge-ai">{aiVisualText(lang, type)}</span>
        {sourceRefs.length > 0 && <span>{sourceRefs.join(" / ")}</span>}
      </div>
      <div className="ai-agent-visual-title">{aiVisualText(lang, visual?.title)}</div>
      {visual?.reason && <div className="ai-agent-visual-reason">{aiVisualText(lang, visual.reason)}</div>}
      {renderBody()}
    </div>
  );
}

function AiMessageArtifact({ artifact, lang }) {
  const sourceEvidence = Array.isArray(artifact?.sourceEvidence) ? artifact.sourceEvidence : [];
  const claims = Array.isArray(artifact?.claims) ? artifact.claims : [];
  const visualizations = Array.isArray(artifact?.visualizations) ? artifact.visualizations : [];
  const runtime = artifact?.runtime || {};
  const llm = runtime.llm || {};
  const budget = runtime.budget || {};
  const visibleSources = sourceEvidence.filter((ref) => ref?.model).slice(0, 4);
  const totalTokens =
    llm.totalTokens ??
    llm.usage?.total_tokens ??
    llm.usage?.totalTokens ??
    budget.tokensUsed ??
    null;
  const remainingTokens =
    budget.remainingTokens ??
    budget.tokensRemaining ??
    budget.remaining ??
    null;

  return (
    <div className="ai-artifact">
      <div className="ai-artifact-runtime">
        <div className="t-small" style={{ fontWeight: 600 }}>{aiCanvasText(lang, "AI runtime")}</div>
        <div className="ai-artifact-runtime-items">
          <span className="badge badge-ai" style={{ height: 20, fontSize: 10.5 }}>{aiStatusText(lang, llm.status || "pending")}</span>
          <span className="badge" style={{ height: 20, fontSize: 10.5 }}>{llm.model || llm.provider || "server-side"}</span>
          <span className="badge" style={{ height: 20, fontSize: 10.5 }}>
            {aiTokenBudgetBadgeText(lang, totalTokens, remainingTokens)}
          </span>
        </div>
      </div>

      {visualizations.length > 0 && (
        <div className="ai-agent-visual-grid">
          {visualizations.map((visual, index) => (
            <AiAgentVisualization key={visual?.id || `${visual?.type}-${index}`} visual={visual} lang={lang} index={index}/>
          ))}
        </div>
      )}

      {claims.length > 0 && (
        <div className="ai-artifact-proof">
          <div className="between" style={{ gap: 10 }}>
            <div className="t-small" style={{ fontWeight: 600 }}>{aiCanvasText(lang, "Claim proof")}</div>
            <span className="badge badge-ai" style={{ height: 20, fontSize: 10 }}>{aiCanvasText(lang, "numeric refs")}</span>
          </div>
          <div className="ai-artifact-proof-list">
            {claims.slice(0, 2).map((claim, index) => (
              <div key={`${claim.text || "claim"}-${index}`} className="ai-artifact-claim">
                <div className="t-small" style={{ lineHeight: 1.45 }}>{claim.text || aiCanvasText(lang, "Source-backed claim")}</div>
                <div className="row" style={{ gap: 6, flexWrap: "wrap", marginTop: 7 }}>
                  {(claim.numericValues || []).slice(0, 3).map((numeric) => (
                    <span key={`${numeric.label}-${numeric.value}`} className="badge" style={{ height: 20, fontSize: 10.5 }}>
                      {aiCanvasText(lang, numeric.label)}: <span className="t-num" style={{ marginInlineStart: 4 }}>{Number(numeric.value || 0).toLocaleString("en")}</span>{numeric.unit ? ` ${aiCanvasText(lang, numeric.unit)}` : ""}
                    </span>
                  ))}
                </div>
              </div>
            ))}
          </div>
        </div>
      )}

      {visibleSources.length > 0 && (
        <div className="ai-artifact-proof">
          <div className="t-small" style={{ fontWeight: 600 }}>{aiCanvasText(lang, "Source evidence")}</div>
          <div className="ai-artifact-source-grid">
            {visibleSources.map((ref, index) => {
              const modelLabel = String(ref.model || "").replace(/^bayaan\./, "").replace(/^pos\./, "");
              const samples = Array.isArray(ref.sampleRefs) ? ref.sampleRefs.slice(0, 2).filter(Boolean) : [];
              return (
                <div key={`${ref.model || "source"}-${index}`} className="ai-artifact-source">
                  <span>{modelLabel || ref.model}</span>
                  <span>{Number(ref.rowCount || 0).toLocaleString("en")} {aiCanvasText(lang, "rows")}</span>
                  {samples.length > 0 && (
                    <span className="ai-artifact-source-samples">
                      {aiCanvasText(lang, "samples")}: {samples.join(", ")}
                    </span>
                  )}
                </div>
              );
            })}
          </div>
        </div>
      )}

    </div>
  );
}

function ChatMessage({ message, lang }) {
  const ar = lang === "ar";
  const isUser = message.role === "user";
  const isLive = message.streaming;
  const target = message.text || "";
  const streamed = useStream(isLive ? target : "", 12);
  const display = isLive ? streamed : target;
  const localizedDisplay = ar ? arTerm(lang, display) : display;

  if (isUser) {
    return (
      <div style={{
        alignSelf: "flex-end", maxWidth: "85%",
        padding: "8px 12px",
        background: "var(--ink)", color: "var(--ink-inverse)",
        borderRadius: "12px 12px 4px 12px",
        fontSize: 13, lineHeight: 1.45,
        animation: "insMsgIn 280ms cubic-bezier(0.22,1,0.36,1) both",
      }}>
        {target}
      </div>
    );
  }
  return (
    <div style={{
      alignSelf: "flex-start", maxWidth: "92%",
      animation: "insMsgIn 280ms cubic-bezier(0.22,1,0.36,1) both",
    }}>
      <div className="row" style={{ gap: 6, marginBottom: 4 }}>
        <AITag>AI</AITag>
        <span className="t-small subtle" style={{ fontSize: 10.5 }}>{ar ? BRAND.arabic : BRAND.name.toLowerCase()}</span>
      </div>
      <div style={{
        fontSize: 13, lineHeight: 1.55,
        color: "var(--ink-1)",
      }}>
        {localizedDisplay}
        {isLive && display.length < target.length && <span className="ins-caret"/>}
      </div>
      {!isLive && message.cite && (
        <div className="t-small subtle" style={{ fontSize: 10.5, marginTop: 6, fontFamily: "var(--font-mono)" }}>
          {ar ? "تم عرض" : "rendered"} {arTerm(lang, message.cite)} {ar ? "على اللوحة" : "on canvas"}
        </div>
      )}
    </div>
  );
}

function TypingIndicator() {
  return (
    <div style={{ alignSelf: "flex-start", display: "flex", alignItems: "center", gap: 4 }}>
      <span style={{ width: 6, height: 6, borderRadius: "50%", background: "var(--ink-3)", animation: "insDot 1.2s ease-in-out infinite" }}/>
      <span style={{ width: 6, height: 6, borderRadius: "50%", background: "var(--ink-3)", animation: "insDot 1.2s ease-in-out 0.15s infinite" }}/>
      <span style={{ width: 6, height: 6, borderRadius: "50%", background: "var(--ink-3)", animation: "insDot 1.2s ease-in-out 0.3s infinite" }}/>
    </div>
  );
}

function aiAssistantIntroText(ar, sourceMeta, liveAiEnabled) {
  if (sourceMeta.empty) {
    return ar
      ? "لا توجد صفوف موثقة بعد. لن أعرض أي ملخص تجريبي في وضع البيانات المباشرة فقط."
      : "No verified rows are loaded yet. I will not show a demo summary in live-only mode.";
  }
  if (liveAiEnabled) {
    return ar
      ? "أهلاً. أنا مساعد بيان المباشر. اسألني أي شيء؛ عندما يلمس سؤالك العمليات سأستدعي نموذج اللغة من الخادم، وأقرأ حزم تقارير المحرك الموثقة، وأعرض دليل المصدر. لن أنفذ أي تغييرات تجارية من دون موافقة بشرية."
      : "Hi. I am the live Bayaan assistant. Ask me anything; when your question touches operations I will call the server-side LLM, read verified engine report packs, and show source proof. I will not execute business changes without a human.";
  }
  return ar
    ? "الذكاء المباشر غير متصل في هذه الجلسة. يمكنني عرض معاينة تخطيط محلية فقط إلى أن يتم تفعيل مسار نموذج اللغة الموثق."
    : "Live AI is not connected in this session. I will not replace it with a mock answer until the verified engine LLM route is enabled.";
}

function aiLocalPreviewText(ar) {
  return ar
    ? "الذكاء المباشر غير متصل في هذه الجلسة. هذه معاينة تخطيط محلية فقط، وليست إجابة من نموذج اللغة."
    : "Live AI is not connected in this session. I will not answer with a mockup; connect the verified engine LLM route first.";
}

// ============================================================
// Main screen
// ============================================================
function InsightsScreen({ lang, bootstrap, sourceOfTruth, canCreateProduct = false, canReceiveInvoice = false, refreshOdoo, warehouses = [] }) {
  const sourceMeta = useMemoIns(() => insightSourceMeta(bootstrap), [bootstrap]);
  const ar = lang === "ar";
  const { showToast: insightsShowToast } = useToast();
  const productDraftIngredientOptions = useMemoIns(() => odooIngredientOptions(bootstrap), [bootstrap]);
  const productDraftCtx = useMemoIns(() => ({
    gateway: sourceOfTruth,
    showToast: insightsShowToast,
    refreshOdoo,
    canConfirm: canCreateProduct,
    ingredientOptions: productDraftIngredientOptions,
  }), [sourceOfTruth, insightsShowToast, refreshOdoo, canCreateProduct, productDraftIngredientOptions]);
  const invoiceCatalog = useMemoIns(() => (odooProductCatalogRows(bootstrap) || []).map((row) => ({ id: row.id, code: row.code, name: row.name, uom: row.uom })), [bootstrap]);
  const invoiceDraftCtx = useMemoIns(() => ({
    gateway: sourceOfTruth,
    showToast: insightsShowToast,
    refreshOdoo,
    canConfirm: canReceiveInvoice,
    warehouses,
    catalog: invoiceCatalog,
  }), [sourceOfTruth, insightsShowToast, refreshOdoo, canReceiveInvoice, warehouses, invoiceCatalog]);
  const liveAiEnabled = Boolean(sourceOfTruth?.enabled && !isSimulationRuntime());
  const introText = aiAssistantIntroText(ar, sourceMeta, liveAiEnabled);
  const introLocale = ar ? "ar" : "en";
  const [scene, setScene] = useStateIns("default");
  const [plan, setPlan] = useStateIns(null);
  const [aiEvidence, setAiEvidence] = useStateIns(null);
  const [aiRuntime, setAiRuntime] = useStateIns(null);
  const [aiClaims, setAiClaims] = useStateIns(null);
  const [aiReportPack, setAiReportPack] = useStateIns(null);
  const [assistantCanvasArtifact, setAssistantCanvasArtifact] = useStateIns(null);
  const [assistantCanvasSelectedItemId, setAssistantCanvasSelectedItemId] = useStateIns(null);
  const [assistantCanvasMessageKey, setAssistantCanvasMessageKey] = useStateIns(null);
  const [assistantCanvasPending, setAssistantCanvasPending] = useStateIns(false);
  const [assistantCanvasStage, setAssistantCanvasStage] = useStateIns("idle");
  const [messages, setMessages] = useStateIns([]);
  const [busy, setBusy] = useStateIns(false);
  const [exportPayload, setExportPayload] = useStateIns(null);
  const [reasoningMode, setReasoningMode] = useStateIns("standard"); // "standard" | "deep" — user picks the model
  const reasoningModeRef = useRefIns("standard");
  reasoningModeRef.current = reasoningMode;
  const resolveReasoningPref = () => reasoningModeRef.current === "deep";

  const assistantInitialMessages = useMemoIns(() => ([
    {
      role: "assistant",
      content: introText,
      status: { type: "complete", reason: "stop" },
      metadata: {
        custom: {
          cite: liveAiEnabled ? "live LLM ready" : sourceMeta.cite,
          nativeLocale: introLocale,
        },
      },
    },
  ]), [introText, liveAiEnabled, sourceMeta.cite, introLocale]);

  const selectAssistantArtifact = useMemoIns(() => (artifact, itemId, messageKey) => {
    if (!assistantArtifactHasCanvas(artifact)) return;
    const nextItemId = itemId || assistantArtifactDefaultItemId(artifact);
    setAssistantCanvasArtifact(artifact);
    setAssistantCanvasSelectedItemId(nextItemId);
    setAssistantCanvasMessageKey(messageKey || assistantArtifactBundleId(artifact));
    setAssistantCanvasPending(false);
    setAssistantCanvasStage("ready");
  }, []);

  // Invoice scan: read the photo -> server vision extract -> push the draft into
  // the canvas directly (no LLM chat turn). The form (rendered from this artifact)
  // does the human-confirmed deterministic commit.
  const handleAttachInvoice = async (file) => {
    if (!sourceOfTruth?.extractInvoice) {
      insightsShowToast(ar ? "اربط الخلفية المباشرة لمسح الفواتير" : "Connect the live backend to scan invoices", "warn");
      return;
    }
    try {
      const base64 = await readFileAsBase64(file);
      const mimeType = file.type || "image/jpeg";
      const dataUrl = `data:${mimeType};base64,${base64}`;
      setAssistantCanvasPending(true);
      setAssistantCanvasStage("thinking");
      const response = unwrapOdoo(await sourceOfTruth.extractInvoice({ imageBase64: base64, mimeType }));
      const proposal = response && response.invoiceProposal;
      if (!proposal) {
        insightsShowToast((response && response.error) || (ar ? "تعذّر قراءة الفاتورة" : "Could not read the invoice"), "warn");
        setAssistantCanvasPending(false);
        setAssistantCanvasStage("idle");
        return;
      }
      setAssistantCanvasArtifact({ invoiceProposal: proposal, scannedImage: { dataUrl, base64, mimeType, name: file.name || "invoice" } });
      setAssistantCanvasSelectedItemId("invoice-draft");
      setAssistantCanvasMessageKey("invoice-" + (proposal.invoiceRef || "draft"));
      setAssistantCanvasPending(false);
      setAssistantCanvasStage("ready");
    } catch (error) {
      insightsShowToast(compactError(error) || (ar ? "تعذّر قراءة الفاتورة" : "Could not read the invoice"), "warn");
      setAssistantCanvasPending(false);
      setAssistantCanvasStage("idle");
    }
  };

  const runAssistantTurn = useMemoIns(() => async function* runBayaanAssistantTurn(options) {
    const { text: q, sceneIdHint } = latestUserTurn(options?.messages || []);
    const abortSignal = options?.abortSignal;

    const applyAiResponseToState = (response) => {
      const resolvedPlan = response?.plan || null;
      const responseEvidence = Array.isArray(response?.sourceEvidence)
        ? response.sourceEvidence
        : response?.reportPack?.sourceEvidence || null;
      const responseClaims = Array.isArray(response?.claims) ? response.claims : null;
      const responseVisualizations = Array.isArray(response?.visualizations) ? response.visualizations : [];
      const responseRuntime = {
        llm: response?.llm || null,
        featureTier: response?.featureTier || null,
        budget: response?.budget || null,
      };
      setPlan(resolvedPlan);
      setAiEvidence(responseEvidence);
      setAiClaims(responseClaims);
      setAiReportPack(response?.reportPack || null);
      setAiRuntime(responseRuntime);
      const responseArtifact = {
        plan: resolvedPlan,
        sourceEvidence: responseEvidence,
        claims: responseClaims,
        visualizations: responseVisualizations,
        productProposal: response?.productProposal || null,
        reportPack: response?.reportPack || null,
        runtime: responseRuntime,
      };
      const guessed = sceneIdHint || sceneIdForAiDashboardPlan(resolvedPlan);
      const sceneObj = SCENES[guessed] || SCENES.default;
      const target = aiDashboardResponseText(response, sceneObj, ar);
      const artifactBundleId = assistantArtifactBundleId(responseArtifact, response?.llm?.responseId || target);
      const defaultArtifactItemId = assistantArtifactDefaultItemId(responseArtifact);
      const hasCanvasArtifact = assistantArtifactHasCanvas(responseArtifact);
      setAssistantCanvasArtifact(hasCanvasArtifact ? responseArtifact : null);
      setAssistantCanvasSelectedItemId(hasCanvasArtifact ? defaultArtifactItemId : null);
      setAssistantCanvasMessageKey(hasCanvasArtifact ? artifactBundleId : null);
      setAssistantCanvasPending(false);
      setAssistantCanvasStage("ready");
      setScene(guessed);
      const cite = aiDashboardCitation(response, sourceMeta);
      return {
        target,
        custom: {
          cite,
          nativeLocale: response?.locale || lang,
          serverStream: true,
          artifact: responseArtifact,
          artifactBundleId,
        },
      };
    };

    if (!q) {
      setAssistantCanvasPending(false);
      yield assistantRunResult("", { cite: sourceMeta.cite, nativeLocale: lang }, { type: "complete", reason: "stop" });
      return;
    }

    if (sourceMeta.empty && !sourceOfTruth?.enabled) {
      setAssistantCanvasArtifact(null);
      setAssistantCanvasSelectedItemId(null);
      setAssistantCanvasMessageKey(null);
      setAssistantCanvasPending(false);
      const target = ar ? "لا توجد بيانات محرك موثقة للإجابة عليها الآن." : "There are no verified engine rows to answer from yet.";
      yield assistantRunResult(target, { cite: sourceMeta.cite, nativeLocale: lang }, { type: "complete", reason: "stop" });
      return;
    }

    if (liveAiEnabled) {
      setAssistantCanvasArtifact(null);
      setAssistantCanvasSelectedItemId(null);
      setAssistantCanvasMessageKey(null);
      setAssistantCanvasPending(true);
      setAssistantCanvasStage("thinking");
      const queue = createAssistantEventQueue();
      let streamedText = "";
      let latestCustom = {
        cite: "live LLM stream",
        nativeLocale: lang,
        serverStream: true,
        visualPending: true,
        visualStage: "thinking",
      };
      let sawFinal = false;
      let sawStreamError = false;
      const request = sourceOfTruth.streamAiDashboardPlan({
        query: q,
        locale: lang,
        scope: { sectionId: "insights", timeRange: "today" },
        reasoning: resolveReasoningPref(),
      }, {
        signal: abortSignal,
        onArtifact: (response) => queue.push({ type: "artifact_pending", response }),
        onTextDelta: (delta) => queue.push({ type: "text_delta", delta }),
        onFinal: (response) => {
          sawFinal = true;
          queue.push({ type: "final", response });
        },
        onError: (message) => {
          sawStreamError = true;
          queue.push({ type: "stream_error", message });
        },
      })
        .then((response) => {
          if (!sawFinal) queue.push({ type: "final", response });
        })
        .catch((error) => {
          if (!sawStreamError) queue.push({ type: "error", error });
        })
        .finally(() => queue.close());

      yield assistantRunResult("", latestCustom);

      while (true) {
        const event = await queue.next();
        if (!event || abortSignal?.aborted) break;
        if (event.type === "text_delta") {
          streamedText += event.delta || "";
          latestCustom = { ...latestCustom, visualStage: streamedText ? "assembling" : "thinking" };
          if (streamedText) setAssistantCanvasStage("assembling");
          yield assistantRunResult(streamedText, latestCustom);
        } else if (event.type === "artifact_pending") {
          latestCustom = { ...latestCustom, visualStage: "assembling" };
          setAssistantCanvasPending(true);
          setAssistantCanvasStage("assembling");
          continue;
        } else if (event.type === "final") {
          const { target, custom } = applyAiResponseToState(event.response);
          latestCustom = custom;
          yield assistantRunResult(target || streamedText, latestCustom, { type: "complete", reason: "stop" });
        } else if (event.type === "stream_error") {
          setAssistantCanvasPending(false);
          const target = ar ? "أرسل الخادم خطأ أثناء البث. لم يتم اختراع إجابة بديلة." : `The server stream reported an error: ${event.message}`;
          yield assistantRunResult(target, { cite: sourceMeta.cite, nativeLocale: lang }, { type: "complete", reason: "unknown" });
        } else if (event.type === "error") {
          setPlan(null);
          setAiEvidence(null);
          setAiClaims(null);
          setAiReportPack(null);
          setAiRuntime({ llm: { status: "provider_error", error: compactError(event.error) }, featureTier: null, budget: null });
          setAssistantCanvasArtifact(null);
          setAssistantCanvasSelectedItemId(null);
          setAssistantCanvasMessageKey(null);
          setAssistantCanvasPending(false);
          setAssistantCanvasStage("error");
          setScene(sceneIdHint || "default");
          const target = ar
            ? "تعذر الوصول إلى خدمة الذكاء على الخادم. لم يتم اختراع إجابة."
            : `Server AI request failed: ${compactError(event.error)}`;
          yield assistantRunResult(target, { cite: sourceMeta.cite, nativeLocale: lang }, { type: "complete", reason: "unknown" });
        }
      }
      await request.catch(() => undefined);
      return;
    }

    setPlan(null);
    setAiEvidence(null);
    setAiClaims(null);
    setAiReportPack(null);
    setAiRuntime({ llm: { status: "local-plan" }, featureTier: null, budget: null });
    setAssistantCanvasArtifact(null);
    setAssistantCanvasSelectedItemId(null);
    setAssistantCanvasMessageKey(null);
    setAssistantCanvasPending(false);
    setAssistantCanvasStage("idle");
    setScene(sceneIdHint || "default");
    const target = aiLocalPreviewText(ar);
    for (let index = 1; index <= target.length; index += 5) {
      yield assistantRunResult(target.slice(0, index), { cite: sourceMeta.cite, nativeLocale: introLocale, visualPending: false });
      await sleepAssistantFrame(16, abortSignal);
    }
    yield assistantRunResult(target, { cite: sourceMeta.cite, nativeLocale: introLocale, visualPending: false }, { type: "complete", reason: "stop" });
  }, [ar, introLocale, lang, liveAiEnabled, sourceMeta, sourceOfTruth]);

  const sendQuestion = async (q, sceneIdHint) => {
    if (sourceMeta.empty && !sourceOfTruth?.enabled) {
      setMessages((m) => [
        ...m,
        { role: "user", text: q, nativeLocale: lang },
        {
          role: "ai",
          text: ar ? "لا توجد بيانات محرك موثقة للإجابة عليها الآن." : "There are no verified engine rows to answer from yet.",
          cite: sourceMeta.cite,
          nativeLocale: lang,
        },
      ]);
      return;
    }

    setMessages(m => [...m, { role: "user", text: q, nativeLocale: lang }]);
    setBusy(true);

    if (liveAiEnabled) {
      const assistantMessageId = `ai-${Date.now()}-${Math.random().toString(36).slice(2)}`;
      const applyLiveAiResponse = (response, keepExistingText = false, stillStreaming = false) => {
        const resolvedPlan = response?.plan || null;
        const responseEvidence = Array.isArray(response?.sourceEvidence)
          ? response.sourceEvidence
          : response?.reportPack?.sourceEvidence || null;
        const responseClaims = Array.isArray(response?.claims) ? response.claims : null;
        const responseVisualizations = Array.isArray(response?.visualizations) ? response.visualizations : [];
        const responseRuntime = {
          llm: response?.llm || null,
          featureTier: response?.featureTier || null,
          budget: response?.budget || null,
        };
        setPlan(resolvedPlan);
        setAiEvidence(responseEvidence);
        setAiClaims(responseClaims);
        setAiReportPack(response?.reportPack || null);
        setAiRuntime(responseRuntime);
        const guessed = sceneIdHint || sceneIdForAiDashboardPlan(resolvedPlan);
        setScene(guessed);
        const sceneObj = SCENES[guessed] || SCENES.default;
        const target = aiDashboardResponseText(response, sceneObj, ar);
        const cite = aiDashboardCitation(response, sourceMeta);
        setMessages(m => m.map((item) => (
          item.id === assistantMessageId
            ? {
                ...item,
                text: keepExistingText && item.text ? item.text : target,
                streaming: stillStreaming,
                serverStream: true,
                cite,
                nativeLocale: response?.locale || lang,
                artifact: {
                  plan: resolvedPlan,
                  sourceEvidence: responseEvidence,
                  claims: responseClaims,
                  visualizations: responseVisualizations,
                  productProposal: response?.productProposal || null,
                  reportPack: response?.reportPack || null,
                  runtime: responseRuntime,
                },
              }
            : item
        )));
      };
      setMessages(m => [...m, {
        id: assistantMessageId,
        role: "ai",
        text: "",
        streaming: true,
        serverStream: true,
        cite: "live LLM stream",
        nativeLocale: lang,
      }]);
      try {
        await sourceOfTruth.streamAiDashboardPlan({
          query: q,
          locale: lang,
          scope: { sectionId: "insights", timeRange: "today" },
          reasoning: resolveReasoningPref(),
        }, {
          onArtifact: () => undefined,
          onTextDelta: (delta) => {
            setMessages(m => m.map((item) => (
              item.id === assistantMessageId
                ? { ...item, text: `${item.text || ""}${delta}`, streaming: true, serverStream: true }
                : item
            )));
          },
          onFinal: (response) => applyLiveAiResponse(response, false, false),
        });
        setBusy(false);
      } catch (error) {
        setPlan(null);
        setAiEvidence(null);
        setAiClaims(null);
        setAiReportPack(null);
        setAiRuntime({ llm: { status: "provider_error", error: compactError(error) }, featureTier: null, budget: null });
        setScene(sceneIdHint || "default");
        setMessages(m => m.filter((item) => item.id !== assistantMessageId));
        setMessages(m => [...m, {
          role: "ai",
          text: ar ? "تعذر الوصول إلى خدمة الذكاء على الخادم. لم يتم اختراع إجابة." : `Server AI request failed: ${compactError(error)}`,
          cite: sourceMeta.cite,
          nativeLocale: lang,
        }]);
        setBusy(false);
      }
      return;
    }

    setPlan(null);
    setAiEvidence(null);
    setAiClaims(null);
    setAiReportPack(null);
    setAiRuntime({ llm: { status: "local-plan" }, featureTier: null, budget: null });

    const guessed = sceneIdHint || "default";
    setTimeout(() => {
      setScene(guessed);
      const target = aiLocalPreviewText(ar);
      setMessages(m => [...m, { role: "ai", text: target, streaming: true, cite: sourceMeta.cite, nativeLocale: introLocale }]);
      // mark stream complete after enough time
      const streamMs = Math.min(4500, target.length * 14 + 400);
      setTimeout(() => {
        setMessages(m => m.map((x, i) => i === m.length - 1 ? { ...x, streaming: false } : x));
        setBusy(false);
      }, streamMs);
    }, 700);
  };

  const onSuggested = (s) => {
    if (busy) return;
    sendQuestion(suggestedText(s, lang), s.id);
  };

  return (
    <div className="ai-chat-workspace" style={{
      height: "100%",
      margin: 0,
    }}>
      {/* Inline animation rules */}
      <style>{`
        @keyframes insCardIn {
          0% { opacity: 0; transform: translateY(12px) scale(0.98); }
          100% { opacity: 1; transform: none; }
        }
        @keyframes insBarGrow {
          0% { transform: scaleY(0); }
          100% { transform: scaleY(1); }
        }
        @keyframes insBarRow {
          0% { transform: scaleX(0); }
          100% { transform: scaleX(1); }
        }
        @keyframes insStackGrow {
          0% { transform: scaleX(0); opacity: 0.6; }
          100% { transform: scaleX(1); opacity: 1; }
        }
        @keyframes insRowIn {
          0% { opacity: 0; transform: translateX(-6px); }
          100% { opacity: 1; transform: none; }
        }
        @keyframes insDotIn {
          0% { transform: scale(0); opacity: 0; }
          100% { transform: scale(1); opacity: 0.85; }
        }
        @keyframes insMsgIn {
          0% { opacity: 0; transform: translateY(6px); }
          100% { opacity: 1; transform: none; }
        }
        @keyframes insDot {
          0%, 60%, 100% { transform: translateY(0); opacity: 0.5; }
          30% { transform: translateY(-3px); opacity: 1; }
        }
        .ins-card {
          background: var(--surface);
          border: 1px solid var(--line);
          border-radius: var(--r-3);
          padding: 16px;
          padding-inline-start: 18px;
          box-shadow: var(--shadow-1);
        }
        .ins-caret {
          display: inline-block; width: 1.5px; height: 13px;
          background: var(--ink-1); margin-left: 2px;
          vertical-align: -2px;
          animation: insBlink 0.85s steps(1) infinite;
        }
        @keyframes insBlink {
          0%, 50% { opacity: 1; }
          51%, 100% { opacity: 0; }
        }
      `}</style>

      <ProductDraftContext.Provider value={productDraftCtx}>
      <InvoiceDraftContext.Provider value={invoiceDraftCtx}>
      <BayaanAssistantThreadPanel
        key={`${lang}-${liveAiEnabled ? "live" : "local"}-${sourceMeta.cite}`}
        runTurn={runAssistantTurn}
        sourceMeta={sourceMeta}
        liveMode={liveAiEnabled}
        lang={lang}
        artifactCanvas={{
          artifact: assistantCanvasArtifact,
          pending: assistantCanvasPending,
          selectedItemId: assistantCanvasSelectedItemId,
          selectedMessageKey: assistantCanvasMessageKey,
          onSelect: selectAssistantArtifact,
          stage: assistantCanvasStage,
        }}
        onExport={setExportPayload}
        reasoningMode={reasoningMode}
        onReasoningModeChange={setReasoningMode}
        onAttachInvoice={handleAttachInvoice}
      />
      </InvoiceDraftContext.Provider>
      </ProductDraftContext.Provider>
      {exportPayload && (
        <BayaanInsightsExportOverlay
          payload={exportPayload}
          lang={lang}
          onClose={() => setExportPayload(null)}
        />
      )}
    </div>
  );
}

function sceneIdForAiDashboardPlan(plan) {
  if (!plan?.intent) return "default";
  if (plan.intent === "kiosk-diagnosis") return "k04";
  if (plan.intent === "waste-anomaly-review") return "waste";
  if (plan.intent === "recipe-margin-review") return "weekend";
  if (plan.intent === "stock-allocation") return "stock";
  if (plan.intent === "close-review") return "close";
  return "default";
}

function aiDashboardResponseText(response, sceneObj, ar) {
  const explanation = typeof response?.explanation === "string" ? response.explanation.trim() : "";
  if (explanation) return explanation;
  if (response?.skipped || response?.demo || response?.simulation) {
    return ar
      ? "الذكاء المباشر غير متصل في هذه الجلسة. لن أستبدله بإجابة مساعد تجريبية."
      : "Live AI is not connected in this session. I will not replace it with a mock assistant answer.";
  }
  const llmStatus = response?.llm?.status;
  if (llmStatus === "llm_called") {
    return ar
      ? "أرجع النموذج المباشر خطة موثقة من دون نص سردي. أعد السؤال أو ضيّقه؛ لم أستبدل ذلك بإجابة جاهزة."
      : "The live model returned a validated plan but no narrative text. Ask again or narrow the question; no canned dashboard answer was substituted.";
  }
  if (llmStatus === "missing_credentials") {
    return ar
      ? "مفاتيح الذكاء على الخادم غير مضبوطة بعد. أرجع بيان خطة مدعومة بالمصدر من دون استدعاء نموذج اللغة."
      : "Server AI credentials are not configured yet. Bayaan did not make an LLM call or create AI-authored visuals.";
  }
  if (llmStatus === "provider_error") {
    return ar
      ? "فشل مزوّد الذكاء على الخادم. أرجع بيان الخطة الموثقة بالمصدر ولم يخترع إجابة."
      : "The server AI provider failed. Bayaan did not invent an answer or visualization.";
  }
  if (llmStatus === "tier_limited") {
    return ar
      ? "هذه باقة الذكاء لا تسمح بهذا النطاق بعد. أرجع بيان الخطة المدعومة بالمصدر من دون إنفاق رموز النموذج."
      : "This AI tier does not allow that range yet. Bayaan did not ask the model to answer it.";
  }
  if (llmStatus === "budget_exhausted") {
    return ar
      ? "ميزانية رموز الذكاء مستنفدة أو غير كافية لهذا الطلب. أرجع بيان الخطة المدعومة بالمصدر من دون استدعاء النموذج."
      : "The AI token budget is exhausted or too low for this request. Bayaan did not call the model.";
  }
  return ar
    ? "لم ترجع إجابة ذكاء مباشرة. لن أستبدلها برد لوحة جاهز."
    : "No live AI answer was returned. I will not substitute a canned dashboard response.";
}

function formatAiBudgetRemaining(budget) {
  if (!budget) return "-";
  if (budget.remainingTokens === false) return "unlimited";
  if (budget.remainingTokens === undefined || budget.remainingTokens === null) return "-";
  return Number(budget.remainingTokens || 0).toLocaleString("en");
}

function aiDashboardCitation(response, sourceMeta) {
  const refs = Array.isArray(response?.sourceEvidence)
    ? response.sourceEvidence
    : Array.isArray(response?.reportPack?.sourceEvidence)
      ? response.reportPack.sourceEvidence
      : [];
  const topRefs = refs
    .filter((ref) => Number(ref?.rowCount || 0) > 0)
    .slice(0, 4)
    .map((ref) => `${ref.model}:${ref.rowCount}`)
    .join(", ");
  const status = response?.llm?.status || "local-plan";
  return topRefs ? `${status} / ${topRefs}` : `${status} / ${sourceMeta?.cite || "source evidence pending"}`;
}

// =============== KIOSKS ===============
const clampPercent = (value) => Math.max(0, Math.min(100, Number(value) || 0));
const stockTone = (value) => value < 55 ? "crit" : value < 70 ? "warn" : "pos";
const wasteTone = (value) => value > 85 ? "crit" : value > 60 ? "warn" : "pos";
const statusTone = (status) => status === "good" ? "pos" : status === "warn" ? "warn" : "crit";

function HealthBar({ label, value, right, kind = "stock", compact = false }) {
  const safeValue = clampPercent(value);
  const tone = kind === "waste" ? wasteTone(safeValue) : stockTone(safeValue);
  const toneWord = tone === "crit" ? "critical" : tone === "warn" ? "watch" : "healthy";
  return (
    <div className={compact ? "health-bar compact" : "health-bar"}>
      <div className="between health-meta">
        <span>{label}</span>
        <span className="t-num">{right || `${safeValue}%`}</span>
      </div>
      <div
        className="health-track"
        role="progressbar"
        aria-label={`${label}: ${toneWord}, ${safeValue} percent`}
        aria-valuenow={safeValue}
        aria-valuemin={0}
        aria-valuemax={100}
        aria-valuetext={`${safeValue}% — ${toneWord}`}
      >
        <div className={`health-fill tone-${tone}`} style={{ width: `${safeValue}%` }} />
      </div>
    </div>
  );
}

function KioskStatusBadge({ status }) {
  const label = status === "good" ? "Healthy" : status === "warn" ? "Watch" : "Critical";
  return <span className={`badge badge-${statusTone(status)}`}><span className={`dot ${statusTone(status)}`}></span>{label}</span>;
}

function WatchTile({ title, value, detail, tone, children }) {
  return (
    <div className={`card card-pad watch-tile watch-${tone}`}>
      <div className="between" style={{ alignItems: "flex-start", gap: 12 }}>
        <div>
          <div className="t-micro">{title}</div>
          <div className="t-num-big" style={{ marginTop: 8 }}>{value}</div>
        </div>
        <span className={`dot ${tone}`}></span>
      </div>
      <div className="t-small muted" style={{ marginTop: 8 }}>{detail}</div>
      {children && <div style={{ marginTop: 12 }}>{children}</div>}
    </div>
  );
}

function KioskCard({ kiosk, onPick }) {
  return (
    <button className={`card kiosk-card kiosk-${kiosk.status}`} onClick={onPick}>
      <div className="between" style={{ alignItems: "flex-start", gap: 12 }}>
        <div>
          <div className="row" style={{ gap: 8 }}>
            <span className={`dot ${statusTone(kiosk.status)}`}></span>
            <div className="t-h2">{kiosk.name}</div>
          </div>
          <div className="t-small faint" style={{ marginTop: 3 }}>{kiosk.id} · {kiosk.city}</div>
        </div>
        <KioskStatusBadge status={kiosk.status} />
      </div>

      <div className="kiosk-card-metrics">
        <div>
          <div className="t-micro">Revenue</div>
          <div className="t-num">{fmtMoney(kiosk.revenue)}</div>
        </div>
        <div>
          <div className="t-micro">Orders</div>
          <div className="t-num">{kiosk.orders}</div>
        </div>
        <div>
          <div className="t-micro">Margin</div>
          <div className="t-num">{kiosk.margin}%</div>
        </div>
      </div>

      <HealthBar label="Stock health" value={kiosk.stockHealth} right={`${kiosk.stockHealth}%`} />
      <HealthBar label="Waste budget used" value={kiosk.wasteLoad} right={`${kiosk.waste}% waste`} kind="waste" />

      <div className="kiosk-issue">
        <div>
          <div className="t-small" style={{ fontWeight: 500 }}>{kiosk.issue}</div>
          <div className="t-small subtle">Risk item: {kiosk.criticalStock}</div>
        </div>
        <div className={`t-num ${kiosk.variance < -2 ? "delta-neg" : "muted"}`}>{kiosk.variance}%</div>
      </div>

      <div className="between">
        <div className="t-small subtle">7-day sales signal</div>
        <Spark data={kiosk.trend} width={84} height={22}/>
      </div>
    </button>
  );
}

function KiosksScreenPrevious({ lang, onPick, bootstrap }) {
  const [view, setView] = useState("list");
  const rows = odooKioskRows(bootstrap);
  const totalRevenue = rows.reduce((sum, k) => sum + k.revenue, 0);
  const avgMargin = rows.reduce((sum, k) => sum + k.margin, 0) / rows.length;
  const avgStock = Math.round(rows.reduce((sum, k) => sum + k.stockHealth, 0) / rows.length);
  const avgWasteLoad = Math.round(rows.reduce((sum, k) => sum + k.wasteLoad, 0) / rows.length);
  const problemCount = rows.filter(k => k.status !== "good").length;
  const stockRiskCount = rows.filter(k => k.stockHealth < 65).length;
  const wasteRiskCount = rows.filter(k => k.wasteLoad > 60).length;

  return (
    <div className="col" style={{ gap: 14 }}>
      <div className="kiosk-kpi-grid">
        <KPI label="Active" value={String(rows.length)} footer="stock locations"/>
        <KPI label="Today's revenue" value={fmtMoney(totalRevenue)} delta="8.4%" deltaDir="up"/>
        <KPI label="Avg margin" value={`${avgMargin.toFixed(1)}%`} delta="0.8 pts" deltaDir="up"/>
        <KPI label="Need attention" value={String(problemCount)} footer="watch or critical"/>
      </div>

      <div className="ops-watch-grid">
        <WatchTile title="Problems now" value={String(problemCount)} detail="Kiosks with stock, waste, margin, or variance risk" tone={problemCount > 3 ? "crit" : "warn"}>
          <HealthBar compact label="Problem load" value={(problemCount / rows.length) * 100} right={`${problemCount}/${rows.length}`} kind="waste"/>
        </WatchTile>
        <WatchTile title="Stock inventory" value={`${avgStock}%`} detail={`${stockRiskCount} kiosks below the stock safety line`} tone={avgStock < 60 ? "crit" : avgStock < 75 ? "warn" : "pos"}>
          <HealthBar compact label="Average stock health" value={avgStock} right={`${avgStock}%`}/>
        </WatchTile>
        <WatchTile title="Waste tracker" value={`${avgWasteLoad}%`} detail={`${wasteRiskCount} kiosks above today's waste budget`} tone={avgWasteLoad > 75 ? "crit" : avgWasteLoad > 55 ? "warn" : "pos"}>
          <HealthBar compact label="Average waste budget used" value={avgWasteLoad} right={`${avgWasteLoad}%`} kind="waste"/>
        </WatchTile>
      </div>

      <div className="between kiosk-toolbar">
        <div className="row" style={{ gap: 8 }}>
          <button className="btn btn-primary" style={{ height: 28, fontSize: 12 }}>All cities <Icon name="chevDown" size={11}/></button>
          <button className="btn btn-ghost" style={{ height: 28, fontSize: 12 }}>Status <Icon name="chevDown" size={11}/></button>
          <button className="btn btn-ghost" style={{ height: 28, fontSize: 12 }}>Sort: risk first <Icon name="chevDown" size={11}/></button>
        </div>
        <div className="row" style={{ gap: 8 }}>
          <div className="segmented" aria-label="Kiosk view">
            <button className={`seg-btn ${view === "list" ? "active" : ""}`} onClick={() => setView("list")}><Icon name="list" size={12}/>List</button>
            <button className={`seg-btn ${view === "cards" ? "active" : ""}`} onClick={() => setView("cards")}><Icon name="grid" size={12}/>Cards</button>
          </div>
          <button className="btn btn-ghost" style={{ height: 28, fontSize: 12 }}><Icon name="plus" size={12}/>Add kiosk</button>
        </div>
      </div>

      {view === "list" ? (
        <div className="card kiosk-table-card">
          <div className="kiosk-table-scroll">
            <table className="tbl kiosk-health-table">
              <thead>
                <tr>
                  <th scope="col" style={{ width: 32 }}></th>
                  <th scope="col">Kiosk</th>
                  <th scope="col">City</th>
                  <th scope="col" style={{ textAlign: "end" }}>Revenue</th>
                  <th scope="col" style={{ textAlign: "end" }}>Orders</th>
                  <th scope="col" style={{ textAlign: "end" }}>Margin</th>
                  <th scope="col">Stock inventory</th>
                  <th scope="col">Waste tracker</th>
                  <th scope="col">Issue</th>
                  <th scope="col">7-day</th>
                  <th scope="col"></th>
                </tr>
              </thead>
              <tbody>
                {rows.map(k => (
                  <tr
                    key={k.id}
                    className="row-click"
                    onClick={onPick}
                    tabIndex={0}
                    onKeyDown={(e) => { if (e.key === "Enter" || e.key === " ") { e.preventDefault(); onPick?.(); } }}
                    aria-label={`${k.name}, ${k.city}, open kiosk details`}
                  >
                    <td><span className={`dot ${statusTone(k.status)}`}></span></td>
                    <td>
                      <div style={{ fontWeight: 500 }}>{k.name}</div>
                      <div className="t-small faint">{k.id}</div>
                    </td>
                    <td className="muted">{k.city}</td>
                    <td style={{ textAlign: "end" }} className="t-num">{fmtMoney(k.revenue)}</td>
                    <td style={{ textAlign: "end" }} className="t-num muted">{k.orders}</td>
                    <td style={{ textAlign: "end" }} className="t-num">{k.margin}%</td>
                    <td style={{ minWidth: 174 }}>
                      <HealthBar compact label="Stock" value={k.stockHealth} right={`${k.stockHealth}%`}/>
                    </td>
                    <td style={{ minWidth: 174 }}>
                      <HealthBar compact label="Waste" value={k.wasteLoad} right={`${k.waste}%`} kind="waste"/>
                    </td>
                    <td style={{ minWidth: 180 }}>
                      <div style={{ fontWeight: 500 }}>{k.issue}</div>
                      <div className="t-small subtle">{k.criticalStock} · variance <span className={`t-num ${k.variance < -2 ? "delta-neg" : "muted"}`}>{k.variance}%</span></div>
                    </td>
                    <td><Spark data={k.trend} width={70} height={20}/></td>
                    <td><Icon name="chevRight" size={13} style={{ color: "var(--ink-3)" }}/></td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      ) : (
        <div className="kiosk-card-grid">
          {rows.map(k => <KioskCard key={k.id} kiosk={k} onPick={onPick}/>)}
        </div>
      )}
    </div>
  );
}

const WASTE_TARGET = 4.0;

function deriveKioskOps(k, allowDemoEstimate = false) {
  const code = String(k.id || "K-00");
  const a = code.charCodeAt(2) || code.charCodeAt(0) || 75;
  const b = code.charCodeAt(3) || code.charCodeAt(code.length - 1) || 48;
  const seed = (a * 13 + b * 7) % 24;
  let inv;
  if (k.status === "good") inv = 66 + seed;
  else if (k.status === "warn") inv = 38 + (seed % 24);
  else inv = 18 + (seed % 16);
  const slots = Number(k.stockItems || 0) || (allowDemoEstimate ? 24 : 0);
  const lowItems = Number(k.lowStockItems ?? (allowDemoEstimate ? (k.status === "crit" ? 5 + (seed % 3) : k.status === "warn" ? 2 + (seed % 2) : (seed % 2)) : 0));
  const critItems = Number(k.zeroStockItems ?? (allowDemoEstimate ? (k.status === "crit" ? 2 + (seed % 2) : k.status === "warn" ? (seed % 2) : 0) : 0));
  const hours = k.runoutHours ?? k.runout_hours ?? (allowDemoEstimate ? (k.status === "crit" ? 2 + (seed % 4) : k.status === "warn" ? 6 + (seed % 6) : 18 + (seed % 24)) : null);
  const queue = Number(k.queueDepth ?? k.queue_depth ?? (allowDemoEstimate ? seed % 5 : 0));
  const lastSale = Number(k.lastSaleMinutes ?? k.last_sale_minutes ?? (allowDemoEstimate ? (seed % 50) + 4 : 0));
  return { inv: Math.min(96, Math.max(8, k.stockHealth || inv)), lowItems, critItems, slots, hours, queue, lastSale };
}

function InventoryMeter({ pct, status }) {
  const segs = 14;
  const filled = Math.round((pct / 100) * segs);
  const color = status === "crit" ? "var(--crit)" : status === "warn" ? "var(--warn)" : "var(--pos)";
  return (
    <div style={{ display: "flex", gap: 2, height: 10 }}>
      {Array.from({ length: segs }).map((_, i) => (
        <div key={i} style={{
          flex: 1,
          background: i < filled ? color : "var(--surface-sunk)",
          borderRadius: 1.5,
          opacity: i < filled ? (i < filled - 2 ? 1 : 0.85) : 1,
          transition: "background 400ms ease",
        }}/>
      ))}
    </div>
  );
}

function WasteMeter({ pct, status }) {
  const scale = 8;
  const fillW = Math.min(100, (pct / scale) * 100);
  const targetX = (WASTE_TARGET / scale) * 100;
  const over = pct > WASTE_TARGET;
  const color = over ? (status === "crit" ? "var(--crit)" : "var(--warn)") : "var(--ink-1)";
  return (
    <div style={{ position: "relative", height: 10, marginTop: 4 }}>
      <div style={{ position: "absolute", inset: 0, background: "var(--surface-sunk)", borderRadius: 2, overflow: "hidden" }}>
        <div style={{
          position: "absolute", inset: 0, width: `${fillW}%`,
          background: color, opacity: over ? 0.9 : 0.75,
          transition: "width 600ms ease, background 400ms ease",
        }}/>
      </div>
      <div style={{
        position: "absolute", top: -3, bottom: -3, left: `${targetX}%`,
        width: 1.5, marginLeft: -0.75, background: "var(--ink-1)", opacity: 0.55,
      }}/>
      <div style={{
        position: "absolute", top: -5, left: `calc(${targetX}% - 3px)`,
        width: 6, height: 4, background: "var(--ink-1)", opacity: 0.6,
        clipPath: "polygon(50% 100%, 0 0, 100% 0)",
      }}/>
    </div>
  );
}

function LivePulse({ status, lang = "en" }) {
  const color = status === "crit" ? "var(--crit)" : status === "warn" ? "var(--warn)" : "var(--pos)";
  return (
    <span style={{ display: "inline-flex", alignItems: "center", gap: 5 }}>
      <span style={{ position: "relative", width: 6, height: 6 }}>
        <span style={{ position: "absolute", inset: 0, borderRadius: "50%", background: color }}/>
        <span style={{
          position: "absolute", inset: -3, borderRadius: "50%", background: color,
          opacity: 0.35, animation: "kioskPulse 1.6s ease-out infinite",
        }}/>
      </span>
      <span style={{ fontSize: 10, fontWeight: 500, letterSpacing: "0.06em", color: "var(--ink-3)" }}>{lang === "ar" ? "مباشر" : "LIVE"}</span>
    </span>
  );
}

function kioskOperationalStatus(k, lang = "en") {
  const issue = String(k.issue || "").toLowerCase();
  let label = "open";
  if (issue.includes("variance")) label = "variance issue";
  else if (issue.includes("closing")) label = "needs closing";
  else if (Number(k.stockHealth || 0) < 55 || Number(k.ops?.inv || 100) < 55) label = "low stock";
  else if (k.status === "crit") label = "needs closing";
  else if (k.status === "warn") label = "open / watch";
  return arTerm(lang, label);
}

function RealtimeKioskCard({ k, ops, onPick, lang }) {
  const ar = lang === "ar";
  const statusLabel = kioskOperationalStatus({ ...k, ops }, lang);
  const badgeClass = k.status === "good" ? "badge-pos" : k.status === "warn" ? "badge-warn" : "badge-crit";
  const stockedItems = Math.max(0, Number(ops.slots || 0) - Number(ops.critItems || 0) - Number(ops.lowItems || 0));
  const staffCount = Number(k.staff);
  const staffLabel = Number.isFinite(staffCount) && staffCount > 0
    ? (ar ? `${staffCount} موظفين` : `${staffCount} staff`)
    : (ar ? "الطاقم غير متاح" : "staff unknown");
  const activityLabel = ops.queue > 0
    ? (ar ? `${ops.queue} في الطابور` : `${ops.queue} in queue`)
    : ops.lastSale > 0
      ? (ar ? `بيع قبل ${ops.lastSale}ث` : `sale ${ops.lastSale}s ago`)
      : (ar ? "متزامن" : "synced");
  return (
    <div className="card" onClick={onPick} style={{
      display: "flex", flexDirection: "column",
      cursor: "pointer", overflow: "hidden",
      transition: "border-color 100ms ease, box-shadow 100ms ease, transform 100ms ease",
    }}
      onMouseEnter={e => { e.currentTarget.style.borderColor = "var(--line-strong)"; e.currentTarget.style.boxShadow = "var(--shadow-1)"; }}
      onMouseLeave={e => { e.currentTarget.style.borderColor = ""; e.currentTarget.style.boxShadow = ""; }}
    >
      <div style={{ padding: "14px 16px 12px", borderBottom: "1px solid var(--line-soft)" }}>
        <div className="between" style={{ marginBottom: 4 }}>
          <div className="row" style={{ gap: 8, minWidth: 0 }}>
            <span className={`badge ${badgeClass}`} style={{ height: 18, fontSize: 10.5 }}>{statusLabel}</span>
            <span className="t-small faint t-num">{k.id}</span>
          </div>
          <LivePulse status={k.status} lang={lang}/>
        </div>
        <div style={{ fontSize: 15.5, fontWeight: 500, letterSpacing: "-0.01em", lineHeight: 1.2 }}>{arTerm(lang, k.name)}</div>
        <div className="t-small subtle" style={{ marginTop: 2 }}>
          {arTerm(lang, k.city)} · {staffLabel} · {activityLabel}
        </div>
      </div>

      <div style={{ display: "grid", gridTemplateColumns: "1.2fr 1fr 1fr", borderBottom: "1px solid var(--line-soft)" }}>
        <div style={{ padding: "10px 12px 10px 16px", borderInlineEnd: "1px solid var(--line-soft)" }}>
          <div className="t-micro" style={{ marginBottom: 2 }}>{ar ? "الإيراد" : "Revenue"}</div>
          <div className="t-num" style={{ fontSize: 16, fontWeight: 500, fontVariantNumeric: "tabular-nums" }}>{fmtMoney(k.revenue)}</div>
        </div>
        <div style={{ padding: "10px 12px", borderInlineEnd: "1px solid var(--line-soft)" }}>
          <div className="t-micro" style={{ marginBottom: 2 }}>{ar ? "الطلبات" : "Orders"}</div>
          <div className="t-num" style={{ fontSize: 16, fontWeight: 500, fontVariantNumeric: "tabular-nums" }}>{k.orders}</div>
        </div>
        <div style={{ padding: "10px 16px 10px 12px" }}>
          <div className="t-micro" style={{ marginBottom: 2 }}>{ar ? "الهامش" : "Margin"}</div>
          <div className="t-num" style={{ fontSize: 16, fontWeight: 500, fontVariantNumeric: "tabular-nums" }}>{k.margin}%</div>
        </div>
      </div>

      <div style={{ padding: "14px 16px 8px" }}>
        <div className="between" style={{ marginBottom: 6 }}>
          <span className="t-micro">{ar ? "المخزون" : "Inventory"}</span>
          <span className="t-num" style={{ fontSize: 12.5, fontWeight: 500 }}>{ops.inv}%</span>
        </div>
        <InventoryMeter pct={ops.inv} status={k.status}/>
        <div className="t-small subtle" style={{ marginTop: 6, fontSize: 11.5 }}>
          {ops.critItems > 0
            ? <><span style={{ color: "var(--crit)" }}>{ops.critItems} {ar ? "حرج" : "critical"}</span> · {ops.lowItems} {ar ? "منخفض" : "low"} · {stockedItems} {ar ? "متوفر" : "stocked"}</>
            : ops.lowItems > 0
              ? <><span style={{ color: "var(--warn)" }}>{ops.lowItems} {ar ? "منخفض" : "low"}</span> · {stockedItems} {ar ? "متوفر" : "stocked"}{ops.hours != null ? <> · {ar ? "نفاد خلال" : "runout"} ~{ops.hours}h</> : null}</>
              : <>{ops.slots} {ar ? "بنود بحالة جيدة" : "items in good standing"}{ops.hours != null ? <> · {ar ? "نفاد خلال" : "runout"} {ops.hours}h+</> : null}</>
          }
        </div>
      </div>

      <div style={{ padding: "10px 16px 14px" }}>
        <div className="between" style={{ marginBottom: 6 }}>
          <span className="t-micro">{ar ? "هدر اليوم" : "Waste today"}</span>
          <div className="row" style={{ gap: 8 }}>
            <span className="t-small subtle" style={{ fontSize: 11 }}>{ar ? "الهدف" : "target"} {WASTE_TARGET}%</span>
            <span className={"t-num " + (k.waste > WASTE_TARGET ? "delta-neg" : "")} style={{ fontSize: 12.5, fontWeight: 500 }}>{Number(k.waste).toFixed(1)}%</span>
          </div>
        </div>
        <WasteMeter pct={k.waste} status={k.status}/>
        <div className="t-small subtle" style={{ marginTop: 6, fontSize: 11.5 }}>
          IQD {Math.round(k.revenue * k.waste / 100).toLocaleString()} {ar ? "خسارة تقديرية" : "estimated loss"}
          {k.waste > WASTE_TARGET && <> · <span style={{ color: "var(--warn)" }}>{(k.waste - WASTE_TARGET).toFixed(1)} {ar ? "نقاط فوق" : "pts over"}</span></>}
        </div>
      </div>
    </div>
  );
}

const makeKioskDraft = (sourceDriven = false) => ({
  kioskCode: sourceDriven ? "" : "K-11",
  name: sourceDriven ? "" : "New Kiosk",
  city: sourceDriven ? "" : "Baghdad",
  area: sourceDriven ? "" : "Mansour",
  warehouse: "",
});

function KiosksScreen({ lang, onPick, bootstrap, sync, sourceOfTruth, refreshOdoo, scope = "Daily" }) {
  const ar = lang === "ar";
  const [view, setView] = useState("cards");
  const [city, setCity] = useState("all");
  const [sortBy, setSortBy] = useState("status");
  const rows = odooKioskRows(bootstrap, scope);
  const [tick, setTick] = useState(0);
  const sourceDriven = isSourceDrivenPayload(bootstrap);
  const animateDemoMetrics = canUseDemoFallback(bootstrap);
  const scopeWord = scope === "Monthly" ? (ar ? "هذا الشهر" : "this month")
    : scope === "Weekly" ? (ar ? "هذا الأسبوع" : "this week")
      : scope === "Yearly" ? (ar ? "هذه السنة" : "this year")
        : (ar ? "اليوم" : "today");
  const revenueScopeLabel = ar ? `الإيراد ${scopeWord}` : `Revenue ${scopeWord}`;

  const setup = unwrapOdoo(sync?.warehouseSetup) || EMPTY_WAREHOUSE_SETUP;
  const enabled = Boolean(sourceOfTruth?.enabled);
  const [kioskModalOpen, setKioskModalOpen] = useState(false);
  const [kioskBusy, setKioskBusy] = useState(false);
  const [kioskError, setKioskError] = useState("");
  const [kioskDraft, setKioskDraft] = useState(() => makeKioskDraft(sourceDriven));
  useEffect(() => {
    if (!sourceDriven) return;
    setKioskDraft((d) => {
      const next = {
        ...d,
        kioskCode: d.kioskCode === "K-11" ? "" : d.kioskCode,
        name: d.name === "New Kiosk" ? "" : d.name,
        city: d.city === "Baghdad" ? "" : d.city,
        area: d.area === "Mansour" ? "" : d.area,
      };
      return next.kioskCode === d.kioskCode && next.name === d.name && next.city === d.city && next.area === d.area ? d : next;
    });
  }, [sourceDriven]);
  useEffect(() => {
    setKioskDraft((d) => d.warehouse ? d : { ...d, warehouse: setup.warehouses?.[0]?.id || setup.warehouses?.[0]?.code || "" });
  }, [setup.warehouses]);

  const submitKiosk = async (event) => {
    event.preventDefault();
    if (!enabled) {
      setKioskError("Connect the source engine before creating source kiosks");
      return;
    }
    setKioskBusy(true);
    setKioskError("");
    try {
      await sourceOfTruth.createKiosk(kioskDraft);
      await refreshOdoo?.();
      setKioskDraft({
        ...makeKioskDraft(sourceDriven),
        warehouse: setup.warehouses?.[0]?.id || setup.warehouses?.[0]?.code || "",
      });
      setKioskModalOpen(false);
    } catch (error) {
      setKioskError(compactError(error));
    } finally {
      setKioskBusy(false);
    }
  };

  useEffect(() => {
    if (!animateDemoMetrics) return undefined;
    const id = setInterval(() => setTick(t => t + 1), 3200);
    return () => clearInterval(id);
  }, [animateDemoMetrics]);

  const live = useMemo(() => rows.map((k, i) => {
    const ops = deriveKioskOps(k, animateDemoMetrics);
    if (!animateDemoMetrics) {
      return { ...k, ops };
    }
    const phase = (tick + i) % 6;
    const revBump = phase * 4 + (i * 3) % 11;
    const ordBump = phase % 3;
    const invJitter = ((tick * (i + 1)) % 5) - 2;
    const wasteJitter = (((tick + i * 2) % 7) - 3) * 0.04;
    return {
      ...k,
      revenue: k.revenue + revBump * 6,
      orders: k.orders + ordBump,
      waste: Math.max(0.4, Number(k.waste || 0) + wasteJitter),
      ops: { ...ops, inv: Math.max(8, Math.min(96, ops.inv + invJitter)) },
    };
  }), [animateDemoMetrics, rows, tick]);

  const cities = ["all", ...new Set(rows.map(k => k.city))];
  const sorted = useMemo(() => {
    let arr = city === "all" ? live : live.filter(k => k.city === city);
    arr = [...arr];
    if (sortBy === "status") {
      const order = { crit: 0, warn: 1, good: 2 };
      arr.sort((a, b) => order[a.status] - order[b.status] || b.revenue - a.revenue);
    } else if (sortBy === "revenue") arr.sort((a, b) => b.revenue - a.revenue);
    else if (sortBy === "waste") arr.sort((a, b) => b.waste - a.waste);
    else if (sortBy === "inventory") arr.sort((a, b) => a.ops.inv - b.ops.inv);
    return arr;
  }, [live, city, sortBy]);

  const counts = useMemo(() => ({
    crit: live.filter(k => k.status === "crit").length,
    warn: live.filter(k => k.status === "warn").length,
    good: live.filter(k => k.status === "good").length,
    avgInv: live.length ? Math.round(live.reduce((s, k) => s + k.ops.inv, 0) / live.length) : 0,
    avgWaste: live.length ? (live.reduce((s, k) => s + k.waste, 0) / live.length).toFixed(1) : "0.0",
  }), [live]);
  const totalRevenue = live.reduce((s, k) => s + k.revenue, 0);
  const totalOrders = live.reduce((s, k) => s + k.orders, 0);
  const revenueDelta = sourceDriven
    ? (ar ? `${totalOrders} طلبات مصدر` : `${totalOrders} source orders`)
    : "8.4%";

  return (
    <div className="col" style={{ gap: 14 }}>
      <style>{`
        @keyframes kioskPulse {
          0% { transform: scale(0.8); opacity: 0.55; }
          70% { transform: scale(1.8); opacity: 0; }
          100% { transform: scale(1.8); opacity: 0; }
        }
      `}</style>

      <div style={{ display: "grid", gridTemplateColumns: "repeat(4, 1fr)", gap: 12 }}>
        <KPI label={ar ? "النشطة" : "Active"} value={String(rows.length)} footer={ar ? `${counts.good} سليم · ${counts.warn} مراقبة · ${counts.crit} حرج` : `${counts.good} ok · ${counts.warn} watch · ${counts.crit} crit`}/>
        <KPI label={revenueScopeLabel} value={fmtMoney(totalRevenue)} delta={revenueDelta} deltaDir={sourceDriven ? "flat" : "up"}/>
        <KPI label={ar ? "متوسط المخزون" : "Avg inventory"} value={`${counts.avgInv}%`} footer={ar ? "عبر الشبكة" : "across fleet"}/>
        <KPI label={ar ? "متوسط الهدر" : "Avg waste"} value={`${counts.avgWaste}%`} delta={`${ar ? "الهدف" : "target"} ${WASTE_TARGET}%`} deltaDir={parseFloat(counts.avgWaste) <= WASTE_TARGET ? "up" : "down"}/>
      </div>

      <div style={{ display: "flex", flexWrap: "wrap", alignItems: "center", justifyContent: "space-between", gap: 10, padding: "0 2px" }}>
        <div className="row" style={{ gap: 6, flexWrap: "wrap" }}>
          {cities.map(c => (
            <button key={c} onClick={() => setCity(c)}
              className={"btn " + (city === c ? "btn-primary" : "btn-ghost")}
              style={{ height: 28, fontSize: 12 }}>
              {c === "all" ? (ar ? "كل المدن" : "All cities") : arTerm(lang, c)}
              {c !== "all" && <span className="subtle" style={{ marginInlineStart: 4, fontSize: 11 }}>{rows.filter(k => k.city === c).length}</span>}
            </button>
          ))}
        </div>
        <div className="row" style={{ gap: 8 }}>
          <span className="t-small subtle" style={{ fontSize: 11.5 }}>{ar ? "ترتيب" : "Sort"}</span>
          <div className="row" style={{ gap: 0, border: "1px solid var(--line)", borderRadius: 6, overflow: "hidden", height: 28 }}>
            {[
              { id: "status", l: ar ? "الحالة" : "Status" },
              { id: "revenue", l: ar ? "الإيراد" : "Revenue" },
              { id: "inventory", l: ar ? "المخزون" : "Inventory" },
              { id: "waste", l: ar ? "الهدر" : "Waste" },
            ].map(s => (
              <button key={s.id} onClick={() => setSortBy(s.id)}
                style={{
                  padding: "0 10px", fontSize: 12,
                  background: sortBy === s.id ? "var(--surface-sunk)" : "transparent",
                  color: sortBy === s.id ? "var(--ink)" : "var(--ink-2)",
                  borderInlineEnd: "1px solid var(--line-soft)",
                }}>{s.l}</button>
            ))}
          </div>
          <div className="row" style={{ gap: 0, border: "1px solid var(--line)", borderRadius: 6, overflow: "hidden", height: 28 }}>
            <button onClick={() => setView("cards")}
              title={ar ? "بطاقات" : "Cards"}
              style={{
                width: 32, display: "grid", placeItems: "center",
                background: view === "cards" ? "var(--surface-sunk)" : "transparent",
                color: view === "cards" ? "var(--ink)" : "var(--ink-3)",
                borderInlineEnd: "1px solid var(--line-soft)",
              }}><Icon name="grid" size={13}/></button>
            <button onClick={() => setView("table")}
              title={ar ? "جدول" : "Table"}
              style={{
                width: 32, display: "grid", placeItems: "center",
                background: view === "table" ? "var(--surface-sunk)" : "transparent",
                color: view === "table" ? "var(--ink)" : "var(--ink-3)",
              }}><Icon name="list" size={13}/></button>
          </div>
          <button type="button" className="btn btn-primary"
            onClick={() => { setKioskError(""); setKioskModalOpen(true); }}
            disabled={!enabled}
            style={{ height: 28, fontSize: 12 }}>
            <Icon name="plus" size={12}/> {ar ? "إنشاء موقع كشك" : "Create kiosk location"}
          </button>
        </div>
      </div>

      {view === "cards" ? (
        <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fill, minmax(320px, 1fr))", gap: 12 }}>
          {sorted.map(k => <RealtimeKioskCard key={k.id} k={k} ops={k.ops} onPick={() => onPick(k)} lang={lang}/>)}
        </div>
      ) : (
        <div className="card">
          <table className="tbl">
            <thead>
              <tr>
                <th scope="col" style={{ width: 32 }}></th>
                <th scope="col">{ar ? "الكشك" : "Kiosk"}</th>
                <th scope="col">{ar ? "المدينة" : "City"}</th>
                <th scope="col">{ar ? "الحالة" : "Status"}</th>
                <th scope="col" style={{ textAlign: "end" }}>{revenueScopeLabel}</th>
                <th scope="col" style={{ textAlign: "end" }}>{ar ? "الطلبات" : "Orders"}</th>
                <th scope="col" style={{ width: 160 }}>{ar ? "المخزون" : "Inventory"}</th>
                <th scope="col" style={{ width: 160 }}>{ar ? "الهدر" : "Waste"}</th>
                <th scope="col" style={{ textAlign: "end" }}>{ar ? "الهامش" : "Margin"}</th>
                <th scope="col"></th>
              </tr>
            </thead>
            <tbody>
              {sorted.map(k => (
                <tr
                  key={k.id}
                  className="row-click"
                  onClick={() => onPick(k)}
                  tabIndex={0}
                  onKeyDown={(e) => { if (e.key === "Enter" || e.key === " ") { e.preventDefault(); onPick(k); } }}
                  aria-label={`${arTerm(lang, k.name)}, ${ar ? "فتح تفاصيل الكشك" : "open kiosk details"}`}
                >
                  <td><span className={`dot ${statusTone(k.status)}`}></span></td>
                  <td>
                    <div style={{ fontWeight: 500 }}>{arTerm(lang, k.name)}</div>
                    <div className="t-small faint">{k.id}</div>
                  </td>
                  <td className="muted">{arTerm(lang, k.city)}</td>
                  <td><span className={`badge ${k.status === "good" ? "badge-pos" : k.status === "warn" ? "badge-warn" : "badge-crit"}`}>{kioskOperationalStatus(k, lang)}</span></td>
                  <td style={{ textAlign: "end" }} className="t-num">{fmtMoney(k.revenue)}</td>
                  <td style={{ textAlign: "end" }} className="t-num muted">{k.orders}</td>
                  <td>
                    <div className="row" style={{ gap: 8 }}>
                      <div style={{ flex: 1 }}><InventoryMeter pct={k.ops.inv} status={k.status}/></div>
                      <span className="t-num" style={{ fontSize: 11.5, width: 28, textAlign: "end" }}>{k.ops.inv}%</span>
                    </div>
                  </td>
                  <td>
                    <div className="row" style={{ gap: 8 }}>
                      <div style={{ flex: 1 }}><WasteMeter pct={k.waste} status={k.status}/></div>
                      <span className={"t-num " + (k.waste > WASTE_TARGET ? "delta-neg" : "")} style={{ fontSize: 11.5, width: 32, textAlign: "end" }}>{k.waste.toFixed(1)}%</span>
                    </div>
                  </td>
                  <td style={{ textAlign: "end" }} className="t-num">{k.margin}%</td>
                  <td><Icon name="chevRight" size={13} style={{ color: "var(--ink-3)" }}/></td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}

      <Modal open={kioskModalOpen} onClose={() => !kioskBusy && setKioskModalOpen(false)}
        title={ar ? "إنشاء موقع كشك" : "Create kiosk location"}
        sub={ar ? "ينشئ stock.location + ضبط POS + كشك بيان" : "Creates stock.location + POS config + Bayaan kiosk"}>
        <form onSubmit={submitKiosk}>
          <div className="col" style={{ gap: 10 }}>
            {!enabled && (
              <div className="t-small muted" style={{ padding: 10, background: "var(--warn-soft)", borderRadius: 8 }}>
                {ar ? "المحرك الخلفي غير مضبوط في جلسة المتصفح. اضبط رابط الخلفية وسجل الدخول لإنشاء سجلات حقيقية." : "Backend engine is not configured in this browser session. Set the backend URL and sign in to create real records."}
              </div>
            )}
            <div style={{ display: "grid", gridTemplateColumns: "0.55fr 1fr", gap: 10 }}>
              <div>
                <label className="t-small muted">{ar ? "الرمز" : "Code"}</label>
                <input className="input" placeholder={sourceDriven ? "Source kiosk code" : "K-11"} value={kioskDraft.kioskCode} onChange={(event) => setKioskDraft({ ...kioskDraft, kioskCode: event.target.value.toUpperCase() })} />
              </div>
              <div>
                <label className="t-small muted">{ar ? "الاسم" : "Name"}</label>
                <input className="input" placeholder={sourceDriven ? "Source kiosk name" : "New Kiosk"} value={kioskDraft.name} onChange={(event) => setKioskDraft({ ...kioskDraft, name: event.target.value })} />
              </div>
            </div>
            <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 10 }}>
              <div>
                <label className="t-small muted">{ar ? "المدينة" : "City"}</label>
                <input className="input" placeholder={sourceDriven ? "City from source setup" : "Baghdad"} value={kioskDraft.city} onChange={(event) => setKioskDraft({ ...kioskDraft, city: event.target.value })} />
              </div>
              <div>
                <label className="t-small muted">{ar ? "المنطقة" : "Area"}</label>
                <input className="input" placeholder={sourceDriven ? "Area from source setup" : "Mansour"} value={kioskDraft.area} onChange={(event) => setKioskDraft({ ...kioskDraft, area: event.target.value })} />
              </div>
            </div>
            <label className="t-small muted">{ar ? "المستودع الأب" : "Parent warehouse"}</label>
            <select className="input" value={kioskDraft.warehouse} onChange={(event) => setKioskDraft({ ...kioskDraft, warehouse: event.target.value })}>
              {(setup.warehouses || []).map((warehouse) => (
                <option key={warehouse.id} value={warehouse.id}>{warehouse.code} · {warehouse.name}</option>
              ))}
            </select>
            {kioskError && <div className="t-small delta-neg">{kioskError}</div>}
            <div className="row" style={{ gap: 8, justifyContent: "flex-end", marginTop: 6 }}>
              <button type="button" className="btn btn-ghost" onClick={() => setKioskModalOpen(false)} disabled={kioskBusy}>{ui(ar, "cancel")}</button>
              <button type="submit" className="btn btn-primary"
                disabled={!enabled || kioskBusy || !(setup.warehouses || []).length}
                style={{ justifyContent: "center" }}>
                <Icon name="plus" size={12}/> {kioskBusy ? (ar ? "جار الإنشاء..." : "Creating...") : (ar ? "إنشاء كشك متزامن" : "Create synced kiosk")}
              </button>
            </div>
          </div>
        </form>
      </Modal>
    </div>
  );
}

