function AuditLogRail({ lang, sourceOfTruth }) {
  const ar = lang === "ar";
  const [events, setEvents] = React.useState(() => []);
  const [status, setStatus] = React.useState("idle");
  const [error, setError] = React.useState("");
  const loadEvents = React.useCallback(async () => {
    if (!sourceOfTruth?.enabled) {
      setEvents([]);
      setStatus("source-missing");
      setError("");
      return;
    }
    setStatus("loading");
    try {
      const payload = await sourceOfTruth.getAuditLog({ limit: 80 });
      const rows = normalizeAuditEvents(payload);
      setEvents(rows);
      setStatus("live");
      setError("");
    } catch (err) {
      setStatus("error");
      setError(compactError(err));
    }
  }, [sourceOfTruth]);

  React.useEffect(() => {
    void loadEvents();
    if (!sourceOfTruth?.enabled) return undefined;
    const subscription = sourceOfTruth.subscribeRealtime?.({
      onStatus: (next) => {
        if (next === "live" || next === "polling") setStatus("live");
      },
      onEvent: (event) => {
        setStatus("live");
        setEvents((rows) => {
          const next = normalizeRealtimeAuditEvent(event);
          return [next, ...rows.filter((row) => row.id !== next.id)].slice(0, 80);
        });
      },
      onError: (err) => {
        setStatus("error");
        setError(compactError(err));
      },
    });
    if (subscription) return () => subscription.close();
    const timer = window.setInterval(() => void loadEvents(), 8000);
    return () => window.clearInterval(timer);
  }, [loadEvents, sourceOfTruth?.enabled]);
  const sourceAuditMissing = status === "source-missing";

  return (
    <aside style={{
      width: 340,
      flexShrink: 0,
      background: "var(--surface)",
      borderInlineEnd: "1px solid var(--line)",
      display: "flex",
      flexDirection: "column",
      minHeight: 0,
    }}>
      <div className="between" style={{ height: 56, padding: "0 16px", borderBottom: "1px solid var(--line)" }}>
        <div>
          <div className="t-h2">{ui(ar, "liveActionLog")}</div>
          <div className="t-small subtle">
            {status === "live" ? (ar ? "متصل" : ui(ar, "realtimeStream")) : sourceAuditMissing ? (ar ? "سجل تدقيق المصدر غير متاح" : "Source audit log unavailable") : status === "error" ? ui(ar, "logUnavailable") : ui(ar, "loading")}
          </div>
        </div>
        <button className="btn btn-ghost" onClick={loadEvents} style={{ height: 28, fontSize: 12 }}>
          <Icon name="refresh" size={12}/>{ui(ar, "refresh")}
        </button>
      </div>
      {error && (
        <div className="t-small" style={{ margin: 12, padding: 10, border: "1px solid var(--crit)", borderRadius: 6, color: "var(--crit)", background: "var(--crit-soft)" }}>
          {error}
        </div>
      )}
      <div className="scroll" style={{ flex: 1, minHeight: 0, overflow: "auto", padding: 12 }}>
        <div className="col" style={{ gap: 10 }}>
          {events.map((event) => (
            <div key={event.id} className="card" style={{ padding: 12 }}>
              <div className="between" style={{ alignItems: "flex-start", gap: 8 }}>
                <div className="row" style={{ gap: 8, alignItems: "flex-start", minWidth: 0 }}>
                  <span className={`dot ${auditDotClass(event.severity)}`} style={{ marginTop: 7, flexShrink: 0 }}></span>
                  <div style={{ minWidth: 0 }}>
                    <div style={{ fontSize: 13, fontWeight: 500, lineHeight: 1.35 }}>{event.title}</div>
                    <div className="t-small subtle" style={{ marginTop: 3, lineHeight: 1.45 }}>{event.detail}</div>
                  </div>
                </div>
                <span className="t-num faint" style={{ fontSize: 11, whiteSpace: "nowrap" }}>{auditTimeLabel(event.occurredAt)}</span>
              </div>
              <div className="row" style={{ gap: 6, marginTop: 10, flexWrap: "wrap" }}>
                <span className={`badge ${auditSeverityClass(event.severity)}`}>{event.eventType || "system"}</span>
                {event.kiosk && <span className="badge">{event.kiosk}</span>}
                {event.reference && <span className="badge">{event.reference}</span>}
              </div>
              <div className="t-small faint" style={{ marginTop: 8 }}>{event.actor}</div>
            </div>
          ))}
          {!events.length && (
            <div className="card" style={{ padding: 14 }}>
              <div style={{ fontSize: 13, fontWeight: 500 }}>{sourceAuditMissing ? (ar ? "لا توجد أحداث تدقيق من المصدر" : "No source audit events loaded") : ui(ar, "noEventsYet")}</div>
              <div className="t-small subtle" style={{ marginTop: 4 }}>{sourceAuditMissing ? (ar ? "اربط محرك المصدر لعرض أحداث تدقيق بيان." : "Connect the source engine to show Bayaan audit events.") : ui(ar, "systemChangesAppear")}</div>
            </div>
          )}
        </div>
      </div>
    </aside>
  );
}

function AdminPanel({ lang, scope = "Daily" }) {
  const bayaan = useBayaan();
  const [active, setActive] = useState("overview");
  const [selectedKiosk, setSelectedKiosk] = useState(null);
  const allowedIds = useMemo(() => allowedAdminIds(bayaan.auth, bayaan.hasBackend), [bayaan.auth, bayaan.hasBackend]);
  const canViewAuditLog = isSuperadminAuth(bayaan.auth);
  // Backend requires procurement + manager scope for /product_create_bundle; a
  // manager (or owner/superadmin) satisfies both. This only gates the Confirm
  // button UX — the route enforces it server-side regardless.
  const canCreateProduct = useMemo(() => {
    if (!bayaan.hasBackend) return false;
    const user = bayaan.auth?.user;
    if (!user) return false;
    const roles = Array.isArray(user.roles) ? user.roles : [];
    const allowed = ["manager", "superadmin", "owner"];
    return roles.some((r) => allowed.includes(r)) || allowed.includes(user.primaryRole);
  }, [bayaan.auth, bayaan.hasBackend]);
  // Invoice receipt = procurement scope (logistics suffices, unlike product creation).
  const canReceiveInvoice = useMemo(() => {
    if (!bayaan.hasBackend) return false;
    const user = bayaan.auth?.user;
    if (!user) return false;
    const roles = Array.isArray(user.roles) ? user.roles : [];
    const allowed = ["logistics", "manager", "superadmin", "owner"];
    return roles.some((r) => allowed.includes(r)) || allowed.includes(user.primaryRole);
  }, [bayaan.auth, bayaan.hasBackend]);
  // Server capability map (auth_status -> bayaan.auth.user.capabilities). Null
  // in demo/no-backend so the demo is unaffected (null => treat as all-allowed).
  // Threaded into each write-bearing screen (closing/suppliers/staff/settings/
  // accounting) as a `caps` prop; the top-bar New Transfer/Approvals controls are
  // gated inside AdminSidebar from the same capability map.
  const caps = useMemo(() => authCaps(bayaan.auth, bayaan.hasBackend), [bayaan.auth, bayaan.hasBackend]);
  const [auditLogOpen, setAuditLogOpen] = useState(false);
  // The AdminPanel uses the SAME gateway as the BayaanProvider. When the
  // user toggles to Demo mode, we present a transparent noop wrapper so
  // every screen's `sourceOfTruth?.enabled` check falls through to the
  // existing MOCK fallback paths without any per-screen plumbing.
  // Live-only product: the AdminPanel always uses the real Bayaan gateway. When no
  // backend URL is configured the gateway is simply disabled (enabled:false) and the
  // dashboard shows honest empty/"connect backend" states — never demo data.
  const baseGateway = bayaan.gateway;
  const liveBackendActive = baseGateway.enabled;
  const sourceOfTruth = baseGateway;
  const [sync, setSync] = useState({
    status: liveBackendActive ? "syncing" : "missing",
    bootstrap: EMPTY_ENGINE_SNAPSHOT,
    warehouseSetup: EMPTY_WAREHOUSE_SETUP,
    error: "",
  });
  const [realtime, setRealtime] = useState({
    status: liveBackendActive ? "connecting" : "missing",
    lastEvent: null,
    eventCount: 0,
    error: "",
  });
  const realtimeRefreshRef = React.useRef(false);

  useEffectIns(() => {
    if (typeof window === "undefined") return undefined;
    window.__bayaanSetAdminSection = setActive;
    return () => {
      if (window.__bayaanSetAdminSection === setActive) delete window.__bayaanSetAdminSection;
    };
  }, []);

  const refreshOdoo = React.useCallback(async () => {
    if (!baseGateway.enabled) {
      setSync({
        status: "missing",
        bootstrap: EMPTY_ENGINE_SNAPSHOT,
        warehouseSetup: EMPTY_WAREHOUSE_SETUP,
        error: "No backend connected. Configure the Bayaan engine URL to load live data.",
      });
      return;
    }
    setSync((current) => ({ ...current, status: "syncing", error: "" }));
    try {
      const [bootstrap, warehouseSetup] = await Promise.all([
        sourceOfTruth.getChainBootstrap(),
        sourceOfTruth.getWarehouseSetup(),
      ]);
      setSync({
        status: "synced",
        bootstrap: markLiveOnlySnapshot(bootstrap),
        warehouseSetup: markLiveOnlyWarehouseSetup(warehouseSetup),
        error: "",
      });
    } catch (error) {
      setSync((current) => ({
        ...current,
        status: "error",
        bootstrap: current.bootstrap || EMPTY_ENGINE_SNAPSHOT,
        warehouseSetup: current.warehouseSetup || EMPTY_WAREHOUSE_SETUP,
        error: compactError(error),
      }));
    }
  }, [baseGateway.enabled, sourceOfTruth]);

  useEffect(() => {
    void refreshOdoo();
  }, [refreshOdoo, baseGateway.enabled]);

  useEffect(() => {
    if (!liveBackendActive) return undefined;
    const refreshAfterSourceMutation = () => {
      void refreshOdoo();
    };
    window.addEventListener("bayaan:source-mutated", refreshAfterSourceMutation);
    return () => window.removeEventListener("bayaan:source-mutated", refreshAfterSourceMutation);
  }, [liveBackendActive, refreshOdoo]);

  useEffect(() => {
    if (!liveBackendActive) {
      setRealtime({
        status: "missing",
        lastEvent: null,
        eventCount: 0,
        error: "",
      });
      return undefined;
    }
    if (!bayaan.auth.authenticated) {
      setRealtime({
        status: "missing",
        lastEvent: null,
        eventCount: 0,
        error: "Sign in to start the realtime stream.",
      });
      return undefined;
    }
    const subscription = sourceOfTruth.subscribeRealtime({
      onStatus: (status) => {
        setRealtime((current) => ({ ...current, status, error: "" }));
      },
      onEvent: (event) => {
        setRealtime((current) => ({
          status: current.status === "polling" ? "polling" : "live",
          lastEvent: event,
          eventCount: current.eventCount + 1,
          error: "",
        }));
        if (!realtimeRefreshRef.current) {
          realtimeRefreshRef.current = true;
          window.setTimeout(() => {
            realtimeRefreshRef.current = false;
            void refreshOdoo();
          }, 250);
        }
      },
      onError: (error) => {
        setRealtime((current) => ({ ...current, status: "error", error: compactError(error) }));
      },
    });
    return () => subscription.close();
  }, [liveBackendActive, bayaan.auth.authenticated, refreshOdoo, sourceOfTruth]);

  useEffect(() => {
    if (!allowedIds.length || active === "kioskDetail") return;
    if (!allowedIds.includes(active)) setActive(allowedIds[0]);
  }, [active, allowedIds]);

  useEffect(() => {
    if (!canViewAuditLog && auditLogOpen) setAuditLogOpen(false);
  }, [auditLogOpen, canViewAuditLog]);

  const openKiosk = (kiosk) => {
    setSelectedKiosk(kiosk || null);
    setActive("kioskDetail");
  };

  const dashboardSync = useMemo(() => ({
    ...sync,
    status: sync.status === "demo" ? "missing" : sync.status,
    bootstrap: sync.bootstrap || EMPTY_ENGINE_SNAPSHOT,
    warehouseSetup: sync.warehouseSetup || EMPTY_WAREHOUSE_SETUP,
  }), [sync]);
  const dashboardBootstrap = dashboardSync.bootstrap;
  const dashboardWarehouses = (unwrapOdoo(dashboardSync?.warehouseSetup)?.warehouses) || [];

  // Global time scope: when a non-daily period is selected, fetch that period's orders
  // once here and overlay them into the bootstrap (buildScopedBootstrap). Passing the
  // scoped bootstrap to every screen makes all order/summary-derived views — Overview
  // live feed, kiosk-detail tabs, Sales monitor, payment mix, etc. — follow the toggle.
  const [scopeOrders, setScopeOrders] = useState(null);
  useEffect(() => {
    if (!scope || scope === "Daily" || !liveBackendActive || typeof sourceOfTruth.getPosOrdersHistory !== "function") {
      setScopeOrders(null);
      return undefined;
    }
    let alive = true;
    setScopeOrders(null);
    sourceOfTruth.getPosOrdersHistory({ scope })
      .then((res) => { if (alive) setScopeOrders(Array.isArray(res?.orders) ? res.orders : []); })
      .catch(() => { if (alive) setScopeOrders([]); });
    return () => { alive = false; };
  }, [scope, liveBackendActive, sourceOfTruth, dashboardBootstrap]);
  const scopedBootstrap = useMemo(
    () => buildScopedBootstrap(dashboardBootstrap, scope, scopeOrders),
    [dashboardBootstrap, scope, scopeOrders],
  );

  const screens = {
    overview: <OverviewScreen lang={lang} bootstrap={scopedBootstrap} scope={scope}/>,
    insights: <InsightsScreen lang={lang} bootstrap={scopedBootstrap} sourceOfTruth={sourceOfTruth} navigate={setActive} refreshOdoo={refreshOdoo} canCreateProduct={canCreateProduct} canReceiveInvoice={canReceiveInvoice} warehouses={dashboardWarehouses}/>,
    sales: <SalesMonitorScreen lang={lang} bootstrap={scopedBootstrap} scope={scope} sourceOfTruth={sourceOfTruth}/>,
    kiosks: <KiosksScreen lang={lang} bootstrap={scopedBootstrap} sync={dashboardSync} sourceOfTruth={sourceOfTruth} refreshOdoo={refreshOdoo} onPick={openKiosk} scope={scope}/>,
    kioskDetail: <KioskDetailScreen lang={lang} kiosk={selectedKiosk} bootstrap={scopedBootstrap} sourceOfTruth={sourceOfTruth} refreshOdoo={refreshOdoo} onBack={() => setActive("kiosks")} scope={scope}/>,
    warehouses: <WarehousesScreen lang={lang} sync={dashboardSync} sourceOfTruth={sourceOfTruth} refreshOdoo={refreshOdoo}/>,
    items: <ItemsCatalogScreen lang={lang} bootstrap={scopedBootstrap} sourceOfTruth={sourceOfTruth} refreshOdoo={refreshOdoo}/>,
    inventory: <InventoryScreen lang={lang} bootstrap={scopedBootstrap} sync={dashboardSync} sourceOfTruth={sourceOfTruth} refreshOdoo={refreshOdoo}/>,
    products: <ProductsScreen lang={lang} bootstrap={scopedBootstrap} sourceOfTruth={sourceOfTruth} refreshOdoo={refreshOdoo}/>,
    closing: <ClosingScreen lang={lang} bootstrap={scopedBootstrap} sourceOfTruth={sourceOfTruth} caps={caps}/>,
    waste: <WasteScreen lang={lang} bootstrap={scopedBootstrap}/>,
    suppliers: <SuppliersScreen lang={lang} bootstrap={scopedBootstrap} sync={dashboardSync} sourceOfTruth={sourceOfTruth} refreshOdoo={refreshOdoo} caps={caps}/>,
    staff: <HRPayrollScreen lang={lang} bootstrap={scopedBootstrap} sourceOfTruth={sourceOfTruth} refreshOdoo={refreshOdoo} caps={caps}/>,
    finance: <ReportsScreen lang={lang} bootstrap={scopedBootstrap} mode="finance" sourceOfTruth={sourceOfTruth} refreshOdoo={refreshOdoo} scope={scope}/>,
    gl: <AccountingScreen lang={lang} view="gl" bootstrap={scopedBootstrap} sourceOfTruth={sourceOfTruth} scope={scope} caps={caps}/>,
    journals: <AccountingScreen lang={lang} view="journals" bootstrap={scopedBootstrap} sourceOfTruth={sourceOfTruth} scope={scope} caps={caps}/>,
    trialBalance: <AccountingScreen lang={lang} view="trialBalance" bootstrap={scopedBootstrap} sourceOfTruth={sourceOfTruth} scope={scope} caps={caps}/>,
    statements: <AccountingScreen lang={lang} view="statements" bootstrap={scopedBootstrap} sourceOfTruth={sourceOfTruth} scope={scope} caps={caps}/>,
    cashFlow: <AccountingScreen lang={lang} view="cashFlow" bootstrap={scopedBootstrap} sourceOfTruth={sourceOfTruth} scope={scope} caps={caps}/>,
    agedPayable: <AccountingScreen lang={lang} view="agedPayable" bootstrap={scopedBootstrap} sourceOfTruth={sourceOfTruth} scope={scope} caps={caps}/>,
    agedReceivable: <AccountingScreen lang={lang} view="agedReceivable" bootstrap={scopedBootstrap} sourceOfTruth={sourceOfTruth} scope={scope} caps={caps}/>,
    taxReport: <AccountingScreen lang={lang} view="taxReport" bootstrap={scopedBootstrap} sourceOfTruth={sourceOfTruth} scope={scope} caps={caps}/>,
    coa: <AccountingScreen lang={lang} view="coa" bootstrap={scopedBootstrap} sourceOfTruth={sourceOfTruth} scope={scope} caps={caps}/>,
    reports: <ReportsScreen lang={lang} bootstrap={scopedBootstrap} scope={scope}/>,
    settings: <SettingsScreen lang={lang} sourceOfTruth={sourceOfTruth} refreshOdoo={refreshOdoo} caps={caps}/>,
  };
  const adminSourceDriven = isSourceDrivenPayload(dashboardBootstrap);
  const adminSummary = useMemo(() => odooSummary(dashboardBootstrap), [dashboardBootstrap]);
  const adminKiosks = useMemo(() => odooKioskRows(dashboardBootstrap), [dashboardBootstrap]);
  const adminWasteRows = useMemo(() => odooWasteRows(dashboardBootstrap), [dashboardBootstrap]);
  useEffect(() => {
    if (!adminKiosks.length) {
      setSelectedKiosk(null);
      return;
    }
    setSelectedKiosk((current) => {
      if (current && adminKiosks.some((row) => matchesKiosk(row.id, current))) return current;
      return adminKiosks[0];
    });
  }, [adminKiosks]);
  const adminSourceCounts = adminSummary?.sourceCounts || {};
  const sourceKioskCount = Number(adminSourceCounts.kiosks ?? adminKiosks.length ?? 0);
  const sourceCityCount = new Set(adminKiosks.map((kiosk) => kiosk.city).filter(Boolean)).size;
  const sourceOrderCount = Number(adminSourceCounts.orders ?? adminSummary?.totals?.ordersToday ?? 0);
  const sourcePaymentCount = Number(adminSourceCounts.payments ?? 0);
  const sourceClosingCount = Number(adminSourceCounts.closingRows ?? 0);
  const sourceWasteCount = Number(adminSourceCounts.wasteRows ?? adminWasteRows.length ?? 0);
  const sourceWasteAlerts = Number(adminSummary?.alerts?.wasteLossAlerts ?? 0);
  const sourceUnresolvedAlerts = Number(adminSummary?.alerts?.unresolvedVariances ?? 0);
  const sourceRecipeIssues = Number(adminSummary?.alerts?.recipePostingIssues ?? 0);
  const sourceLowStockAlerts = Number(adminSummary?.alerts?.lowStockItems ?? 0);
  const sourceInsightAlerts = sourceUnresolvedAlerts + sourceWasteAlerts + sourceRecipeIssues + sourceLowStockAlerts;
  const selectedForTitle = selectedKiosk || adminKiosks[0] || null;
  const adminNavBadges = adminSourceDriven ? {
    insights: sourceInsightAlerts,
    closing: sourceUnresolvedAlerts + sourceRecipeIssues,
    waste: sourceWasteAlerts,
  } : null;
  const sourceOverviewSub = {
    en: `${sourceKioskCount} source kiosks / ${sourceOrderCount} orders / ${sourceClosingCount} closes`,
    ar: `${sourceKioskCount} أكشاك مصدر / ${sourceOrderCount} طلبات / ${sourceClosingCount} إغلاقات`,
  };
  const sourceKiosksSub = {
    en: `${sourceKioskCount} source locations${sourceCityCount ? ` / ${sourceCityCount} cities` : ""}`,
    ar: `${sourceKioskCount} مواقع مصدر${sourceCityCount ? ` / ${sourceCityCount} مدن` : ""}`,
  };
  const sourceKioskDetailSub = {
    en: `${selectedForTitle?.city || selectedForTitle?.area || "Source kiosk"} - ${selectedForTitle?.stockLocation || selectedForTitle?.warehouse || selectedForTitle?.posConfig || "stock location pending"}`,
    ar: `${selectedForTitle?.city || selectedForTitle?.area || "كشك مصدر"} - ${selectedForTitle?.stockLocation || selectedForTitle?.warehouse || selectedForTitle?.posConfig || "موقع المخزون غير محمل"}`,
  };
  const sourceSalesSub = {
    en: `${sourceOrderCount} source orders / ${sourcePaymentCount} payment rows / recipe posting status`,
    ar: `${sourceOrderCount} طلبات مصدر / ${sourcePaymentCount} سطور دفع / حالة ترحيل الوصفة`,
  };
  const sourceWasteSub = {
    en: `${sourceWasteCount} verified waste rows / ${sourceWasteAlerts} source alerts`,
    ar: `${sourceWasteCount} سطور هدر موثقة / ${sourceWasteAlerts} تنبيهات مصدر`,
  };
  const titles = {
    overview: { en: "Today Command Center", ar: "مركز قيادة اليوم", sub: adminSourceDriven ? sourceOverviewSub : { en: "Saturday, May 9 - all kiosks", ar: "السبت، 9 مايو · جميع الأكشاك" } },
    insights: { en: "AI Assistant", ar: "المساعد الذكي", sub: { en: "Ask, analyze, and take action — AI-assisted", ar: "اسأل، حلّل، ونفّذ — بمساعدة الذكاء الاصطناعي" } },
    kiosks: { en: "Kiosks", ar: "الأكشاك", sub: adminSourceDriven ? sourceKiosksSub : { en: "10 active locations - 3 cities", ar: "١٠ مواقع نشطة · ٣ مدن" } },
    kioskDetail: {
      en: `${selectedForTitle?.name || "Kiosk"} - ${selectedForTitle?.id || selectedForTitle?.kiosk_code || "--"}`,
      ar: `${selectedForTitle?.name || "كشك"} · ${selectedForTitle?.id || selectedForTitle?.kiosk_code || "--"}`,
      sub: adminSourceDriven ? sourceKioskDetailSub : {
            en: `${selectedForTitle?.city || "-"} - ${selectedForTitle?.staff ?? "staff unknown"} staff - stock location scoped`,
            ar: `${selectedForTitle?.city || "-"} · ${selectedForTitle?.staff ?? "الطاقم غير متاح"} موظفين · مخزون مستقل`,
          },
    },
    sales: { en: "Sales & POS Monitor", ar: "مراقبة المبيعات ونقاط البيع", sub: adminSourceDriven ? sourceSalesSub : { en: "Demo POS orders, payment methods, refunds, voids, and recipe posting", ar: "أوامر POS تجريبية وطرق الدفع والمرتجعات والإلغاءات وترحيل الوصفة" } },
    warehouses: { en: "Warehouses", ar: "المستودعات", sub: { en: "Central receiving warehouses and stock receipts", ar: "مستودعات الاستلام المركزية وحركات المخزون" } },
    items: { en: "Stock inventory", ar: "جرد المخزون", sub: { en: "Global purchasable stock items used by suppliers, purchases, and recipes", ar: "بنود مخزون عالمية للموردين والمشتريات والوصفات" } },
    inventory: { en: "Stock & Allocation", ar: "المخزون والتوزيع", sub: { en: "Warehouse stock, kiosk stock, stock needs, and transfer execution", ar: "مخزون المستودع والأكشاك والتحويلات والتنبيهات" } },
    products: { en: "Products & Recipes", ar: "المنتجات والوصفات", sub: { en: "Menu, prices, sizes, images, ingredient recipes", ar: "القائمة والأسعار والأحجام والصور ووصفات المكونات" } },
    closing: { en: "Daily Close & Variance", ar: "الإغلاق اليومي والمطابقة", sub: { en: "Expected vs counted - across kiosks", ar: "متوقع مقابل فعلي — عبر الأكشاك" } },
    waste: { en: "Waste & Loss", ar: "الهدر والخسارة", sub: adminSourceDriven ? sourceWasteSub : { en: "Demo last 7 days - 3 anomalies flagged", ar: "آخر ٧ أيام تجريبية · ٣ حالات شاذة" } },
    suppliers: { en: "Purchases & Suppliers", ar: "المشتريات والموردون", sub: { en: "Supplier health, purchase orders, ingredient costs, and margin impact", ar: "الموردون وطلبات الشراء وتكاليف المكونات وأثر الهامش" } },
    staff: { en: uiText("en", "hrPayroll"), ar: uiText("ar", "hrPayroll"), sub: { en: uiText("en", "hrPayrollSub"), ar: uiText("ar", "hrPayrollSub") } },
    finance: { en: "Finance overview", ar: "نظرة عامة مالية", sub: { en: "Profit, cash flow, payment split, and payroll impact", ar: "الأرباح والتدفق النقدي وطرق الدفع وأثر الرواتب" }, tip: { en: "A plain-language summary of the chain's money: revenue, estimated profit, cash-vs-online split, and how payroll affects the bottom line. Start here, then drill into the formal books below.", ar: "ملخّص مبسّط لأموال السلسلة: الإيرادات والربح التقديري وتقسيم النقد مقابل الدفع الإلكتروني وأثر الرواتب على صافي الربح. ابدأ من هنا ثم انتقل إلى الدفاتر الرسمية أدناه." } },
    gl: { en: "General Ledger", ar: "دفتر الأستاذ العام", sub: { en: "Every posted journal item from the ledger", ar: "كل قيد مرحّل من دفتر الأستاذ" }, tip: { en: "Every individual posted accounting line (debits and credits), account by account — the most detailed view of the books. Use it to trace any number back to the exact transaction behind it.", ar: "كل سطر محاسبي مرحّل على حدة (مدين ودائن) حساباً بحساب — أكثر العروض تفصيلاً للدفاتر. استخدمه لتتبّع أي رقم وصولاً إلى المعاملة الدقيقة وراءه." } },
    journals: { en: "Journal Entries", ar: "قيود اليومية", sub: { en: "Posted entries — POS sessions, bills, bank, manual", ar: "القيود المرحّلة — جلسات البيع والفواتير والبنك واليدوية" }, tip: { en: "Each accounting transaction grouped as one balanced entry — from POS sessions, supplier bills, bank, and manual postings. Open an entry to see its debit and credit lines.", ar: "كل معاملة محاسبية مجمّعة كقيد واحد متوازن — من جلسات نقاط البيع وفواتير الموردين والبنك والقيود اليدوية. افتح أي قيد لرؤية سطور المدين والدائن فيه." } },
    trialBalance: { en: "Trial Balance", ar: "ميزان المراجعة", sub: { en: "Opening, movement and closing balance per account", ar: "الرصيد الافتتاحي والحركة والختامي لكل حساب" }, tip: { en: "Each account's opening balance, movement, and closing balance, with total debits equal to total credits — the quick proof that the books are in balance for the period.", ar: "الرصيد الافتتاحي والحركة والرصيد الختامي لكل حساب، مع تساوي إجمالي المدين مع إجمالي الدائن — الدليل السريع على توازن الدفاتر خلال الفترة." } },
    statements: { en: "Income Statement & Balance Sheet", ar: "قائمة الدخل والميزانية", sub: { en: "Profit & loss and financial position from the real books", ar: "الأرباح والخسائر والمركز المالي من الدفاتر الحقيقية" }, tip: { en: "The two core financial statements: the income statement (profit & loss) shows performance over the period, and the balance sheet shows what the business owns and owes at a point in time.", ar: "القائمتان الماليتان الأساسيتان: قائمة الدخل (الأرباح والخسائر) تُظهر الأداء خلال الفترة، والميزانية العمومية تُظهر ما تملكه المنشأة وما عليها في لحظة معينة." } },
    coa: { en: "Chart of Accounts", ar: "دليل الحسابات", sub: { en: "Every account in the books with its balance", ar: "كل حساب في الدفاتر مع رصيده" }, tip: { en: "The master list of every account used in the books — assets, liabilities, income and expenses — with each balance. This is where you create, rename, reclassify, or archive accounts.", ar: "القائمة الرئيسية لكل حساب مستخدم في الدفاتر — الأصول والخصوم والإيرادات والمصروفات — مع رصيد كل حساب. من هنا تُنشئ الحسابات أو تعيد تسميتها أو تصنيفها أو تؤرشفها." } },
    cashFlow: { en: "Cash flow statement", ar: "قائمة التدفقات النقدية", sub: { en: "Cash in and out by counterpart account, with opening and closing cash", ar: "النقد الوارد والصادر حسب الحساب المقابل مع الرصيد الافتتاحي والختامي" }, tip: { en: "Where cash actually moved in and out over the period, by counterpart account, with opening and closing cash balances — separate from accrual profit, so you can see real liquidity.", ar: "من أين دخل النقد فعلياً وإلى أين خرج خلال الفترة حسب الحساب المقابل، مع الرصيد النقدي الافتتاحي والختامي — منفصلاً عن ربح الاستحقاق لرؤية السيولة الحقيقية." } },
    agedPayable: { en: "Aged payables", ar: "أعمار الذمم الدائنة", sub: { en: "What the chain owes suppliers, bucketed by age (open bills only)", ar: "ما تدين به السلسلة للموردين موزّعاً حسب العمر (الفواتير المفتوحة فقط)" }, tip: { en: "What the chain still owes its suppliers, grouped by how overdue each open bill is (current, 30, 60, 90+ days) — so you know who to pay and when.", ar: "ما لا تزال السلسلة تدين به لمورديها، مصنّفاً حسب مدى تأخّر كل فاتورة مفتوحة (حالية، ٣٠، ٦٠، ٩٠+ يوماً) — لتعرف من تدفع له ومتى." } },
    agedReceivable: { en: "Aged receivables", ar: "أعمار الذمم المدينة", sub: { en: "What is owed to the chain, bucketed by age (open invoices only)", ar: "ما هو مستحق للسلسلة موزّعاً حسب العمر (الفواتير المفتوحة فقط)" }, tip: { en: "What customers and partners still owe the chain, grouped by how overdue each open invoice is (current, 30, 60, 90+ days) — so you can chase collections before they age.", ar: "ما لا يزال العملاء والشركاء يدينون به للسلسلة، مصنّفاً حسب مدى تأخّر كل فاتورة مفتوحة (حالية، ٣٠، ٦٠، ٩٠+ يوماً) — لمتابعة التحصيل قبل تقادمه." } },
    taxReport: { en: "VAT / tax return", ar: "إقرار ضريبة القيمة المضافة", sub: { en: "Taxable base and tax due per tax code for the period", ar: "الأساس الخاضع والضريبة المستحقة لكل رمز ضريبي للفترة" }, tip: { en: "The taxable sales base and VAT due per tax code for the period — the figures you need to file the tax return. Iraq's default VAT rate here is 0%, set on the Settings → Tax page.", ar: "الأساس الخاضع للضريبة وضريبة القيمة المضافة المستحقة لكل رمز ضريبي للفترة — الأرقام اللازمة لتقديم الإقرار الضريبي. نسبة العراق الافتراضية هنا 0%، وتُضبط في الإعدادات ← الضريبة." } },
    reports: { en: "Reports", ar: "التقارير", sub: { en: "Sales, P&L, cash flow", ar: "المبيعات والأرباح والتدفق النقدي" } },
    settings: { en: "Settings", ar: "الإعدادات", sub: { en: "Tax & VAT, company, and tenant configuration", ar: "الضريبة والشركة وإعدادات النظام" } },
  };
  const t = titles[active] || titles.overview;
  const assistantCanvasActive = active === "insights";

  return (
    <div className={`admin-shell-layout ${assistantCanvasActive ? "admin-shell-layout-assistant" : "admin-shell-layout-dashboard"}`}>
      <AdminSidebar active={active === "kioskDetail" ? "kiosks" : active} setActive={setActive} lang={lang} navBadges={adminNavBadges}/>
      {canViewAuditLog && auditLogOpen && <AuditLogRail lang={lang} sourceOfTruth={sourceOfTruth}/>}
      <main className={`admin-content-inset ${assistantCanvasActive ? "admin-content-inset-assistant" : "admin-content-inset-dashboard"}`}>
        <AdminTopBar title={lang === "ar" ? t.ar : t.en} sub={lang === "ar" ? t.sub.ar : t.sub.en} lang={lang}
          tip={t.tip ? (lang === "ar" ? t.tip.ar : t.tip.en) : null}
          right={(
            <div className="row" style={{ gap: 6 }}>
              {canViewAuditLog && (
                <button
                  className={`btn ${auditLogOpen ? "btn-primary" : "btn-ghost"}`}
                  onClick={() => setAuditLogOpen((open) => !open)}
                  style={{ height: 28, fontSize: 12 }}
                >
                  <Icon name="list" size={12}/>{lang === "ar" ? "السجل" : "Log"}
                </button>
              )}
              <span className={`badge ${sync.status === "synced" ? "badge-pos" : ["error", "missing"].includes(sync.status) ? "badge-crit" : "badge-warn"}`}>
                <span className={`dot ${sync.status === "synced" ? "pos" : ["error", "missing"].includes(sync.status) ? "crit" : "warn"}`}></span>
                {sync.status === "synced"
                  ? (lang === "ar" ? "تمت مزامنة المحرك" : "Engine synced")
                  : sync.status === "error"
                    ? (lang === "ar" ? "خطأ في المحرك" : "Engine error")
                    : sync.status === "missing"
                      ? (lang === "ar" ? "الخلفية غير مضبوطة" : "Backend missing")
                      : (lang === "ar" ? "جار مزامنة المحرك" : "Engine syncing")}
              </span>
              <span
                className={`badge ${["live", "polling"].includes(realtime.status) ? "badge-pos" : realtime.status === "error" ? "badge-crit" : "badge-warn"}`}
                title={realtime.lastEvent?.title || realtime.error || "Bayaan realtime stream"}
              >
                <span className={`dot ${["live", "polling"].includes(realtime.status) ? "pos" : realtime.status === "error" ? "crit" : "warn"}`}></span>
                {realtime.status === "live"
                  ? (lang === "ar" ? "التدفق مباشر" : "Stream live")
                  : realtime.status === "polling"
                    ? (lang === "ar" ? "استرجاع عبر الناقل" : "Bus fallback")
                    : realtime.status === "error"
                      ? (lang === "ar" ? "خطأ في التدفق" : "Stream error")
                    : realtime.status === "missing"
                        ? bayaan.auth.authenticated ? (lang === "ar" ? "التدفق مفقود" : "Stream missing") : (lang === "ar" ? "التدفق ينتظر" : "Stream waiting")
                        : (lang === "ar" ? "جار الاتصال بالتدفق" : "Stream connecting")}
              </span>
              {active === "overview" && (
                <button className="btn btn-ghost"><Icon name="download" size={13}/>{lang === "ar" ? "تصدير" : "Export"}</button>
              )}
            </div>
          )}
        />
        <div className="scroll" style={{
          flex: 1,
          overflow: active === "insights" ? "hidden" : "auto",
          display: "flex", flexDirection: "column", minHeight: 0,
        }}>
          <div className="fade-up" key={active} style={{
            padding: active === "insights" ? 0 : "24px 28px 80px",
            flex: 1, minHeight: 0,
            display: active === "insights" ? "flex" : "block",
            flexDirection: "column",
          }}>
            {screens[active] || screens.overview}
          </div>
        </div>
      </main>
    </div>
  );
}



/* ===== pos.jsx ===== */

/* ============================================================
   POS panel — login, sale, payment, waste entry
   Tablet, landscape, 1180×800
   ============================================================ */

const { useState: useStatePOS } = React;

function POSPanel({ lang }) {
  const bayaan = useBayaan();
  const { showToast } = useToast();
  const [screen, setScreen] = useStatePOS(bayaan.shift ? "sale" : "login");
  const [cart, setCart] = useStatePOS([]);
  const [tender, setTender] = useStatePOS(null);
  const [posTransfers, setPosTransfers] = useStatePOS([]);
  const [transferBusy, setTransferBusy] = useStatePOS("");
  const [posBootstrap, setPosBootstrap] = useStatePOS(() => bayaan.mode === "live" ? EMPTY_ENGINE_SNAPSHOT : null);

  const goSale = () => { setScreen("sale"); setCart([]); };
  const endShiftAndLogout = () => {
    bayaan.endShift();
    setCart([]);
    setTender(null);
    setScreen("login");
  };
  const addItem = (item, size, modifiers) => {
    setCart(c => {
      const signature = modifiers?.signature || "";
      const key = item.id + ":" + size + (signature ? ":" + signature : "");
      const lineDelta = modifiers?.priceDelta || 0;
      const linePrice = (item.price || 0) + lineDelta;
      const existing = c.find(x => x.key === key);
      if (existing) return c.map(x => x === existing ? { ...x, qty: x.qty + 1 } : x);
      return [...c, {
        key, id: item.id, name: item.name, image: item.image,
        size, price: linePrice, qty: 1,
        modifierSummary: modifiers?.summary || "",
        modifierSignature: signature,
        modifierRecipeFactor: typeof modifiers?.recipeFactor === "number" ? modifiers.recipeFactor : 1,
        modifierPriceDelta: lineDelta,
      }];
    });
  };
  // Menu prices are VAT-inclusive: the cart total IS what the cashier charges and what
  // the backend records (kiosk_sale treats the kiosk sticker price as tax-included). The VAT
  // rate is tenant-configured (Settings -> Tax/VAT) and arrives on auth_status; Iraq = 0%.
  // Showing VAT as the portion already inside the price keeps Subtotal + VAT == Total AND keeps
  // the charged amount equal to the Odoo order total, so kiosk_sale never rejects on a mismatch.
  const vatRate = Number(bayaan.auth?.vatRate ?? 0) / 100;
  const total = cart.reduce((s, x) => s + x.price * x.qty, 0);
  const vat = vatRate > 0 ? total - Math.round(total / (1 + vatRate)) : 0;
  const subTotal = total - vat;

  // Track last added item for the "just added" flash on customer display
  const [lastAdded, setLastAdded] = useStatePOS(null);
  const wrappedAdd = (item, size, modifiers) => {
    const signature = modifiers?.signature || "";
    const key = item.id + ":" + size + (signature ? ":" + signature : "");
    addItem(item, size, modifiers);
    const lineDelta = modifiers?.priceDelta || 0;
    setLastAdded({ key, name: item.name, price: (item.price || 0) + lineDelta, t: Date.now() });
  };
  const posKioskId = bayaan.shift?.kioskId || bayaan.kioskId;
  React.useEffect(() => {
    if (bayaan.mode === "live" && !posBootstrap) {
      setPosBootstrap(EMPTY_ENGINE_SNAPSHOT);
    } else if (bayaan.mode !== "live" && isLiveOnlyPayload(posBootstrap)) {
      setPosBootstrap(null);
    }
  }, [bayaan.mode, posBootstrap]);
  const posScreenBootstrap = bayaan.mode === "live" ? posBootstrap || EMPTY_ENGINE_SNAPSHOT : posBootstrap;

  const loadPosTransfers = React.useCallback(async () => {
    try {
      const rawBootstrap = bayaan.mode === "live" && bayaan.hasBackend
        ? await bayaan.gateway.getChainBootstrap()
        : null;
      // Mark the snapshot live-only BEFORE deriving rows so odooTransferRows never
      // falls back to MOCK.pendingTransfers (the hardcoded TR-2040 "Milk → K-01" that
      // can't be confirmed because it doesn't exist in the backend).
      const bootstrap = rawBootstrap ? markLiveOnlySnapshot(rawBootstrap) : null;
      if (bootstrap) setPosBootstrap(bootstrap);
      const rows = bootstrap
        ? odooTransferRows(bootstrap)
        : bayaan.mode === "live"
          ? []
          : MOCK.pendingTransfers;
      setPosTransfers(rows.filter((transfer) => {
        const status = String(transfer.status || "").toLowerCase();
        if (["cancel", "cancelled"].includes(status)) return false;
        return matchesKiosk(transfer.toKioskId || transfer.to, { id: posKioskId, kiosk_code: posKioskId });
      }));
    } catch {
      setPosTransfers([]);
    }
  }, [bayaan.gateway, bayaan.hasBackend, bayaan.mode, posKioskId]);

  React.useEffect(() => {
    void loadPosTransfers();
  }, [loadPosTransfers]);

  React.useEffect(() => {
    if (!(bayaan.mode === "live" && bayaan.hasBackend)) return undefined;
    const subscription = bayaan.gateway.subscribeRealtime?.({
      onEvent: (event) => {
        const action = event.action || event.type || "";
        if (
          action.startsWith("transfer.")
          || action.startsWith("purchase.")
          || matchesKiosk(event.kiosk || event.kioskName, { id: posKioskId, kiosk_code: posKioskId })
        ) {
          void loadPosTransfers();
        }
      },
    });
    return () => subscription?.close();
  }, [bayaan.gateway, bayaan.hasBackend, bayaan.mode, loadPosTransfers, posKioskId]);

  const receivePosTransfer = async (transfer) => {
    if (bayaan.mode === "live" && !bayaan.hasBackend) {
      showToast("Connect the source engine before receiving source stock transfers", "warn");
      return;
    }
    setTransferBusy(transfer.id);
    try {
      if (bayaan.mode === "live" && bayaan.hasBackend) {
        const result = unwrapOdoo(await bayaan.gateway.stockTransferAction({ transfer: transfer.id, action: "receive" }));
        const receivedStatus = result?.bayaan_state || "received";
        setPosTransfers((rows) => rows.map((row) => row.id === transfer.id
          ? { ...row, status: receivedStatus, engineState: result?.state || row.engineState || "done", eta: "received" }
          : row));
        await loadPosTransfers();
        window.dispatchEvent(new CustomEvent("bayaan:source-mutated", {
          detail: { action: "transfer.received", transfer: transfer.id, kiosk: posKioskId },
        }));
      } else {
        setPosTransfers((rows) => rows.map((row) => row.id === transfer.id ? { ...row, status: "received" } : row));
      }
      showToast(`Transfer ${transfer.id} received at ${posKioskId}`, "success");
    } catch (error) {
      showToast(error?.message || "Could not receive transfer", "warn");
    } finally {
      setTransferBusy("");
    }
  };

  return (
    <div className="tablet-stage" style={{ gap: 24, padding: 24 }}>
      <div className="tablet">
        <div className="tablet-cam"></div>
        <div className="tablet-screen" dir={lang === "ar" ? "rtl" : "ltr"}>
          {screen === "login" && <POSLogin lang={lang} onIn={goSale}/>}
          {screen === "sale" && <POSSale lang={lang}
            cart={cart} setCart={setCart} addItem={wrappedAdd}
            lastAdded={lastAdded}
            subTotal={subTotal} vat={vat} total={total} vatRatePct={Number(bayaan.auth?.vatRate ?? 0)}
            bootstrap={posScreenBootstrap}
            onCharge={() => setScreen("payment")}
            onWaste={() => setScreen("waste")}
            onStock={() => setScreen("stock")}
            expectedTransfers={posTransfers}
            onLogout={() => setScreen("close")}
          />}
          {screen === "payment" && <POSPayment lang={lang}
            total={total} cart={cart} vatRatePct={Number(bayaan.auth?.vatRate ?? 0)}
            bootstrap={posScreenBootstrap}
            onTender={(t) => setTender(t)}
            tender={tender}
            onDone={() => { setScreen("sale"); setCart([]); setTender(null); }}
            onBack={() => setScreen("sale")}
          />}
          {screen === "waste" && <POSWaste lang={lang}
            bootstrap={posScreenBootstrap}
            onDone={() => setScreen("sale")} onBack={() => setScreen("sale")}/>}
          {screen === "close" && <POSClose lang={lang}
            bootstrap={posScreenBootstrap}
            onBack={() => setScreen("sale")}
            onClosed={endShiftAndLogout}/>}
          {screen === "stock" && <POSTransfers lang={lang}
            kioskId={posKioskId}
            transfers={posTransfers}
            busy={transferBusy}
            onReceive={receivePosTransfer}
            onRefresh={loadPosTransfers}
            onBack={() => setScreen("sale")}/>}
        </div>
      </div>

      {/* Customer-facing display */}
      <div className="tablet tablet-portrait">
        <div className="tablet-cam tablet-cam-portrait"></div>
        <div className="tablet-screen" dir={lang === "ar" ? "rtl" : "ltr"}>
          <CustomerDisplay lang={lang} screen={screen} cart={cart}
            subTotal={subTotal} vat={vat} total={total} vatRatePct={Number(bayaan.auth?.vatRate ?? 0)} tender={tender} lastAdded={lastAdded}/>
        </div>
        <div style={{ position: "absolute", bottom: -22, insetInlineStart: 0, insetInlineEnd: 0,
          textAlign: "center", fontSize: 10.5, color: "#6E6E68", letterSpacing: "0.04em", textTransform: "uppercase" }}>
          {lang === "ar" ? "شاشة العميل" : "Customer-facing display"}
        </div>
      </div>
    </div>
  );
}

// =============== LOGIN ===============
// Simulation-only placeholder cashiers (used solely by the peak-opening simulation
// runtime, which has no real Odoo auth). The live product always authenticates the
// cashier through /bayaan/api/auth_status + /bayaan/api/open_session; PINs here never
// reach a real shift.
const SIMULATION_STAFF = [
  { name: "Maya Ahmed", arName: "مايا أحمد", role: "Cashier", arRole: "كاشير", pin: "1234", openingCash: 175000 },
  { name: "Yusuf Saleh", arName: "يوسف صالح", role: "Barista", arRole: "باريستا", pin: "2345", openingCash: 175000 },
  { name: "Omar Khaled", arName: "عمر خالد", role: "Supervisor", arRole: "مشرف", pin: "3456", openingCash: 250000 },
  { name: "Sara Younis", arName: "سارة يونس", role: "Barista", arRole: "باريستا", pin: "4567", openingCash: 175000 },
];

function POSLogin({ lang, onIn }) {
  const ar = lang === "ar";
  const bayaan = useBayaan();
  const { showToast } = useToast();
  const simulationRuntime = isSimulationRuntime();
  const sourceEngineMissing = bayaan.mode === "live" && !bayaan.hasBackend;
  const sourceBackedShift = bayaan.mode === "live" && bayaan.hasBackend && !simulationRuntime;
  const sourceUser = bayaan.auth?.user || {};
  // Live mode lists the signed-in user first, then the staff assigned to this
  // kiosk (auth_status user.kioskStaff). The official pos.session always
  // belongs to the authenticated user; the picked name is the operating
  // cashier, recorded on the session-opened audit event.
  const kioskStaff = Array.isArray(sourceUser.kioskStaff) ? sourceUser.kioskStaff : [];
  const staffForKiosk = kioskStaff.filter((member) => !bayaan.kioskId || member.kioskCode === bayaan.kioskId);
  const colleagueCards = (staffForKiosk.length ? staffForKiosk : kioskStaff)
    .filter((member) => member.login !== sourceUser.login)
    .map((member) => ({
      name: member.name,
      arName: member.name,
      role: member.kioskCode && member.kioskCode !== bayaan.kioskId
        ? `${member.role} · ${member.kioskCode}`
        : member.role,
      arRole: arTerm(lang, member.role),
      pin: "",
      openingCash: 0,
    }));
  const staff = sourceEngineMissing
    ? []
    : sourceBackedShift
      ? [{
          name: sourceUser.name || sourceUser.login || "Bayaan cashier",
          arName: sourceUser.name || sourceUser.login || "كاشير بيان",
          role: sourceUser.primaryRole || "Cashier",
          arRole: arTerm(lang, sourceUser.primaryRole || "Cashier"),
          pin: "",
          openingCash: 0,
        }, ...colleagueCards]
      : SIMULATION_STAFF;
  const [picked, setPicked] = useStatePOS(null);
  const [pin, setPin] = useStatePOS("");
  const [error, setError] = useStatePOS("");
  const [busy, setBusy] = useStatePOS(false);

  React.useEffect(() => {
    if (!sourceEngineMissing) return;
    setPicked(null);
    setPin("");
    setError("");
  }, [sourceEngineMissing]);

  const tryStartShift = async () => {
    if (sourceEngineMissing) {
      setError(ar ? "اربط محرك المصدر قبل فتح وردية POS." : "Connect the source engine before opening a source POS shift.");
      showToast(ar ? "محرك المصدر غير متصل" : "Source engine is not connected", "warn");
      return;
    }
    if (!picked) return;
    if (!sourceBackedShift && pin.length !== 4) {
      setError(ar ? "أدخل رمز ٤ أرقام" : "Enter your 4-digit PIN");
      return;
    }
    if (!sourceBackedShift && pin !== picked.pin) {
      setError(ar ? "رمز غير صحيح" : "Incorrect PIN");
      setPin("");
      showToast(ar ? "رمز الدخول غير صحيح" : "Incorrect PIN", "warn");
      return;
    }
    setBusy(true);
    const result = await bayaan.startShift({
      kioskId: bayaan.kioskId,
      cashier: picked.name,
      openingCash: sourceBackedShift ? 0 : picked.openingCash,
    });
    setBusy(false);
    if (!result.ok) {
      setError(result.error);
      showToast(result.error, "warn");
      return;
    }
    setError("");
    onIn();
  };

  return (
      <div style={{ height: "100%", display: "flex", flexDirection: "column" }}>
        {/* Top bar */}
        <div style={{ height: 56, padding: "0 28px", display: "flex", alignItems: "center", justifyContent: "space-between", borderBottom: "1px solid var(--line)" }}>
          <div className="row" style={{ gap: 10 }}>
          <BrandLogo className="cashier-pos-logo" alt={ar ? BRAND.arabic : BRAND.name}/>
          <div className="col">
            <div style={{ fontSize: 13.5, fontWeight: 500 }}>
              {ar ? `الكشك · ${bayaan.kioskId}` : `Kiosk - ${bayaan.kioskId}`}
            </div>
            <div style={{ fontSize: 11.5, color: "var(--ink-3)" }}>
              {new Date().toLocaleString(ar ? "ar-IQ" : "en-US", { weekday: "short", month: "short", day: "numeric", hour: "numeric", minute: "2-digit" })}
            </div>
          </div>
        </div>
        <div className="row" style={{ gap: 10, fontSize: 11.5, color: "var(--ink-3)" }}>
          <span className="row" style={{ gap: 5 }}><span className={`dot ${sourceEngineMissing ? "crit" : "pos"}`}></span>{sourceEngineMissing ? (ar ? "مصدر مطلوب" : "Source required") : sourceBackedShift ? (ar ? "مصدر موثق" : "Source verified") : (ar ? "متصل" : "Online")}</span>
          <span>·</span>
          <span>{sourceEngineMissing ? (ar ? "لا توجد مزامنة مصدر" : "No source sync") : sourceBackedShift ? (ar ? "تم التحقق من حساب بيان" : "Bayaan account verified") : (ar ? "آخر مزامنة الآن" : "Last sync just now")}</span>
        </div>
      </div>

      {/* Body */}
      <div style={{ flex: 1, display: "grid", gridTemplateColumns: picked ? "1fr 380px" : "1fr", overflow: "hidden" }}>
        <div style={{ padding: "40px 56px", overflow: "auto" }}>
          <div className="t-display" style={{ fontWeight: 500, marginBottom: 6 }}>{ar ? "صباح الخير" : "Good morning"}</div>
          <div className="t-h2 muted" style={{ fontWeight: 400, marginBottom: 28 }}>{ar ? "اختر اسمك للبدء" : "Pick your name to start the shift"}</div>
          <div style={{ display: "grid", gridTemplateColumns: "repeat(2, 1fr)", gap: 12, maxWidth: 640 }}>
            {sourceEngineMissing && (
              <div className="card" style={{ gridColumn: "1 / -1", padding: 22 }}>
                <div style={{ fontSize: 15, fontWeight: 500 }}>{ar ? "لا توجد وردية POS من المصدر" : "No source POS shift available"}</div>
                <div className="t-small subtle" style={{ marginTop: 6 }}>{ar ? "اربط محرك المصدر لاستخدام /bayaan/api/auth_status و /bayaan/api/open_session قبل بدء البيع." : "Connect the source engine so /bayaan/api/auth_status and /bayaan/api/open_session can verify the cashier before selling."}</div>
              </div>
            )}
            {staff.map(s => (
              <button key={s.name} onClick={() => { setPicked(s); setPin(""); }}
                className="card"
                style={{
                  padding: "20px 22px", textAlign: "start", cursor: "pointer",
                  display: "flex", alignItems: "center", gap: 14,
                  borderColor: picked?.name === s.name ? "var(--ink)" : "var(--line)",
                  background: picked?.name === s.name ? "var(--surface)" : "var(--surface)",
                  transition: "border-color 100ms"
                }}>
                <Avatar name={s.name} size={48}/>
                <div>
                  <div style={{ fontSize: 16, fontWeight: 500 }}>{ar ? s.arName : s.name}</div>
                  <div style={{ fontSize: 12.5, color: "var(--ink-3)", marginTop: 2 }}>{ar ? s.arRole : s.role}</div>
                </div>
              </button>
            ))}
          </div>
        </div>

        {picked && (
          <div className="fade-up" style={{ borderInlineStart: "1px solid var(--line)", padding: "40px 32px", background: "var(--surface)", display: "flex", flexDirection: "column" }}>
            <div className="row" style={{ gap: 12, marginBottom: 24 }}>
              <Avatar name={picked.name} size={36}/>
              <div>
                <div style={{ fontSize: 15, fontWeight: 500 }}>{ar ? picked.arName : picked.name}</div>
                <div style={{ fontSize: 12, color: "var(--ink-3)" }}>{ar ? picked.arRole : picked.role}</div>
              </div>
            </div>
            <div className="t-micro" style={{ marginBottom: 12 }}>{ar ? "أدخل رمز الدخول" : "Enter PIN"}</div>
            <div className="row" style={{ gap: 10, marginBottom: 22 }}>
              {[0,1,2,3].map(i => (
                <div key={i} style={{
                  width: 56, height: 56, borderRadius: 8,
                  border: "1px solid " + (pin.length === i ? "var(--ink)" : "var(--line)"),
                  background: "var(--surface)",
                  display: "grid", placeItems: "center",
                  fontSize: 22, fontFamily: "var(--font-mono)"
                }}>
                  {pin[i] ? "•" : ""}
                </div>
              ))}
            </div>
            <div style={{ display: "grid", gridTemplateColumns: "repeat(3, 1fr)", gap: 8 }}>
              {[1,2,3,4,5,6,7,8,9].map(n => (
                <button key={n} onClick={() => { setError(""); setPin(p => (p + n).slice(0, 4)); }}
                  style={{ height: 56, fontSize: 20, fontFamily: "var(--font-mono)", border: "1px solid var(--line)", borderRadius: 8, background: "var(--surface)", cursor: "pointer" }}>{n}</button>
              ))}
              <button onClick={() => { setPicked(null); setPin(""); setError(""); }} style={{ height: 56, fontSize: 12, color: "var(--ink-2)", border: "1px solid var(--line)", borderRadius: 8, background: "var(--surface)", cursor: "pointer" }}>{ar ? "عودة" : "Back"}</button>
              <button onClick={() => { setError(""); setPin(p => (p + 0).slice(0, 4)); }} style={{ height: 56, fontSize: 20, fontFamily: "var(--font-mono)", border: "1px solid var(--line)", borderRadius: 8, background: "var(--surface)", cursor: "pointer" }}>0</button>
              <button onClick={() => setPin(p => p.slice(0, -1))} style={{ height: 56, fontSize: 18, color: "var(--ink-2)", border: "1px solid var(--line)", borderRadius: 8, background: "var(--surface)", cursor: "pointer" }}>⌫</button>
            </div>
            {error && (
              <div style={{ marginTop: 10, fontSize: 12, color: "var(--crit, #C04A38)", textAlign: "center" }}>{error}</div>
            )}
            <button onClick={tryStartShift} disabled={busy || (!sourceBackedShift && pin.length !== 4)} className="btn btn-primary btn-xl" style={{ marginTop: 14, justifyContent: "center", opacity: sourceBackedShift || pin.length === 4 ? 1 : 0.4 }}>
              {busy ? (ar ? "جارٍ الفتح..." : "Opening...") : (ar ? "ابدأ الوردية" : "Start shift")} <Icon name="arrowRight" size={14}/>
            </button>
            <div style={{ marginTop: 14, fontSize: 11.5, color: "var(--ink-3)", textAlign: "center" }}>
              {sourceBackedShift
                ? (ar ? "سيتم فتح الوردية عبر محرك المصدر." : "Shift will open through the source engine.")
                : (ar ? `العد النقدي: د.ع ${picked.openingCash.toLocaleString("en")}` : `Cash float: IQD ${picked.openingCash.toLocaleString("en")}`)}
            </div>
          </div>
        )}
      </div>
    </div>
  );
}



/* ===== pos-screens.jsx ===== */

/* ============================================================
   POS Sale screen — order taking
   ============================================================ */

function POSSale({ lang, cart, setCart, addItem, lastAdded, subTotal, vat, total, vatRatePct = 0, bootstrap, onCharge, onWaste, onStock, expectedTransfers = [], onLogout }) {
  const ar = lang === "ar";
  const bayaan = useBayaan();
  const { showToast } = useToast();
  const catalog = useCatalog();
  const cartLineRefs = React.useRef(new Map());
  const menu = React.useMemo(() => (
    bayaan.mode === "live"
      ? bayaan.hasBackend
        ? odooPosMenu(bootstrap)
        : []
      : catalog.menuByCategory()
  ), [bayaan.hasBackend, bayaan.mode, bootstrap, catalog.state.products]);
  const [activeCat, setActiveCat] = useStatePOS(0);
  const [search, setSearch] = useStatePOS("");
  const [modifierTarget, setModifierTarget] = React.useState(null); // { item, groups }
  // Tabs are derived from the actual menu categories, with a leading "All" tab, so products
  // always appear under their real category instead of a fixed positional slot (Hot/Iced/...).
  const allItems = React.useMemo(() => menu.flatMap((g) => g.items), [menu]);
  const tabGroups = React.useMemo(
    () => (menu.length ? [{ cat: ar ? "الكل" : "All", items: allItems }, ...menu] : []),
    [menu, allItems, ar],
  );
  const cat = tabGroups[activeCat] ?? tabGroups[0] ?? { cat: "", items: [] };
  const items = search
    ? allItems.filter(i => i.name.toLowerCase().includes(search.toLowerCase()))
    : cat.items;
  const dispatchedTransfers = expectedTransfers.filter((transfer) => isDispatchedTransfer(transfer.status));
  const sourceMenuMissing = bayaan.mode === "live" && items.length === 0;
  const cashierName = bayaan.shift?.cashier || (ar ? "كاشير بيان" : "Bayaan cashier");

  // ---- Low-stock alert + request-from-warehouse (cashier-initiated) ----
  const posKioskId = bayaan.shift?.kioskId || bayaan.kioskId;
  const [requestBusy, setRequestBusy] = useStatePOS(false);
  const lowStockItems = React.useMemo(() => {
    const snap = unwrapOdoo(bootstrap);
    const rows = (snap?.kiosk_stock_rows || []).filter((row) =>
      matchesKiosk(row.kiosk, { id: posKioskId, kiosk_code: posKioskId }));
    return rows
      .map((row) => {
        const actual = Number(row.actual_qty || 0);
        const reorder = Number(row.reorder_qty || 0);
        const target = Number(row.target_qty || 0);
        const critical = Number(row.critical_qty || 0);
        const status = String(row.stock_status || "").toLowerCase();
        const isLow = status === "low" || status === "critical"
          || (reorder > 0 && actual <= reorder)
          || (critical > 0 && actual <= critical);
        if (!isLow) return null;
        return {
          item: row.item,
          name: row.item,
          actual,
          target,
          uom: row.uom || "",
          // Top the item back up to its configured target (fallback: reorder qty).
          reqQty: Math.max(Math.ceil((target || reorder || actual) - actual), 1),
          critical: status === "critical" || (critical > 0 && actual <= critical),
        };
      })
      .filter(Boolean);
  }, [bootstrap, posKioskId]);
  const hasCritical = lowStockItems.some((row) => row.critical);
  const requestLowStock = async () => {
    if (!lowStockItems.length || requestBusy) return;
    if (!(bayaan.mode === "live" && bayaan.hasBackend)) {
      showToast(ar ? "اربط محرك المصدر لطلب المخزون" : "Connect the source engine to request stock", "warn");
      return;
    }
    setRequestBusy(true);
    try {
      await bayaan.gateway.requestStock({
        kioskId: posKioskId,
        items: lowStockItems.map((row) => ({ itemId: row.item, qty: row.reqQty, uom: row.uom })),
      });
      showToast(
        ar ? "تم إرسال طلب المخزون إلى المستودع" : "Stock request sent to the warehouse",
        "success",
      );
      window.dispatchEvent(new CustomEvent("bayaan:source-mutated", {
        detail: { action: "stock.requested", kiosk: posKioskId },
      }));
    } catch (error) {
      showToast((ar ? "تعذّر إرسال الطلب: " : "Could not send request: ") + (error?.message || ""), "warn");
    } finally {
      setRequestBusy(false);
    }
  };

  const inc = (key) => setCart(c => c.map(x => x.key === key ? { ...x, qty: x.qty + 1 } : x));
  const dec = (key) => setCart(c => c.flatMap(x => x.key === key ? (x.qty > 1 ? [{ ...x, qty: x.qty - 1 }] : []) : [x]));
  const rm = (key) => setCart(c => c.filter(x => x.key !== key));

  React.useEffect(() => {
    if (!lastAdded?.key) return;
    const line = cartLineRefs.current.get(lastAdded.key);
    line?.scrollIntoView({ behavior: "smooth", block: "nearest" });
  }, [lastAdded?.t]);

  return (
    <div style={{ height: "100%", minHeight: 0, display: "flex", flexDirection: "column" }}>
      {/* Top bar */}
      <div style={{ height: 52, padding: "0 18px", display: "flex", alignItems: "center", justifyContent: "space-between", borderBottom: "1px solid var(--line)", background: "var(--surface)" }}>
        <div className="row" style={{ gap: 12 }}>
          <Avatar name={cashierName} size={26}/>
          <div className="col" style={{ lineHeight: 1.1 }}>
            <div style={{ fontSize: 12.5, fontWeight: 500 }}>{cashierName}</div>
            <div style={{ fontSize: 10.5, color: "var(--ink-3)" }}>{bayaan.kioskId} · {bayaan.mode === "live" ? (ar ? "وردية مصدر" : "Source shift") : (ar ? "وردية تجريبية" : "Demo shift")}</div>
          </div>
          <span style={{ width: 1, height: 24, background: "var(--line)", marginInlineStart: 6 }}></span>
          <span className="badge"><span className="dot pos"></span>{ar ? "متصل" : "Online"}</span>
        </div>
        <div className="row" style={{ gap: 6 }}>
          <button className="btn btn-ghost" onClick={onWaste}><Icon name="trash" size={13}/>{ar ? "هدر" : "Waste"}</button>
          <button className="btn btn-ghost" onClick={onStock}>
            <Icon name="box" size={13}/>{ar ? "استلام المخزون" : "Receive stock"}
            {dispatchedTransfers.length > 0 && <span className="badge badge-warn" style={{ marginInlineStart: 4 }}>{dispatchedTransfers.length}</span>}
          </button>
          <button className="btn btn-ghost" onClick={onLogout}>{ar ? "إنهاء" : "End shift"}</button>
        </div>
      </div>

      {dispatchedTransfers.length > 0 && (
        <button type="button" onClick={onStock}
          style={{
            margin: 0,
            padding: "10px 18px",
            border: 0,
            borderBottom: "1px solid var(--line)",
            background: "var(--warn-soft)",
            color: "var(--ink)",
            display: "flex",
            alignItems: "center",
            justifyContent: "space-between",
            gap: 12,
            textAlign: "start",
            cursor: "pointer",
          }}>
          <span className="row" style={{ gap: 8, minWidth: 0 }}>
            <Icon name="truck" size={14}/>
            <span style={{ fontSize: 12.5, fontWeight: 500 }}>
              {dispatchedTransfers.length === 1 ? "1 transfer arrived for kiosk confirmation" : `${dispatchedTransfers.length} transfers arrived for kiosk confirmation`}
            </span>
          </span>
          <span className="badge badge-warn">{ar ? "استلام" : "Confirm receipt"}</span>
        </button>
      )}

      {lowStockItems.length > 0 && (
        <button type="button" onClick={requestLowStock} disabled={requestBusy}
          title={lowStockItems.map((row) => `${row.name}: ${row.actual}${row.uom ? " " + row.uom : ""}`).join("  ·  ")}
          style={{
            margin: 0,
            padding: "10px 18px",
            border: 0,
            borderBottom: "1px solid var(--line)",
            background: hasCritical ? "var(--crit-soft, #FBE9E7)" : "var(--warn-soft)",
            color: "var(--ink)",
            display: "flex",
            alignItems: "center",
            justifyContent: "space-between",
            gap: 12,
            textAlign: "start",
            cursor: requestBusy ? "default" : "pointer",
            opacity: requestBusy ? 0.6 : 1,
          }}>
          <span className="row" style={{ gap: 8, minWidth: 0 }}>
            <Icon name="bell" size={14}/>
            <span style={{ fontSize: 12.5, fontWeight: 500 }}>
              {ar
                ? `${lowStockItems.length} صنف منخفض المخزون${hasCritical ? " (حرِج)" : ""} — اطلب من المستودع`
                : `${lowStockItems.length} item${lowStockItems.length === 1 ? "" : "s"} low on stock${hasCritical ? " (critical)" : ""} — request from warehouse`}
            </span>
          </span>
          <span className={"badge " + (hasCritical ? "badge-crit" : "badge-warn")}>
            {requestBusy ? (ar ? "جارٍ الإرسال" : "Requesting…") : (ar ? "طلب مخزون" : "Request stock")}
          </span>
        </button>
      )}

      {/* Body */}
      <div style={{ flex: 1, minHeight: 0, display: "grid", gridTemplateColumns: "1fr 380px", overflow: "hidden" }}>
        {/* Menu */}
        <div style={{ minHeight: 0, display: "flex", flexDirection: "column", overflow: "hidden", background: "var(--paper)" }}>
          <div style={{ padding: "14px 18px 10px", display: "flex", gap: 10, alignItems: "center" }}>
            <div className="row" style={{ gap: 6, padding: "0 10px", height: 36, background: "var(--surface)", border: "1px solid var(--line)", borderRadius: 8, flex: 1, maxWidth: 320 }}>
              <Icon name="search" size={14} style={{ color: "var(--ink-3)" }}/>
              <input value={search} onChange={e => setSearch(e.target.value)}
                placeholder={ar ? "بحث عن منتج" : "Search product"}
                style={{ flex: 1, border: 0, background: "transparent", outline: "none", fontSize: 13.5 }}/>
            </div>
            <span style={{ flex: 1 }}></span>
            <div className="row" style={{ gap: 4, flexWrap: "wrap", justifyContent: "flex-end" }}>
              {tabGroups.map((group, idx) => (
                <button key={(group.cat || "") + idx} onClick={() => { setActiveCat(idx); setSearch(""); }}
                  className={"btn " + (activeCat === idx && !search ? "btn-primary" : "btn-ghost")}
                  style={{ height: 34, fontSize: 13 }}>
                  {group.cat}
                </button>
              ))}
            </div>
          </div>

          <div className="scroll" style={{ flex: 1, overflow: "auto", padding: "8px 18px 24px" }}>
            <div style={{ display: "grid", gridTemplateColumns: "repeat(4, 1fr)", gap: 10 }}>
              {items.map(it => {
                // Robust resolution: source options → category bindings → synthesized size group.
                const modGroups = posModifierGroupsFor(it, cat.cat);
                const handleClick = () => {
                  if (modGroups.length > 0) {
                    setModifierTarget({ item: it, groups: modGroups });
                  } else {
                    addItem(it, it.sizes[0]);
                  }
                };
                return (
                <button key={it.id} onClick={handleClick}
                  data-product-id={it.id}
                  data-has-modifiers={modGroups.length > 0 ? "true" : "false"}
                  className="card"
                  style={{
                    padding: 0, textAlign: "start", overflow: "hidden",
                    cursor: "pointer", display: "flex", flexDirection: "row",
                    minHeight: 110, position: "relative", transition: "transform 100ms, border-color 100ms"
                  }}
                  onMouseDown={e => e.currentTarget.style.transform = "scale(0.985)"}
                  onMouseUp={e => e.currentTarget.style.transform = "none"}
                  onMouseLeave={e => e.currentTarget.style.transform = "none"}>
                  <div style={{ width: "50%", aspectRatio: "1 / 1", flexShrink: 0, alignSelf: "stretch", overflow: "hidden", background: "var(--surface-sunk)" }}>
                    <ProductImage slug={it.image} name={it.name} fill radius={0}/>
                  </div>
                  <div style={{ flex: 1, padding: "12px 14px", display: "flex", flexDirection: "column", justifyContent: "center", minWidth: 0, gap: 4 }}>
                    <div style={{ fontSize: 13.5, fontWeight: 500, lineHeight: 1.3 }}>{it.name}</div>
                    <div className="t-num" style={{ fontSize: 13 }}>IQD {it.price.toLocaleString("en")}</div>
                    <div className="t-small subtle">{it.sizes.join(" · ")}{modGroups.length > 0 ? (ar ? " · قابل للتخصيص" : " · customizable") : ""}</div>
                  </div>
                </button>
                );
              })}
            </div>
            {sourceMenuMissing ? (
              <div style={{ textAlign: "center", padding: 60, color: "var(--ink-3)" }}>
                <Icon name="box" size={28} style={{ marginBottom: 12, opacity: 0.5 }}/>
                <div style={{ fontSize: 13, fontWeight: 500, color: "var(--ink-2)" }}>
                  {ar ? "لا توجد منتجات POS من المصدر" : "No source POS products loaded"}
                </div>
                <div className="t-small subtle" style={{ marginTop: 6 }}>
                  {ar ? "اربط محرك المصدر أو فعّل منتجات نقطة البيع في بيان." : "Connect the source engine or enable POS products in Bayaan before taking orders."}
                </div>
              </div>
            ) : items.length === 0 && (
              <div style={{ textAlign: "center", padding: 60, color: "var(--ink-3)" }}>
                {ar ? "لا توجد نتائج" : "No matches"}
              </div>
            )}
          </div>
        </div>

        {/* Cart */}
        <div className="pos-cart-panel">
          <div style={{ padding: "16px 20px", borderBottom: "1px solid var(--line)" }}>
            <div className="between">
              <div>
                <div style={{ fontSize: 14, fontWeight: 500 }}>{ar ? "الطلب الحالي" : "Current order"}</div>
                <div className="t-small subtle">#A-{1247 + cart.length}</div>
              </div>
              <button className="btn btn-quiet" style={{ height: 26, fontSize: 12 }} onClick={() => setCart([])} disabled={cart.length === 0}>
                {ar ? "مسح" : "Clear"}
              </button>
            </div>
          </div>

          <div className="scroll pos-cart-items">
            {cart.length === 0 && (
              <div style={{ textAlign: "center", padding: "60px 20px", color: "var(--ink-3)" }}>
                <Icon name="receipt" size={28} style={{ marginBottom: 12, opacity: 0.5 }}/>
                <div style={{ fontSize: 13 }}>{ar ? "اختر منتجاً للبدء" : "Tap an item to start"}</div>
              </div>
            )}
            {cart.map(line => (
              <div
                key={line.key}
                ref={(node) => {
                  if (node) cartLineRefs.current.set(line.key, node);
                  else cartLineRefs.current.delete(line.key);
                }}
                style={{ padding: "12px 20px", borderBottom: "1px solid var(--line-soft)" }}
              >
                <div className="between" style={{ alignItems: "flex-start" }}>
                  <div style={{ flex: 1, minWidth: 0 }}>
                    <div style={{ fontSize: 13.5, fontWeight: 500 }}>{line.name}</div>
                    <div className="t-small subtle">{line.size}</div>
                    {line.modifierSummary ? (
                      <div className="t-small subtle" data-testid="cart-line-modifiers" style={{ marginTop: 2 }}>{line.modifierSummary}</div>
                    ) : null}
                  </div>
                  <div className="t-num" style={{ fontSize: 13 }}>IQD {(line.price * line.qty).toLocaleString("en")}</div>
                </div>
                <div className="row" style={{ marginTop: 8, justifyContent: "space-between" }}>
                  <div className="pos-qty-stepper">
                    <button type="button" aria-label="Decrease quantity" onClick={() => dec(line.key)} className="pos-qty-button"><Icon name="minus" size={11}/></button>
                    <div className="pos-qty-value">{line.qty}</div>
                    <button type="button" aria-label="Increase quantity" onClick={() => inc(line.key)} className="pos-qty-button"><Icon name="plus" size={11}/></button>
                  </div>
                  <button onClick={() => rm(line.key)} className="btn btn-quiet" style={{ height: 24, fontSize: 11, color: "var(--ink-3)" }}>{ar ? "إزالة" : "Remove"}</button>
                </div>
              </div>
            ))}
          </div>

          <div className="pos-cart-footer">
            <div className="col" style={{ gap: 6, marginBottom: 14 }}>
              {vatRatePct > 0 && (<>
              <div className="between"><span className="muted t-small">{ar ? "المجموع الفرعي" : "Subtotal"}</span><span className="t-num">{fmtMoney(subTotal)}</span></div>
              <div className="between"><span className="muted t-small">{ar ? `ضريبة ${vatRatePct}٪` : `VAT ${vatRatePct}%`}</span><span className="t-num muted">{fmtMoney(vat)}</span></div>
              </>)}
              <div className="between" style={{ marginTop: 4 }}>
                <span style={{ fontSize: 14, fontWeight: 500 }}>{ar ? "الإجمالي" : "Total"}</span>
                <span className="t-num" style={{ fontSize: 22 }}>{fmtMoney(total)}</span>
              </div>
            </div>
            <button onClick={onCharge} disabled={cart.length === 0}
              className="btn btn-primary"
              style={{ width: "100%", height: 56, justifyContent: "center", fontSize: 16, borderRadius: 10, opacity: cart.length === 0 ? 0.4 : 1 }}>
              {ar ? "احسب" : "Charge"} {fmtMoney(total)}
            </button>
          </div>
        </div>
      </div>
      {modifierTarget ? (
        <ProductModifierSheet
          item={modifierTarget.item}
          groups={modifierTarget.groups}
          lang={lang}
          onCancel={() => setModifierTarget(null)}
          onConfirm={(payload) => {
            addItem(modifierTarget.item, modifierTarget.item.sizes[0], payload);
            setModifierTarget(null);
          }}
        />
      ) : null}
    </div>
  );
}

function POSTransfers({ lang, kioskId, transfers, busy, onReceive, onRefresh, onBack }) {
  const ar = lang === "ar";
  const actionable = transfers.filter((transfer) => String(transfer.status || "").toLowerCase() === "dispatched");
  const sortedTransfers = [...transfers].sort((a, b) => {
    const aReady = isDispatchedTransfer(a.status) ? 0 : isReceivedTransfer(a.status) ? 2 : 1;
    const bReady = isDispatchedTransfer(b.status) ? 0 : isReceivedTransfer(b.status) ? 2 : 1;
    return aReady - bReady;
  });
  return (
    <div style={{ height: "100%", display: "flex", flexDirection: "column", background: "var(--paper)" }}>
      <div style={{ height: 52, padding: "0 18px", display: "flex", alignItems: "center", justifyContent: "space-between", borderBottom: "1px solid var(--line)", background: "var(--surface)" }}>
        <div className="row" style={{ gap: 10 }}>
          <button className="btn btn-ghost" onClick={onBack} style={{ width: 30, height: 30, padding: 0, justifyContent: "center" }}>
            <Icon name="arrowLeft" size={14}/>
          </button>
          <div>
            <div style={{ fontSize: 13.5, fontWeight: 500 }}>{ui(ar, "expectedTransfers")}</div>
            <div className="t-small subtle">{ui(ar, "kioskReceivesOnlyArrived", { kioskId })}</div>
          </div>
        </div>
        <button className="btn btn-ghost" onClick={onRefresh} style={{ height: 30, fontSize: 12 }}>
          <Icon name="refresh" size={12}/>{ui(ar, "refresh")}
        </button>
      </div>

      <div className="scroll" style={{ flex: 1, overflow: "auto", padding: 18 }}>
        <div className="col" style={{ gap: 10 }}>
          {sortedTransfers.map((transfer) => {
            const status = String(transfer.status || "").toLowerCase();
            const canReceive = isDispatchedTransfer(status);
            const received = isReceivedTransfer(status);
            return (
              <div key={transfer.id} className="card" style={{ padding: 14 }}>
                <div className="between" style={{ alignItems: "flex-start", gap: 12 }}>
                  <div style={{ minWidth: 0 }}>
                    <div style={{ fontSize: 13.5, fontWeight: 500 }}>{transfer.id}</div>
                    <div className="t-small subtle" style={{ marginTop: 3 }}>{transfer.from}{" -> "}{transfer.to}</div>
                    <div className="t-small" style={{ marginTop: 8 }}>{transfer.items}</div>
                  </div>
                  <span className={`badge ${transferStatusClass(status)}`}>{received ? arTerm(lang, "received") : arTerm(lang, transfer.status)}</span>
                </div>
                <div className="row" style={{ justifyContent: "space-between", gap: 8, marginTop: 12 }}>
                  <div className="t-small subtle">
                    {received ? ui(ar, "confirmedAtKiosk") : canReceive ? ui(ar, "transferArrivedWaiting") : (ar ? `الوصول ${transfer.eta || "--:--"}` : `ETA ${transfer.eta || "--:--"}`)}
                  </div>
                  <button className="btn btn-primary" disabled={!canReceive || busy === transfer.id} onClick={() => onReceive(transfer)} style={{ height: 30, fontSize: 12 }}>
                    {busy === transfer.id ? ui(ar, "receiving") : received ? ui(ar, "confirmed") : ui(ar, "confirmArrived")}
                  </button>
                </div>
              </div>
            );
          })}
          {transfers.length === 0 && (
            <div className="card" style={{ padding: 24, textAlign: "center" }}>
              <Icon name="box" size={26} style={{ color: "var(--ink-3)", marginBottom: 10 }}/>
              <div style={{ fontSize: 14, fontWeight: 500 }}>{ui(ar, "noExpectedTransfers")}</div>
              <div className="t-small subtle" style={{ marginTop: 5 }}>{ui(ar, "transferReceiptEmpty")}</div>
            </div>
          )}
        </div>
      </div>

      <div style={{ padding: "12px 18px", borderTop: "1px solid var(--line)", background: "var(--surface)" }}>
        <div className="t-small subtle">{ui(ar, "transfersWaiting", { count: actionable.length, suffix: actionable.length === 1 ? "" : "s" })}</div>
      </div>
    </div>
  );
}

function POSClose({ lang, bootstrap, onBack, onClosed }) {
  const ar = lang === "ar";
  const bayaan = useBayaan();
  const { showToast } = useToast();
  const snapshot = unwrapOdoo(bootstrap);
  const simulationClose = isSimulationPayload(snapshot);
  const kioskId = bayaan.shift?.kioskId || bayaan.kioskId;
  const stockRows = React.useMemo(() => (
    (snapshot?.kiosk_stock_rows || [])
      .filter((row) => matchesKiosk(row.kiosk, { id: kioskId, kiosk_code: kioskId }))
      .slice(0, 12)
  ), [kioskId, snapshot]);
  const closeSales = React.useMemo(() => {
    const openedAt = Date.parse(bayaan.shift?.openedAt || "");
    return (snapshot?.today?.orders || [])
      .filter((order) => matchesKiosk(order.kiosk || order.pos_config, { id: kioskId, kiosk_code: kioskId }))
      .filter((order) => {
        if (simulationClose) return true;
        if (Number.isNaN(openedAt)) return true;
        const orderAt = Date.parse(order.date_order || "");
        return Number.isNaN(orderAt) || orderAt >= openedAt;
      })
      .map((order) => {
        const payment = order.payments?.[0] || {};
        // Classify via the shared provider classifier (not a substring match on the
        // method name) so a wallet like "Zain Cash" is never miscounted as cash/card.
        const providerInfo = classifyPaymentProvider(payment.method, payment.provider);
        const method = providerInfo.category === "cash" ? "cash" : providerInfo.category === "card" ? "card" : "wallet";
        const total = Number(order.amount_total || 0);
        return {
          id: order.name || String(order.id || "POS"),
          lines: [],
          subtotal: total,
          tax: 0,
          total,
          tender: { method },
          createdAt: order.date_order || new Date().toISOString(),
        };
      });
  }, [bayaan.shift?.openedAt, kioskId, simulationClose, snapshot]);
  const expectedCash = bayaan.shift
    ? bayaan.shift.openingCash + closeSales
      .filter((sale) => sale.tender.method === "cash")
      .reduce((sum, sale) => sum + sale.total, 0)
    : 0;
  // Card terminal batch the cashier reconciles via the PIN pad at end of day.
  const expectedCard = closeSales
    .filter((sale) => sale.tender.method === "card")
    .reduce((sum, sale) => sum + sale.total, 0);
  const [actualCash, setActualCash] = useStatePOS("");
  const [actualCard, setActualCard] = useStatePOS("");
  const [counts, setCounts] = useStatePOS({});
  const [rowMode, setRowMode] = useStatePOS({}); // item -> "confirmed" | "editing"
  const [busy, setBusy] = useStatePOS(false);

  // Check = "count matches the expected on-hand" (no typing); Modify = enter the
  // real counted figure. Confirming sets actual := expected so variance is zero.
  const confirmRow = (item, expected) => {
    setCounts((current) => ({ ...current, [item]: String(expected ?? 0) }));
    setRowMode((current) => ({ ...current, [item]: "confirmed" }));
  };
  const modifyRow = (item, expected) => {
    setCounts((current) => ({ ...current, [item]: current[item] ?? String(expected ?? 0) }));
    setRowMode((current) => ({ ...current, [item]: "editing" }));
  };
  const confirmCash = () => setActualCash(String(Math.round(expectedCash || 0)));
  const confirmCard = () => setActualCard(String(Math.round(expectedCard || 0)));

  const submitClose = async () => {
    if (!bayaan.shift) return;
    if (bayaan.mode === "live" && !bayaan.hasBackend) {
      showToast(ar ? "اربط محرك المصدر قبل إرسال إغلاق وردية مصدر." : "Connect the source engine before submitting source shift close", "warn");
      return;
    }
    if (bayaan.pendingCount > 0) {
      showToast(ar ? "Sync offline queue before closing shift" : "Sync offline queue before closing shift", "warn");
      return;
    }
    const cash = Number(actualCash || 0);
    setBusy(true);
    try {
      if (bayaan.mode === "live" && bayaan.hasBackend) {
        const stockCounts = stockRows.map((row) => ({
          item: row.item,
          uom: row.uom || "Units",
          expected_qty: Number(row.actual_qty || 0),
          actual_qty: Number(counts[row.item] ?? row.actual_qty ?? 0),
        }));
        const result = await bayaan.submitShiftClose({
          kioskId,
          cashier: bayaan.shift.cashier,
          stock: [],
          shift: {
            openedAt: bayaan.shift.openedAt,
            openingCash: bayaan.shift.openingCash,
            sales: closeSales,
            waste: [],
          },
          draft: {
            actualCash: cash,
            actualCard: Number(actualCard || 0),
            stockCounts,
            ingredientCounts: stockCounts.map((line) => ({
              ingredient: line.item,
              actual_qty: line.actual_qty,
            })),
          },
        });
        if (!result.ok) throw new Error(result.error);
      }
      showToast(ar ? "تم إرسال إغلاق الوردية" : "Shift close submitted", "success");
      onClosed();
    } catch (error) {
      showToast(error?.message || "Could not submit shift close", "warn");
    } finally {
      setBusy(false);
    }
  };

  return (
    <div style={{ height: "100%", display: "flex", flexDirection: "column" }}>
      <div className="between" style={{ height: 52, padding: "0 18px", borderBottom: "1px solid var(--line)", background: "var(--surface)" }}>
        <button className="btn btn-ghost" onClick={onBack}><Icon name="arrowLeft" size={13}/>{ar ? "عودة" : "Back"}</button>
        <div className="t-h2">{ui(ar, "closeShift")}</div>
        <span className="badge">{kioskId}</span>
      </div>
      <div className="col" style={{ gap: 14, padding: 18, overflow: "auto" }}>
        <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 14 }}>
          <div className="card card-pad">
            <label className="t-micro">{ui(ar, "countedCash")}</label>
            <input className="input" type="number" min={0} value={actualCash} onChange={(event) => setActualCash(event.target.value)} placeholder={String(Math.round(expectedCash || bayaan.shift?.openingCash || 0))}/>
            <div className="t-small subtle" style={{ marginTop: 6 }}>
              {ar ? "المتوقع نقداً: " : "Expected cash: "}IQD {Math.round(expectedCash || 0).toLocaleString("en")}
            </div>
            <button type="button" className="btn btn-quiet" style={{ marginTop: 8, height: 28, padding: "0 10px", color: "var(--pos, #2C7C58)" }} onClick={confirmCash}>
              <Icon name="check" size={12}/>{ar ? "النقد مطابق للمتوقع" : "Cash matches expected"}
            </button>
          </div>
          <div className="card card-pad">
            <label className="t-micro">{ar ? "البطاقة المعدودة (الجهاز)" : "Counted card (terminal)"}</label>
            <input className="input" type="number" min={0} value={actualCard} onChange={(event) => setActualCard(event.target.value)} placeholder={String(Math.round(expectedCard || 0))}/>
            <div className="t-small subtle" style={{ marginTop: 6 }}>
              {ar ? "متوقع البطاقة: " : "Expected card: "}IQD {Math.round(expectedCard || 0).toLocaleString("en")}
            </div>
            <button type="button" className="btn btn-quiet" style={{ marginTop: 8, height: 28, padding: "0 10px", color: "var(--pos, #2C7C58)" }} onClick={confirmCard}>
              <Icon name="check" size={12}/>{ar ? "البطاقة مطابقة للمتوقع" : "Card matches expected"}
            </button>
          </div>
        </div>
        <div className="card">
          <div className="between" style={{ padding: "12px 14px" }}>
            <div>
              <div className="t-h2">{ui(ar, "stockCount")}</div>
              <div className="t-small subtle">{ui(ar, "varianceRecordSub")}</div>
            </div>
          </div>
          <table className="tbl">
            <tbody>
              {stockRows.map((row) => (
                <tr key={row.item}>
                  <td>{cleanDisplayName(row.item)}</td>
                  <td className="t-num muted">{Number(row.actual_qty || 0).toLocaleString("en", { maximumFractionDigits: 2 })} {row.uom}</td>
                  <td style={{ width: 220 }}>
                    {rowMode[row.item] === "editing" ? (
                      <input className="input" type="number" min={0} step={0.01} autoFocus
                        value={counts[row.item] ?? ""}
                        onChange={(event) => setCounts((current) => ({ ...current, [row.item]: event.target.value }))}
                        placeholder={String(Number(row.actual_qty || 0))}/>
                    ) : rowMode[row.item] === "confirmed" ? (
                      <div className="row" style={{ gap: 8, justifyContent: "flex-end", alignItems: "center" }}>
                        <span className="badge badge-pos" style={{ display: "inline-flex", alignItems: "center", gap: 4 }}>
                          <Icon name="check" size={11}/>{ar ? "مطابق" : "Matches"}
                        </span>
                        <button type="button" className="btn btn-quiet" style={{ height: 26, padding: "0 8px" }} onClick={() => modifyRow(row.item, row.actual_qty)}>{ar ? "تعديل" : "Edit"}</button>
                      </div>
                    ) : (
                      <div className="row" style={{ gap: 6, justifyContent: "flex-end", alignItems: "center" }}>
                        <button type="button" className="btn btn-quiet" title={ar ? "العدد مطابق للمتوقع" : "Count matches expected"} style={{ height: 26, padding: "0 8px", color: "var(--pos, #2C7C58)" }} onClick={() => confirmRow(row.item, row.actual_qty)}>
                          <Icon name="check" size={12}/>{ar ? "مطابق" : "Correct"}
                        </button>
                        <button type="button" className="btn btn-quiet" title={ar ? "أدخل العدد الفعلي" : "Enter actual count"} style={{ height: 26, padding: "0 8px" }} onClick={() => modifyRow(row.item, row.actual_qty)}>
                          {ar ? "تعديل" : "Modify"}
                        </button>
                      </div>
                    )}
                  </td>
                </tr>
              ))}
              {!stockRows.length && (
                <tr><td className="muted" style={{ textAlign: "center", padding: 24 }}>{ui(ar, "noSourceKioskStock")}</td></tr>
              )}
            </tbody>
          </table>
        </div>
        <button className="btn btn-primary btn-xl" onClick={submitClose} disabled={busy || !actualCash || bayaan.pendingCount > 0} style={{ justifyContent: "center" }}>
          <Icon name="check" size={14}/>{busy ? ui(ar, "submitting") : ui(ar, "submitClose")}
        </button>
      </div>
    </div>
  );
}

// =============== PAYMENT ===============
function POSPayment({ lang, total, cart, vatRatePct = 0, bootstrap, onTender, tender, onDone, onBack }) {
  const ar = lang === "ar";
  const bayaan = useBayaan();
  const { showToast } = useToast();
  const [phase, setPhase] = useStatePOS("choose"); // choose -> processing -> done
  const [cashGiven, setCashGiven] = useStatePOS("");
  const [submitState, setSubmitState] = useStatePOS({ status: "idle", externalId: null, queued: false, error: "" });
  const demoTenderOptions = React.useMemo(() => [
    { id: "card", icon: "card", label: ar ? "بطاقة" : "Card", sub: ar ? "تلامس أو إدخال" : "Tap or insert card", category: "card" },
    { id: "cash", icon: "cash", label: ar ? "نقد" : "Cash", sub: ar ? "أدخل المبلغ المستلم" : "Enter amount received", category: "cash" },
    { id: "zain cash", icon: "card", label: "Zain Cash", sub: ar ? "محفظة أو رابط دفع" : "Wallet or pay link", category: "mobile_wallet" },
    { id: "fib", icon: "card", label: "FIB", sub: ar ? "تطبيق البنك أو QR" : "Bank app or QR", category: "bank_app" },
    { id: "qi card", icon: "card", label: "Qi Card", sub: ar ? "بطاقة أو SuperQi" : "Card or SuperQi", category: "card" },
    { id: "fastpay", icon: "card", label: "FastPay", sub: ar ? "QR التاجر" : "Merchant QR", category: "mobile_wallet" },
  ], [ar]);
  const sourceTenderOptions = React.useMemo(
    () => sourcePosPaymentOptions(bootstrap, bayaan.kioskId, ar),
    [ar, bayaan.kioskId, bootstrap],
  );
  const tenderOptions = bayaan.mode === "live" ? sourceTenderOptions : demoTenderOptions;
  const noSourceTenderOptions = bayaan.mode === "live" && tenderOptions.length === 0;
  const cashTender = tenderOptions.find((option) => option.category === "cash" || normalizePaymentText(option.id) === "cash");

  const pickTender = (t) => {
    if (noSourceTenderOptions) {
      showToast(ar ? "لا توجد طرق دفع مصدر مهيأة." : "No source payment methods are configured.", "warn");
      return;
    }
    onTender(t);
    setPhase("processing");
    setSubmitState({ status: "submitting", externalId: null, queued: false, error: "" });
    const tenderOption = tenderOptions.find((option) => option.id === t);
    const minProcessingMs = tenderOption?.category === "card" ? 1400 : 600;
    const submitPromise = bayaan.submitSale({ cart, tender: t, total });
    const delayPromise = new Promise((resolve) => setTimeout(resolve, minProcessingMs));
    Promise.all([submitPromise, delayPromise]).then(([result]) => {
      if (result.ok) {
        const externalId = result.externalId || result.result?.external_id || result.result?.id || null;
        const consumptionState = result.result?.consumption_state;
        if (consumptionState === "missing_recipe" || consumptionState === "failed") {
          // Sale recorded, but the recipe deduction did not post. Do NOT show a clean
          // green "Recorded" — flag it so a manager reconciles stock before close.
          setSubmitState({ status: "consumption_warn", externalId, queued: false, error: result.result?.consumption_error || "" });
          showToast(
            ar ? "تم تسجيل البيع لكن لم تُرحّل الوصفة — يلزم مراجعة المدير" : "Sale recorded — recipe consumption needs manager review",
            "warn",
          );
        } else {
          setSubmitState({ status: "ok", externalId, queued: false, error: "" });
        }
      } else if (result.queued) {
        const blocked = result.queueStatus === "blocked";
        setSubmitState({ status: blocked ? "blocked" : "queued", externalId: result.externalId || null, queued: true, error: result.error });
        showToast(
          ar ? `تم حفظ البيع محلياً وسيتم الإرسال عند رجوع الاتصال` : `Sale queued offline · will sync when online`,
          "warn",
        );
      } else {
        setSubmitState({ status: "error", externalId: null, queued: false, error: result.error });
        showToast(
          (ar ? "فشل البيع: " : "Sale failed: ") + result.error,
          "crit",
        );
      }
      setPhase("done");
    });
  };

  const cashNum = parseFloat(cashGiven) || 0;
  const change = cashNum - total;

  if (phase === "done") {
    const isError = submitState.status === "error";
    const isQueued = submitState.status === "queued";
    const isBlocked = submitState.status === "blocked";
    const isConsumptionWarn = submitState.status === "consumption_warn";
    const isOk = submitState.status === "ok";
    const isCashPayment = tender === "cash" || cashTender?.id === tender || normalizePaymentText(tender) === "cash";
    const handlePrintReceipt = () => {
      const tenderOption = tenderOptions.find((option) => option.id === tender);
      printPosReceipt({
        id: submitState.externalId,
        kioskId: bayaan.shift?.kioskId || bayaan.kioskId,
        cashier: bayaan.shift?.cashier || "",
        tender: tenderOption?.label || tender,
        status: isBlocked ? "blocked" : isQueued ? "queued" : "recorded",
        total,
        cashGiven: isCashPayment && cashNum > 0 ? cashNum : null,
        change: isCashPayment && cashNum > 0 ? change : null,
        lines: cart.map((line) => ({
          name: line.name,
          size: line.size,
          qty: line.qty,
          price: line.price,
        })),
      });
    };
    const titleAr = isError ? "فشل البيع" : isBlocked ? "محفوظ للمراجعة" : isConsumptionWarn ? "تم الدفع — مراجعة الوصفة" : isQueued ? "تم الحفظ بانتظار الاتصال" : "تم الدفع";
    const titleEn = isError ? "Sale failed" : isBlocked ? "Saved for review" : isConsumptionWarn ? "Paid — recipe review" : isQueued ? "Saved offline" : "Payment complete";
    const subAr = isError
      ? "لم يتم تسجيل البيع. أعد المحاولة أو استدعِ المشرف."
      : isBlocked
      ? "Server rejected this local sale. A manager must reconcile it before close."
      : isConsumptionWarn
      ? "تم تسجيل البيع، لكن لم تُرحّل الوصفة. على المدير تسوية المخزون قبل الإغلاق."
      : isQueued
      ? "البيع في قائمة الانتظار وسيُرسل تلقائياً عند رجوع الاتصال."
      : `طلب ${submitState.externalId ? "#" + String(submitState.externalId).slice(-8) : "#A-1247"} مدفوع`;
    const subEn = isError
      ? "Sale was NOT recorded. Retry or call supervisor."
      : isBlocked
      ? "Server rejected this local sale. A manager must reconcile it before close."
      : isConsumptionWarn
      ? "Sale recorded, but recipe consumption did not post. A manager must reconcile stock before close."
      : isQueued
      ? "Sale queued · will sync automatically when network is back."
      : `Order ${submitState.externalId ? "#" + String(submitState.externalId).slice(-8) : "#A-1247"} paid`;
    const iconBg = isError ? "var(--crit, #C04A38)" : (isQueued || isBlocked || isConsumptionWarn) ? "var(--warn, #B8860B)" : "var(--ink)";
    const iconName = isError ? "x" : (isQueued || isBlocked || isConsumptionWarn) ? "clock" : "check";
    return (
      <div style={{ height: "100%", display: "flex", flexDirection: "column" }}>
        <div style={{ height: 52, padding: "0 18px", borderBottom: "1px solid var(--line)", display: "flex", alignItems: "center" }}>
          <span style={{ fontSize: 13, fontWeight: 500 }}>{ar ? titleAr : titleEn}</span>
          {isOk && <span className="badge badge-pos" style={{ marginInlineStart: 10 }}><span className="dot pos"></span>{ar ? "مسجل" : "Recorded"}</span>}
          {isQueued && <span className="badge badge-warn" style={{ marginInlineStart: 10 }}><span className="dot warn"></span>{ar ? "بانتظار" : "Queued"}</span>}
          {isBlocked && <span className="badge badge-warn" style={{ marginInlineStart: 10 }}><span className="dot warn"></span>{ar ? "مراجعة" : "Review"}</span>}
          {isConsumptionWarn && <span className="badge badge-warn" style={{ marginInlineStart: 10 }}><span className="dot warn"></span>{ar ? "مراجعة الوصفة" : "Recipe review"}</span>}
          {isError && <span className="badge badge-crit" style={{ marginInlineStart: 10 }}><span className="dot crit"></span>{ar ? "خطأ" : "Error"}</span>}
        </div>
        <div className="fade-up" style={{ flex: 1, display: "grid", placeItems: "center", padding: 40 }}>
          <div style={{ textAlign: "center", maxWidth: 420 }}>
            <div style={{ width: 64, height: 64, borderRadius: "50%", background: iconBg, color: "var(--ink-inverse)", display: "grid", placeItems: "center", margin: "0 auto 24px" }}>
              <Icon name={iconName} size={28} stroke={2}/>
            </div>
            <div className="t-display" style={{ marginBottom: 6 }}>{fmtMoney(total)}</div>
            <div className="muted" style={{ marginBottom: 4 }}>{ar ? subAr : subEn}</div>
            {tender === "cash" && cashNum >= total && !isError && (
              <div style={{ marginTop: 24, padding: 16, background: "var(--surface)", border: "1px solid var(--line)", borderRadius: 8, display: "inline-block" }}>
                <div className="t-micro">{ar ? "الباقي" : "Change due"}</div>
                <div className="t-num-display">{fmtMoney(Math.max(0, change))}</div>
              </div>
            )}
            {isError && submitState.error && (
              <div style={{ marginTop: 16, padding: 12, background: "var(--surface)", border: "1px solid var(--crit, #C04A38)", borderRadius: 8, fontSize: 12, color: "var(--crit, #C04A38)", maxWidth: 360, marginInline: "auto" }}>
                {submitState.error}
              </div>
            )}
            <div className="row" style={{ gap: 8, justifyContent: "center", marginTop: 32 }}>
              {!isError && <button onClick={handlePrintReceipt} className="btn btn-ghost btn-lg"><Icon name="receipt" size={14}/>{ar ? "اطبع" : "Print"}</button>}
              {!isError && <button className="btn btn-ghost btn-lg">{ar ? "أرسل عبر SMS" : "Send SMS"}</button>}
              {isError
                ? <button onClick={onBack} className="btn btn-primary btn-lg">{ar ? "إعادة المحاولة" : "Retry"} <Icon name="arrowRight" size={13}/></button>
                : <button onClick={onDone} className="btn btn-primary btn-lg">{ar ? "طلب جديد" : "New order"} <Icon name="arrowRight" size={13}/></button>}
            </div>
          </div>
        </div>
      </div>
    );
  }

  if (phase === "processing") {
    return (
      <div style={{ height: "100%", display: "grid", placeItems: "center" }}>
        <div style={{ textAlign: "center" }}>
          <div style={{ width: 48, height: 48, borderRadius: "50%", border: "2px solid var(--line)", borderTopColor: "var(--ink)", animation: "spin 800ms linear infinite", margin: "0 auto 16px" }}/>
          <style>{`@keyframes spin { to { transform: rotate(360deg); } }`}</style>
          <div style={{ fontSize: 15, fontWeight: 500 }}>{tender === "card" ? (ar ? "جارٍ معالجة البطاقة" : "Processing card") : (ar ? "جارٍ التأكيد" : "Confirming")}</div>
          <div className="muted t-small" style={{ marginTop: 6 }}>{fmtMoney(total)}</div>
        </div>
      </div>
    );
  }

  return (
    <div style={{ height: "100%", display: "flex", flexDirection: "column" }}>
      <div style={{ height: 52, padding: "0 18px", borderBottom: "1px solid var(--line)", display: "flex", alignItems: "center", gap: 12 }}>
        <button onClick={onBack} className="btn btn-quiet" style={{ height: 32 }}>
          <Icon name={ar ? "chevRight" : "chevLeft"} size={13}/>{ar ? "عودة للطلب" : "Back to order"}
        </button>
        <span style={{ fontSize: 13, fontWeight: 500 }}>{ar ? "اختر طريقة الدفع" : "Choose payment"}</span>
      </div>
      <div style={{ flex: 1, display: "grid", gridTemplateColumns: "1fr 380px" }}>
        <div style={{ padding: 32, overflow: "auto" }}>
          <div className="t-micro" style={{ marginBottom: 6 }}>{ar ? "الإجمالي المستحق" : "Amount due"}</div>
          <div className="t-num-display" style={{ fontSize: 56, marginBottom: 36, letterSpacing: "-0.03em" }}>{fmtMoney(total)}</div>

          <div style={{ display: "grid", gridTemplateColumns: "repeat(3, 1fr)", gap: 12, maxWidth: 760 }}>
            {tenderOptions.map((option) => (
              <button key={option.id} onClick={() => pickTender(option.id)} className="card" style={{ padding: 24, textAlign: "start", cursor: "pointer", minHeight: 140 }}>
                <Icon name={option.icon} size={28} style={{ color: "var(--ink-1)", marginBottom: 14 }}/>
                <div style={{ fontSize: 17, fontWeight: 500 }}>{option.label}</div>
                <div className="t-small subtle" style={{ marginTop: 4 }}>{option.sub}</div>
              </button>
            ))}
            {noSourceTenderOptions && (
              <div className="card" style={{ gridColumn: "1 / -1", padding: 18 }}>
                <div style={{ fontSize: 13, fontWeight: 500 }}>{ar ? "لا توجد طرق دفع من المصدر" : "No source payment methods loaded"}</div>
                <div className="t-small subtle" style={{ marginTop: 6 }}>{ar ? "حمّل طرق الدفع المهيأة من /bayaan/api/chain_bootstrap قبل إتمام البيع." : "Load configured POS payment methods from /bayaan/api/chain_bootstrap before completing the sale."}</div>
              </div>
            )}
          </div>

          {cashTender && (
            <div style={{ marginTop: 28, maxWidth: 640 }}>
              <div className="t-micro" style={{ marginBottom: 10 }}>{ar ? "نقد سريع" : "Quick cash"}</div>
              <div className="row" style={{ gap: 8, flexWrap: "wrap" }}>
                {(() => { const ceilTo = (t, n) => Math.ceil(t / n) * n; return [total, ceilTo(total, 1000), ceilTo(total, 5000), ceilTo(total, 10000), ceilTo(total, 25000)]; })()
                  .filter((v, i, a) => v >= total && a.indexOf(v) === i).slice(0, 5).map(amt => (
                  <button key={amt} onClick={() => { setCashGiven(String(amt)); pickTender(cashTender.id); }}
                    className="btn btn-ghost btn-lg" style={{ minWidth: 92 }}>
                    {fmtMoney(amt)}
                  </button>
                ))}
              </div>
            </div>
          )}
        </div>
        <div style={{ borderInlineStart: "1px solid var(--line)", padding: 20, background: "var(--surface-2)", overflow: "auto" }}>
          <div className="t-micro" style={{ marginBottom: 12 }}>{ar ? "ملخص الطلب" : "Order summary"}</div>
          <div className="col" style={{ gap: 8 }}>
            {cart.map(l => (
              <div key={l.key} className="between t-small">
                <span>{l.qty}× {l.name}</span>
                <span className="t-num">IQD {(l.price * l.qty).toLocaleString("en")}</span>
              </div>
            ))}
          </div>
          <div className="hairline" style={{ margin: "16px 0" }}></div>
          {vatRatePct > 0 && (() => { const f = Number(vatRatePct) / 100; const v = Math.round(total * f / (1 + f)); return (<>
          <div className="between t-small muted"><span>{ar ? "المجموع الفرعي" : "Subtotal"}</span><span className="t-num">{fmtMoney(total - v)}</span></div>
          <div className="between t-small muted" style={{ marginTop: 4 }}><span>{ar ? `ضريبة ${vatRatePct}٪` : `VAT ${vatRatePct}%`}</span><span className="t-num">{fmtMoney(v)}</span></div>
          </>); })()}
          <div className="between" style={{ marginTop: 10, fontSize: 14, fontWeight: 500 }}><span>{ar ? "الإجمالي" : "Total"}</span><span className="t-num">{fmtMoney(total)}</span></div>
        </div>
      </div>
    </div>
  );
}

// =============== WASTE ENTRY ===============
function POSWaste({ lang, bootstrap, onDone, onBack }) {
  const ar = lang === "ar";
  const bayaan = useBayaan();
  const { showToast } = useToast();
  const [item, setItem] = useStatePOS(null);
  const [qty, setQty] = useStatePOS(1);
  const [reason, setReason] = useStatePOS(null);
  const [busy, setBusy] = useStatePOS(false);

  const liveWasteItems = React.useMemo(() => {
    const snapshot = unwrapOdoo(bootstrap);
    if (bayaan.mode !== "live") return null;
    if (!bayaan.hasBackend || !snapshot) return [];
    const stockRows = (snapshot.kiosk_stock_rows || [])
      .filter((row) => matchesKiosk(row.kiosk, { id: bayaan.kioskId, kiosk_code: bayaan.kioskId }));
    const productsByCode = new Map((snapshot.products || []).map((product) => [product.default_code || product.name, product]));
    const rows = stockRows.map((row) => {
      const product = productsByCode.get(row.item);
      return {
        id: product?.default_code || row.item,
        name: cleanDisplayName(product?.name || row.name || row.item),
        price: Number(product?.standard_price || row.standard_price || row.unit_cost || row.unitCost || 0),
        uom: row.uom || product?.uom || "",
      };
    });
    return rows;
  }, [bayaan.hasBackend, bayaan.kioskId, bayaan.mode, bootstrap]);

  const items = liveWasteItems ?? [
    { id: "menu-croissant-plain", name: "Croissant — Plain", price: 12 },
    { id: "menu-croissant-chocolate", name: "Croissant — Chocolate", price: 14 },
    { id: "menu-pistachio-cake", name: "Pistachio Cake", price: 32 },
    { id: "menu-latte", name: "Latte", price: 22 },
    { id: "menu-iced-latte", name: "Iced Latte", price: 24 },
    { id: "ing-milk-whole", name: "Milk (whole) 1L", price: 12 },
  ];
  const reasons = ar
    ? ["انتهاء اليوم", "خطأ في الطلب", "إسقاط/سكب", "رفض جودة", "تالف"]
    : ["End of day", "Wrong order", "Spill / drop", "Quality reject", "Spoiled"];

  const cost = item ? item.price * qty : 0;
  const canSubmit = !!item && !!reason && qty > 0 && !busy;

  const handleSubmit = async () => {
    if (!canSubmit) return;
    if (bayaan.mode === "live" && !bayaan.hasBackend) {
      showToast(ar ? "اربط محرك المصدر قبل تسجيل هدر مصدر." : "Connect the source engine before recording source waste", "warn");
      return;
    }
    setBusy(true);
    try {
      const result = await bayaan.submitWaste({ item, qty, reason });
      if (result.ok) {
        showToast(
          ar ? `تم تسجيل الهدر — ${item.name}` : `Waste recorded — ${item.name}`,
          "success",
        );
        onDone();
      } else if (result.queued) {
        showToast(
          ar ? "حُفظ الهدر محلياً وسيُرسل عند الاتصال" : "Waste queued · will sync when online",
          "warn",
        );
        onDone();
      } else {
        showToast(
          (ar ? "فشل تسجيل الهدر: " : "Waste failed: ") + result.error,
          "crit",
        );
      }
    } finally {
      setBusy(false);
    }
  };

  return (
    <div style={{ height: "100%", display: "flex", flexDirection: "column" }}>
      <div style={{ height: 52, padding: "0 18px", borderBottom: "1px solid var(--line)", display: "flex", alignItems: "center", gap: 12 }}>
        <button onClick={onBack} className="btn btn-quiet" style={{ height: 32 }}>
          <Icon name={ar ? "chevRight" : "chevLeft"} size={13}/>{ar ? "عودة" : "Back"}
        </button>
        <span style={{ fontSize: 13, fontWeight: 500 }}>{ar ? "تسجيل هدر" : "Record waste"}</span>
        <span style={{ flex: 1 }}></span>
        <span className="t-small subtle">{ar ? "يصل المشرف فوراً" : "Notifies supervisor instantly"}</span>
      </div>
      <div style={{ flex: 1, display: "grid", gridTemplateColumns: "1fr 380px", overflow: "hidden" }}>
        <div style={{ padding: 28, overflow: "auto" }}>
          <div className="t-micro" style={{ marginBottom: 10 }}>1 — {ar ? "اختر المنتج" : "Choose item"}</div>
          <div style={{ display: "grid", gridTemplateColumns: "repeat(3, 1fr)", gap: 8, marginBottom: 28 }}>
            {items.map(it => (
              <button key={it.name} onClick={() => setItem(it)}
                className="card"
                style={{
                  padding: "14px 16px", textAlign: "start", cursor: "pointer",
                  borderColor: item?.name === it.name ? "var(--ink)" : "var(--line)"
                }}>
                <div style={{ fontSize: 13, fontWeight: 500 }}>{it.name}</div>
                <div className="t-small subtle">IQD {it.price.toLocaleString("en")}{it.uom ? ` · ${ar ? "للوحدة" : "per"} ${it.uom}` : ""}</div>
              </button>
            ))}
            {items.length === 0 && (
              <div className="card" style={{ gridColumn: "1 / -1", padding: 18, color: "var(--ink-3)" }}>
                <div style={{ fontSize: 13, fontWeight: 500, color: "var(--ink-2)" }}>{ar ? "لا توجد بنود هدر من المصدر" : "No source waste items loaded"}</div>
                <div className="t-small subtle" style={{ marginTop: 6 }}>{ar ? "اربط محرك المصدر أو حمّل مخزون الكشك قبل تسجيل الهدر." : "Connect the source engine or load kiosk stock before recording waste."}</div>
              </div>
            )}
          </div>

          <div className="t-micro" style={{ marginBottom: 10 }}>2 — {ar ? "الكمية" : "Quantity"}{item?.uom ? ` (${item.uom})` : ""}</div>
          {(() => {
            // Ingredients are measured in kg/L, so allow fractional waste (e.g. 0.5 L spilled);
            // discrete units (cups, cakes) step by 1.
            const fractional = /kg|كغ|كجم|\bl\b|liter|litre|لتر/i.test(String(item?.uom || ""));
            const step = fractional ? 0.1 : 1;
            const round = (v) => Math.max(0, Math.round(v * 1000) / 1000);
            return (
              <div className="row" style={{ gap: 0, border: "1px solid var(--line)", borderRadius: 8, width: "fit-content", marginBottom: 28, overflow: "hidden" }}>
                <button onClick={() => setQty(q => round(q - step))} style={{ width: 48, height: 48, background: "var(--surface)", borderInlineEnd: "1px solid var(--line)" }}><Icon name="minus" size={14}/></button>
                <input type="number" min={0} step={step} value={qty}
                  onChange={(e) => setQty(round(Number(e.target.value) || 0))}
                  style={{ width: 96, textAlign: "center", fontFamily: "var(--font-mono)", fontSize: 22, height: 48, background: "var(--surface)", border: "none", outline: "none" }}/>
                <button onClick={() => setQty(q => round(q + step))} style={{ width: 48, height: 48, background: "var(--surface)", borderInlineStart: "1px solid var(--line)" }}><Icon name="plus" size={14}/></button>
              </div>
            );
          })()}

          <div className="t-micro" style={{ marginBottom: 10 }}>3 — {ar ? "السبب" : "Reason"}</div>
          <div className="row" style={{ gap: 8, flexWrap: "wrap" }}>
            {reasons.map(r => (
              <button key={r} onClick={() => setReason(r)}
                className={"btn " + (reason === r ? "btn-primary" : "btn-ghost")}
                style={{ height: 36, fontSize: 13 }}>{r}</button>
            ))}
          </div>
        </div>

        <div style={{ borderInlineStart: "1px solid var(--line)", padding: 24, background: "var(--surface-2)", display: "flex", flexDirection: "column" }}>
          <div className="t-micro" style={{ marginBottom: 8 }}>{ar ? "ملخص" : "Summary"}</div>
          <div style={{ background: "var(--surface)", border: "1px solid var(--line)", borderRadius: 8, padding: 16 }}>
            <div className="t-small subtle">{ar ? "المنتج" : "Item"}</div>
            <div style={{ fontSize: 14, fontWeight: 500, marginTop: 2, minHeight: 22 }}>{item?.name || (ar ? "—" : "Not selected")}</div>
            <div className="hairline" style={{ margin: "12px 0" }}></div>
            <div className="between t-small muted"><span>{ar ? "الكمية" : "Qty"}</span><span className="t-num">{qty}{item?.uom ? ` ${item.uom}` : ""}</span></div>
            <div className="between t-small muted" style={{ marginTop: 4 }}><span>{ar ? "السبب" : "Reason"}</span><span style={{ color: reason ? "var(--ink-1)" : "var(--ink-3)" }}>{reason || (ar ? "—" : "—")}</span></div>
            <div className="hairline" style={{ margin: "12px 0" }}></div>
            <div className="between"><span style={{ fontSize: 13, fontWeight: 500 }}>{ar ? "تكلفة الهدر" : "Loss value"}</span><span className="t-num" style={{ fontSize: 18 }}>{fmtMoney(cost)}</span></div>
          </div>

          <div style={{ flex: 1 }}></div>
          <button disabled={!canSubmit} onClick={handleSubmit}
            className="btn btn-primary btn-xl" style={{ justifyContent: "center", marginTop: 16, opacity: canSubmit ? 1 : 0.4 }}>
            {busy ? (ar ? "جارٍ الحفظ…" : "Saving…") : (ar ? "سجّل الهدر" : "Submit waste")}
          </button>
          <div style={{ fontSize: 11, color: "var(--ink-3)", textAlign: "center", marginTop: 10 }}>
            {bayaan.shift
              ? (ar
                ? `يُسجَّل تحت ${bayaan.shift.cashier} · ${bayaan.shift.kioskId}`
                : `Logged under ${bayaan.shift.cashier} · ${bayaan.shift.kioskId}`)
              : (ar ? "يُسجَّل تحت اسمك ووقت الوردية" : "Logged under your name and shift time")}
          </div>
        </div>
      </div>
    </div>
  );
}



/* ===== customer-display.jsx ===== */

/* ============================================================
   Customer-facing display — vertical tablet next to cashier
   Shows order live, total, and friendly status messages.
   ============================================================ */

function CustomerDisplay({ lang, screen, cart, subTotal, vat, total, vatRatePct = 0, tender, lastAdded }) {
  const ar = lang === "ar";
  const [showFlash, setShowFlash] = React.useState(false);

  React.useEffect(() => {
    if (!lastAdded) return;
    setShowFlash(true);
    const t = setTimeout(() => setShowFlash(false), 1400);
    return () => clearTimeout(t);
  }, [lastAdded?.t]);

  // ---- LOGIN / IDLE: branded standby ----
  // Also shown when cashier is on the sale screen with no items yet
  // (e.g. right after pressing "New order"): customer sees the home
  // screen until the first item is added.
  if (screen === "login" || (screen === "sale" && cart.length === 0)) {
    return (
      <div style={{ height: "100%", display: "flex", flexDirection: "column", background: "var(--terminal)", color: "var(--terminal-ink)" }}>
        <div style={{ flex: 1, display: "flex", flexDirection: "column", justifyContent: "center", alignItems: "center", padding: "0 32px", textAlign: "center" }}>
          <JuiceLottie className="customer-standby-lottie" />
          <BrandLogo className="customer-display-logo" alt={ar ? BRAND.arabic : BRAND.name}/>
          <div className="customer-display-brand-text">{ar ? BRAND.arabic : BRAND.name}</div>
          <div style={{ fontSize: 12, color: "#9A998F", marginTop: 12, letterSpacing: "0.06em", textTransform: "uppercase" }}>
            {ar ? "قهوة · عصائر · مخبوزات" : "Coffee · Juice · Bakery"}
          </div>
          <div style={{ height: 1, width: 40, background: "#3A3A40", margin: "24px auto" }}></div>
          <div style={{ fontSize: 13.5, color: "#C9C8C0", lineHeight: 1.55 }}>
            {ar ? "تفضل عند الكاشير" : "Step up when ready"}
          </div>
        </div>
        <div style={{ padding: "16px 20px", borderTop: "1px solid #2A2A2E", display: "flex", justifyContent: "space-between", fontSize: 11, color: "#6E6E68" }}>
          <span>{ar ? "الكرادة" : "Karrada Center"}</span>
          <span className="t-num">07:42</span>
        </div>
      </div>
    );
  }

  // ---- PAYMENT: pay prompt ----
  if (screen === "payment" && tender == null) {
    return (
      <div style={{ height: "100%", display: "flex", flexDirection: "column", background: "var(--surface)" }}>
        <div style={{ padding: "20px 22px", borderBottom: "1px solid var(--line)" }}>
          <div className="t-micro">{ar ? "إجمالي مستحق" : "Amount due"}</div>
          <div className="t-num-display" style={{ fontSize: 44, marginTop: 4 }}>{fmtMoney(total)}</div>
        </div>
        <div style={{ flex: 1, padding: "24px 22px", overflow: "auto" }}>
          <div className="t-micro" style={{ marginBottom: 10 }}>{ar ? "طلبك" : "Your order"}</div>
          <div className="col" style={{ gap: 8 }}>
            {cart.map(l => (
              <div key={l.key} className="row" style={{ fontSize: 13, gap: 10, justifyContent: "space-between" }}>
                <div className="row" style={{ gap: 8, minWidth: 0, flex: 1 }}>
                  <ProductImage slug={l.image} name={l.name} size={28} radius={4}/>
                  <span className="muted" style={{ minWidth: 0, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>
                    {l.qty}× {l.name}
                  </span>
                </div>
                <span className="t-num">IQD {(l.price * l.qty).toLocaleString("en")}</span>
              </div>
            ))}
          </div>
        </div>
        <div style={{ padding: "20px 22px", background: "var(--terminal)", color: "var(--terminal-ink)", textAlign: "center" }}>
          <div style={{ display: "flex", gap: 14, justifyContent: "center", alignItems: "center", fontSize: 14, fontWeight: 500 }}>
            <Icon name="card" size={18}/>
            <span>{ar ? "اقترب أو أدخل بطاقتك" : "Tap or insert card"}</span>
          </div>
        </div>
      </div>
    );
  }

  if (screen === "payment" && tender != null) {
    // processing/done: show big total + thank you when paid
    return (
      <div style={{ height: "100%", display: "flex", flexDirection: "column", background: "var(--surface)", alignItems: "center", justifyContent: "center", padding: "0 22px", textAlign: "center" }}>
        <SuccessLottie size={72} style={{ marginBottom: 22 }} />
        <div className="t-h2" style={{ marginBottom: 6 }}>{ar ? "شكراً لزيارتك" : "Thank you"}</div>
        <div className="t-num-display" style={{ marginTop: 4 }}>{fmtMoney(total)}</div>
        <div className="muted t-small" style={{ marginTop: 12 }}>{ar ? "نتمنى لك يوماً جميلاً" : "Have a great day"}</div>
      </div>
    );
  }

  // ---- WASTE: cashier-only screen, customer sees standby ----
  if (screen === "waste") {
    return (
      <div style={{ height: "100%", display: "grid", placeItems: "center", background: "var(--surface)", padding: "0 28px", textAlign: "center" }}>
        <div>
          <div style={{ fontSize: 32, fontWeight: 500, letterSpacing: "-0.02em", marginBottom: 10 }}>{ar ? "لحظة من فضلك" : "One moment"}</div>
          <div className="muted" style={{ fontSize: 13.5 }}>{ar ? "الكاشير يعالج طلبك" : "Cashier is with you shortly"}</div>
        </div>
      </div>
    );
  }

  // ---- SALE: live order mirror ----
  return (
      <div style={{ height: "100%", display: "flex", flexDirection: "column", background: "var(--paper)" }}>
        <div style={{ padding: "16px 20px 12px", display: "flex", justifyContent: "space-between", alignItems: "center", borderBottom: "1px solid var(--line)" }}>
          <div className="row" style={{ gap: 8 }}>
          <BrandLogo className="customer-sale-logo" alt={ar ? BRAND.arabic : BRAND.name}/>
          <span style={{ fontSize: 13.5, fontWeight: 500 }}>{ar ? BRAND.arabic : BRAND.name}</span>
        </div>
        <span className="t-small subtle">#A-{1247 + cart.length}</span>
      </div>

      {/* Empty / waiting */}
      {cart.length === 0 && (
        <div style={{ flex: 1, display: "grid", placeItems: "center", padding: "0 28px", textAlign: "center" }}>
          <div>
            <div style={{ fontSize: 26, fontWeight: 500, letterSpacing: "-0.02em", lineHeight: 1.2, marginBottom: 8 }}>
              {ar ? "أهلاً بك" : "Welcome"}
            </div>
            <div className="muted" style={{ fontSize: 13.5, lineHeight: 1.55 }}>
              {ar ? "سيظهر طلبك هنا أثناء التحضير" : "Your order will appear here as it's added"}
            </div>
          </div>
        </div>
      )}

      {/* Order list */}
      {cart.length > 0 && (
        <div className="scroll" style={{ flex: 1, overflow: "auto", padding: "10px 20px" }}>
          <div className="t-micro" style={{ marginBottom: 10 }}>{ar ? "طلبك" : "Your order"}</div>
          <div className="col" style={{ gap: 0 }}>
            {cart.map(l => {
              const isJust = lastAdded && lastAdded.name === l.name && showFlash;
              return (
                <div key={l.key} style={{
                  padding: "12px 0", borderBottom: "1px solid var(--line-soft)",
                  display: "flex", justifyContent: "space-between", alignItems: "center", gap: 12,
                  background: isJust ? "var(--accent-soft)" : "transparent",
                  marginInline: isJust ? -10 : 0,
                  paddingInline: isJust ? 10 : 0,
                  borderRadius: isJust ? 6 : 0,
                  transition: "background 400ms ease, margin 200ms, padding 200ms"
                }}>
                  <ProductImage slug={l.image} name={l.name} size={48} radius={6}/>
                  <div style={{ minWidth: 0, flex: 1 }}>
                    <div style={{ fontSize: 14, fontWeight: 500 }}>{l.name}</div>
                    <div className="t-small subtle">{l.size} · IQD {l.price.toLocaleString("en")}</div>
                  </div>
                  <div className="row" style={{ gap: 12 }}>
                    <span className="t-num muted" style={{ fontSize: 13 }}>×{l.qty}</span>
                    <span className="t-num" style={{ fontSize: 14, minWidth: 80, textAlign: "end" }}>IQD {(l.price * l.qty).toLocaleString("en")}</span>
                  </div>
                </div>
              );
            })}
          </div>
        </div>
      )}

      {/* Totals */}
      <div style={{ padding: "16px 20px", borderTop: "1px solid var(--line)", background: "var(--surface)" }}>
        {vatRatePct > 0 && (<>
        <div className="between t-small muted"><span>{ar ? "المجموع" : "Subtotal"}</span><span className="t-num">{fmtMoney(subTotal)}</span></div>
        <div className="between t-small muted" style={{ marginTop: 4 }}><span>{ar ? `ضريبة ${vatRatePct}٪` : `VAT ${vatRatePct}%`}</span><span className="t-num">{fmtMoney(vat)}</span></div>
        </>)}
        <div className="between" style={{ marginTop: 10, paddingTop: 10, borderTop: "1px solid var(--line-soft)" }}>
          <span style={{ fontSize: 14, fontWeight: 500 }}>{ar ? "الإجمالي" : "Total"}</span>
          <span className="t-num" style={{ fontSize: 26, letterSpacing: "-0.02em" }}>{fmtMoney(total)}</span>
        </div>
      </div>

      <div style={{ padding: "10px 20px", background: "var(--terminal)", color: "var(--terminal-ink)", fontSize: 11.5, textAlign: "center", letterSpacing: "0.06em", textTransform: "uppercase" }}>
        {cart.length === 0
          ? (ar ? "بانتظار طلبك" : "Awaiting order")
          : (ar ? "أكد مع الكاشير عند الانتهاء" : "Confirm with cashier when ready")}
      </div>
    </div>
  );
}



/* ===== app.jsx ===== */

/* ============================================================
   App shell — master switcher (Admin / POS), language toggle
   ============================================================ */

const { useState: useStateApp } = React;

const THEME_STORAGE_KEY = "bayaan-dashboard-theme";

function getInitialTheme() {
  if (typeof window === "undefined") return "light";
  const stored = window.localStorage.getItem(THEME_STORAGE_KEY);
  if (stored === "light" || stored === "dark") return stored;
  return window.matchMedia?.("(prefers-color-scheme: dark)").matches ? "dark" : "light";
}

function AuthChip({ lang }) {
  const bayaan = useBayaan();
  const { showToast } = useToast();
  const ar = lang === "ar";
  const [open, setOpen] = useState(false);
  const [form, setForm] = useState({ login: "owner@miza.iq", password: "test" });
  if (!bayaan.hasBackend) return null;

  const user = bayaan.auth.user || {};
  const roleLabel = ar ? (ROLE_LABELS_DISPLAY_AR[user.primaryRole] || "مستخدم") : (ROLE_LABELS[user.primaryRole] || "User");
  const signedIn = bayaan.auth.authenticated;
  const submit = async (event) => {
    event.preventDefault();
    const result = await bayaan.login(form);
    if (result.ok) {
      showToast(ar ? "تم تسجيل الدخول" : `Signed in as ${form.login}`, "success");
      setOpen(false);
    } else {
      showToast(result.error, "warn");
    }
  };
  const signOut = async () => {
    await bayaan.logout();
    showToast(ar ? "تم تسجيل الخروج" : "Signed out", "info");
    setOpen(false);
  };

  return (
    <>
      <button type="button" className="btn btn-ghost" style={{ height: 28, fontSize: 12 }} onClick={() => setOpen(true)}>
        <Icon name="user" size={12}/>
        {signedIn ? `${roleLabel} · ${arTerm(lang, user.name || user.login)}` : (ar ? "دخول" : "Sign in")}
      </button>
      <Modal open={open} onClose={() => setOpen(false)} title={signedIn ? (ar ? "حساب بيان" : "Bayaan account") : (ar ? "الدخول إلى بيان" : "Sign in to Bayaan")} width={420}>
        {signedIn ? (
          <div style={{ display: "grid", gap: 14 }}>
            <div className="card" style={{ padding: 14 }}>
              <div style={{ fontWeight: 600 }}>{arTerm(lang, user.name)}</div>
              <div className="t-small subtle">{user.login}</div>
              <div style={{ marginTop: 10 }}><span className="badge">{roleLabel}</span></div>
            </div>
            <div className="between">
              <button type="button" className="btn btn-ghost" onClick={() => setOpen(false)}>{ar ? "إغلاق" : "Close"}</button>
              <button type="button" className="btn btn-primary" onClick={signOut}>{ar ? "خروج" : "Sign out"}</button>
            </div>
          </div>
        ) : (
          <form onSubmit={submit} style={{ display: "grid", gap: 12 }}>
            <label className="field-label">{ar ? "الدخول" : "Login"}</label>
            <input className="input" value={form.login} onChange={(event) => setForm((current) => ({ ...current, login: event.target.value }))}/>
            <label className="field-label">{ar ? "كلمة المرور" : "Password"}</label>
            <input className="input" type="password" value={form.password} onChange={(event) => setForm((current) => ({ ...current, password: event.target.value }))}/>
            <div className="grid" style={{ gridTemplateColumns: "1fr 1fr", gap: 8 }}>
              {TEST_ACCOUNTS.map((account) => (
                <button
                  key={account.login}
                  type="button"
                  className="btn btn-ghost"
                  style={{ justifyContent: "flex-start", fontSize: 12 }}
                  onClick={() => setForm({ login: account.login, password: "test" })}
                >
                  {arTerm(lang, account.role)}
                </button>
              ))}
            </div>
            {bayaan.auth.error && (
              <div className="t-small" style={{ color: "var(--crit)", background: "var(--crit-soft)", border: "1px solid var(--crit)", borderRadius: 6, padding: 10 }}>
                {bayaan.auth.error}
              </div>
            )}
            <div className="between">
              <button type="button" className="btn btn-ghost" onClick={() => setOpen(false)}>{ui(ar, "cancel")}</button>
              <button type="submit" className="btn btn-primary" disabled={bayaan.auth.busy || !form.login || !form.password}>
                {bayaan.auth.busy ? (ar ? "جار الدخول" : "Signing in") : (ar ? "دخول" : "Sign in")}
              </button>
            </div>
          </form>
        )}
      </Modal>
    </>
  );
}

function MasterTop({ panel, setPanel, lang, setLang, theme, setTheme, scope, setScope }) {
  const bayaan = useBayaan();
  const ar = lang === "ar";
  const canAdmin = authAllowsPanel(bayaan.auth, bayaan.hasBackend, "admin");
  const canPos = authAllowsPanel(bayaan.auth, bayaan.hasBackend, "pos");
  return (
    <div className="master-top">
      <div className="brand">
        <BrandLogo className="master-brand-logo" />
        <span style={{ color: "#6E6E68", fontWeight: 400 }}>{ar ? "- العمليات" : "- operations"}</span>
      </div>
      <div className="seg">
        <button className={panel === "admin" ? "on" : ""} disabled={!canAdmin} onClick={() => setPanel("admin")}>{ar ? "الإدارة" : "Admin"}</button>
        <button className={panel === "pos" ? "on" : ""} disabled={!canPos} onClick={() => setPanel("pos")}>POS</button>
      </div>
      <div className="row" style={{ gap: 12 }}>
        <AuthChip lang={lang}/>
        {typeof setScope === "function" && (
          <label className="scope-select" aria-label={ar ? "النطاق الزمني" : "Time scope"}
            style={{ display: "inline-flex", alignItems: "center", gap: 4 }}>
            <Icon name="clock" size={12}/>
            <select
              value={scope || "Daily"}
              onChange={(event) => setScope(event.target.value)}
              title={ar ? "النطاق الزمني للوحة" : "Dashboard time scope"}
              style={{
                height: 26, borderRadius: 6, border: "1px solid var(--line)",
                background: "var(--surface)", color: "var(--ink-1)", cursor: "pointer",
                fontSize: 11.5, fontFamily: "var(--font-mono)", padding: "0 6px",
              }}
            >
              <option value="Daily">{ar ? "يومي" : "Daily"}</option>
              <option value="Weekly">{ar ? "أسبوعي" : "Weekly"}</option>
              <option value="Monthly">{ar ? "شهري" : "Monthly"}</option>
              <option value="Yearly">{ar ? "سنوي" : "Yearly"}</option>
            </select>
          </label>
        )}
        <div className="theme-switch" role="group" aria-label="Theme">
          <button
            type="button"
            className={theme === "light" ? "on" : ""}
            aria-label="Light theme"
            aria-pressed={theme === "light"}
            title="Light theme"
            onClick={() => setTheme("light")}
          >
            <Icon name="sun" size={13}/>
          </button>
          <button
            type="button"
            className={theme === "dark" ? "on" : ""}
            aria-label="Dark theme"
            aria-pressed={theme === "dark"}
            title="Dark theme"
            onClick={() => setTheme("dark")}
          >
            <Icon name="moon" size={13}/>
          </button>
        </div>
        <div className="lang">
          <button className={lang === "en" ? "on" : ""} onClick={() => setLang("en")}>EN</button>
          <button className={lang === "ar" ? "on" : ""} onClick={() => setLang("ar")}>AR</button>
        </div>
      </div>
    </div>
  );
}

function AuthRequired({ lang }) {
  const bayaan = useBayaan();
  const ar = lang === "ar";
  return (
    <div style={{ flex: 1, display: "grid", placeItems: "center", background: "var(--paper)", padding: 24 }}>
      <div className="card" style={{ width: 420, maxWidth: "100%", padding: 18 }}>
        <div className="t-h2">{ar ? "تسجيل الدخول" : "Sign in"}</div>
        <div className="t-small subtle" style={{ marginTop: 4 }}>
          {ar ? "وضع التشغيل يحتاج حساب بيان." : "Live mode uses Bayaan users and role groups."}
        </div>
        <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 8, marginTop: 16 }}>
          {TEST_ACCOUNTS.map((account) => (
            <button
              key={account.login}
              type="button"
              className="btn btn-ghost"
              style={{ justifyContent: "flex-start", height: 34 }}
              onClick={() => void bayaan.login({ login: account.login, password: "test" })}
            >
              {arTerm(lang, account.role)}
            </button>
          ))}
        </div>
        {bayaan.auth.error && (
          <div className="t-small" style={{ marginTop: 12, color: "var(--crit)" }}>{bayaan.auth.error}</div>
        )}
      </div>
    </div>
  );
}

function AppContent() {
  const bayaan = useBayaan();
  const [panel, setPanel] = useStateApp("admin");
  const [lang, setLang] = useStateApp("en");
  const [theme, setTheme] = useStateApp(getInitialTheme);
  // Global dashboard time scope (Daily | Weekly | Monthly | Yearly). Drives the
  // report-period views (Finance/Reports, Overview headline metrics, Sales & POS
  // history) off the backend's precomputed reportPeriods. "Daily" === the prior
  // today-scoped behaviour, so this is additive and changes nothing by default.
  const [scope, setScope] = useStateApp("Daily");
  const dir = lang === "ar" ? "rtl" : "ltr";
  const needsLogin = bayaan.hasBackend && bayaan.mode === "live" && (!bayaan.auth.checked || !bayaan.auth.authenticated);

  useEffect(() => {
    document.documentElement.dataset.theme = theme;
    window.localStorage.setItem(THEME_STORAGE_KEY, theme);
  }, [theme]);

  useEffect(() => {
    if (authAllowsPanel(bayaan.auth, bayaan.hasBackend, panel)) return;
    if (authAllowsPanel(bayaan.auth, bayaan.hasBackend, "admin")) setPanel("admin");
    else if (authAllowsPanel(bayaan.auth, bayaan.hasBackend, "pos")) setPanel("pos");
  }, [bayaan.auth, bayaan.hasBackend, panel]);

  return (
    <div className={`app-frame panel-${panel}`} data-theme={theme} dir={dir} lang={lang}>
      <MasterTop panel={panel} setPanel={setPanel} lang={lang} setLang={setLang} theme={theme} setTheme={setTheme} scope={scope} setScope={setScope}/>
      {needsLogin
        ? <AuthRequired lang={lang}/>
        : panel === "admin"
          ? <AdminPanel lang={lang} scope={scope}/>
          : <POSPanel lang={lang}/>}
    </div>
  );
}

function App() {
  return (
    <ToastProvider>
      <BayaanProvider>
        <CatalogProvider>
          <AppContent/>
        </CatalogProvider>
      </BayaanProvider>
    </ToastProvider>
  );
}



export default App;
